insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 60, "Según el artículo 48 del Estatuto de autonomía de las Illes Balears, las leyes del Parlamento una vez promulgadas en nombre del rey por el presidente de la comunidad autónoma, se ha de ordenar  la publicación:", "En el Boletín Oficial de las Islas Baleares.", "En el Diario Oficial de la Unión Europea.", "En el Boletín Oficial del Estado.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 61, "Según el artículo 49 del Estatuto de autonomía de las Illes Balears, ¿qué norma puede dictar el Consejo de Gobierno en caso de extraordinaria y urgente necesidad?", "Una ley ordinaria.", "Un decreto.", "Un decreto ley.", "Una ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 62, "Según el artículo 49 del Estatuto de autonomía de las Illes Balears, ¿qué materias, entre otras, no pueden ser modificadas mediante un decreto ley?", "Educación y salud.", "La reforma del Estatuto.", "Los presupuestos generales de la Comunidad Autónoma.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 63, "Según el artículo 50 del Estatuto de autonomía de las Illes Balears, ¿qué órgano designa el senador o senadores que han de representar a la comunidad autónoma de las Islas Baleares en el Senado?", "El Gobierno de les Illes Balears.", "El Parlamento.", "El presidente del Gobierno.", "La Diputación Permanente del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 64, "Según el artículo 54 del Estatuto de autonomía de las Illes Balears, ¿quién elige al presidente de las Islas Baleares?", "El rey.", "El Consejo de Gobierno.", "El Parlamento ,de entre sus miembros.", "Los ciudadanos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 65, "Según el artículo 55 del Estatuto de autonomía de las Illes Balears, ¿quién puede acordar la disolución del Parlamento de las Islas Baleares con anticipación al plazo natural de la legislatura?", "El presidente del Gobierno.", "El Consejo de Gobierno.", "El rey.", "El presidente del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 66, "Según el artículo 56 del Estatuto de autonomía de las Illes Balears, ¿quién nombra y separa a los miembros que han de formar el Gobierno?", "El rey.", "El presidente del Parlamento.", "El Parlamento.", "El presidente del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 67, "Según el artículo 57 del Estatuto de autonomía de las Illes Balears, ¿qué tipo de funciones ejerce el Gobierno de las Islas Baleares?", "Únicamente funciones ejecutivas.", "Funciones ejecutivas y administrativas.", "Funciones ejecutivas y legislativas.", "Funciones administrativas y legislativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 68, "Según el artículo 58 del Estatuto de autonomía de las Illes Balears, ¿qué órgano elabora los presupuestos de la Comunidad Autónoma?", "El Gobierno de las Islas Baleares.", "El Parlamento.", "La consejería competente en materia de presupuestos.", "La comisión permanente en materia de presupuestos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 69, "Según el artículo 61 del Estatuto de autonomía de las Illes Balears, ¿cuál es la institución de gobierno de cada una de las Islas?", "El Gobierno de las Islas Baleares.", "Los ayuntamientos.", "Los consejos insulares.", "La Delegación del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 70, "Según el artículo 75 del Estatuto de autonomía de las Illes Balears, ¿cuál es la entidad local básica de la organización territorial de las Islas Baleares?", "La isla.", "La provincia.", "La comunidad autónoma.", "El municipio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 71, "Según el artículo 76 del Estatuto de autonomía de las Illes Balears, ¿cuál es el órgano superior de consulta de la Comunidad Autónoma de las Islas Baleares?", "El Consejo Consultivo de las Islas Baleares.", "La Abogacía del Gobierno.", "El Consejo Económico y Social.", "La Sindicatura de Cuentas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 72, "Según el artículo 82 del Estatuto de autonomía de las Illes Balears, la Sindicatura de Cuentas será formada:", "Por cinco síndicos.", "Por cuatro síndicos.", "Por tres síndicos.", "Por seis síndicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 73, "Según el artículo 93 del Estatuto de autonomía de las Illes Balears, el órgano jurisdiccional quel culmina la organización judicial de las Islas Baleares dentro de su ámbito territorial es:", "El Tribunal Superior de Justicia de las Islas Baleares.", "El Tribunal Supremo.", "La Audiencia provincial.", "El Tribunal Constitucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 74, "Según el artículo 139 del Estatuto de autonomía de las Illes Balears, ¿a quién corresponde la iniciativa de reforma del Estatuto de autonomía?", "Únicamente al Parlamento.", "Únicamente al Gobierno de la Comunidad Autónoma.", "Únicamente al Parlamento y al Gobierno de la Comunidad Autónoma.", "Al Parlamento, al Gobierno de la Comunidad Autónoma y a las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 5, 75, "La Ley Orgánica 1/2007, de 28 de febrero, de reforma del Estatuto de autonomía de las Illes Balears consta:", "una exposición de motivos, un preámbulo, siete títulos y disposiciones.", "De una exposición de motivos, un preámbulo, ocho títulos y disposiciones.", "De una exposición de motivos, un preámbulo, nueve títulos y disposiciones.", "De una exposición de motivos, un preámbulo, diez títulos y disposiciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 1, "Según el art. 25.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las Entidades Locales ejercen la potestad sancionadora de conformidad con lo dispuesto en:", "El Título XI de la Ley 39/2015, de 1 de octubre.", "El Título IX de la Ley 7/1985, de 2 de abril.", "El Título IX de la Ley 39/2015, de 1 de octubre.", "El Título XI de la Ley 7/1985, de 2 de abril."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 2, "El art. 25.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, dispone que el ejercicio de la potestad sancionadora corresponde a los órganos administrativos que la tengan expresamente atribuida:", "Por la Constitución.", "Por una norma con rango de Ley.", "Por disposición de rango legal o reglamentario.", "Por las normas específicas de cada órgano."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 3, "Según el art. 26.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las disposiciones sancionadoras:", "Podrán producir efecto retroactivo en cuanto favorezcan al presunto infractor.", "Producirán efecto irretroactivo en cuanto favorezcan al presunto infractor.", "No producirán efecto retroactivo en cuanto favorezcan al presunto infractor.", "Producirán efecto retroactivo en cuanto favorezcan al presunto infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 4, "Según el art. 27.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las disposiciones reglamentarias:", "Podrán introducir especificaciones o graduaciones al cuadro de las infracciones o sanciones establecidas legalmente.", "Podrán introducir infracciones y sanciones de carácter leve.", "Podrán regular infracciones y sanciones administrativas en defecto de ley.", "Únicamente podrán regular el procedimiento sancionador."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 5, "Según el art. 28.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los grupos de afectados:", "Podrán ser sancionados por hechos constitutivos de infracción administrativa.", "Podrán ser sancionados por hechos constitutivos de infracción administrativa cuando una ley les reconozca capacidad de obrar.", "No podrán ser sancionados por hechos constitutivos de infracción administrativa.", "No podrán ser sancionados por hechos constitutivos de infracción administrativa cuando una ley les reconozca capacidad de obrar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 6, "Según el art. 28.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuándo pueden ser sancionados los patrimonios independientes o autónomos?", "Cuando una ley les reconozca capacidad de obrar.", "Cuando su estatuto les reconozca capacidad de obrar.", "Cuando una ley o un reglamento les reconozca capacidad de obrar.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 7, "Según el art. 28.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las personas jurídicas podrán ser sancionadas:", "Por hechos constitutivos de infracción administrativa.", "Por hechos constitutivos de infracción administrativa, cuando una Ley les reconozca capacidad de obrar.", "Por hechos constitutivos de sanción administrativa.", "Por hechos constitutivos de infracción administrativa, salvo que una Ley limite su capacidad de obrar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 8, "Según el art. 28.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los infractores son responsables a título de:", "Dolo o culpa.", "Dolo.", "Culpa.", "Dolo, culpa o imprudencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 9, "Según el art. 28.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las responsabilidades administrativas que se deriven de la comisión de una infracción:", "Serán compatibles con la exigencia al infractor de la reposición de la situación alterada por el mismo a su estado originario.", "Serán compatibles con la indemnización por los daños y perjuicios causados.", "Serán incompatibles con la indemnización por los daños y perjuicios causados.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 10, "Según el art. 28.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando el cumplimiento de una obligación establecida por una norma con rango de Ley corresponda a varias personas conjuntamente:", "Responderán de forma solidaria de las infracciones que, en su caso, se cometan y de las sanciones que se impongan.", "Responderán de forma mancomunada de las infracciones que, en su caso, se cometan y de las sanciones que se impongan.", "Responderán de forma subsidiaria de las infracciones que, en su caso, se cometan y de las sanciones que se impongan.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 11, "Según el art. 28.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando se imponga una sanción pecuniaria a varias personas conjuntamente, si es posible:", "Se tendrá en cuenta la capacidad económica de los responsables.", "Se individualizará en la resolución en función de la capacidad económica de cada responsable.", "No se debe valorar el grado de participación de cada responsable.", "Se individualizará en la resolución en función del grado de participación de cada responsable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 12, "Según el art. 28.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las leyes reguladoras de los distintos regímenes sancionadores:", "Deberán prever los supuestos en que determinadas personas responderán del pago de las sanciones pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "Podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "Deberán prever los supuestos en que determinadas personas responderán de las sanciones impuestas a quienes de ellas dependan o estén vinculadas.", "Podrán prever los supuestos en que determinadas personas responderán de las sanciones impuestas a quienes de ellas dependan o estén vinculadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 13, "Según el art. 29.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, es un criterio de graduación de la sanción:", "La reincidencia, por comisión en el término de un año de más de una infracción de la misma naturaleza cuando así haya sido declarado por resolución firme en vía administrativa.", "La reiteración, por comisión en el término de un año de más de una infracción de la misma naturaleza cuando así haya sido declarado por resolución firme en vía administrativa.", "La reincidencia, por comisión en el término de un año de más de una infracción cuando así haya sido declarado por resolución firme en vía administrativa.", "La reiteración, por comisión en el término de un año de más de una infracción cuando así haya sido declarado por resolución firme en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 14, "¿Cuál de las siguientes reglas no figura entre los criterios de graduación de la sanción del art. 29.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público?", "El grado de culpabilidad.", "La existencia de intencionalidad.", "La capacidad económica.", "La continuidad o persistencia en la conducta infractora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 15, "Según el art. 29.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, se podrá imponer la sanción en el grado inferior:", "Cuando las circunstancias lo aconsejen y lo solicite el interesado.", "Cuando haya razones de interés público.", "Cuando lo justifique la debida adecuación entre la sanción que deba aplicarse con la gravedad del hecho constitutivo de la infracción y las circunstancias concurrentes.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 16, "Según el art. 29.5 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando de la comisión de una infracción derive necesariamente la comisión de otra u otras:", "Se podrá calificar únicamente la infracción más grave cometida.", "Se deberá imponer únicamente la sanción correspondiente a la infracción más grave cometida.", "Se deberá calificar únicamente la infracción más grave cometida.", "Se podrá imponer únicamente la sanción correspondiente a la infracción más leve cometida."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 17, "Según el art. 30.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en defecto de una ley específica las infracciones muy graves prescriben:", "A los seis meses.", "Al año.", "A los dos años.", "A los tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 18, "Según el art. 30.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las sanciones impuestas por faltas leves prescriben:", "Según lo dispuesto en las leyes que las establezcan o, en su defecto, al año.", "Al año.", "Según lo dispuesto en las leyes que las establezcan o, en su defecto, a los seis meses.", "A los seis meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 19, "Según el art. 30.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en defecto de una ley específica las sanciones impuestas por faltas graves prescriben:", "A los seis meses.", "Al año.", "A los dos años.", "A los tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 20, "Según el art. 30.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿es posible aumentar el plazo de prescripción de las infracciones graves a hasta los tres años?", "Sí, mediante una ley.", "No, únicamente se pueden reducir los plazos de prescripción.", "Sí, mediante una ley específica o un reglamento sectorial.", "No, los plazos de prescripción no pueden ser modificados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 21, "Según el art. 30.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de prescripción de las infracciones comenzará a contarse:", "Desde el día en que la infracción se hubiera cometido.", "Desde el día siguiente a aquel en que la resolución sea ejecutable.", "Desde el día siguiente a aquel en que la infracción se hubiera cometido.", "Desde el día en que la resolución sea ejecutable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 22, "Según el art. 30.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la iniciación, con conocimiento del interesado, de un procedimiento administrativo de naturaleza sancionadora:", "Interrumpe el plazo de prescripción de la sanción.", "Interrumpe el plazo de prescripción de la infracción.", "Interrumpe el plazo de prescripción de la infracción y de la sanción.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 23, "Según el art. 30.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de prescripción de la infracción se reinicia si el expediente sancionador:", "Estuviera paralizado durante menos de un mes.", "Estuviera paralizado durante menos de un mes por causa no imputable al presunto responsable.", "Estuviera paralizado durante más de un mes.", "Estuviera paralizado durante más de un mes por causa no imputable al presunto responsable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 24, "Según el art. 30.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de prescripción de las sanciones comenzará a contarse:", "Desde el día en que sea ejecutable la resolución por la que se impone la sanción o haya transcurrido el plazo para recurrirla.", "Desde el día en que la infracción se hubiera cometido.", "Desde el día siguiente a aquel en que sea ejecutable la resolución por la que se impone la sanción o haya transcurrido el plazo para recurrirla.", "Desde el día siguiente a aquel en que la infracción se hubiera cometido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 25, "Según el art. 30.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo la prescripción de las sanciones vuelve a transcurrir cuando el procedimiento esté paralizado:", "Durante menos de un mes por causa no imputable al infractor.", "Durante más de un mes.", "Durante más de un mes por causa imputable al infractor.", "Durante más de un mes por causa no imputable al infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 26, "Según el art. 30.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en el caso de desestimación presunta del recurso de alzada interpuesto contra la resolución por la que se impone la sanción, el plazo de prescripción de la sanción comenzará a contarse:", "Desde el día siguiente a aquel en que finalice el plazo legalmente previsto para la resolución de dicho recurso.", "Desde el día siguiente a aquel en que sea ejecutable la resolución por la que se impone la sanción o haya transcurrido el plazo para recurrirla.", "Desde el día en que finalice el plazo legalmente previsto para la resolución de dicho recurso.", "Desde el día en que sea ejecutable la resolución por la que se impone la sanción o haya transcurrido el plazo para recurrirla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 27, "El art. 31.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, dispone que:", "No podrán sancionarse los hechos que lo hayan sido penalmente, en los casos en que se aprecie identidad del sujeto, hecho y fundamento.", "No podrán sancionarse los hechos que lo hayan sido penalmente.", "No podrán sancionarse los hechos que lo hayan sido penal o administrativamente, en los casos en que se aprecie identidad del sujeto, hecho y fundamento.", "No podrán sancionarse los hechos que lo hayan sido penal o administrativamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 28, "Según el art. 31.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando un órgano de la Unión Europea hubiera impuesto una sanción por los mismos hechos, y siempre que no concurra la identidad de sujeto y fundamento, el órgano competente para resolver:", "Podrá tenerla en cuenta a efectos de graduar la que, en su caso, deba imponer, pudiendo minorarla, sin perjuicio de declarar la comisión de la infracción.", "Deberá archivar el procedimiento.", "Deberá tenerla en cuenta a efectos de graduar la que, en su caso, deba imponer, pudiendo minorarla, sin perjuicio de declarar la comisión de la infracción.", "Podrá archivar el procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 29, "Según el art. 32.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, no hay responsabilidad patrimonial de las administraciones públicas por daños que el particular:", "Tenga el deber jurídico de soportar de acuerdo con la Ley.", "Tenga el deber jurídico de soportar de acuerdo con las normas.", "No tenga el deber jurídico de soportar de acuerdo con la Ley.", "No tenga el deber jurídico de soportar de acuerdo con las normas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 30, "Según el art. 32.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la anulación en vía administrativa o por el orden jurisdiccional contencioso administrativo de los actos o disposiciones administrativas:", "No presupone, por sí misma, derecho a la indemnización.", "Presupone el derecho a la indemnización.", "No presupone, por sí misma, derecho a la sanción.", "Presupone el derecho al reconocimiento de la situación jurídica individualizada del particular afectado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 31, "Según el art. 32.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los supuestos de responsabilidad patrimonial el daño alegado debe ser:", "Efectivo.", "Evaluable económicamente.", "Individualizado con relación a una persona o grupo de personas.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 32, "Según el art. 32.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿en cuál de los siguientes supuestos puede surgir la responsabilidad patrimonial del Estado legislador?", "Cuando los daños deriven de la aplicación de una norma contraria al Derecho de la Unión Europea.", "Cuando los daños deriven de la aplicación de una norma comunitaria contraria al derecho interno.", "Cuando los daños deriven de la aplicación de una ley o una disposición general contraria al ordenamiento jurídico.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 33, "Según el art. 32.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿qué requisitos deben cumplirse para obtener una indemnización por una lesión que sea consecuencia de la aplicación de una norma con rango de ley declarada inconstitucional?", "Que el particular haya obtenido, en cualquier instancia, sentencia firme desestimatoria de un recurso contra la actuación administrativa que ocasionó el daño.", "Que se hubiera alegado la inconstitucionalidad posteriormente declarada.", "Que el incumplimiento esté suficientemente caracterizado.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 34, "Según el art. 32.6 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿desde cuándo producirá efectos la sentencia que declare la inconstitucionalidad de una norma con rango de ley?", "Desde la fecha de la notificación a los interesados.", "Desde la fecha de su publicación en el «Boletín Oficial del Estado», salvo que en la sentencia se establezca otra cosa.", "Desde la fecha de su publicación en el «Boletín Oficial del Estado» o en el boletín oficial correspondiente, salvo que en ella se establezca otra cosa.", "Desde la fecha de su publicación en el «Boletín Oficial del Estado»."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 35, "Según el art. 32.8 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando el Tribunal Constitucional haya declarado, a instancia de parte interesada, la existencia de un funcionamiento anormal en la tramitación de los recursos de amparo o de las cuestiones de inconstitucionalidad, ¿qué órgano fijará el importe de las indemnizaciones que proceda abonar?", "El Consejo de Ministros.", "El Consejo de Ministros o el órgano de gobierno de la comunidad autónoma.", "El Tribunal Constitucional.", "El Ministerio de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 36, "Según el art. 32.8 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando el Tribunal Constitucional haya declarado, a instancia de parte interesada, la existencia de un funcionamiento anormal en la tramitación de los recursos de amparo o de las cuestiones de inconstitucionalidad, el procedimiento para fijar el importe de las indemnizaciones se tramitará por:", "El Consejo de Estado, con audiencia al Consejo de Ministros.", "El Ministerio de Justicia, con audiencia al Consejo de Estado.", "El Consejo General del Poder Judicial, con audiencia al Consejo de Estado.", "El Consejo de Ministros o el órgano de gobierno de la comunidad autónoma, con audiencia al Consejo de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 37, "Según el art. 32.9 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, habrá responsabilidad de las Administraciones Públicas por los daños y perjuicios causados a terceros durante la ejecución de contratos cuando sean consecuencia:", "De una orden inmediata y directa de la Administración.", "De los vicios del proyecto elaborado por el contratista.", "De los vicios del proyecto elaborado por la Administración.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 38, "Según el art. 33.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el instrumento jurídico regulador de la actuación conjunta de diversas Administraciones públicas:", "Deberá determinar la distribución de la responsabilidad entre las diferentes Administraciones públicas.", "Podrá determinar la distribución de la responsabilidad entre las diferentes Administraciones públicas.", "Deberá determinar la distribución de la responsabilidad en función de la capacidad económica de las diferentes Administraciones públicas.", "Podrá determinar la exención de la responsabilidad de las diferentes Administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 39, "Según el art. 33.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿qué criterios se tendrán en cuenta para fijar la responsabilidad patrimonial en caso de concurrencia de varias Administraciones públicas?", "Competencia.", "Interés público tutelado.", "Intensidad de la intervención.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 40, "Según el art. 34.1 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, no serán indemnizables los daños que se deriven de hechos o circunstancias:", "Que no se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de producción de aquéllos.", "Que se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de producción de aquéllos.", "Que no se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de la tasación de aquéllos.", "Que se hubiesen podido prever o evitar según el estado de los conocimientos de la ciencia o de la técnica existentes en el momento de la tasación de aquéllos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 41, "Según el art. 34.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los casos de responsabilidad patrimonial la indemnización se calculará con arreglo a los criterios de valoración establecidos en la legislación fiscal, de expropiación forzosa y demás normas aplicables:", "Y subsidiariamente se aplicarán las valoraciones predominantes en el mercado.", "Ponderándose, en su caso, las valoraciones predominantes en el mercado.", "Ponderándose, en su caso, las valoraciones realizadas por un perito judicial.", "Y subsidiariamente se realizará una tasación judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 42, "Según el art. 34.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿qué valoración se podrá tomar como referencia para calcular la indemnización en los casos de muerte o lesiones corporales?", "La incluida en los baremos del anexo II de la Ley 40/2015.", "La incluida en los baremos de la normativa vigente en materia de Seguros obligatorios y de la Seguridad Social.", "La incluida en los baremos de la Ley sobre responsabilidad civil y seguro en la circulación de vehículos a motor.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 43, "Según el art. 34.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los casos de responsabilidad patrimonial, ¿cuándo se puede abonar la indemnización mediante pagos periódicos?", "Cuando no haya disponibilidad presupuestaria para abonar la indemnización durante el año en curso.", "Cuando se prevea en las normas sectoriales específicas.", "Cuando resulte más adecuado para lograr la reparación debida y convenga al interés público.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 44, "Según el art. 35 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, cuando las Administraciones Públicas actúen, directamente o a través de una entidad de derecho privado, en relaciones de esta naturaleza, su responsabilidad se exigirá de conformidad con lo previsto en los artículos 32 y siguientes:", "Incluso cuando la responsabilidad se exija directamente a la entidad de derecho privado a través de la cual actúe la Administración.", "Salvo cuando la responsabilidad se exija directamente a la entidad de derecho privado a través de la cual actúe la Administración.", "Salvo cuando la responsabilidad se exija directamente a la entidad que cubra la responsabilidad.", "Incluso cuando la responsabilidad se exija indirecta y subsidiariamente a la entidad de derecho privado a través de la cual actúe la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 45, "Según el art. 36.2 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿qué criterios se ponderarán para cuantificar la indemnización que deben abonar los empleados de la Administración en los casos de responsabilidad patrimonial?", "El resultado dañoso producido.", "El grado de culpabilidad.", "La responsabilidad profesional del personal al servicio de las Administraciones públicas y su relación con la producción del resultado dañoso.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 46, "Según el art. 36.3 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿en qué casos se debe exigir responsabilidad a los empleados públicos por los daños y perjuicios causados en los bienes o derechos de la Administración?", "Cuando concurra dolo, o culpa o negligencia graves.", "Cuando concurra dolo o negligencia graves.", "Cuando concurra dolo o culpa graves.", "Cuando concurra dolo, culpa o imprudencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 47, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de alegaciones y el plazo de audiencia en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas es de:", "Diez días en ambos casos.", "Diez días para presentar alegaciones y quince días para realizar la audiencia.", "Quince días para presentar alegaciones y diez días para realizar la audiencia.", "Quince días en ambos casos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 48, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo para practicar pruebas en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas es:", "De diez días.", "No inferior a diez días ni superior a treinta.", "De quince días.", "No inferior a quince días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 49, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el plazo de audiencia en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas es:", "De diez días.", "No inferior a diez días.", "De quince días.", "No inferior a quince días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 50, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas, ¿en qué plazo se formulará la propuesta de resolución?", "Diez días a contar desde la conclusión de la fase de prueba.", "Cinco días a contar desde la finalización del trámite de audiencia.", "Diez días a contar desde la finalización del trámite de audiencia.", "No hay ningún plazo específico para formular la propuesta de resolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 51, "Según el art. 36.4 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuál es el plazo para dictar resolución en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas?", "Cinco días a contar desde la finalización del trámite de audiencia.", "Diez días.", "Diez días a contar desde la finalización del trámite de audiencia.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 52, "Según el art. 36.5 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la resolución declaratoria de responsabilidad en los procedimientos de responsabilidad patrimonial a las autoridades y personal al servicio de las Administraciones Públicas:", "No podrá fin a la vía administrativa.", "Pondrá fin a la vía administrativa.", "Pondrá o no fin a la vía administrativa en función del órgano que la dicta.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 53, "Según el art. 64.2.c) de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el acuerdo de iniciación de los procedimientos de naturaleza sancionadora contendrá:", "Identificación del instructor y, en su caso, Secretario del procedimiento, con expresa indicación del régimen de recusación de los mismos.", "Identificación del instructor y, en su caso, Secretario del procedimiento.", "Identificación del instructor y del Secretario del procedimiento, con expresa indicación del régimen de recusación de los mismos.", "Identificación del instructor, con expresa indicación del régimen de recusación del mismo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 54, "Indique cuál de las siguientes afirmaciones es correcta según el art. 65.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al inicio de oficio de los procedimientos de responsabilidad patrimonial:", "El procedimiento iniciado se archivará si los particulares presuntamente lesionados no se personan en el plazo establecido.", "El plazo de alegaciones no será inferior a diez días.", "Para iniciar el procedimiento será necesario que no haya prescrito el derecho a la reclamación del interesado al que se refiere el artículo 67.", "El acuerdo de iniciación se notificará al instructor y al secretario del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 55, "Según el art. 65.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el plazo para presentar alegaciones en los procedimientos de responsabilidad patrimonial será de:", "Cinco días.", "Diez días.", "Quince días.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 56, "Según el art. 67.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los interesados sólo podrán solicitar el inicio de un procedimiento de responsabilidad patrimonial:", "Cuando no haya prescrito su derecho a reclamar.", "Cuando no haya caducado su derecho a reclamar.", "Cuando no haya prescrito o caducado su derecho a reclamar.", "Cuando haya prescrito o caducado su derecho a reclamar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 57, "Según el art. 67.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en caso de daños de carácter físico o psíquico a las personas, el plazo para reclamar responsabilidad patrimonial empezará a computarse:", "Desde la curación o la determinación del alcance de las secuelas.", "Desde la fecha de producción de los daños.", "Desde que se manifieste el efecto lesivo.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 58, "Según el art. 67.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los casos en que proceda reconocer derecho a indemnización por anulación en vía administrativa o contencioso-administrativa de un acto o disposición de carácter general, el derecho a reclamar:", "Caducará al año de haberse notificado la resolución administrativa o la sentencia definitiva.", "Prescribirá al año de haberse dictado la resolución administrativa o la sentencia definitiva.", "Caducará al año de haberse dictado la resolución administrativa o la sentencia definitiva.", "Prescribirá al año de haberse notificado la resolución administrativa o la sentencia definitiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 59, "Según el art. 67.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál es el plazo de prescripción del derecho para reclamar responsabilidad patrimonial?", "Un mes.", "Seis meses.", "Un año.", "Tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 60, "Según el art. 67.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las solicitudes de responsabilidad patrimonial deben especificar:", "Las lesiones producidas.", "La presunta relación de causalidad entre las lesiones y el funcionamiento del servicio público.", "El momento en que la lesión efectivamente se produjo.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 61, "Según el art. 81.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el plazo para emitir el dictamen del Consejo de Estado en los procedimientos de responsabilidad patrimonial:", "No podrá ser inferior a dos meses.", "Es de dos meses.", "Es de un mes.", "No podrá ser inferior a un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 62, "Según el art. 81.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿en qué casos es preceptivo solicitar dictamen del Consejo de Estado o, en su caso, del órgano consultivo de la Comunidad Autónoma en los procedimientos de responsabilidad patrimonial?", "Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 50.000 euros o a la que se establezca en la correspondiente legislación autonómica.", "En aquellos casos que disponga la Ley Orgánica 3/1980, de 22 de abril, del Consejo de Estado.", "Cuando las indemnizaciones reclamadas sean de cuantía igual o superior a 30.000 euros o a la que se establezca en la correspondiente legislación autonómica.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 63, "Según el art. 81.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial el órgano instructor remitirá al órgano competente para solicitar el dictamen una propuesta de resolución:", "En el plazo de diez días a contar desde la finalización del trámite de audiencia.", "En un plazo no superior a diez días.", "En el plazo de diez días a contar desde la emisión de la propuesta de resolución.", "En un plazo no inferior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 64, "Según el art. 81.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿sobre cuál de los siguientes aspectos debe pronunciarse el dictamen del Consejo de Estado emitido en los procedimientos de responsabilidad patrimonial?", "La continuidad o persistencia en la conducta infractora.", "La valoración del daño causado y la cuantía y modo de la indemnización.", "El grado de culpabilidad o la existencia de intencionalidad.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 65, "Según el art. 81.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial del Estado por el funcionamiento anormal de la Administración de Justicia, el plazo para dictar resolución:", "Podrá quedar suspendido por el tiempo que medie entre la solicitud del informe del Consejo General del Poder Judicial y su recepción.", "Quedará suspendido por el tiempo que medie entre la solicitud del informe del Consejo General del Poder Judicial y su recepción.", "Podrá quedar suspendido por el tiempo que medie entre la solicitud del informe del Consejo de Estado y su recepción.", "Quedará suspendido por el tiempo que medie entre la solicitud del informe del Consejo de Estado y su recepción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 66, "Según el art. 81.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en el caso de reclamaciones en materia de responsabilidad patrimonial del Estado por el funcionamiento anormal de la Administración de Justicia, el informe del Consejo General del Poder Judicial será emitido:", "En el plazo máximo de dos meses.", "En un plazo no inferior a dos meses.", "En el plazo máximo de un mes.", "En un plazo no inferior a un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 67, "Según el art. 85.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las reducciones del importe de la sanción por reconocimiento de la responsabilidad y por pago voluntario anterior a la resolución:", "Serán acumulables entre sí.", "Serán acumulables entre sí cuando el interesado desista de ejercer cualquier recurso en vía administrativa o judicial contra la sanción.", "No serán acumulables entre sí.", "Serán acumulables entre sí cuando el interesado desista de ejercer cualquier recurso en vía judicial contra la sanción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 68, "Según el art. 85.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿es posible modificar los porcentajes de reducción de la sanción previstos en esta la Ley?", "No, dado que la Ley tiene carácter básico.", "Sí, podrán ser incrementados reglamentariamente.", "Sí, pero únicamente pueden ser incrementados mediante ley específica.", "No, dado que la Ley lo prohíbe expresamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 69, "Según el art. 90.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a las especialidades de la resolución en los procedimientos sancionadores:", "En la resolución se podrán aceptar hechos distintos de los determinados en el curso del procedimiento, con un trámite de audiencia a los interesados no inferior a siete días.", "En la resolución se podrán aceptar hechos distintos de los determinados en el curso del procedimiento.", "En la resolución no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento.", "En la resolución se podrán aceptar hechos distintos de los determinados en el curso del procedimiento, con un trámite de audiencia a los interesados no inferior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 70, "Según el art. 90.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se podrá suspender la ejecución de la sanción si el interesado manifiesta a la Administración su intención de interponer:", "Recurso contencioso-administrativo contra la resolución firme en vía administrativa.", "Recurso administrativo contra la sanción contra la sanción definitiva.", "Recurso administrativo contra la sanción firme en vía administrativa.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 71, "Según el art. 90.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la resolución del procedimiento complementario para fijar la cuantía de los daños o perjuicios causados a la Administración:", "No pondrá fin a la vía administrativa.", "No pondrá fin a la vía administrativa, salvo que por ley específica se disponga otra cosa.", "Pondrá fin a la vía administrativa.", "Pondrá fin a la vía administrativa, salvo que por ley específica se disponga otra cosa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 72, "Según el art. 91.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la resolución de los procedimientos de responsabilidad patrimonial, ¿cuándo se someterá la propuesta de acuerdo para su formalización por el interesado y por el órgano administrativo competente para suscribirlo?", "Una vez finalizado el trámite de audiencia.", "Una vez recibido, en su caso, el dictamen al que se refiere el artículo 81.2 o, cuando éste no sea preceptivo, una vez finalizado el trámite de audiencia.", "Una vez notificada la propuesta de resolución.", "Una vez iniciado el trámite de audiencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 73, "Según el art. 91.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial será necesario que la resolución se pronuncie sobre:", "La cuantía y el modo de la indemnización, cuando proceda.", "La existencia o no de la relación de causalidad entre el funcionamiento del servicio público y la lesión producida.", "La continuidad o persistencia en la conducta infractora.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 74, "Según el art. 91.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál es el plazo para resolver los procedimientos de responsabilidad patrimonial?", "Un mes.", "Tres meses.", "Seis meses.", "Un año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 11, 75, "Según el art. 91.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, transcurridos seis meses desde que se inició el procedimiento de responsabilidad patrimonial sin que haya recaído y se notifique resolución expresa o, en su caso, se haya formalizado el acuerdo:", "Se producirá la prescripción del procedimiento.", "Podrá entenderse que la resolución es favorable a la indemnización del particular.", "El procedimiento quedará archivado.", "Podrá entenderse que la resolución es contraria a la indemnización del particular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 1, "De acuerdo con el Código civil, las normas jurídicas contenidas en los tratados internacionales:", "No tienen aplicación directa en España.", "Aunque no pueden llegar a tener aplicación directa en España, tienen carácter informador del ordenamiento jurídico interno.", "Son de aplicación directa en España desde la firma del tratado internacional correspondiente.", "No son de aplicación directa en España mientras no hayan pasado a formar parte del ordenamiento interno mediante la publicación íntegra en Boletín Oficial del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 2, "¿Cuál de las materias siguientes es regulable por un decreto ley?", "El régimen de las comunidades autónomas.", "El derecho electoral general.", "Los derechos, los deberes y las libertades de los ciudadanos que se regulan en el título I de la Constitución.", "Ninguna de las materias anteriores es regulable por un decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 3, "¿Cuándo se aplica la costumbre como fuente de derecho?", "A falta de ley aplicable, siempre que no sea contraria a la moral o al orden público, y que resulte probada.", "Cuando sea de aplicación por razón de la materia.", "En cualquier caso, aunque haya una ley aplicable.", "Cuando no haya principios generales del derecho aplicables al caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 4, "Las disposiciones administrativas que contradigan lo que establece una norma de carácter superior:", "Son nulas de pleno derecho.", "Tienen que ser adaptadas.", "Tienen que ser recorridas ante el Tribunal Supremo.", "Son anuladas por las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 5, "¿Qué artículo del Código civil establece las fuentes del derecho?", "Ninguno.", "El artículo 1.", "El artículo 18.", "El artículo 35."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 6, "De conformidad con la Constitución española, los estatutos de autonomía son:", "La norma institucional básica de cada comunidad autónoma.", "Una ley orgánica estatal.", "Parte integrante del ordenamiento jurídico del Estado.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 7, "La Constitución española establece que la reforma de los estatutos se ajustará al procedimiento que se establezca y requerirá, en todo caso:", "La aprobación del Congreso, por una ley ordinaria.", "La aprobación de las Cortes Generales por mayoría simple, con un dictamen previo favorable del Consejo de Estado.", "La aprobación de las Cortes Generales, por una ley orgánica.", "La aprobación de las Cortes Generales, por una ley ordinaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 8, "El principio de legalidad se establece en la Constitución en:", "El artículo 2.", "El artículo 9.", "El artículo 104.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 9, "En caso de necesidad extraordinaria y urgente, el Gobierno puede dictar disposiciones legislativas provisionales que adoptan la forma de:", "Decreto legislativo.", "Ley de bases.", "Decreto ley.", "Ley marco."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 10, "Las disposiciones dictadas por los ministros se publican con la denominación:", "De orden.", "De orden ministerial.", "De decreto.", "De decreto ministerial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 11, "El principio de jerarquía de las fuentes del derecho administrativo:", "Determina la invalidez de la norma inferior que contradiga lo que dispone la superior.", "Se regula en el artículo 9.3 de la Constitución.", "No se aplica en las relaciones entre las leyes ordinarias y las orgánicas.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 12, "El principio de reserva de ley significa:", "Que la ley se sitúa en la posición más elevada de la pirámide normativa.", "Que no es posible negarse a la aplicación o el cumplimiento de la ley.", "Que el enjuiciamiento de la ley compite en exclusiva a los tribunales o les está reservado.", "Que determinadas materias establecidas por la Constitución sólo pueden ser reguladas por una norma con rango legal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 13, "Los principios generales del derecho:", "Son fuente indirecta.", "Tienen un valor normativo superior a la costumbre.", "Son fuente de aplicación a falta de ley y costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico.", "Tienen un valor normativo superior a la costumbre, sin perjuicio de su carácter informador del ordenamiento jurídico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 14, "En relación con los decretos ley:", "Son aprobados por el Consejo de Ministros.", "Son aprobados por el Consejo de Ministros, con la autorización previa del Congreso.", "Son aprobados por el Consejo de Ministros, con la autorización previa de las Cortes Generales.", "Son aprobados por el presidente del Gobierno, con la deliberación previa del Consejo de Ministros y la consulta al Congreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 15, "En la ley marco:", "Se fijan los principios para armonizar las disposiciones normativas de las comunidades autónomas cuando lo exija el interés general.", "Se transfieren facultades de titularidad estatal a las comunidades autónomas, por una ley orgánica.", "Se establece la modalidad de control de las Cortes Generales sobre determinadas normas legislativas de las comunidades autónomas.", "Puede otorgarse una delegación legislativa en el Gobierno porque armonice actuaciones autonómicas cuando así lo exija el interés general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 16, "La aprobación, modificación o derogación de una ley orgánica exige:", "La mayoría absoluta del Congreso.", "La mayoría absoluta del Senado.", "La mayoría absoluta de las Cortes.", "La mayoría simple del Congreso, en votación final sobre el conjunto del proyecto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 17, "La delegación legislativa efectuada por las Cortes Generales a favor del Gobierno, con el fin de formar un texto articulado, tendrá que hacerse:", "A través de una ley marco.", "A través de una ley básica.", "A través de una ley ordinaria.", "A través de una ley de bases."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 18, "El Estatuto de autonomía tiene que contener:", "La delimitación del territorio de la comunidad autónoma.", "La denominación, la organización y la sede de las instituciones autonómicas propias.", "La denominación de la comunidad autónoma.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 19, "De acuerdo con el artículo 149.3 de la Constitución, qué normas prevalecen en caso de conflicto entre las de una comunidad y las del Estado?", "Siempre las del Estado.", "Siempre las de la comunidad.", "Las del Estado, salvo que la materia esté atribuida exclusivamente a la comunidad.", "Las de la comunidad, salvo que la materia esté atribuida exclusivamente al Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 20, "De acuerdo con la Constitución, son leyes orgánicas las relativas:", "Al régimen de las comunidades autónomas.", "Al desarrollo de los derechos fundamentales y de las libertades públicas.", "Al régimen electoral general.", "Las respondidas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 21, "De acuerdo con la Constitución, los decretos ley:", "Tendrán que ser sometidos inmediatamente a debate y votación de la totalidad en el Congreso en el plazo de quince días desde la promulgación.", "Podrán afectar los derechos fundamentales y las libertades públicas.", "Tendrán que ser sometidos inmediatamente a debate y votación de la totalidad en el Congreso en el plazo de los veinte días siguientes a la promulgación.", "Durante el plazo para la convalidación o derogación, las Cortes podrán tramitarlos como proyecto de ley por el procedimiento de urgencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 22, "En relación con la supletoriedad del derecho estatal respecto del autonómico, el artículo 149.3 de la Constitución establece que:", "El derecho estatal será, en todo caso, supletorio del de las comunidades autónomas.", "Sólo será supletorio del derecho de las comunidades autónomas en el caso que estas no hayan legislado sobre sus competencias asumidas.", "El derecho estatal sólo será supletorio cuando así lo establezca una norma con rango de ley.", "Será supletorio del derecho de las comunidades autónomas excepto en las materias de competencia exclusiva de estas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 23, "Según la Constitución española:", "El Congreso podrá delegar en el Gobierno la potestad de dictar normas con rango de ley sobre materias determinadas, excepto las que se tengan que aprobar con una ley orgánica.", "El Senado, como cámara de representación territorial, podrá delegar en el Gobierno la potestad de dictar normas con rango de ley sobre la distribución territorial del Estado.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley sobre el desarrollo de los derechos fundamentales y las libertades públicas, sobre el régimen electoral general y sobre las otras materias previstas en la Constitución.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normes con rango de ley sobre materias determinadas no incluidas en el artículo 81."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 24, "De acuedo con la Ley 50/1997, de 27 de noviembre, del Gobierno, los reglamentos dictados por el presidente del Gobierno se publican con la denominación de:", "Reales decretos del presidente del Gobierno.", "Decretos del presidente.", "Decretos de Presidencia.", "Reales decretos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 25, "De acuerdo con el Código civil, con relación a las fuentes del derecho:", "La costumbre sólo regirá a falta de una ley aplicable, siempre que no sea contraria a la moral o al interés social y que resulte probada.", "La jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de manera reiterada, establezca el Tribunal Supremo al interpretar y aplicar la ley y la costumbre.", "Los principios generales del derecho se aplican a falta de ley, sin perjuicio de su carácter informador del ordenamiento jurídico.", "La jurisprudencia complementará el ordenamiento jurídico con la doctrina que, de manera reiterada, establezca el Tribunal Supremo al interpretar y aplicar la ley, la costumbre y los principios generales del derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 26, "Las materias que tienen que ser desarrolladas por medio de una ley orgánica se contienen en la Constitución en:", "El artículo 9.", "El artículo 82.", "El artículo 81.", "El artículo 84."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 27, "Los decretos ley son convalidados:", "Por el Congreso de los Diputados.", "Por el Senado.", "Por las Cortes Generales.", "Por el Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 28, "El plazo para convalidar uno decreto ley es de:", "Veinte días.", "Quince días.", "Un mes.", "Treinta días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 29, "Las disposiciones del Gobierno que contienen legislación delegada se denominan:", "Decretos leyes.", "Leyes de delegación.", "Decretos legislativos.", "Decretos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 30, "Una ley estatal que contiene los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas en una materia es:", "Una ley orgánica.", "Una ley de armonización.", "Una ley de bases.", "Una ley de delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 31, "En relación con el procedimiento de la elaboración de las leyes que se prevé en la Constitución:", "El rey sancionará en el plazo de quince días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará la publicación inmediata.", "El rey sancionará en el plazo de veinte días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará la publicación inmediata.", "El rey sancionará en el plazo de treinta días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará la publicación inmediata.", "El presidente del Gobierno, en nombre del rey, sancionará en el plazo de quince días las leyes aprobadas por las Cortes Generales, y las promulgará y ordenará la publicación inmediata."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 32, "En cuanto a la regulación dispuesta en la Constitución respeto de los decretos legislativos:", "La delegación legislativa tendrá que otorgarse por una ley ordinaria cuando el objeto sea la formación de textos articulados o por una ley de bases cuando se trate de refundir varios textos legales en uno sólo.", "Las Cortes Generales podrán delegar en el Gobierno la potestad de dictar normas con rango de ley, incluida la regulación de las posibles formas de colaboración financiera entre las comunidades autónomas y el Estado.", "La delegación legislativa tendrá que otorgarse en el Gobierno de forma expresa para una materia concreta y con fijación del plazo de ejercicio. La delegación se agota por el uso que haga el Gobierno mediante la publicación de la norma correspondiente.", "La delegación legislativa tendrá que otorgarse por una ley orgánica cuando el objeto sea la formación de textos articulados o por una ley de bases cuando se trate de refundir varios textos legales en uno sólo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 33, "Indicad la respuesta correcta:", "Las Cortes Generales, en materia de competencia estatal, podrán atribuir a todas o a alguna de las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, las bases y las directrices que fije una ley estatal.", "Las Cortes Generales, en materia de competencia estatal, podrán atribuir a todas o a alguna de las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, las bases y las directrices que fije una ley de bases.", "El Gobierno, en materia de competencia estatal, podrá atribuir a todas o a alguna de las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, las bases y las directrices que fije una ley estatal.", "El Congreso, en materia de competencia estatal, podrá atribuir a todas o a alguna de las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en el marco de los principios, las bases y las directrices que fije una ley estatal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 34, "Según lo que dispone la Constitución, las leyes de bases podrán:", "Autorizar la modificación de la ley de bases.", "Facultar para dictar normas con carácter retroactivo.", "Facultar para refundir varios textos legales en uno sólo.", "Facultar para la formación de textos articulados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 35, "Las resoluciones de los ministros se denominan:", "Resoluciones ministeriales.", "Órdenes ministeriales.", "Decretos ministeriales.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 36, "Señalad la respuesta incorrecta:", "La iniciativa legislativa la ejercerán los órganos de gobierno de las comunidades autónomas en los términos que establecen la Constitución y sus correspondientes estatutos de autonomía.", "El Gobierno de la Nación podrá aprobar reales decretos ley y reales decretos legislativos en los términos que prevé la Constitución.", "Los órganos de gobierno de las comunidades autónomas no podrán aprobar normas equivalentes a reales decretos leyes y reales decretos legislativos en su ámbito territorial.", "La iniciativa popular no procederá en materias propias de ley orgánica, tributarias o de caracter internacional, ni en lo relativo a la prerrogativa de gracia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 37, "Los reglamentos independientes se caracterizan para ser:", "Los que regulen materias sobre las cuales la Constitución ha previsto expresamente una reserva reglamentaria.", "Aquellos que regulen materias en que no se ha producido una regulación previa por ley y que no están protegidas por reserva material de ley.", "Los que regulen materias sobre las cuales la Constitución ha previsto expresamente una reserva reglamentaria, así como aquellos que regulen materias en que no se ha producido una regulación previa por ley y que no están protegidas por reserva material de ley.", "En España no pueden haber reglamentos independientes, dado que la Constitución no ha previsto expresamente una reserva reglamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 38, "Los reglamentos ejecutivos son los que:", "Regulan materias en las cuales no se ha producido una regulación previa por ley y que no están protegidas por reserva material de ley.", "Desarrollan y complementan una ley.", "Dicta la Administración para hacer frente a riesgos extraordinarios, suspendiendo la vigencia de las leyes a los que contradicen mientras dure la situación de emergencia.", "Los que regulan materias sobre las cuales la Constitución española ha previsto una reserva reglamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 39, "La autorización en el Gobierno de la Nación para dictar un texto refundido tiene que efectuarse a través:", "De una ley ordinaria.", "De un decreto legislativo.", "De una ley orgánica.", "De un decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 40, "Un decreto ley del Gobierno de la Nación no puede afectar:", "El sistema tributario.", "Los presupuestos generales del Estado.", "El régimen de derechos, deberes y libertades del título I de la Constitución española.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 41, "Para aplicar una costumbre a falta de un principio general del derecho:", "No puede atentar contra la moral.", "Tiene que ser probado.", "No puede ir en contra del orden público.", "Ninguna de las respuestas anteriores son correctas, porque se aplica siempre antes de que el principio general del derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 42, "De conformidad con la Constitución española, las administraciones públicas no actúan de acuerdo con el principio de:", "Coordinación.", "Jerarquía.", "Desconcentración.", "Delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 43, "Los reglamentos son disposiciones normativas:", "De carácter general.", "De rango inferior a la Ley.", "Que emanan del poder ejecutivo en virtud de su potestad reglamentaria.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 44, "Indicad cuál de las respuestas siguientes es la incorrecta con relación a los reglamentos:", "El control de las normas reglamentarias dictadas por la Administración de la Comunidad Autónoma de las Illes Balears corresponde a la jurisdicción contenciosa administrativa.", "La entrada en vigor de los reglamentos aprobados por el Gobierno de la Nación requiere la publicación íntegra en Boletín Oficial del Estado.", "De acuerdo con la Ley 1/2019, de 31 de enero, de Gobierno de las Illes Balears, en casos de urgencia y de forma excepcional, la entrada en vigor de determinados reglamentos aprobados por el Consejo de Gobierno requiere únicamente la publicación de un extracto en el Boletín Oficial de las Illes Balears.", "Los reglamentos dictados por las entidades locales se tienen que publicar en el boletín oficial que corresponda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 45, "Los reglamentos se pueden definir como:", "Cualquier disposición jurídica de carácter singular dictada por la Administración pública y subordinada a la ley.", "Cualquier disposición jurídica dictada por el Gobierno y la Administración en virtud de la delegación normativa efectuada a su favor por las Cortes Generales.", "Cualquier disposición jurídica de carácter general dictada por el Gobierno y la Administración pública, subordinada a la ley.", "Cualquier disposición administrativa dictada en el seno de un procedimiento, con efecto erga omnes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 46, "De acuerdo con la Ley 1/2019, de 31 de enero, de Gobierno de las Illes Balears, señalad el orden jerárquico correcto:", "Primero los decretos aprobados por el Consejo de Gobierno, y segundo las órdenes de los consejeros.", "Primero los decretos de los consejeros, y segundo las resoluciones de los consejeros.", "Primero los decretos aprobados por el Consejo de Gobierno o por el presidente, y segundo las órdenes de los consejeros.", "Ninguna de las respuestas anteriores es la correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 47, "Las normas se pueden ordenar jerárquicamente de la forma siguiente:", "Constitución, leyes y normas con rango de ley, reglamentos, principios generales del derecho y costumbres.", "Constitución, leyes y normas con rango de ley, reglamentos, costumbres y principios generales del derecho.", "Constitución, reglamentos, leyes y normas con rango de ley y costumbres.", "Constitución, leyes, reglamentos, normas con rango de ley y costumbres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 48, "Señalad cuál de las siguientes frases es la incorrecta:", "La supremacía formal implica que la Constitución no puede ser modificada ni derogada por ninguna otra norma.", "En cuanto a la norma, la Constitución disfruta de una posición de supremacía normativa en un doble plano, material y formal.", "La Constitución se sobrepone a los ciudadanos, a todos los poderes públicos y, por lo tanto, a todas las normas de cualquier naturaleza que de estos dimanen.", "La Constitución es un poder constituido, los otros poderes son meros poderes constituyentes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 49, "¿Qué artículo de la Constitución está dedicado a la irretroactividad de las disposiciones sancionadoras desfavorables o restrictivas de derechos individuales?", "El artículo 9.3.", "El artículo 9.2.", "El artículo 9.4.", "El artículo 10."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 50, "¿Cuántos componentes debe tener la delegación autonómica encargada de la defensa de una proposición de ley autonómica en el Congreso?", "Mínimo dos.", "Tres.", "Cuatro.", "Máximo tres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 51, "¿Cuál es el número de firmas necesario para el ejercicio de la iniciativa legislativa popular?", "No menos de 500.000 firmas acreditadas.", "500.000 firmas acreditadas.", "Más de 600.000 firmas acreditadas.", "600.000 firmas acreditadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 52, "¿En cuál de las siguientes materias es procedente la iniciativa legislativa popular?", "En materias tributarias.", "En materias de carácter internacional.", "En materias relativas a la prerrogativa de gracia.", "Ninguna de las materias anteriores pueden ser objeto de una iniciativa legislativa popular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 53, "¿Puede el Gobierno subdelegar la facultad de dictar legislación delegada?", "En ningún caso.", "Sí, siempre que lo autorice la ley de delegación.", "Sí, siempre que delegue en autoridades administrativas.", "No, salvo que delegue en órganos administrativos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 54, "Un estatuto de autonomía tiene que ser aprobado:", "Por ley ordinaria.", "Por ley orgánica.", "Por real decreto.", "Por decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 55, "Indicad la respuesta incorrecta relativa al reglamento de necesidad:", "El reglamento de necesidad implica la suspensión de la legalidad establecida.", "El reglamento de necesidad tiene carácter transitorio en el ordenamiento jurídico.", "El reglamento de necesidad sólo se puede dictar por razón de la concurrencia de circunstancias extraordinarias.", "El reglamento de necesidad tiene carácter de permanencia en el ordenamiento jurídico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 56, "¿Qué otro principio, además del de jerarquía normativa, debemos tener en cuenta para explicar la relación entre las diferentes fuentes del ordenamiento?", "Principio de cooperación.", "Principio de colaboración.", "Principio de coordinación.", "Principio de competencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 57, "No tiene que ser regulado por ley orgánica:", "El derecho de propiedad.", "El derecho de reunión.", "El régimen electoral general.", "El derecho de huelga."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 58, "Jerárquicamente, la ley orgánica:", "Es superior a la ley ordinaria.", "Tiene el mismo rango que la ley ordinaria.", "Tiene el mismo rango que la Constitución.", "Tiene rango inferior al decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 59, "¿Pueden las asambleas de las comunidades autónomas remitir a las Cortes Generales proposiciones de ley?", "No, en ningún caso.", "Sí, en el Congreso y en el Senado.", "Sí, pero sólo a la Mesa del Senado, que es la cámara de representación territorial.", "Sí, pero sólo a la Mesa del Congreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 60, "De acuerdo con la Constitución española, la apreciación de la necesidad de dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas corresponde:", "En el Congreso, por mayoría de tres quintas partes de sus miembros.", "Al Consejo de Ministros.", "En el Senado, en calidad de cámara de representación territorial.", "A las Cortes Generales, por mayoría absoluta de cada cámara."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 61, "¿Qué mayoría se necesita en el Senado para interponer un veto a una proposición de ley aprobada en el Congreso de los Diputados?", "Mayoría simple.", "Mayoría absoluta.", "Mayoría de dos tercios.", "El Senado no puede vetar materias aprobadas por el Congreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 62, "¿Qué otro nombre reciben los decretos legislativos?", "Legislación ejecutiva.", "Legislación delegada.", "Legislación delegando.", "Legislación secundaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 63, "¿De acuerdo con las clasificaciones doctrinales clásicas de los reglamentos, como se denomina el reglamento que se dicta sin una habilitación o una remisión específica de una ley?", "Reglamento ejecutivo.", "Reglamento independiente.", "Reglamento de necesidad.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 64, "¿Cuál de estas normas tiene un procedimiento especial de aprobación?", "Las leyes orgánicas.", "Las leyes armonizadoras.", "Los decretos ley.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 65, "¿Qué se entiende por inderogabilidad singular de los reglamentos?", "Que las resoluciones administrativas de carácter particular pueden vulnerar los reglamentos cuando procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Que las resoluciones administrativas de carácter particular pueden vulnerar los reglamentos únicamente cuando procedan del Gobierno en casos de extraordinaria y urgente necesidad.", "Que las resoluciones administrativas de carácter particular no pueden vulnerar las disposiciones reglamentarias aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Que la vulneración de una disposición de alcance general por una de carácter particular requiere el acuerdo del Consejo de Ministros o del Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 66, "La posibilidad del Gobierno de regularizar, aclarar y armonizar los textos legales es posible cuando dicte:", "Textos articulados.", "Textos refundidos.", "Reales decretos.", "Reglamentos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 67, "Indicad cuál de las materias siguientes no se regula por una ley orgánica:", "Las condiciones y el procedimiento de las diferentes modalidades de referéndum previstas en la Constitución.", "Las funciones, los principios básicos de actuación y los estatutos de las fuerzas y los cuerpos de seguridad.", "La composición y las competencias del Consejo de Estado.", "Los colegios profesionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 68, "El derecho administrativo:", "Es un derecho público.", "Es un derecho común.", "Es un derecho limitativo.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 69, "Al hablar de los límites formales de los reglamentos se puede afirmar:", "Que el reglamento sólo está sujeto a la Constitución y a las leyes orgánicas por el principio de jerarquía.", "Que las relaciones entre la ley y el reglamento son de competencia y no de jerarquía.", "Que el reglamento está jerárquicamente subordinado a la Constitución y a la ley, de acuerdo con el artículo 97 de la Constitución y el artículo 128 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas.", "Que no hay jerarquía normativa entre reglamentos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 70, "¿Los principios generales del derecho operan como límite material de los reglamentos?", "Sólo los principios que recoge el artículo 103 de la Constitución.", "Sí.", "No; los límites materiales de los reglamentos son la Constitución, los estatutos de autonomía y las normas con rango de ley.", "Sólo opera como límite el principio de no arbitrariedad de los poderes públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 71, "Un reglamento que vulnere otro reglamento de rango superior:", "Puede ser convalidado.", "Es anulable.", "Es nulo de pleno derecho.", "Es nulo de pleno derecho; no obstante, el plazo para declarar la nulidad o impugnarlo es de un año, de acuerdo con lo que prevé la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 72, "¿Qué tienen que hacer los jueces y los magistrados ante un reglamento ilegal?", "Aplicarlo hasta que el Tribunal Constitucional declare la nulidad.", "No aplicarlo, atendida la obligación que establece la Ley orgánica del poder judicial de no aplicar los reglamentos o cualquier otra disposición contraria a la Constitución, a la ley o al principio de jerarquía normativa.", "Puede no aplicarlo, debido a la independencia del poder judicial.", "No aplicarlo siempre que lo haya alegado la parte recurrente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 73, "¿Qué tiene que hacer un funcionario ante un reglamento ilegal?", "Aplicarlo hasta que el Tribunal Constitucional declare la nulidad.", "No aplicarlo, dado que los funcionarios están sujetos a la Constitución y a la ley.", "Aplicarlo si así lo impone una instrucción o una orden de servicio.", "Las respondidas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 74, "Ante un reglamento ilegal, la Administración puede:", "Convalidarlo, reparando los vicios que presente.", "Revisarlo de oficio, con un dictamen previo del Consejo Consultivo.", "Revisarlo de oficio, con audiencia previa e información pública.", "Revocarlo, siempre que sean normas desfavorables."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 8, 75, "Las disposiciones reglamentarias deben estar encabezadas:", "Con una exposición de motivos, que exprese la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta.", "Con un preámbulo, que exprese la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta.", "Con una exposición motivada, que exprese la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta.", "Con unos antecedentes, que expresen la finalidad de las medidas adoptadas en la regulación y el marco normativo en que se inserta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 1, "De acuerdo con el artículo 135 del Estatuto de Autonomía de las Islas Baleares, el presupuesto general de la Comunidad Autónoma de las Islas Baleares:", "Tiene carácter anual, es complejo y diverso y constituye la expresión cifrada, individualizada y sistemática de todos los gastos de las instituciones que constituyen el sector público.", "Tiene carácter anual, es único y constituye la expresión cifrada, conjunta y sistemática de todos los gastos y de todos los ingresos de las instituciones, organismos, entidades y empresas que constituyen el sector público autonómico.", "Tiene carácter anual, es único y constituye la expresión cifrada, conjunta y sistemática de todos los ingresos de las instituciones y empresas que constituyen el sector público autonómico.", "Tiene carácter anual, es diverso y constituye la expresión cifrada, conjunta y sistemática de todos los gastos de las instituciones, organismos, entidades y empresas que constituyen el sector público autonómico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 2, "A efectos de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, se entiende por actividad económico-financiera:", "El conjunto de actuaciones dirigidas a la liquidación y obtención de derechos e ingresos y a la realización de gastos y pagos para cumplir las funciones o finalidades propias de la Comunidad Autónoma.", "El conjunto de actuaciones dirigidas a la liquidación de derechos y a la realización de gastos y pagos para cumplir la finalidad del plan presupuestario anual.", "El conjunto de actuaciones dirigidas a restablecer derechos y a realizar gastos y pagos para cumplir las funciones o finalidades propias de la Comunidad Autónoma.", "El conjunto de actuaciones dirigidas a liquidar y a obtener gastos y a realizar ingresos y pagos para cumplir las funciones o finalidades propias del principio de estabilidad presupuestaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 3, "En la clasificación económica de gastos, se agrupan los créditos según la naturaleza económica de los gastos, que deben separarse en:", "Operaciones corrientes, operaciones de capital, operaciones financieras y fondo de contingencia.", "Operaciones de capital, operaciones financieras y fondo de contingencia.", "Operaciones de gastos corrientes y operaciones financieras.", "Operaciones corrientes, operaciones de capital y fondo de contingencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 4, "Señale la respuesta incorrecta. A efectos de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, forman parte del sector público de la Comunidad Autónoma de las Illes Balears los siguientes órganos y entidades:", "La Administración de la Comunidad Autónoma de las Illes Balears.", "La Agencia Tributaria de las Islas Baleares.", "Los organismos autónomos no dependientes de la Administración de la Comunidad Autónoma de las Illes Balears.", "El Servicio de Salud de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 5, "De acuerdo con el artículo 4 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad autónoma de las Illes Balears, los gastos públicos, incluidos en los presupuestos generales de la Comunidad Autónoma:", "Procurarán una asignación equitativa de los recursos públicos.", "Procurarán una asignación especial de los recursos públicos.", "Procurarán una asignación económica de los recursos públicos.", "Procurarán una asignación proporcional de los recursos públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 6, "De acuerdo con el artículo 4 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad autónoma de las Illes Balears, se entiende por equilibrio patrimonial:", "La inexistencia de un patrimonio neto negativo, de acuerdo con las normas de contabilidad aplicables a cada entidad.", "La existencia de un patrimonio neto negativo, de acuerdo a las normas de contabilidad aplicables a cada entidad.", "La inexistencia de un patrimonio neto positivo, de acuerdo con las normas de contabilidad aplicables a cada entidad.", "La existencia de un patrimonio neto positivo, de acuerdo con las normas de contabilidad aplicables a cada entidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 7, "La vinculación de crédito está relacionada con el principio:", "De especialidad cualitativa", "De especialidad cuantitativa.", "De especialidad temporal.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 8, "De acuerdo con el artículo 5 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, la Comunidad Autónoma de las Illes Balears está sometida a los siguientes principios presupuestarios:", "Estabilidad presupuestaria y sensibilidad financiera.", "Transparencia, prudencia y unidad de caja de la hacienda pública.", "Afectación de los ingresos y presupuesto neto.", "Presupuesto mensual en equilibrio, contabilidad privada y control externo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 9, "Señale la respuesta incorrecta. El principio de presupuesto en equilibrio regulado en la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Islas Baleares supone que:", "El importe total del presupuesto inicial de gastos no puede superar en ningún caso el importe de las previsiones de ingresos.", "El presupuesto debe estar equilibrado desde el punto de vista de los objetivos anuales de estabilidad presupuestaria.", "Es un principio regulado en el artículo 5 de la Ley 14/2014, de 29 de diciembre, de finanzas de la comunidad autónoma de las Illes Balears.", "El importe total del presupuesto inicial de gastos puede superar el importe de las previsiones de ingresos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 10, "Los presupuestos de la Comunidad Autónoma de las Islas Baleares se regulan:", "Por reglamento.", "Por proposición de ley.", "Por decreto.", "Por ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 11, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, deben regularse por ley:", "La creación y la regulación de instituciones de crédito propias de la Comunidad Autónoma.", "El establecimiento, la modificación y la supresión de recargos sobre los tributos estatales.", "La regulación del régimen general y especial en materia económico-financiera de las entidades del sector público instrumental de la Comunidad Autónoma.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 12, "De acuerdo con el artículo 7 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, corresponde al Consejo de Gobierno:", "Aprobar los proyectos de leyes de créditos extraordinarios y de suplementos de crédito y remitirlos al Parlamento de las Illes Balears cuando corresponda.", "Prestar o denegar su conformidad a la tramitación de las proposiciones de ley que supongan incremento de los gastos o disminución de los ingresos.", "Aprobar, en su caso, los planes de reequilibrio, económico-financieros o de ajuste que garanticen el cumplimiento de los objetivos de estabilidad presupuestaria, de equilibrio patrimonial y de deuda pública, de acuerdo con la presente ley y con la normativa básica estatal.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 13, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Islas Baleares, ¿a quién corresponde aprobar el proyecto de ley de presupuestos generales de la Comunidad Autónoma?", "Corresponde al Parlamento.", "Corresponde al Consejo de Gobierno.", "Corresponde al consejero competente en materia de hacienda y presupuestos.", "No existe ninguna respuesta correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 14, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Islas Baleares, corresponde al consejero competente en materia de hacienda y presupuestos:", "Acordar el límite máximo de gasto no financiero, coherente con el objetivo de estabilidad presupuestaria y la regla de gasto, y someter el acuerdo correspondiente a la deliberación del Parlamento de las Islas Baleares.", "Aprobar el proyecto de ley de presupuestos generales de la Comunidad Autónoma de cada año y remitirlo al Parlamento de las Illes Balears.", "El establecimiento, modificación y supresión de recargos sobre los tributos estatales.", "Proponer al Consejo de Gobierno el límite máximo del gasto no financiero."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 15, "Señale la respuesta incorrecta. De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, son funciones de los organismos autónomos y del resto de entidades instrumentales del sector público administrativo de la comunidad autónoma:", "Autorizar y disponer los gastos que no sean de la competencia del Consejo de Gobierno, y, mediante la consejería de adscripción, elevarle los que lo sean.", "Gestionar los créditos para gastos correspondientes a sus secciones presupuestarias o presupuesto propio, y proponer o acordar sus modificaciones, según corresponda, de acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears y las leyes de presupuestos generales de la Comunidad Autónoma.", "Reconocer obligaciones económicas sin ordenar en ningún caso su pago.", "Preparar el anteproyecto de presupuesto anual de la sección presupuestaria o del presupuesto propio correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 16, "Señale la respuesta incorrecta. De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Islas Baleares, son recursos de la hacienda pública de la Comunidad Autónoma:", "Las participaciones en ingresos del Estado, mediante los fondos y demás mecanismos que establezca la legislación estatal.", "Las transferencias que procedan de los fondos regulados en la legislación estatal de financiación de las comunidades autónomas.", "Los precios públicos.", "Los recargos sobre los tributos municipales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 17, "De acuerdo con el artículo 33 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Islas Baleares, el plan presupuestario a medio plazo:", "Debe incluir un período mínimo de tres años.", "Debe contener los objetivos de estabilidad presupuestaria y de deuda pública, y la regla del gasto.", "Debe contener una evaluación de cómo las medidas previstas pueden afectar a la sostenibilidad de las finanzas públicas a largo plazo.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 18, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, el Consejo de Gobierno debe aprobar el límite máximo de gasto no financiero, que debe tenerse en cuenta también en la elaboración de los presupuestos generales de la Comunidad Autónoma para el ejercicio siguiente:", "Antes de día 1 de agosto de cada año.", "Antes del día 31 de julio de cada año.", "Antes del día 1 de julio de cada año.", "Antes del día 31 de agosto de cada año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 19, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Islas Baleares, integran los presupuestos generales de la Comunidad Autónoma:", "Los presupuestos del Servicio de Salud de las Islas Baleares.", "El presupuesto de la Universidad de las Islas Baleares.", "Los presupuestos de las entidades que integran el sector público fundacional.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 20, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, los presupuestos generales de la Comunidad Autónoma deben contener:", "Los estados de gastos de los entes del sector público administrativo con la correspondiente especificación de los créditos necesarios para atender el cumplimiento de las obligaciones.", "Los estados de ingresos de los entes del sector público administrativo, que deben comprender las estimaciones de los diversos derechos económicos que deben reconocerse o liquidarse durante el ejercicio y la previsión de endeudamiento.", "Los presupuestos de explotación y de capital de los entes del sector público empresarial y fundacional, con las previsiones correspondientes de los gastos y de los ingresos y variaciones de activos y pasivos del ejercicio.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 21, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, los créditos contenidos en los estados de gastos deben estructurarse de acuerdo con las siguientes clasificaciones:", "La clasificación orgánica, la clasificación financiera, la clasificación económica y en lo que se refiere al capítulo de gastos en inversiones reales, se incluirá una clasificación territorial por ámbitos insulares y, en su caso, por municipios.", "La clasificación orgánica, clasificación financiera y clasificación económica.", "La clasificación orgánica, la clasificación funcional, la clasificación económica y con respecto al capítulo de gastos en inversiones reales, debe incluirse una clasificación territorial por ámbitos insulares y, en su caso, por municipios.", "La clasificación orgánica, la clasificación funcional y en lo que se refiere al capítulo de gastos en inversiones reales, se incluirá una clasificación territorial por ámbitos insulares y, en su caso, por municipios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 22, "El plan presupuestario a medio plazo:", "Se revisará al menos cada tres años.", "Se revisará cada año.", "Se revisará cada tres años, pero se revisará de forma anual si la previsión de ingresos no se adecua a la provisión de gastos.", "Se revisará en cualquier momento a fin de adecuar los gastos previstos a los ingresos generados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 23, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, en la clasificación económica, que agrupa los créditos según la naturaleza económica de los gastos, éstos deben separarse en :", "Operaciones corrientes, operaciones de capital, operaciones financieras y fondo de contingencia.", "Operaciones financieras y fondo de contingencia.", "Operaciones de capital y operaciones corrientes.", "Operaciones corrientes y de capital."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 24, "La ley de presupuestos generales de cada ejercicio debe determinar la cuantía de la dotación anual correspondiente al fondo de contingencia:", "Con un mínimo del 1% y un máximo del 2% de los estados de gastos no financieros del presupuesto inicial consolidado de la Administración de la Comunidad Autónoma y de las entidades integrantes del sector público administrativo.", "Con un mínimo del 0,5% y un máximo del 2% de los estados de gastos no financieros del presupuesto inicial consolidado de la Administración de la Comunidad Autónoma y de las entidades integrantes del sector público administrativo.", "Con un mínimo del 0,5% y un máximo del 1% de los estados de gastos no financieros del presupuesto inicial consolidado de la Administración de la Comunidad Autónoma y de las entidades integrantes del sector público administrativo.", "Con un mínimo del 0,5% y un máximo del 2% de los estados de gastos financieros del presupuesto inicial consolidado de la Administración de la Comunidad Autónoma y de las entidades integrantes del sector público administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 25, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, el fondo de contingencia debe destinarse, cuando sea procedente, a atender:", "Necesidades aplazables.", "Necesidades de carácter discrecional.", "Necesidades no previstas en los presupuestos generales aprobados inicialmente.", "Necesidades que pueden presentarse únicamente a principios del ejercicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 26, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, las previsiones contenidas en los estados de ingresos se estructuran de acuerdo con las siguientes clasificaciones:", "La clasificación orgánica y la clasificación funcional.", "La clasificación orgánica y la clasificación económica.", "La clasificación funcional y clasificación económica.", "La clasificación funcional y la clasificación territorial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 27, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, las previsiones correspondientes a las actividades económico-financieras de cada una de las entidades del sector público empresarial y fundacional deben reflejarse en un presupuesto, cuya estructura debe determinar el consejero competente en materia de hacienda y presupuestos. Este presupuesto, como mínimo, debe contener:", "Un presupuesto de explotación, que incluirá las previsiones de los gastos y de los ingresos imputables a la cuenta de pérdidas y ganancias del ejercicio.", "Un presupuesto de capital, que incluirá las previsiones en las variaciones de los activos y pasivos, financieros y no financieros, imputables al balance de situación del ejercicio.", "Un presupuesto de explotación, que incluirá las previsiones de los gastos y de los ingresos imputables a la cuenta de pérdidas y ganancias del ejercicio siguiente.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 28, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, tienen el carácter de gastos con financiación afectada los que se financien, en todo o en parte, mediante unos recursos concretos en los cuales deben concurrir las siguientes condiciones:", "La obligación de destinar los recursos a unas finalidades concretas que implican gasto; la pérdida del derecho al cobro efectivo de los recursos, en todo o en parte, en caso de que no se realice el gasto correspondiente y la obligación de reintegro de los recursos ya obtenidos previamente, en todo o en parte, en caso de que no se realice gasto correspondiente.", "La obligación de destinar los recursos a unas finalidades concretas que impliquen ingresos; la pérdida del derecho al reintegro efectivo de los recursos, en todo o en parte, en caso de que no se realice el gasto correspondiente, y la obligación de gasto de los recursos ya obtenidos previamente, en todo o en parte.", "La obligación de destinar los recursos a unas finalidades concretas que impliquen gasto; la pérdida del derecho al cobro efectivo de los recursos, en todo o en parte, en caso de que no se realice el gasto correspondiente, y la obligación de reintegro de los recursos obtenidos con posterioridad.", "La obligación de destinar los recursos a unas finalidades indeterminadas que impliquen gasto; la pérdida del derecho al cobro efectivo de los recursos en parte y la obligación de reintegro de los recursos ya obtenidos previamente, siempre que se realice el gasto correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 29, "De acuerdo con el artículo 44 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Islas Baleares:", "El consejero competente en materia de hacienda y presupuestos elaborará el anteproyecto de ley de presupuestos generales de la Comunidad Autónoma y lo someterá al acuerdo del Consejo de Gobierno.", "La consejería competente en materia de hacienda y presupuestos elaborará el anteproyecto de ley de presupuestos generales de la comunidad autónoma y lo someterá al acuerdo del Consejo de Gobierno.", "La consejería competente en materia de hacienda y presupuestos elaborará el anteproyecto de ley de presupuestos generales de la comunidad autónoma y lo someterá al acuerdo del Parlamento.", "El director general competente en materia de hacienda y presupuestos elaborará el anteproyecto de ley de presupuestos generales de la comunidad autónoma y lo someterá al acuerdo de la consejería competente en materia de hacienda y presupuestos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 30, "Se adjuntará al anteproyecto de ley de presupuestos generales de la Comunidad Autónoma, únicamente, la siguiente documentación:", "Una estimación del importe de los beneficios fiscales que afecten a los tributos estatales cedidos y a los impuestos propios detallado por figuras tributarias.", "Una memoria explicativa del contenido y las principales modificaciones que presente el anteproyecto, comparado con el presupuesto vigente.", "Un avance del estado de ejecución de los presupuestos del año en curso.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 31, "El proyecto de ley de presupuestos generales de la Comunidad Autónoma, con la documentación complementaria oportuna, se remitirá al Parlamento de las Illes Balears:", "El día 1 de noviembre de cada año.", "Antes del día 1 de noviembre de cada año.", "El día 30 de noviembre de cada año.", "Antes del día 1 de diciembre de cada año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 32, "Si la ley de presupuestos generales de la Comunidad Autónoma no entra en vigor el día 1 de enero del ejercicio en que deba ser efectiva, se considerarán automáticamente prorrogados los presupuestos iniciales del ejercicio anterior, hasta que entre en vigor la nueva ley de presupuestos generales, con las siguientes particularidades:", "Se podrán prorrogar los créditos definitivos con financiación afectada a lo largo del ejercicio anterior que tengan que mantener ese carácter en el ejercicio corriente.", "Se podrán prorrogar los créditos para los gastos correspondientes a programas o actuaciones que acaben en el ejercicio anterior o por obligaciones que deban extinguirse en el ejercicio corriente.", "Los nuevos presupuestos generales que entren en vigor producen efectos desde el 1 de enero.", "La estructura orgánica de los presupuestos prorrogados no debe adaptarse a la organización administrativa en vigor en el ejercicio en que el presupuesto debe ejecutarse."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 33, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, a todos los efectos, los créditos presupuestarios se rigen:", "Por el principio de calidad, en las vertientes cuantitativa, especial y temporal de este principio.", "Por el principio de especialidad, en las vertientes cualitativa, cuantitativa y temporal de este principio.", "Por el principio de temporalidad, en las vertientes cualitativa, cuantitativa y especial de este principio.", "Por el principio de especificidad, en las vertientes cualitativa y cuantitativa de este principio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 34, "De acuerdo con el artículo 50 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Islas Baleares, los niveles de vinculación de los créditos de las entidades que integran el sector público administrativo son:", "Los niveles que para cada año establezca la ley de presupuestos generales de la Comunidad Autónoma.", "Los niveles que para cada año establezca una orden del consejero competente en materia de hacienda y presupuestos.", "Los niveles que para cada año establezca un decreto del consejo de gobierno.", "Los niveles que para cada año establezca una resolución del director general competente en materia de hacienda y presupuestos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 35, "De acuerdo con el artículo 51 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, deben aplicarse a los créditos del presupuesto vigente en el momento del reconocimiento presupuestario de la obligación los siguientes gastos:", "Los que resulten de la liquidación de atrasos a favor del personal al servicio del sector público de la comunidad autónoma.", "Los devengados en ejercicios anteriores que venzan en el ejercicio en curso.", "Los devengados y vencidos en ejercicios anteriores, cuando se hayan contabilizado en el cierre del ejercicio anterior en la cuenta Acreedores por operaciones devengadas y se imputen al presupuesto corriente antes del último día del mes de febrero.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 36, "De acuerdo con el artículo 109 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, la Intervención General de la Comunidad Autónoma:", "Se adscribe a la consejería competente en materia de hacienda y presupuestos, sin perjuicio de su plena autonomía funcional respecto de los órganos y entidades sujetas a su control.", "Se adscribe a la consejería competente en materia de tesorería, con autonomía funcional parcial respecto de los órganos y entidades sujetas a su control.", "Se adscribe a la consejería competente en materia de hacienda y presupuestos, sin perjuicio de su limitada autonomía respecto de los órganos y entidades sujetas a su control.", "Se adscribe a la consejería competente en materia de tesorería, sin perjuicio de su plena autonomía funcional respecto de los órganos sujetos a su control."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 37, "Señale la respuesta correcta. La estructura y las funciones de la Intervención General:", "Se desarrollarán mediante decreto del Consejo de Gobierno, a propuesta del consejero competente en materia de hacienda y presupuestos, y previo informe del interventor general.", "Se desarrollarán mediante orden del consejero competente en materia de hacienda y presupuestos, y previo informe del interventor general.", "Se desarrollarán mediante decreto del Consejo de Gobierno, a propuesta del director general competente en materia de hacienda y presupuestos, y previo informe del interventor general.", "Se desarrollarán mediante Acuerdo del Consejo de Gobierno, a propuesta del consejero competente en materia de hacienda y presupuestos, y previo informe de la Sindicatura de Cuentas de la Comunidad Autónoma de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 38, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, son objetivos del control interno de la gestión económico-financiera:", "Verificar el cumplimiento de la normativa aplicable en la gestión objeto del control.", "Verificar el registro y la contabilización adecuados de las operaciones.", "Verificar el cumplimiento de los objetivos asignados a los centros gestores de gasto, de acuerdo con los presupuestos generales de la Comunidad Autónoma.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 39, "La función interventora en el ejercicio de control interno de la gestión económico-financiera del sector público de la Comunidad Autónoma de las Illes Balears es aplicable:", "A la Administración de la Comunidad Autónoma y a las entidades instrumentales que integran el sector público administrativo.", "A la Universidad de las Islas Baleares.", "A los consorcios.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 40, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, el control financiero debe ejercerse, principalmente:", "Mediante técnicas de auditoría.", "Mediante control previo permanente.", "Mediante muestreo.", "Mediante control aleatorio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 41, "La Intervención General de la Comunidad Autónoma de las Illes Balears, en el ejercicio de las funciones de control interno, se somete:", "A los principios de autonomía funcional e independencia jerárquica.", "A los principios de independencia jerárquica y procedimiento contradictorio.", "A los principios de procedimiento contradictorio y dependencia funcional.", "A los principios de autonomía funcional, jerarquía interna y procedimiento contradictorio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 42, "El principio de autonomía plena en el ejercicio del control interno implica:", "Que los funcionarios que lo lleven a cabo tienen independencia funcional respecto de los titulares de los órganos y entidades cuya gestión controlen.", "Que los funcionarios deben ajustar sus actuaciones a las instrucciones que a tal fin dicten los órganos competentes de la Intervención General.", "Que los funcionarios deben ajustar sus actuaciones a las instrucciones que a tal fin dicte la Sindicatura de cuentas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 43, "De acuerdo con el artículo 113 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, corresponde a la Intervención General de la Comunidad Autónoma, como centro director del control interno:", "Establecer, mediante instrucciones, las pautas o los criterios de actuación por los que deben regirse los órganos y unidades administrativas jerárquicamente dependientes, y, en su caso, las unidades de gestión económica y demás unidades que las tengan que cumplir por razón de las tareas que desarrollan.", "Promover el ejercicio de la potestad reglamentaria en materia de control interno.", "Definir los procedimientos de carácter económico-financiero en lo que afecte al ejercicio de sus competencias en materia de control interno y determinar los requerimientos funcionales y los procedimientos informáticos de los sistemas de información en materia de control interno.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 44, "Señale la respuesta incorrecta. La función interventora tiene por objetivo:", "Controlar, antes de su aprobación, todos los actos que puedan dar lugar al reconocimiento de derechos u obligaciones de contenido económico, así como los cobros y pagos que se deriven.", "Controlar, antes de su aprobación, la inversión y aplicación en general de los fondos públicos y las modificaciones presupuestarias, para asegurar que estos actos se ajustan a las disposiciones aplicables en cada caso.", "La fiscalización previa de los actos que den lugar al reconocimiento de los derechos y la de los cobros deben sustituirse por las comprobaciones inherentes a la anotación contable de estas operaciones y por el control financiero.", "Controlar, antes de su aprobación, todos los actos que puedan dar lugar a responsabilidades en materia de contabilidad pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 45, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Islas Baleares, el ejercicio de la función interventora comprende:", "La fiscalización previa de los expedientes de modificación de crédito, con el alcance que se determine reglamentariamente.", "La intervención material de los pagos que no hayan sido ordenados y tramitados por procedimientos automáticos.", "La fiscalización previa de todos los actos, documentos o expedientes susceptibles de producir obligaciones de contenido económico, únicamente en las fases de disposición o compromiso del gasto, y reconocimiento de la obligación y propuesta de pago.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 46, "Señale la respuesta incorrecta. El Consejo de Gobierno, a propuesta del consejero competente en materia de hacienda y presupuestos y previo informe de la Intervención General, puede limitar la fiscalización previa a comprobar los siguientes requisitos básicos:", "La existencia de crédito presupuestario adecuado a la naturaleza del gasto, y suficiente, o la adecuada imputación contable en caso de operaciones no presupuestarias.", "El cumplimiento de las normas sobre igualdad aplicables a los expedientes de gasto correspondientes.", "La competencia del órgano que genera el gasto o la obligación.", "El cumplimiento de las normas aplicables a los expedientes relativos a gastos de carácter plurianual y a gastos estructurales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 47, "De acuerdo con el artículo 118 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, en caso de que el órgano interventor formule objeciones que afecten a la autorización o la disposición de gastos, el reconocimiento de obligaciones o la ordenación de pagos, se suspenderá la tramitación del expediente, hasta que se subsane o resuelva la objeción, en los siguientes casos:", "Cuando la objeción se refiera a expedientes de gastos pluriannuales.", "Cuando la objeción se refiera a la suficiencia de adecuación del crédito.", "Cuando la objeción se refiera a la falta de requisitos o trámites esenciales en el expediente, o cuando se aprecie la posibilidad de pérdidas económicas graves si el expediente sigue su curso.", "Cuando la objeción se derive de irregularidades subsanables en la documentación justificativa de las órdenes de pago o cuando el derecho del perceptor quede suficientemente justificado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 48, "Señale la respuesta incorrecta respecto del procedimiento para resolver objeciones:", "En los casos en que la objeción haya sido formulada por una intervención delegada o adjunta, corresponde al Interventor General conocer la discrepancia, siendo la resolución que dicte de obligado cumplimiento para aquella intervención.", "Cuando la objeción emane del interventor general o él mismo haya confirmado la formulada por una intervención delegada o adjunta, y subsista la discrepancia, corresponde al consejero competente en materia de hacienda y presupuestos adoptar la resolución definitiva.", "Cuando la objeción emane del interventor general o él mismo haya confirmado la formulada por una intervención delegada o adjunta, y subsista la discrepancia, corresponde al Consejo de Gobierno adoptar la resolución definitiva.", "Los informes de la Intervención y, especialmente, las objeciones y discrepancias que se hayan producido durante la tramitación de los expedientes deben adjuntarse siempre a estos expedientes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 49, "De acuerdo con el artículo 121 de la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, la Intervención General de la Comunidad Autónoma ejerce el control financiero, el cual se extiende a la comprobación de los siguientes aspectos:", "La inadecuación al ordenamiento jurídico de la actuación de cada uno de los órganos y entidades sometidos a esta modalidad de control.", "El registro de algunas operaciones que lleva a cabo cada órgano o entidad, y el reflejo aproximado en las cuentas y estados que, de acuerdo con las disposiciones aplicables, estos órganos y entidades deban formar.", "La constatación de que los procedimientos aplicados garantizan en todo caso que las operaciones se desarrollan de acuerdo con la normativa aplicable.", "La verificación de la buena gestión financiera, según los principios de economía, eficacia y eficiencia, así como la verificación del nivel de resultados obtenidos con relación a los medios utilizados y a los efectos producidos, de acuerdo con los indicadores que se establezcan al efecto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 50, "De acuerdo con la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears, corresponde a la Intervención General de la Comunidad Autónoma de las Illes Balears:", "Coordinar cualquier trabajo de auditoría, efectuado con medios propios o ajenos, que se realice en cumplimiento de las previsiones de control contenidas en la Ley 14/2014, de 29 de diciembre, de finanzas.", "Dirigir cualquier trabajo de auditoría, efectuado con medios propios o ajenos, que se realice en cumplimiento de las previsiones de control contenidas en la Ley 14/2014, de 29 de diciembre, de finanzas.", "Controlar cualquier trabajo de auditoría, efectuado con medios propios o ajenos, que se realice en cumplimiento de las previsiones de control contenidas en la Ley 14/2014, de 29 de diciembre, de finanzas.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 51, "A efectos del Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, tiene la consideración de subvención cualquier disposición dineraria llevada a cabo por las entidades del sector público a favor de personas públicas o privadas, que cumpla los siguientes requisitos:", "Que se lleve a cabo sin contraprestación directa de los beneficiarios.", "Que se sujete al cumplimiento de un determinado objetivo, la ejecución de un proyecto, la realización de una actividad, la adopción de un comportamiento singular, ya realizados o por realizar, o la concurrencia de una situación, con el deber del beneficiario de cumplir las obligaciones materiales y formales establecidas.", "Que el proyecto, acción, conducta o situación financiada tenga por objeto el fomento de una actividad de utilidad pública o de interés social o de promoción de una finalidad pública.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 52, "Señale la respuesta incorrecta. De acuerdo con la normativa estatal y autonómica de subvenciones, no tienen la consideración de subvención, y deben regirse por la normativa específica que les sea aplicable, los siguientes supuestos:", "Las aportaciones dinerarias a favor de entidades autónomas, empresas públicas, consorcios sometidos al ordenamiento autonómico y fundaciones del sector público autonómico destinadas a financiar la actividad de estos entes en el ámbito de sus funciones.", "Las prestaciones reconocidas por el Fondo de Garantía Social .", "Las prestaciones contributivas y no contributivas del sistema de la Seguridad Social.", "Las prestaciones a favor de los afectados por el síndrome tóxico y las ayudas sociales a las personas con hemofilia u otras coagulopatías congénitas que hayan desarrollado la hepatitis C que regula la Ley 14/2002, de 5 de junio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 53, "Señale la respuesta incorrecta. Están excluidas del ámbito material del Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la ley de subvenciones:", "Las ayudas que consistan en la cesión de bienes o derechos o en la prestación de servicios, cuya adquisición o contratación se haya realizado con la finalidad exclusiva de entregarlos o prestarlos a terceras personas.", "Las ayudas inherentes a la financiación de determinados proyectos de actuación en el marco de los planes anuales del turismo sostenible a que se refiere la Ley 2/2016, de 30 de marzo, del impuesto sobre estancias turísticas en las Illes Balears y de medidas de impulso del turismo sostenible.", "Los premios que se otorguen sin la previa solicitud del beneficiario.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 54, "De acuerdo con el Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la ley de subvenciones, no deben aplicarse los principios de publicidad y concurrencia:", "Cuando la concesión o la cuantía de las subvenciones esté impuesta por una disposición normativa.", "Cuando las subvenciones tengan asignación nominativa en los presupuestos del ente público que las concede.", "En general, cuando por las características del beneficiario o de la actividad subvencionada no sea posible promover su concurrencia pública, así como cuando se acrediten razones de interés público, social, económico y humanitario, o cualquier otra razón debidamente justificada que dificulte esta concurrencia.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 55, "En las entidades de derecho público dependientes, quiénes son los órganos competentes para la concesión de subvenciones:", "En las entidades de derecho público dependientes, los órganos de dirección de estas entidades, de acuerdo con lo que prevé su normativa reguladora, previa autorización del órgano colegiado superior de la entidad en los casos de las subvenciones en las que excepcionalmente no sea posible promover la concurrencia pública de acuerdo con lo establecido en el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones.", "En las entidades de derecho público dependientes, los órganos de dirección de estas entidades, de acuerdo con lo que prevé su normativa reguladora, previa autorización del Consejo de Gobierno en el caso de las subvenciones en las que excepcionalmente no sea posible promover la concurrencia pública de acuerdo con lo establecido en el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones.", "En las entidades de derecho público dependientes, los órganos de dirección de estas entidades o el órgano que determinen las bases reguladoras, previa autorización del Consejo de Gobierno en el caso de las subvenciones en las que excepcionalmente no se puedan aplicar los principios de publicidad y concurrencia por las características especiales del beneficiario, o de la actividad subvencionada, no sea posible, objetivamente, promover su concurrencia pública, así como cuando se acrediten razones de interés público, social, económico o humanitario, o cualquiera otra razón debidamente justificada que dificulte esta concurrencia.", "En las entidades de derecho público dependientes, los órganos de dirección de estas entidades o el órgano que determinen las bases reguladoras, previa autorización del órgano colegiado superior de la entidad en el caso de las subvenciones en las que excepcionalmente no se puedan aplicar los principios de publicidad y concurrencia de acuerdo con lo establecido en el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 56, "¿Qué lleva implícito el acto de concesión de una subvención?", "La disposición del gasto correspondiente.", "El reconocimiento de la obligación correspondiente.", "El pago de la cuantía concedida.", "La aprobación del gasto correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 57, "De acuerdo con el artículo 9 del Decreto Legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la ley de subvenciones, pueden tener la consideración de beneficiarios:", "El destinatario de los fondos públicos que debe llevar a cabo la actividad que fundamenta su otorgamiento, o que está en la situación que legitima su concesión.", "En cualquier caso, las agrupaciones de personas físicas o jurídicas, públicas o privadas, las comunidades de bienes o cualquier otro tipo de unidad económica o patrimonio separado que, a pesar de no tener personalidad jurídica, puedan llevar a cabo los proyectos, actividades o los comportamientos o se encuentren en la situación que motiva la concesión de la subvención.", "En todo caso, las personas que formen parte de la misma como miembros de una persona jurídica que resulte beneficiaria y que se comprometan a llevar a cabo la totalidad o parte de las actividades que fundamentan la concesión de la subvención en nombre y por cuenta de esta.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 58, "No pueden ser beneficiarias de subvenciones las personas o entidades en las que concurran alguna de las siguientes circunstancias, salvo que por la naturaleza de la subvención lo exceptúe la normativa reguladora:", "Haber dado lugar a la resolución de cualquier contrato suscrito con la Administración.", "Tener la residencia fiscal en un país o territorio extranjero.", "No estar al corriente de pago de obligaciones por reintegro de subvenciones en los términos que se determinen por una ley.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 59, "De acuerdo con el artículo 11 del Decreto legislativo 2/2005, de 29 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, son obligaciones de los beneficiarios:", "Llevar a cabo la actividad o la inversión o adoptar el comportamiento que fundamenta la concesión de la subvención.", "Comunicar al órgano que concede la subvención o, en su caso, a la entidad colaboradora, la solicitud o la obtención de otras subvenciones para la misma finalidad. Esta comunicación debe realizarse dentro del plazo de diez días hábiles desde la solicitud o la obtención de la subvención concurrente y, en todo caso, antes de la justificación de la aplicación que se haya dado a los fondos percibidos .", "Acreditar, en la forma que se establezca reglamentariamente y antes de dictar la resolución de concesión, que se encuentra al corriente de las obligaciones tributarias y de la Seguridad Social ante la Administración del Estado, y de las obligaciones tributarias ante la hacienda autonómica .", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 60, "Señale la respuesta incorrecta. ¿Cuáles son los aspectos que deben contener las bases reguladoras de la concesión de subvenciones?", "Los requisitos generales que deben cumplir los beneficiarios de la subvención, la forma de acreditarlos y, en su caso, el período durante el cual deben mantenerse.", "Las medidas de garantía a favor de los intereses públicos que, en su caso, se consideren necesarias, así como, en su caso, los supuestos específicos que pueden dar lugar a la revocación de la subvención.", "Los órganos competentes para la iniciación, la instrucción y la resolución del procedimiento, así como la existencia o no de comisión evaluadora.", "Las condiciones de solvencia que deben cumplir las personas físicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 61, "Entre otros, el acto de convocatoria de una subvención contendrá los siguientes extremos:", "El importe máximo que se destina a la convocatoria y los créditos presupuestarios a los que se imputa.", "La forma, los plazos y las condiciones concretas para el pago total o, en su caso, fraccionado, y la forma y la cuantía de las garantías que, en su caso, deban exigirse a los beneficiarios para el pago anticipado de la subvención en los términos establecidos en el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones.", "Los plazos concretos para efectuar la solicitud y cualquier otro que deba determinarse de acuerdo con las bases reguladoras.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 62, "Señale la respuesta incorrecta. Según el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, corresponde al órgano instructor llevar a cabo de oficio las actuaciones necesarias para la determinación, el conocimiento y la comprobación de los datos en virtud de los cuales debe dictarse la resolución y, en concreto:", "Emitir el informe que debe servir de base para la elaboración de la propuesta de resolución.", "Resolver las dudas de interpretación que puedan surgir en relación a las bases reguladoras de la subvención y la convocatoria.", "Abrir, cuando proceda, el trámite de audiencia e incorporar el resultado al expediente.", "Determinar los participantes admitidos en la convocatoria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 63, "De acuerdo con el artículo 19 del Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, ¿en qué caso debe constituirse la comisión evaluadora?", "Las comisiones evaluadoras deben constituirse, preceptivamente, con independencia del procedimiento de selección de los beneficiarios.", "No existe ninguna respuesta correcta.", "Las comisiones evaluadoras deben constituirse, preceptivamente, en los procedimientos de concurso, siempre que el importe global de los fondos públicos previstos en la convocatoria sea superior a 50.000,00 euros, o el importe individual máximo de las subvenciones sea superior a 7.000,00 euros.", "Las comisiones evaluadoras deben constituirse, preceptivamente, en los procedimientos de concurso, siempre que el importe global de los fondos públicos previstos en la convocatoria sea superior a 50.000,00 euros, y el importe individual máximo de las subvenciones sea superior a 7.000,00 euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 64, "De acuerdo con el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, las comisiones evaluadoras estarán integradas por:", "Un presidente, un secretario y un número de vocales no inferior a tres.", "Un presidente, un secretario y un número de vocales máximo de tres.", "Un presidente y un número de vocales no inferior a cuatro.", "Un presidente o un secretario y un número de vocales no inferior a tres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 65, "Los plazos máximos para dictar y notificar la resolución expresa en los procedimientos de concesión de las subvenciones reguladas en el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones son:", "El plazo máximo para dictar y notificar la resolución expresa de concesión es el que fija la norma reguladora del procedimiento correspondiente o, en su caso, los que establecen las bases reguladoras.", "El plazo máximo para dictar y notificar la resolución expresa de concesión será de tres meses.", "El plazo máximo para dictar y notificar la resolución expresa de concesión será de seis meses.", "No existe ninguna respuesta correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 66, "¿Qué entidades pueden obtener la condición de entidades colaboradoras de acuerdo con lo establecido en el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones?", ") Las corporaciones de derecho público, los consorcios y las fundaciones del sector público.", "Las entidades autónomas y el resto de entidades de derecho público de la Comunidad Autónoma de las Islas Baleares.", "La Administración general del Estado y los organismos públicos dependientes.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 67, "Cuando la Administración decida que la entrega de los fondos públicos a los beneficiarios o la realización de otras funciones de gestión se efectúe mediante una entidad colaboradora, ambas partes formalizarán un convenio. El convenio de colaboración contendrá, como mínimo, los siguientes extremos:", "Compensación económica que, en su caso, se fije a favor de la entidad colaboradora.", "Plazo de duración del convenio.", "Identificación de la normativa reguladora específica de las subvenciones que deba gestionar la entidad colaboradora.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 68, "Se consideran gastos subvencionables:", "El gasto de amortización, siempre que así lo prevean las bases reguladoras y la subvención haya contribuido a la compra de bienes.", "Los gastos financieros, los gastos de asesoría jurídica o financiera, los gastos notariales y registrales, y los gastos periciales para la realización del proyecto subvencionado y los de administración específicas son subvencionables si están directamente relacionados con la actividad subvencionada.", "Los impuestos indirectos no susceptibles de recuperación o compensación.", "Los intereses deudores de las cuentas bancarias, los intereses, recargos y sanciones administrativas y penales, y los gastos de procedimientos judiciales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 69, "La Administración puede comprobar el valor de mercado de los gastos subvencionados empleando uno o varios de los siguientes medios:", "Precios medios de mercado.", "Cotizaciones en mercados nacionales y extranjeros.", "Tasación pericial contradictoria.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 70, "La liquidación de la subvención debe dictarse y notificarse dentro del plazo de prescripción:", "De cinco años que establece la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears.", "De cuatro años que establece la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears.", "De tres años que establece la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears.", "De seis años que establece la Ley 14/2014, de 29 de diciembre, de finanzas de la Comunidad Autónoma de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 71, "De acuerdo con lo establecido en el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, corresponde el reintegro, total o parcial, de las cuantías recibidas y la exigencia del interés de demora establecido con carácter general en la legislación de finanzas de la Comunidad Autónoma, en los siguientes casos:", "Incumplimiento de las obligaciones impuestas por la Administración a las entidades colaboradoras y beneficiarios, así como de los compromisos asumidos por éstos con motivo de la concesión de la subvención, siempre que afecten o se refieran a la forma en que deben conseguirse objetivos, ejercer la actividad, ejecutar el proyecto o adoptar el comportamiento que fundamenta la concesión de la subvención.", "Resistencia, excusa, obstrucción o negativa a las actuaciones de comprobación y control financiero, así como el incumplimiento de las obligaciones contables, registrales o de conservación de documentos cuando de ello derive la imposibilidad de verificar el uso que se ha hecho de los fondos percibidos, el cumplimiento del objetivo, la realidad y la regularidad de las actividades subvencionadas, o la concurrencia de subvenciones, ayudas, ingresos o recursos para tal fin, procedentes de cualesquiera administraciones o entes públicos o privados, nacionales, de la Unión Europea o de organismos internacionales.", "Incumplimiento total o parcial del objetivo, de la actividad o del proyecto, o la no adopción del comportamiento que fundamentan la concesión de la subvención.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 72, "De acuerdo con el Decreto legislativo 2/2005, de 28 de diciembre, por el que se aprueba el texto refundido de la Ley de subvenciones, el plazo máximo para resolver y notificar la resolución del procedimiento de reintegro:", "Es de seis meses, transcurrido el cual se producirá la caducidad en los términos previstos en la legislación de procedimiento administrativo común de las administraciones públicas, sin que sean exigibles los intereses moratorios que puedan devengarse a partir del día siguiente al del transcurso del mismo plazo máximo. Tampoco serán exigibles los intereses moratorios que puedan devengarse a partir del día siguiente al transcurso del plazo máximo para resolver y notificar la resolución en los procedimientos de recurso en vía administrativa contra las resoluciones de reintegro.", "Es de doce meses, transcurrido el cual se producirá la caducidad en los términos previstos en la legislación de procedimiento administrativo común de las administraciones públicas, sin que sean exigibles los intereses moratorios que puedan devengarse a partir del día siguiente al del transcurso de este plazo máximo. Tampoco serán exigibles los intereses moratorios que puedan devengarse a partir del día siguiente al transcurso del plazo máximo para resolver y notificar la resolución en los procedimientos de recurso en vía administrativa contra las resoluciones de reintegro.", "Es de seis meses, transcurrido el cual se producirá la caducidad en los términos previstos en la legislación de procedimiento administrativo común de las administraciones públicas, sin que sean exigibles los intereses moratorios que puedan devengarse a partir del día siguiente al del transcurso del mismo plazo máximo. No obstante, sí serán exigibles los intereses moratorios que pudieran devengarse a partir del día siguiente al transcurso del plazo máximo para resolver y notificar la resolución en los procedimientos de recurso en vía administrativa contra las resoluciones de reintegro.", "Es de doce meses, transcurrido el cual se producirá la caducidad en los términos previstos en la legislación de procedimiento administrativo común de las administraciones públicas, sin que sean exigibles los intereses moratorios que puedan devengarse a partir del día siguiente al del transcurso del mismo plazo máximo. No obstante, sí serán exigibles los intereses moratorios que pudieran devengarse a partir del día siguiente al transcurso del plazo máximo para resolver y notificar la resolución en los procedimientos de recurso en vía administrativa contra las resoluciones de reintegro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 73, "Señale la respuesta incorrecta. Respecto de los obligados al reintegro de subvenciones:", "Los beneficiarios y las entidades colaboradoras, en los casos previstos legalmente, deben reintegrar, total o parcialmente, las cantidades percibidas más, en su caso, los correspondientes intereses de demora.", "Responden solidariamente de la obligación de reintegro los administradores de las sociedades mercantiles, o aquellos que tengan la representación legal de otras personas jurídicas, cuando no lleven a cabo los actos necesarios que sean de su incumbencia para el cumplimiento de las obligaciones infringidas, adopten acuerdos que hagan posible los incumplimientos o consientan los de quienes dependan de ellos.", "En el caso de sociedades o entidades disueltas y liquidadas, las obligaciones de reintegro pendientes se transmiten a los socios o a los partícipes en el capital, los cuales responden solidariamente y hasta el límite del valor de la cuota de liquidación que se les haya adjudicado.", "En el caso de fallecimiento del obligado al reintegro, la obligación de satisfacer las cantidades pendientes de restitución se transmite a los derechohabientes, sin perjuicio de lo que establezca el derecho civil común, foral o especial aplicable a la sucesión para determinados casos, particularmente para el caso de aceptación de la herencia a beneficio de inventario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 74, "¿A quién corresponde, con carácter ordinario, el control económico y financiero de las subvenciones?", "A la Sindicatura de Cuentas de las Islas Baleares.", "A la Intervención General de la Comunidad Autónoma.", "A la Dirección General de Presupuestos.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 14, 75, "En el caso de las subvenciones, la presentación fuera de plazo de las cuentas justificativas de la aplicación de los fondos percibidos es una infracción de carácter:", "Grave.", "Muy grave.", "Leve.", "No supone ninguna infracción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 1, "La sede electrónica de una Administración Pública es:", "La dirección electrónica de una Administración disponible para la ciudadanía a través de redes de telecomunicaciones.", "La red de telecomunicaciones de la Administración que ofrece los servicios a toda la ciudadanía.", "El conjunto agrupado de todos los procedimientos administrativos inventariados y clasificados por unidades orgánicas pertenecientes a una Administración.", "El punto de acceso para la ciudadanía a las actuaciones que puede realizar con la Administración por medio de una autenticación electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 2, "¿Qué actuaciones y trámites se efectúan mediante la sede electrónica de una Administración Pública?", "Todas las actuaciones y trámites referidos a procedimientos o servicios que requieran la identificación de la Administración Pública y, en su caso, la identificación o firma electrónica de las personas interesadas.", "Todas las actuaciones y trámites referidos a procedimientos que requieran la identificación de la Administración Pública o aquellos servicios que requieran un asiento de registro de entrada dentro de la Administración Pública y, en su caso, la identificación o firma electrónica de la ciudadanía.", "Únicamente aquellas actuaciones y trámites referidos a procedimientos o servicios que estén implantados sobre una plataforma de tramitación telemática. Aquellas actuaciones o trámites que no dispongan de tramitación telemática, no tienen cabida en la sede electrónica.", "Todas las actuaciones y trámites referidos a procedimientos o servicios que requieran un asiento de registro de entrada dentro de la Administración Pública y, en su caso, la identificación o firma electrónica de la ciudadanía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 3, "¿Puede corresponder la titularidad de una sede electrónica a más de un organismo público?", "No, puesto que siempre corresponde a una Administración Pública.", "No, puede corresponder a un organismo público, pero no a más de uno.", "Sí, en el ámbito de sus competencias.", "Sí, siempre que sea titular a la vez la Administración Pública de la que depende."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 4, "Señale la respuesta incorrecta, en materia de sede electrónica:", "El establecimiento de una sede electrónica conlleva la responsabilidad del titular respecto de la integridad, veracidad y actualización de la información y servicios a los que se pueda acceder a través de la sede.", "Las sedes electrónicas deben disponer de sistemas que permitan siempre establecer comunicaciones seguras.", "Las sedes electrónicas deben utilizar, para identificarse y garantizar una comunicación segura con estas sedes, certificados reconocidos o cualificados de autenticación de sitio web o medio equivalente.", "La publicación en las sedes electrónicas de informaciones, servicios y transacciones debe respetar los principios de accesibilidad y uso de acuerdo con las normas establecidas al respecto, estándares abiertos y, en su caso, aquellos otros que sean de uso generalizado por parte de los ciudadanos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 5, "Cada Administración Pública determinará las condiciones y los instrumentos de creación de las sedes electrónicas con sujeción, entre otros, a los principios de:", "Transparencia, publicidad, responsabilidad, calidad, seguridad, disponibilidad, accesibilidad, neutralidad e interoperabilidad.", "Transparencia, publicidad, responsabilidad, eficacia, seguridad, disponibilidad, accesibilidad, coordinación e interoperabilidad.", "Transparencia, desconcentración, responsabilidad, eficacia, seguridad, disponibilidad, accesibilidad, coordinación e interoperabilidad.", "Transparencia, publicidad, responsabilidad, calidad, seguridad, disponibilidad, accesibilidad, coordinación e interoperabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 6, "En materia de funcionamiento del sector público por medios electrónicos, ¿se pueden crear sedes electrónicas paralelas?", "No, este concepto no existe.", "Sí, por razones técnicas y organizativas; además, una vez creadas se pueden suprimir.", "Sí, por razones técnicas y procedimentales; sin embargo, una vez creadas no se pueden suprimir.", "No, la sede electrónica es única."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 7, "El proceso para crear una sede electrónica asociada es:", "La publicación del acto o resolución de creación de la sede electrónica asociada en el boletín oficial que corresponda en función de cuál sea la Administración Pública titular de la sede.", "La publicación en el directorio del Punto de Acceso General Electrónico que corresponda.", "La sede electrónica asociada no requiere ningún acto o resolución de creación, ya que únicamente se crea por razones técnicas y organizativas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 8, "No forma parte de los elementos obligatorios que deben constar en el acto o resolución de creación de una sede electrónica de una Administración Pública:", "La identificación del titular del órgano responsable de la sede electrónica.", "La identificación del órgano u órganos encargados de la gestión y servicios puestos a disposición en la sede.", "La identificación de la dirección de la sede electrónica de referencia de la sede electrónica o sede electrónica asociada que se cree.", "El ámbito de aplicación de la sede electrónica o sede electrónica asociada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 9, "¿Cuál de las siguientes normas técnicas de interoperabilidad hace referencia a la interconexión con la sede electrónica?", "Norma Técnica de Interoperabilidad del modelo de datos y condiciones de interoperabilidad de los registros de funcionarios habilitados.", "Norma Técnica de Interoperabilidad del modelo de datos y condiciones de interoperabilidad de los registros electrónicos de apoderamientos.", "Norma Técnica de Interoperabilidad de las condiciones de interconexión con las sedes  electrónicas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 10, "No forma parte del contenido mínimo que toda sede electrónica o sede electrónica asociada debe poner a disposición de las personas interesadas:", "La identificación del acto o disposición de creación.", "El acceso al acto o disposición de creación.", "La normativa reguladora del Registro al que se acceda a través de la sede electrónica.", "La identificación de la dirección electrónica de referencia de la sede electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 11, "Cuanto a aspectos temporales, ¿cuál de los siguientes elementos es un contenido mínimo que debe disponer toda sede electrónica?", "La fecha oficial, así como el calendario de días inhábiles a efectos de comprobar la validez de un registro.", "La fecha y hora oficial, y, en su caso, el calendario de días inhábiles a efectos de comprobar la validez de un registro.", "El calendario de días hábiles a efectos del cómputo de plazos.", "La fecha y hora oficial, así como el calendario de días inhábiles a efectos del cómputo de plazos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 12, "¿Cuál de las siguientes no forma parte de la información necesaria que toda sede electrónica debe publicar para su correcta utilización?", "Mapa de la sede o información equivalente.", "Especificación de la estructura de navegación.", "Especificación de las distintas secciones disponibles.", "Mapa interactivo del menú."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 13, "El sistema de verificación de los certificados de la sede electrónica:", "Es un contenido que la sede puede poner a disposición de las personas interesadas.", "Es un contenido mínimo que toda sede electrónica o sede electrónica asociada debe poner a disposición de las personas interesadas.", "Es un servicio que la sede puede poner a disposición de las personas interesadas.", "Es un servicio mínimo que toda sede electrónica o sede electrónica asociada debe poner a disposición de las personas interesadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 14, "La fecha y hora oficial, como un elemento mínimo que debe formar parte de la sede electrónica, ¿con qué organismo se sincronizará?", "Con el Centro Español de Predicción Metrológica.", "Con el Registro de Control Metrológico.", "Con el Real Instituto y Observatorio de la Armada.", "Con el Ministerio de Ciencia y Tecnología."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 15, "¿Quién es el responsable de los procedimientos que figuren en una sede electrónica asociada a la que se haya accedido a través de un enlace publicado en una sede electrónica?", "El titular de la sede electrónica que contiene el enlace, en todo caso.", "El titular de la sede electrónica asociada, en todo caso.", "El titular de la sede electrónica asociada, sin perjuicio de la debida diligencia del titular de la sede electrónica que contiene el enlace respecto de la incorporación de los contenidos en esta sede.", "Tanto el titular de la sede electrónica que contiene el enlace como el titular de la sede electrónica asociada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 16, "¿Puede una sede electrónica contener procedimientos o servicios cuya competencia corresponda a un órgano de otra Administración?", "Sí, siempre que se indique explícitamente que el titular de esta sede no se hace responsable de la integridad, veracidad y actualización de lo referente a estos procedimientos o servicios.", "No, una sede sólo puede publicar procedimientos o servicios cuya competencia sea de un órgano de la propia Administración.", "Sí, y así mismo, la responsabilidad de la integridad, veracidad y actualización de lo referente a estos procedimientos o servicios es del titular de la competencia de estos procedimientos, sin perjuicio de la debida diligencia del titular de la sede electrónica respecto de la incorporación de los contenidos en esta sede.", "No, si quiere publicarlos debe poner un enlace o vínculo a la sede propietaria de los procedimientos o servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 17, "Si una administración pública opta por utilizar un sistema de código seguro de verificación de documentos en el ejercicio de actuaciones automatizadas, este código:", "Permitirá en todo caso la comprobación de la integridad del documento en la sede electrónica o sede electrónica asociada correspondiente, y en su caso, en el portal del registro electrónico general, mediante un procedimiento de verificación directo y gratuito para las personas interesadas.", "Permitirá en todo caso la comprobación de la integridad del documento en la sede electrónica o sede electrónica asociada correspondiente mediante un procedimiento de verificación directo y gratuito para las personas interesadas.", "Permitirá en todo caso la comprobación de la integridad del documento en la sede electrónica o sede electrónica asociada correspondiente, y en su caso, con el sistema de custodia documental, mediante un procedimiento de verificación indirecto y gratuito para las personas interesadas.", "Permitirá en todo caso la comprobación de la integridad del documento en la sede electrónica o sede electrónica asociada correspondiente mediante un procedimiento de verificación indirecto y gratuito para las personas interesadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 18, "Señale la respuesta incorrecta respecto a la relación de sellos electrónicos utilizados por cada Administración Pública:", "Esta relación incluirá las características de los certificados electrónicos.", "Esta relación será pública y accesible por medios electrónicos.", "Esta relación se publicará en la sede electrónica o sede asociada, y en el portal de internet correspondiente.", "Esta relación incluirá las características de los prestadores que los expiden."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 19, "El nivel de seguridad en la identificación electrónica exigido en los procedimientos y servicios que gestiona una entidad perteneciente al sector público:", "Se definirá y publicará en la sede electrónica.", "Se determinará en base a la accesibilidad universal, de acuerdo con el Esquema Nacional de Seguridad y la normativa correspondiente.", "Se determinará sobre la base del análisis de riesgos, de acuerdo con el Esquema Nacional de Interoperabilidad y la normativa correspondiente.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 20, "¿Qué normativa autonómica regula la sede electrónica de la Administración de la Comunidad Autónoma de las Illes Balears?", "El Decreto 113/2010, de 6 de noviembre, de acceso electrónico a los servicios públicos del Gobierno de las Illes Balears.", "El Decreto 112/2012, de 5 de noviembre, de acceso electrónico a los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears.", "El Decreto 113/2010, de 5 de noviembre, de acceso electrónico a los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears.", "El Decreto 112/2012, de 6 de noviembre, de acceso electrónico a los servicios públicos del Gobierno de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 21, "La edición electrónica del Boletín Oficial de las Illes Balears:", "Es un contenido mínimo que debe contener la página web de la Administración de la Comunidad Autónoma de las Illes Balears.", "Está contenido dentro de la sede electrónica de la Administración de la Comunidad Autónoma de las Illes Balears, pero no es un contenido obligatorio que deba contener su sede.", "Es un contenido mínimo que debe contener la sede electrónica de la Administración de la Comunidad Autónoma de las Illes Balears.", "Tiene su propia sede electrónica, y por tanto, no debe estar contenido dentro de la sede electrónica de la Administración de la Comunidad Autónoma de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 22, "En una actuación administrativa automatizada llevada a cabo mediante un sistema de firma basado en un código seguro de verificación, ¿cómo debe garantizarse la interoperabilidad en las comunicaciones de documentos electrónicos a otros órganos, organismos o entidades?", "Con la superposición de un sello electrónico al código seguro de verificación.", "Con un sello electrónico seguro adjunto al documento electrónico.", "Con la superposición de una firma electrónica al código seguro de verificación.", "Con una firma electrónica del titular del órgano competente que ha elaborado el documento electrónico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 23, "En materia de sistemas de firma electrónica del personal al servicio de las Administraciones Públicas, ¿cómo deben ser los certificados electrónicos de empleado público?", "Cualificados.", "Ajustados a lo establecido en el Esquema Nacional de Seguridad.", "Ajustados a la legislación vigente en materia de identidad y firma electrónica.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 24, "Dentro del conjunto de principios que el sector público debe respetar en sus actuaciones y relaciones electrónicas, ¿qué es el principio de interoperabilidad?", "La capacidad de los sistemas de información y, por ende, de los procedimientos a los que estos dan soporte, de compartir datos y posibilitar el intercambio de información entre ellos.", "La capacidad de los sistemas de información y, por ende, de los procedimientos a los que estos dan soporte, de compartir información y posibilitar el intercambio de datos entre ellos.", "La capacidad de los sistemas de información y, por ende, de los procedimientos a los que éstos dan soporte, de compartir datos o posibilitar el intercambio de información entre ellos.", "La capacidad de los sistemas de información y, por ende, de los procedimientos a los que estos dan soporte, de compartir información o posibilitar el intercambio de datos entre ellos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 25, "¿Cuál es el órgano técnico de cooperación de las administraciones públicas en materia de administración electrónica que asegura la compatibilidad e interoperabilidad de los sistemas y aplicaciones que utilizan las Administraciones Públicas?", "El Comité Sectorial de Administración Electrónica.", "La Comisión Sectorial de Administración Electrónica.", "La Conferencia Sectorial de Administración Electrónica.", "La Comisión Ministerial de Administración Electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 26, "¿Cuál de las siguientes funciones no desarrolla la Comisión Sectorial de Administración Electrónica?", "Asegurar la compatibilidad de los sistemas utilizados por las administraciones públicas.", "Preparar planes y programas conjuntos de actuación para impulsar el desarrollo de la administración electrónica en España.", "Asegurar la interoperabilidad de las aplicaciones utilizadas por las administraciones públicas.", "Asegurar la interconexión entre las administraciones públicas para proporcionar información administrativa clara, actualizada e inequívoca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 27, "¿Cuál es el órgano competente para garantizar la interoperabilidad en materia de ciberseguridad y criptografía?", "Centro Criptográfico Nacional, adscrito al Centro Nacional de Inteligencia.", "Centro Criptológico Nacional, adscrito al Centro Nacional de Interoperabilidad.", "Centro Criptológico Nacional, adscrito al Centro Nacional de Inteligencia.", "Centro Criptográfico Nacional, adscrito al Centro Nacional de Interoperabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 28, "¿Cuál de las siguientes opciones se considera un principio específico del Esquema Nacional de Interoperabilidad?", "El enfoque de soluciones multidimensionales.", "El carácter multilateral de la interoperabilidad.", "La interoperabilidad como elemento integrado con la calidad.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 29, "En el ámbito de la administración electrónica y de acuerdo con la Norma Técnica del Expediente Electrónico, señale la opción incorrecta sobre el índice electrónico de un expediente electrónico:", "El índice electrónico debe garantizar la integridad del expediente electrónico.", "El índice electrónico debe permitir la recuperación del expediente electrónico, siempre que sea necesario.", "El índice electrónico recoge el conjunto de documentos electrónicos asociados al expediente y se crea una vez que el expediente se cierra.", "El índice electrónico es uno de los componentes del expediente electrónico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 30, "En materia de interoperabilidad, ¿cómo se aprueba una Norma Técnica de Interoperabilidad?", "Mediante una Resolución.", "Mediante una Orden Ministerial.", "Mediante un Real Decreto.", "Mediante un Acuerdo de Consejo de Ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 31, "¿Cuál de las siguientes opciones no es una Norma Técnica de Interoperabilidad?", "Catálogo de estándares.", "Política de firma electrónica y de certificados de la administración.", "Relación de modelos de datos.", "Reutilización de datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 32, "En el ámbito de la administración electrónica y de acuerdo con la Norma Técnica de Digitalización de Documentos, ¿cuál es uno de los requisitos de la imagen electrónica?", "La imagen electrónica respetará la geometría del documento origen en tamaño, sin perjuicio de que pueda tener proporciones distintas.", "La imagen electrónica no puede contener caracteres o gráficos que no figuren en el documento origen.", "La resolución máxima de la imagen electrónica será de 200 píxeles por pulgada.", "La imagen electrónica debe aplicar los formatos establecidos para ficheros de imagen en la Norma Técnica de Interoperabilidad de Catálogo de Formatos Estándares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 33, "La red SARA es la red de comunicaciones establecida para conectar e intercomunicar a las Administraciones Públicas Españolas. ¿Dónde están establecidas las condiciones para que una Administración Pública pueda acceder a ella?", "En el Esquema Nacional de Interoperabilidad.", "En el Esquema Nacional de Seguridad.", "En una Norma Técnica de Interoperabilidad.", "En una guía de aplicación de una norma técnica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 34, "Señale la respuesta correcta en relación con las Normas Técnicas de Interoperabilidad:", "El registro electrónico de apoderamientos está tratado en la misma Norma Técnica de Interoperabilidad que trata el registro electrónico general.", "Existe una Norma Técnica de Interoperabilidad que trata el registro electrónico de apoderamientos.", "Existe una Norma Técnica de Interoperabilidad conjunta que trata tanto el registro electrónico de apoderamientos y como el de funcionarios habilitados.", "No existe ninguna Norma Técnica de Interoperabilidad que trate el registro electrónico de apoderamientos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 35, "De acuerdo con el Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, ¿qué no trata la Norma Técnica de Modelo de Datos para el intercambio de asentamientos entre las Entidades Registrales?", "Los aspectos funcionales y técnicos para el intercambio de asientos registrales.", "La gestión de errores y excepciones.", "La gestión de anexos.", "La digitalización."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 36, "De acuerdo con la Norma Técnica de Documento Electrónico, ¿cuáles son los componentes obligatorios de un documento electrónico?", "Contenido, firma electrónica y metadatos del documento electrónico.", "Contenido y metadatos del documento electrónico.", "Contenido, índice electrónico, firma electrónica y metadatos del documento electrónico.", "Contenido y sello electrónico del órgano responsable del documento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 37, "En el ámbito de la administración electrónica y de acuerdo con la Norma Técnica de Documento Electrónico, ¿cuál de las siguientes opciones es un documento administrativo electrónico?", "Una factura presentada por un proveedor en papel, conformada por el responsable del jefe del Servicio de Protección de Especies con una firma manuscrita y escaneada para generar un archivo electrónico en formato PDF.", "Una resolución denegatoria de subvenciones en materia de desplazamientos interislas incorporada a un expediente electrónico creado por el gestor de expedientes electrónico corporativo RIPEA y firmada digitalmente por el Director General de Deportes a través del sistema de portafirmas corporativo PORTAFIB integrado dentro del propio gestor de expedientes.", "Un correo electrónico recibido en un buzón compartido del Servicio de Personal Funcionario de la Dirección General de Función Pública donde un opositor motiva justificadamente dentro del cuerpo del correo su renuncia a la ocupación de un puesto de trabajo que se le ha ofrecido mediante una llamada telefónica.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 38, "De acuerdo con el Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, ¿cuál es la definición de Sistema de Interconexión de Registros?", "La infraestructura básica que permite el intercambio de asientos electrónicos de registro entre las Administraciones Públicas.", "El instrumento que presta servicios de interconexión técnica, organizativa y jurídica entre sistemas de información para un conjunto de Administraciones Públicas bajo las condiciones que estas administraciones fijen.", "La infraestructura que permita la integración, como servicio o como producto, tanto de carácter horizontal como sectorial, entre las distintas plataformas registrales de simplificación administrativa.", "El instrumento que tiene por objeto definir la forma correcta de intercambiar o almacenar los datos de un asiento registral y garantizar su seguridad, conservación e interoperabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 39, "De acuerdo con la normativa Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, las aplicaciones para el tratamiento del Registro Electrónico General, ¿tendrán que permitir interoperabilidad con las herramientas de gestión de expedientes?", "Sí, en el ámbito de la Administración General del Estado.", "No, la ley no hace referencia a ésta de interoperabilidad.", "Sí, en el ámbito de todas las Administraciones Públicas.", "No, la ley recomienda esta interoperabilidad pero no la requiere."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 40, "¿Qué protocolo implementa la Plataforma de Interoperabilidad de las Illes Balears?", "SCSP (Sustitución de Certificados en Soporte Papel).", "SICRES (Sistema de Información Común de Registros de Entrada y Salida).", "SPSC (Servicios de Plataforma para Consultas Centralizadas).", "SICRES (Sistema de Información Común de Reutilización con Estándares Seguros)."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 41, "De forma general, ¿qué versión del protocolo SCSP (Sustitución de Certificados en Soporte Papel) se usa en los servicios de intercambio de datos y documentos entre administraciones públicas?", "La versión 1.", "La versión 2.", "La versión 3.", "Las versiones 2 o 3, de acuerdo con las capacidades técnicas del agente Cedente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 42, "¿De qué organismo es el protocolo que implementa la Plataforma de Interoperabilidad de las Illes Balears?", "Del Ministerio de Hacienda y Administraciones Públicas.", "Del Ministerio de Asuntos Económicos y Transformación Digital.", "Del Ministerio de Ciencia e Innovación.", "Del Ministerio de Asuntos Exteriores, Unión Europea y Cooperación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 43, "En materia de los intercambios intermediados de datos entre Administraciones Públicas, ¿cuál es el agente que colabora en las tareas de auditoría cuando sea requerido para ello, y facilita al Cedente la información o documentos necesarios para el control de las consultas?", "El cedente", "El emisor.", "El cesionario.", "El requirente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 44, "En materia de los intercambios intermediados de datos entre Administraciones Públicas y referente a las autorizaciones de acceso a los servicios, ¿cuál es el agente que define la política de auditoría y realizará auditorías periódicas sobre el uso del sistema relativo a las consultas de sus datos?", "El cedente", "El emisor.", "El cesionario.", "El requirente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 45, "En materia de los intercambios intermediados de datos entre Administraciones Públicas, ¿qué agente actúa como emisor a la vez que como cedente?", "Un cedente que facilita la cesión de sus propios datos.", "Un emisor que facilita la cesión de sus propios datos.", "Un cesionario que realiza directamente la consulta de sus propios datos.", "Un requirente que realiza directamente la consulta de sus propios datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 46, "En materia de los intercambios intermediados de datos entre Administraciones Públicas, ¿qué agente mantendrá la traza de todas las peticiones recibidas y respuestas generadas?", "El cedente", "El emisor.", "El cesionario.", "El requirente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 47, "Dentro de la red corporativa del Govern de les Illes Balears, ¿cómo se puede acceder a la Plataforma de Interoperabilidad de las Illes Balears?", "Con usuario y contraseña.", "Con cualquier tipo de documento digital.", "Sin autenticación.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 48, "En la Plataforma de Interoperabilidad de las Illes Balears, ¿cuál es la tramitación para solicitar para un usuario del Govern de las Illes Balears el acceso a los servicios interesados?", "Solicitar la adhesión a un servicio y el alta como usuario delegado de la Plataforma de Interoperabilidad de las Iles Balears.", "No es necesario ningún tipo de solicitud específica, todos los empleados del Gobierno de las Illes Balears tienen acceso a la Plataforma de Interoperabilidad de las Illes Balears ya los servicios.", "Solicitar la adhesión a un servicio y el alta como usuario representante de la Plataforma de Interoperabilidad de las Illes Balears.", "No es necesario ningún tipo de solicitud específica, con el usuario de acceso a la intranet corporativa se puede acceder directamente a la Plataforma de Interoperabilidad de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 49, "¿Qué tipo de licencia tiene el software que implementa la Plataforma de Interoperabilidad de las Illes Balears?", "Creative Commons.", "GPLv3 (General Public Lisence).", "BSD (Berkeley Software Distribution).", "MPL (Mozilla Public Lisence)."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 50, "Señale la respuesta correcta:", "La Plataforma de Interoperabilidad de las Illes Balears permite realizar consultas simples y consultas complejas.", "La Plataforma de Interoperabilidad de las Illes Balears permite realizar múltiples consultas, siempre que sean para el mismo interesado.", "La Plataforma de Interoperabilidad de las Illes Balears permite realizar consultas simples y consultas múltiples.", "La Plataforma de Interoperabilidad de las Illes Balears permite realizar consultas simples, adjuntando un fichero cumplimentado con los datos de cada petición que se realiza, y consultas múltiples, a través de formulario de datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 51, "¿Quién puede adherirse al convenio de colaboración en materia de interoperabilidad telemática entre las administraciones públicas del ámbito territorial de las Illes Balears?", "Es un convenio cerrado, sin posibilidad de adherirse al mismo.", "Cualquier administración pública del estado español.", "Los organismos públicos y las entidades de derecho público vinculados o dependientes de las administraciones públicas, en todo caso.", "Todas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 52, "¿Cómo se puede realizar la adhesión de un nuevo órgano al convenio de colaboración en materia de interoperabilidad telemática entre las administraciones públicas del ámbito territorial de las Illes Balears?", "Mediante el envío de una solicitud a la Dirección General de Modernización y Administración Digital, junto con un certificado del órgano correspondiente de la adopción de la decisión de la adhesión.", "Mediante el envío de una solicitud a la Consejería de Fondo Europeo, Universidad y Cultura, junto con un certificado de la Dirección General de Modernización y Administración Digital que autoriza técnicamente esta adhesión.", "Mediante una resolución del consejero de Fondo Europeo, Universidad y Cultura donde se autoriza la adhesión del nuevo órgano al convenio.", "Mediante una resolución del consejero de Fondo Europeo, Universidad y Cultura donde se autoriza la adhesión del nuevo órgano al convenio, previo informe vinculante de la Comisión Superior de Sistemas de Información en Tecnología y Comunicaciones que depende de la Dirección General de Modernización y Administración Digital."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 53, "¿Quién no forma parte de la Comisión de Seguimiento del convenio de colaboración en materia de interoperabilidad telemática entre las administraciones públicas del ámbito territorial de las Illes Balears?", "El coordinador del departamento de Nuevas Tecnologías del Consell de Formentera.", "El Director General de Modernización y Administración Digital de la Comunidad Autónoma de las Illes Balears.", "El jefe de la Sección de Sistemas de Información y Seguridad del Consell de Eivissa.", "Todos los anteriores cargos forman parte de la misma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 54, "Según el convenio de colaboración en materia de interoperabilidad telemática entre las administraciones públicas del ámbito territorial de las Illes Balears, ¿qué actuaciones se compromete a llevar a cabo la Dirección General de Modernización y Administración Digital?", "Gestionar la Plataforma de Intermediación de las Illes Balears (PINBAL).", "Establecer y fijar los protocolos de actuación y órganos adecuados para proveer eficientemente de información a las solicitudes enviadas mediante la plataforma.", "Alojar la plataforma de interoperabilidad de las Illes Balears.", "Mantener y mejorar la plataforma de intermediación de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 55, "En materia de interoperabilidad telemática, ¿qué son los servicios propios?", "Son aquellos que permiten a los entes adscritos al convenio de colaboración en materia de interoperabilidad telemática entre las administraciones públicas del ámbito territorial de las Iles Baleare, compartir e intercambiar información mediante la Plataforma de Interoperabilidad de las Illes Balears .", "Son aquellos servicios que ofrece la Administración General del Estado y que pueden consultarse mediante la Plataforma de Interoperabilidad de las Illes Balears.", "Son aquellos servicios cuya consulta no requiere acceder a la Plataforma de Interoperabilidad de las Illes Balears, ya que son accesibles directamente a través de la intranet.", "Son aquellos servicios de verificación y consulta de datos prestados por un órgano de la propia Administración Pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 56, "En la Plataforma de Interoperabilidad de las Illes Balears y haciendo uso del servicio de consulta de grado y nivel de dependencia que ofrece el Instituto de Mayores y Servicios Sociales (IMSERSO), ¿cuál de los siguientes datos no se obtiene de la consulta?", "Número del expediente en vigor y estado de la resolución.", "Grado y nivel de dependencia, y tipos de dependencia reconocida.", "Fecha de reconocimiento.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 57, "¿Cómo se aprueba la Norma Técnica de Interoperabilidad de Protocolos de intermediación de datos?", "Mediante la resolución de 28 de junio de 2010, de la Secretaría de Estado de Administraciones Públicas.", "Mediante el Real Decreto 4/2010 de 8 de enero de 2010.", "Mediante la resolución de 28 de junio de 2012, de la Secretaría de Estado de Administraciones Públicas.", "Mediante el Real Decreto 203/2010 de 30 de marzo de 2021."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 58, "Indique la respuesta incorrecta en relación con la aportación de documentos por parte de las personas interesadas:", "La Administración de la Comunidad Autónoma de las Illes Balears no debe exigir la aportación de documentos si éstos están incorporados a la carpeta documental.", "Las administraciones públicas no deben exigir a la ciudadanía la presentación de documentación si ésta consta en el Catálogo de simplificación documental.", "Los interesados tienen derecho a no aportar documentos que ya se encuentren en poder de la Administración actuante.", "Las copias que aporten los interesados en el procedimiento administrativo tendrán eficacia, exclusivamente, en el ámbito de la actividad de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 59, "Indique la respuesta correcta en relación con la aportación de documentos en un procedimiento administrativo:", "Los ciudadanos deben aportar los datos y los documentos exigidos por las administraciones públicas de acuerdo con lo dispuesto en la normativa aplicable.", "Los interesados deben aportar los datos y los documentos exigidos por las administraciones públicas de acuerdo con lo dispuesto en la normativa aplicable.", "Los interesados deben aportar los datos y los documentos exigidos por las administraciones públicas.", "Los ciudadanos deben aportar los datos y los documentos exigidos por las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 60, "En relación con los documentos que el interesado no debe aportar a un procedimiento, ¿cómo debe obtener la Administración actuante estos datos que están en poder de otra administración?", "Mediante la consulta a las plataformas de intermediación de datos u otro sistema electrónico habilitado al efecto, por este orden.", "Mediante los sistemas electrónicos habilitados al efecto, la consulta a las plataformas de intermediación de datos o las redes corporativas, indistintamente.", "Mediante las redes corporativas, la consulta a las plataformas de intermediación de datos u otros sistemas electrónicos habilitados al efecto, por este orden.", "Mediante la plataforma de intermediación de datos y, en su defecto, el envío de oficios con el sistema VALIB."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 61, "Indique la respuesta correcta. ¿En qué casos el interesado no puede oponerse a que la Administración actuante obtenga los datos en poder de otra administración?", "Cuando la aportación del documento se exige en el marco del ejercicio de potestades sancionadoras.", "Cuando la aportación del documento se exige en el marco del ejercicio de potestades tributarias.", "Cuando la aportación del documento se exige en el marco del ejercicio de potestades de inspección.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 62, "Indique la respuesta incorrecta:", "Las administraciones públicas pueden exigir la presentación de documentos originales a los interesados, en determinados casos.", "Las administraciones públicas no podrán exigir, en ningún caso, la presentación de documentos originales a los interesados.", "Excepcionalmente, la normativa reguladora del procedimiento puede establecer la exigencia de presentar documentos originales a los interesados.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 63, "Si un ciudadano que tiene la condición de interesado en un procedimiento no quiere aportar un determinado documento por el hecho de haberlo presentado antes ante otra Administración:", "Debe indicar día y hora en el que presentó el documento ante la otra Administración.", "Debe indicar cuándo, dónde y por qué presentó el documento ante la otra Administración.", "Debe indicar en qué momento y ante qué órgano administrativo presentó el documento.", "Debe indicar ante qué órgano administrativo presentó el documento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 64, "En relación con el derecho a no aportar documentos a la Administración Pública:", "Es un derecho de los ciudadanos que tienen reconocida su condición de interesados en el procedimiento.", "Es un derecho de los ciudadanos, en general.", "Es un derecho de las personas interesadas.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 65, "¿Puede oponerse un interesado a aportar determinada documentación en el procedimiento administrativo?", "No, los interesados deben aportar al procedimiento los datos y documentos exigidos por las administraciones públicas de acuerdo con lo establecido en la normativa aplicable.", "Sí, en cualquier caso.", "Hay casos en los que el interesado tiene derecho a no aportar documentos.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 66, "Si un interesado tiene derecho a no aportar un determinado documento en el procedimiento porque éste está en poder de otra administración:", "La Administración actuante debe consultar los datos por medios telemáticos, siempre que tenga el consentimiento expreso del interesado.", "La Administración actuante debe consultar los datos por medios telemáticos, siempre que tenga el consentimiento tácito del interesado.", "La Administración actuante debe consultar los datos por medios telemáticos, aunque el interesado se oponga a ellos.", "La Administración actuante debe consultar los datos por medios telemáticos, salvo que el interesado se oponga."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 67, "Cuando la Administración actuante debe recabar un documento en poder de otra administración presentado por el interesado en un procedimiento anterior y no puede conseguirlo:", "El interesado está obligado a presentar de nuevo el documento.", "Si el interesado es persona jurídica, puede requerirla para que presente nuevamente el documento.", "Excepcionalmente, puede requerir nuevamente el documento al interesado.", "No puede requerir de nuevo el documento al interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 68, "Indique la respuesta correcta. Con carácter general, el ciudadano está obligado a presentar los documentos ante una Administración cuando:", "Exista un procedimiento administrativo.", "Se oponga a la consulta de los datos por parte de la Administración actuante.", "Lo exija una administración pública de acuerdo con la normativa aplicable.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 69, "Excepcionalmente, cuando la relevancia del documento en el procedimiento lo exija o existan dudas derivadas de la calidad de la copia:", "La Administración pública actuante no puede requerir al interesado para que aporte más documentación.", "La Administración pública actuante puede requerir al interesado para que exhiba el documento original, por lo que le solicitará motivadamente el cotejo de las copias.", "La Administración pública actuante puede requerir al interesado para que presente nuevamente copia del documento.", "La Administración pública actuante puede requerir al interesado para que comparezca ante las oficinas públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 70, "¿Cuándo puede el órgano instructor de un procedimiento requerir al interesado para que aporte un documento original?", "Excepcionalmente, cuando la copia aportada por el interesado es de muy mala calidad y tiene dudas sobre su contenido.", "Con carácter general, cuando se trate de un documento clave para resolver el procedimiento.", "Cuando el interesado haya aportado la documentación en papel y ésta no está digitalizada.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 71, "Indique la respuesta correcta en relación con la aportación de documentos por los interesados:", "Los documentos que aporten los interesados al procedimiento administrativo, tanto originales como copias de éstos, tendrán eficacia en el ámbito de la actividad de las administraciones públicas.", "Las copias que aporten los interesados al procedimiento administrativo tienen eficacia exclusivamente en el ámbito de la actividad de las administraciones públicas.", "Los documentos que aporten los interesados al procedimiento administrativo tendrán eficacia exclusivamente en el ámbito de la actividad de las administraciones públicas.", "Las copias que aporten los ciudadanos tienen eficacia frente a cualquier administración pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 72, "Señale la respuesta correcta en relación con el Catálogo de simplificación documental:", "El Catálogo contiene documentos de los interesados cuya aportación no es obligatoria en el procedimiento administrativo.", "El Catálogo contribuye a hacer efectivo el derecho de las personas interesadas a no aportar documentación elaborada por las administraciones públicas.", "Los documentos incluidos en el Catálogo serán susceptibles de ser consultados a través de plataformas interoperables.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 73, "¿En qué año se creó el Catálogo de simplificación documental?", "El 2013.", "El 2011.", "El 2015.", "El 2017."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 74, "En el momento de entrar en vigor el Catálogo de simplificación documental, ¿sobre qué documentos se suprimió la obligación de presentarlos?", "Obligaciones tributarias frente a la Hacienda autonómica.", "Datos de residencia.", "Datos de identidad.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 17, 75, "Con carácter general, la Administración de la Comunidad Autónoma de las Illes Balears no debe exigir a los interesados la presentación de documentación cuando:", "Se trate de documentos originales.", "Se trate de documentos en poder de un ayuntamiento.", "Se trate de documentos aportados anteriormente por el interesado.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 1, "Según el artículo 16 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, ¿cuáles son las funciones del secretario de un órgano colegiado?", "Únicamente garantizar que las reglas de constitución de los órganos se cumplen adecuadamente.", "Velar por la legalidad formal y material de las actuaciones del órgano colegiado, certificar las actuaciones del mismo y garantizar que los procedimientos y reglas de constitución y adopción de acuerdos son respetadas.", "Establecer los procedimientos que se tienen que seguir para la adopción de acuerdos.", "Solo asistir a las sesiones de los órganos colegiados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 2, "¿Quién puede solicitar al secretario de un órgano colegiado la expedición de la certificación de sus acuerdos?", "Quienes acrediten la titularidad de un interés legítimo.", "Cualquier persona.", "Nadie.", "Solo los miembros del órgano."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 3, "Señale la respuesta correcta. Según lo dispuesto en el artículo 18 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en el acta de la sesión de un órgano colegiado se incluirá:", "Solo los asistentes y el contenido de los acuerdos adoptados.", "Los asistentes, el orden del día de la reunión, las circunstancias del lugar y tiempo en que se ha celebrado, los puntos principales de las deliberaciones, así como el contenido de los acuerdos adoptados.", "Únicamente el orden del día y el contenido de los acuerdos adoptados.", "Solo los asistentes y las circunstancias del lugar y tiempo en que se ha celebrado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 4, "Señale la respuesta correcta respecto del acta de cada sesión:", "Deberá aprobarse en la misma reunión.", "Solo podrá aprobarse en la reunión siguiente.", "Podrá aprobarse en la misma reunión o en la inmediata siguiente", "Deberá aprobarse en la última reunión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 5, "¿Cuál de las siguientes funciones no corresponde al presidente de los órganos colegiados de la Administración General del Estado y de las Entidades de Derecho Público vinculadas o dependientes de ella?", "Visar las actas y las certificaciones de los acuerdos del órgano.", "Asegurar el cumplimiento de las leyes.", "Acordar la convocatoria de las sesiones ordinarias y extraordinarias y la fijación del orden del día, teniendo en cuenta, en su caso, las peticiones de los demás miembros, siempre que hayan sido formuladas con la suficiente antelación.", "Expedir certificaciones de las consultas, dictámenes y acuerdos aprobados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 6, "¿Cuál de las siguientes funciones no corresponde al secretario de los órganos colegiados de la Administración General del Estado y de las Entidades de Derecho Público vinculadas o dependientes de ella?", "Ostentar la representación del órgano.", "Expedir certificaciones de las consultas, dictámenes y acuerdos aprobados.", "Preparar el despacho de los asuntos, redactar y autorizar las actas de las sesiones.", "Recibir los actos de comunicación de los miembros con el órgano, sean notificaciones, peticiones de datos, rectificaciones o cualquiera otra clase de escritos de los que deba tener conocimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 7, "Señale la respuesta incorrecta. Según el artículo 19 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, los miembros de los órganos colegiados de la Administración General del Estado y de las Entidades de Derecho Público vinculadas o dependientes de ella:", "Tienen que recibir, con una antelación mínima de dos días, la convocatoria conteniendo el orden del día de las reuniones.", "Tienen que la información precisa para cumplir las funciones asignadas.", "Tienen que participar en los debates de las sesiones.", "Tienen que recibir, con una antelación mínima de una semana, la convocatoria conteniendo el orden del día de las reuniones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 8, "¿En qué casos los miembros titulares del órgano colegiado de la Administración General del Estado y de las Entidades de Derecho Público vinculadas o dependientes de ella serán sustituidos por sus suplentes, si los hubiera?", "En casos de ausencia o enfermedad.", "Siempre que lo soliciten.", "Cuando lo soliciten las organizaciones representativas.", "En general, aunque no exista causa justificada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 9, "Si alguna disposición atribuye la competencia a una Administración, sin especificar el órgano que debe ejercerla, se entenderá que la facultad de instruir y resolver los expedientes corresponde:", "A los órganos superiores competentes por razón de la materia.", "A los órganos inferiores competentes por razón de la materia y el territorio.", "A los órganos inferiores que tengan competencia únicamente por razón del territorio.", "A los órganos superiores competentes por razón del territorio y la materia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 10, "¿A quién podrán delegar los órganos de las diferentes Administraciones Públicas el ejercicio de las competencias que tengan atribuidas?", "En otros órganos de la misma Administración, aun cuando no sean jerárquicamente dependientes, o en los Organismos públicos o Entidades de Derecho Público vinculados o dependientes de aquéllas.", "En otros órganos de la misma Administración, siempre que sean jerárquicamente dependientes.", "Siempre deberán delegar en órganos de otra Administración.", "Solo en los Organismos públicos o Entidades de Derecho Público vinculados o dependientes de aquéllas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 11, "¿Dónde deberá publicarse la delegación de competencias y su revocación?", "Únicamente en el Boletín Oficial del Estado.", "Únicamente en el Boletín de la Comunidad Autónoma o en el de la Provincia.", "En el Boletín Oficial del Estado, en el de la Comunidad Autónoma o en el de la Provincia, según la Administración a que pertenezca el órgano delegante, y el ámbito territorial de competencia de éste.", "No es necesaria su publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 12, "Señale la respuesta incorrecta en relación a la delegación de competencias:", "Las resoluciones administrativas que se adopten por delegación indicarán expresamente esta circunstancia y se considerarán dictadas por el órgano delegante.", "Salvo autorización expresa de una Ley, no podrán delegarse las competencias que se ejerzan por delegación.", "La delegación no será revocable en ningún caso por el órgano que la haya conferido.", "El acuerdo de delegación de aquellas competencias atribuidas a órganos colegiados, para cuyo ejercicio se requiera un quórum o mayoría especial, deberá adoptarse observando, en todo caso, dicho quórum o mayoría."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 13, "¿En qué casos la realización de actividades de carácter material o técnico de la competencia de los órganos administrativos o de las Entidades de Derecho Público podrá ser encomendada a otros órganos o Entidades de Derecho Público de la misma o de distinta Administración?", "Siempre que entre sus competencias estén esas actividades, por razones de eficacia o cuando no se posean los medios técnicos idóneos para su desempeño.", "Siempre que entre sus competencias estén esas actividades, por razones de eficacia, aunque se posean los medios técnicos idóneos para su desempeño.", "Por razones técnicas y siempre que no se posean los medios para su desempeño.", "Siempre por razones de eficiencia y eficacia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 14, "¿Dónde deberá publicarse la encomienda de gestión entre órganos y Entidades de Derecho Público de distintas Administraciones?", "Únicamente en el Boletín Oficial del Estado.", "Únicamente en el Boletín de la Comunidad Autónoma o en el de la Provincia.", "En el Boletín Oficial del Estado, en el de la Comunidad Autónoma o en el de la Provincia, según la Administración a que pertenezca el órgano encomendante, salvo en el supuesto de la gestión ordinaria de los servicios de las Comunidades Autónomas por las Diputaciones Provinciales o en su caso Cabildos o Consejos insulares, que se regirá por la legislación de Régimen Local", "No es necesaria su publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 15, "Señale la respuesta incorrecta en relación a la suplencia prevista en el artículo 13 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "Si no se designa suplente, la competencia del órgano administrativo se ejercerá por quien designe el órgano administrativo inmediato superior de quien dependa.", "La suplencia no implicará alteración de la competencia.", "Los titulares de los órganos administrativos podrán ser suplidos temporalmente en los supuestos de vacante, ausencia o enfermedad, así como en los casos en que haya sido declarada su abstención o recusación", "Para su validez es necesaria su publicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 16, "¿Qué deberá hacer el órgano administrativo que se estime incompetente para la resolución de un asunto?", "Deberá remitir directamente las actuaciones al órgano que considere competente, debiendo notificar esta circunstancia a los interesados.", "Deberá remitir a través de un superior jerárquico las actuaciones al órgano que considere competente.", "Deberá remitir directamente las actuaciones al órgano que considere competente, sin necesidad de notificar esta circunstancia a los interesados.", "Deberá dictar una resolución en la que se declare incompetente y notificarla a los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 17, "Señale la respuesta correcta en relación con la competencia:", "Los interesados tanto si son parte en el procedimiento como si no, podrán dirigirse al órgano que se encuentre conociendo de un asunto para que decline su competencia y remita las actuaciones al órgano competente.", "Los conflictos de atribuciones sólo podrán suscitarse entre órganos de una misma Administración no relacionados jerárquicamente, y respecto a asuntos sobre los que no haya finalizado el procedimiento administrativo.", "Los interesados no podrán dirigirse al órgano que estimen competente para que requiera de inhibición al que esté conociendo del asunto.", "Los conflictos de atribuciones sólo podrán suscitarse entre órganos de una misma Administración que estén relacionados jerárquicamente, y respecto a asuntos sobre los que haya finalizado el procedimiento administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 18, "Señale la respuesta incorrecta. Los convenios suscritos por las Administraciones Públicas, sus organismos públicos y entidades de derecho público vinculados o dependientes y las Universidades públicas, deberán incluir:", "El régimen de recursos.", "Los sujetos que suscriben el convenio y la capacidad jurídica con que actúa cada una de las partes.", "El régimen de modificación del convenio.", "El objeto del convenio y actuaciones a realizar por cada sujeto para su cumplimiento, indicando, en su caso, la titularidad de los resultados obtenidos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 19, "Señale la respuesta correcta en relación con el plazo de vigencia de un convenio de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "No podrá ser superior a cuatro años, salvo que normativamente se prevea un plazo superior.", "En ningún caso podrá ser superior a cuatro años.", "No podrá ser superior a 5 años, salvo que normativamente se prevea un plazo superior.", "No podrá ser superior a 3 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 20, "¿Cuál de las siguientes causas no se contempla en el artículo 51 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, como una causa de resolución de un convenio?", "El transcurso del plazo de vigencia del convenio sin haberse acordado la prórroga del mismo.", "El acuerdo unánime de todos los firmantes.", "El incumplimiento de las obligaciones y compromisos asumidos por parte de alguno de los firmantes.", "La renuncia verbal por parte de alguno de los firmantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 21, "En el ámbito de la Administración General del Estado, la designación de suplente podrá efectuarse:", "En los reales decretos de estructura orgánica básica de los Departamentos Ministeriales o en los estatutos de sus Organismos públicos y Entidades vinculados o dependientes según corresponda.", "Únicamente en los estatutos de sus Organismos públicos y Entidades vinculados o dependientes según corresponda.", "En las resoluciones del Gobierno.", "Mediante una ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 22, "Según el artículo 6 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, los órganos administrativos podrán dirigir las actividades de sus órganos jerárquicamente dependientes mediante:", "Instrucciones y circulares", "Circulares", "Instrucciones y órdenes de servicio", "Reglamentos"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 23, "¿Cuándo se publicarán en el boletín oficial que corresponda las instrucciones y órdenes de servicio, de conformidad con el artículo 6 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público?", "Cuando una disposición específica así lo establezca, o se estime conveniente por razón de los destinatarios o de los efectos que puedan producirse, sin perjuicio de su difusión de acuerdo con lo previsto en la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno.", "Siempre.", "Nunca.", "Solo cuando una disposición específica así lo establezca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 24, "Señale la respuesta correcta. Según el artículo 7 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la Administración consultiva podrá articularse mediante órganos específicos dotados de autonomía orgánica y funcional con respecto a la Administración activa, o a través de los servicios de esta última que prestan asistencia jurídica. Señale la respuesta correcta en relación con dichos servicios:", "No pueden estar sujetos a dependencia jerárquica, ya sea orgánica o funcional.", "Pueden estar sujetos a dependencia jerárquica.", "Solo pueden estar sujetos a dependencia jerárquica funcional.", "Solo pueden estar sujetos a dependencia jerárquica orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 25, "Señale la respuesta correcta. El artículo 47.1 de la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, establece que:", "Son convenios los acuerdos con efectos jurídicos adoptados por las Administraciones Públicas, los organismos públicos y entidades de derecho público vinculados o dependientes o las Universidades públicas entre sí o con sujetos de derecho privado para un fin común.", "No tienen la consideración de convenios, los Protocolos Generales de Actuación o instrumentos similares que comporten meras declaraciones de intención de contenido general o que expresen la voluntad de las Administraciones y partes suscriptoras para actuar con un objetivo común, siempre que no supongan la formalización de compromisos jurídicos concretos y exigibles.", "Los convenios no podrán tener por objeto prestaciones propias de los contratos. En tal caso, su naturaleza y régimen jurídico se ajustará a lo previsto en la legislación de contratos del sector público.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 26, "¿Qué requisitos se requieren para la creación de un órgano administrativo de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público?", "Delimitación de sus funciones y competencias.", "Determinación de forma de integración en la Administración Pública de que se trate y su dependencia jerárquica.", "Dotación de los créditos necesarios para su puesta en marcha y funcionamiento.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 27, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en los casos previstos como motivos de abstención, podrá? promoverse recusación por los interesados:", "En cualquier momento de la tramitación del procedimiento.", "En cualquier momento anterior al trámite de audiencia.", "En cualquier momento anterior a la propuesta de resolución.", "En cualquier momento anterior al inicio del procedimiento"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 28, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, las Administraciones Públicas deberán respetar en su actuación y relaciones los siguientes principios (señale la respuesta incorrecta):", "Eficiencia en la asignación y utilización de los recursos públicos.", "Servicio efectivo a los ciudadanos.", "Participación, discrecionalidad y transparencia de la actuación administrativa.", "Responsabilidad por la gestión pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 29, "En relación con los órganos colegiados y de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, no podrá ser objeto de deliberación o acuerdo ningún asunto que no figure incluido en el orden del día:", "Salvo que asista la mayoría de los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de todos los presentes.", "Salvo que asistan todos los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de todos ellos.", "Salvo que asista la mayoría de los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de la mayoría de los presentes.", "Salvo que sistan todos los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de la mayoría."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 30, "De acuerdo con el art. 9.5 de la ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, si la norma reguladora de un procedimiento prevé, como trámite preceptivo, la emisión de un dictamen o informe (señale la opción correcta):", "No podrá delegarse la competencia para resolver dicho procedimiento en ningún caso.", "Sólo podrá delegarse después de haberse emitido el informe o dictamen preceptivo si no fuera vinculante.", "No podrá delegarse la competencia para resolver dicho procedimiento una vez que se haya emitido el dictamen o informe preceptivo.", "Sólo podrá delegarse la competencia para resolver dicho procedimiento una vez se haya dictado el dictamen o informe preceptivo si fuera vinculante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 31, "Indique la respuesta incorrecta en relación con el régimen previsto para las encomiendas de gestión regulades en el artículo 11 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "Las encomiendas de gestión no podrán tener por objeto las prestaciones propias de los contratos regulados en la legislación de contratos del sector público.", "La encomienda de gestión no supone cesión de la titularidad de la competencia del órgano o de la entidad encomendante.", "La encomienda de gestión conlleva la cesión de los elementos esenciales del ejercicio de la competencia del órgano o de la entidad encomendante.", "Para su eficacia, el instrumento de formalización de la encomienda de gestión entre órganos administrativos pertenecientes a la misma Administración y su resolución deberán ser publicadas en el Diario oficial a que corresponda el órgano encomendante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 32, "Señale la opción correcta en materia de órganos colegiados de las distintas administraciones públicas de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "El secretario tendrá siempre la condición de miembro del órgano colegiado.", "Corresponderá al presidente velar por la legalidad formal y material de las actuaciones del órgano colegiado.", "No podrá ser objeto de deliberación o acuerdo ningún asunto que no figure incluido en el orden del día, salvo que asistan todos los miembros del órgano colegiado y sea declarada la urgencia del asunto por el voto favorable de la mayoría.", "Para la válida constitución del órgano colegiado, a efectos de adopción de acuerdos, se requerirá únicamente la asistencia de la mitad más uno de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 33, "De acuerdo con el artículo 5 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, tendrán la consideración de órganos administrativos:", "Las unidades administrativas a las que se les atribuyan funciones que tengan efectos jurídicos frente a terceros, o cuya actuación tenga carácter preceptivo.", "Cualquier unidad administrativa independientemente de si tiene atribuidas funciones que tenga efectos jurídicos a terceros o cuya actuación tenga carácter preceptivo.", "Las unidades administrativas a las que se les atribuyan funciones que tengan efectos jurídicos frente a terceros y cuya actuación tenga carácter preceptivo, debiendo reunir ambas condiciones.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 34, "De conformidad con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, señale la afirmación correcta en relación a los convenios:", "Son convenios los acuerdos con efectos jurídicos adoptados por las Administraciones Públicas, los organismos públicos y entidades de derecho público vinculados o dependientes o las Universidades públicas entre sí o con sujetos de derecho privado para un fin común.", "Es causa de resolución de los convenios el cumplimiento de las actuaciones que constituyen su objeto.", "Los convenios podrán tener por objeto prestaciones propias de los contratos.", "Toda la regulación sobre convenios será de aplicación a las encomiendas de gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 35, "La Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, establece y regula lo siguiente:", "Las bases del régimen jurídico de las Administraciones Públicas.", "Los principios de la potestad sancionadora.", "La organización y funcionamiento del sector público institucional para el desarrollo de sus actividades.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 36, "La Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, se aplica a los siguientes entes:", "Únicamente a la Administración General del Estado.", "Exclusivamente a las Administraciones de las Comunidades Autónomas.", "A la Administración General del Estado, a las Administraciones de las Comunidades Autónomas, a las Entidades que integran la Administración Local y al sector público institucional.", "Exclusivamente a la Administración General del Estado y a las Administraciones de las Comunidades Autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 37, "Conforme al artículo 9 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, ¿cuál de las siguientes competencias podría ser objeto de delegación?", "Los asuntos que se refieran a relaciones la Jefatura del Estado o la Presidencia del Gobierno.", "La adopción de disposiciones de carácter general.", "La resolución de un recurso de alzada en el órgano administrativo que haya dictado el acto objeto de recurso.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 38, "Señale la opción correcta en relación con el régimen que prevé el artículo 8 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en relación con la irrenunciabilidad de la competencia:", "La competencia es irrenunciable salvo los casos de delegación o avocación, cuando se efectúen en los términos previstos en esta u otras leyes.", "La competencia es irrenunciable sin excepción alguna.", "La competencia es irrenunciable salvo los casos de ausencia del titular, cuando se efectúe en los términos previstos en esta u otras leyes.", "La competencia es irrenunciable salvo los casos de vacante, cuando se efectúe en los términos previstos en esta u otras leyes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 39, "Indique la respuesta correcta en relación con lo dispuesto en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en relación a la delegación de firma:", "Ningún titular de órgano administrativo puede delegar su firma.", "Solo puede delegar su firma un director general.", "La delegación de firma no alterará la competencia del órgano delegante y para su validez no será necesaria su publicación.", "Un director general solo puede delegar su firma en el titular de la consejería a la que pertenezca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 40, "¿Qué entes tienen la consideración de Administraciones Públicas de acuerdo con el artículo 2 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público?:", "Las entidades que integran la Administración Local.", "Las Administraciones de las Comunidades Autónomas.", "Los organismos públicos y las entidades de derecho público vinculados o dependientes de las Administraciones Públicas.", "Todas las anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 41, "Señale la opción correcta en relación con la suplencia de acuerdo con la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "La suplencia implicará alteración de la competencia y para su validez no será necesaria su publicación.", "Los titulares de los órganos administrativos podrán ser suplidos temporalmente en los supuestos de vacante, ausencia o enfermedad, así como cuando se haya declarado su abstención o recusación.", "La suplencia implicará alteración de la competencia y para su validez será necesaria su publicación.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 42, "De acuerdo con la ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la realización de una actividad de carácter técnico de la competencia de un órgano administrativo que, por no poseer los medios técnicos idóneos para su desempeño, haya sido encomendada a otro órgano de la misma administración entre cuyas competencias también estén estas actividades, se denomina:", "Avocación.", "Desconcentración.", "Delegación de competencias.", "Encomienda de gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 43, "Conforme a la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, tienen la consideración de convenios, los acuerdos con efectos jurídicos siguientes:", "Los adoptados entre organismos públicos y entidades de derecho público o privado.", "Los Protocolos Generales de Actuación.", "Los adoptados por universidades públicas con sujetos de derecho privado para un fin común.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 44, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, cuál de las siguientes afirmaciones no es correcta:", "Las Administraciones Públicas sirven con objetividad los intereses generales.", "Las Administraciones Públicas deberán respetar en su actuación y relaciones el principio de participación, objetividad y transparencia de la actuación administrativa.", "Las Universidades Públicas tienen la consideración de Administración Pública.", "Corresponde a cada Administración Pública delimitar, en su respectivo ámbito competencial las unidades administrativas que configuran los órganos administrativos propios de las especialidades derivadas de su organización."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 45, "Señale la afirmación correcta respecto a los órganos consultivos regulados en la ley 40/2015, de 1 de octubre, de régimen jurídico del sector público:", "Estarán sujetos a la dependencia jerárquica, orgánica o funcional, de los órganos que hayan elaborado las disposiciones objeto de consulta.", "Podrán recibir las directrices e indicaciones de los órganos que hayan producido los actos objeto de consulta.", "Carecen de autonomía orgánica y funcional.", "Actuarán de forma colegiada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 46, "De conformidad con lo dispuesto en el artículo 17 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, estarán exentos de la responsabilidad que, en su caso, pudiera derivarse de los acuerdos adoptados por los órganos colegiados:", "Los miembros del órgano que emitan su voto por medios electrónicos o por correo.", "Los miembros del órgano que voten a favor.", "Los miembros del órgano que voten en contra o que se abstengan.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 47, "De conformidad con lo dispuesto en el artículo 6 de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuál es la consecuencia del incumplimiento de instrucciones u órdenes de servicio?", "La nulidad jurídica plena de los actos emitidos por los órganos administrativos.", "La nulidad de los actos emitidos por los órganos administrativos.", "No afecta por sí mismo la validez de los actos emitidos por los órganos administrativos.", "La anulabilidad de los actos emitidos por los órganos administrativos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 48, "Según la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público ¿cuándo exigirá la Administración, de oficio, de sus autoridades y demás personal a su servicio la responsabilidad patrimonial en que hubieran podido incurrir?", "Siempre.", "Cuando hubieran incurrido en ella por dolo o culpa o negligencia muy graves.", "Cuando hubieran incurrido en ella por dolo o culpa o negligencia graves.", "Cuando hubieran incurrido en ella no por culpa o negligencia graves, sino por dolo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 49, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, las Administraciones Públicas deberán respetar en su actuación y relaciones los siguientes principios (señale la respuesta incorrecta):", "Eficiencia en la asignación y utilización de los recursos públicos.", "Servicio efectivo a los ciudadanos.", "Participación y discrecionalidad.", "Responsabilidad por la gestión pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 50, "Según el principio de proporcionalidad de la potestad sancionadora que regula la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público (señale la respuesta correcta):", "Será sancionable, como infracción continuada, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo precepto administrativo, en ejecución de un plan preconcebido o aprovechando distinta ocasión.", "Será sancionable, como infracción continuada, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo o semejantes preceptos administrativos, en ejecución de un plan preconcebido o aprovechando idéntica ocasión.", "No será sancionable, como infracción continuada, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo precepto administrativo, en ejecución de un plan preconcebido o aprovechando idéntica ocasión.", "Será sancionable, como infracción intermitente, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo o semejantes preceptos administrativos, en ejecución de un plan preconcebido o aprovechando distinta ocasión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 51, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, señale la respuesta correcta respecto a los datos de carácter personal a los que se pudiera tener acceso en ejecución de la encomienda de gestión:", "La entidad u órgano encomendado no tiene la condición de responsable del fichero o tratamiento.", "La entidad u órgano encomendado tiene la condición de encargado del tratamiento.", "La entidad u órgano encomendante tiene la condición de encargado del tratamiento.", "La entidad u órgano encomendante debe dictar una resolución para determinar qué órgano será el responsable del trataminento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 52, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, deberán remitirse electrónicamente al Tribunal de Cuentas u órgano externo de fiscalización de la Comunidad Autónoma, según corresponda los convenios cuyos compromisos económicos superen:", "Los 600.000 euros dentro de los tres meses siguientes a su suscripción.", "Los 600.000 euros dentro de los tres meses siguientes a contar desde la finalización de la vigencia del convenio.", "Los 300.000 euros dentro de los tres meses siguientes a su suscripción.", "Los 300.000 euros dentro de los tres meses siguientes a contar desde la finalización de la vigencia del convenio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 53, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, en los casos previstos como motivos de abstención, los interesados podrán promover la recusación en los siguientes casos (señale la respuesta correcta):", "En cualquier momento de la tramitación del procedimiento.", "En cualquier momento anterior al trámite de audiencia.", "En cualquier momento anterior a la propuesta de resolución.", "En cualquier momento anterior al inicio del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 54, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, con el fin de contribuir a la más correcta identificación de las conductas o a la más precisa determinación de las sanciones correspondientes, las disposiciones reglamentarias de desarrollo podrán introducir especificaciones o graduaciones al cuadro de las infracciones o sanciones establecidas legalmente:", "Que constituyan nuevas infracciones o sanciones, o alteren la naturaleza o límites de las que la ley contempla.", "Que no constituyan nuevas infracciones o sanciones, pero alteren la naturaleza o límites de las que la ley contempla.", "Que no constituyan nuevas infracciones o sanciones, ni alteren la naturaleza o límites de las que la ley contempla.", "Que constituyan nuevas infracciones o sanciones, pero no alteren la naturaleza o límites de las que la ley contempla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 55, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, las leyes reguladoras de los distintos regímenes sancionadores (señale la respuesta correcta):", "Podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones no pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "Podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "No podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones no pecuniarias impuestas a quienes de ellas dependan o estén vinculadas.", "No podrán prever los supuestos en que determinadas personas responderán del pago de las sanciones pecuniarias impuestas a quienes de ellas dependan o estén vinculadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 56, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la graduación de la sanción considerará especialmente los siguientes criterios (señale la respuesta incorrecta):", "El grado de culpabilidad o la existencia de intencionalidad", "La continuidad o persistencia en la conducta infractora", "La naturaleza de los perjuicios causados", "La reincidencia, por comisión en el término de dos años de más de una infracción de la misma naturaleza cuando así haya sido declarado por resolución firme en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 57, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la responsabilidad patrimonial del Estado por el funcionamiento de la Administración de Justicia se regirá por:", "La Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas.", "La propia Ley 40/2015.", "Las Leyes 39/2015 y 40/2015.", "La Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 58, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la Administración correspondiente, cuando hubiere indemnizado a los lesionados, exigirá de sus autoridades y demás personal a su servicio la responsabilidad en que hubieran incurrido por dolo, o culpa o negligencia graves. ¿Cómo efectuará la Administración dicho requerimiento?", "De oficio, en vía penal.", "De oficio, en vía administrativa, previa instrucción del correspondiente procedimiento.", "De oficio en vía administrativa.", "De oficio, en vía penal, previa instrucción del correspondiente procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 59, "De conformidad a la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, señale la respuesta incorrecta respecto a las sedes electrónicas:", "El establecimiento de una sede electrónica conlleva la responsabilidad del titular respecto de la integridad, veracidad y actualización de la información y los servicios a los que pueda accederse a través de la misma", "Dispondrán de sistemas que permitan el establecimiento de comunicaciones seguras siempre que sean necesarias", "La publicación en las sedes electrónicas de informaciones, servicios y transacciones respetará los principios de accesibilidad y uso, de acuerdo con las normas establecidas al respecto, estándares abiertos y, en su caso, aquellos otros que sean de uso generalizado por los ciudadanos.", "La Administración General del Estado determinará las condiciones e instrumentos de creación de todas las sedes electrónicas, con sujeción a los principios de transparencia, publicidad, responsabilidad, calidad, seguridad, disponibilidad, accesibilidad, neutralidad e interoperabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 60, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, cuando los participantes en las comunicaciones a que hace referencia su artículo 44, pertenezcan a distintas Administraciones, ¿cómo se establecen las condiciones y garantías por las que se rigen?", "Las establece la Administración que inicie el envío de las comunicaciones.", "Se establecen mediante convenio suscrito entre aquéllas.", "Las establece la Administración jerárquicamente superior.", "Serán las que establece la Ley 40/2015."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 61, "Según la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, ¿cómo se almacenarán todos los documentos utilizados en las actuaciones administrativa?", "Por medios electrónicos o medios no electrónicos de forma discrecional.", "Siempre por medios electrónicos.", "Por medios electrónicos, salvo cuando no sea posible.", "En papel con copia digitalizada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 62, "Señale la respuesta incorrecta respecto de los requisitos de validez y eficacia de los convenios según la ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público:", "Se requiere que los convenios que incluyan compromisos financieros deberán ser financieramente sostenibles.", "Las aportaciones financieras que se comprometan a realizar los firmantes pueden ser superiores a los gastos derivados de la ejecución del convenio.", "La suscripción de convenios debe cumplir con la legislación de estabilidad presupuestaria y sostenibilidad financiera.", "Los convenios se perfeccionan por la prestación del consentimiento de las partes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 63, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la suscripción de convenios (señale la respuesta incorrecta):", "Deberá mejorar la eficiencia de la gestión pública", "Deberá facilitar la utilización conjunta de medios y servicios públicos", "Deberá contribuir a la realización de actividades de utilidad pública y privada", "Deberá cumplir con la legislación de estabilidad presupuestaria y sostenibilidad financiera"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 64, "Señale la respuesta correcta respecto de las normas del Capítulo VI del Título Preliminar de la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público:", "Serán de aplicación a las encomiendas de gestión, pero no a los acuerdos de terminación convencional de los procedimientos administrativos.", "No serán de aplicación a las encomiendas de gestión ni a los acuerdos de terminación convencional de los procedimientos administrativos.", "Serán de aplicación a las encomiendas de gestión y los acuerdos de terminación convencional de los procedimientos administrativos.", "Serán de aplicación a los acuerdos de terminación convencional de los procedimientos administrativos, pero no a las encomiendas de gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 65, "Según la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, sin perjuicio de las especialidades que la legislación autonómica pueda prever, será necesario que el convenio se acompañe de una memoria justificativa donde se analice lo siguiente (señale la respuesta incorrecta):", "El impacto económico.", "La necesidad y oportunidad.", "El carácter contractual de la actividad en cuestión.", "El cumplimiento de lo previsto en la citada Ley 40/2015."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 66, "El Título preliminar de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público se denomina:", "Título preliminar.", "De los entes del sector público.", "Disposiciones generales, principios de actuación y funcionamiento del sector público.", "Sector público institucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 67, "Según la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, señale la respuesta correcta en relación con la competencia para la resolución de los recursos administrativos:", "Podrá delegarse en órganos superiores.", "Podrá delegarse en órganos inferiores, en todo caso.", "En ningún caso podrá ser objeto de delegación.", "No podrá delegarse en los órganos administrativos que hayan dictado los actos objeto de recurso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 68, "Según la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, señale la respuesta incorrecta en relación con los supuestos en los que no puede delegarse la competencia:", "Los asuntos que se refieran a relaciones con la Jefatura del Estado, la Presidencia del Gobierno de la Nación, las Cortes Generales, las Presidencias de los Consejos de Gobierno de las Comunidades Autónomas y las Asambleas Legislativas de la Comunidades Autónomas.", "La resolución de recursos en los órganos administrativos que hayan dictado los actos objeto de recurso.", "La adopción de disposiciones de carácter especial.", "Las materias en que así se determine por norma con rango de Ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 69, "De acuerdo con lo previsto en la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, la avocación se realizará mediante acuerdo motivado. ¿En qué momento se notificará a los interesados si los hubiere?", "Con anterioridad o simultáneamente a la resolución final que se dicte.", "Simultáneamente a la resolución final que se dicte.", "Con posterioridad a la resolución final que se dicte.", "Simultáneamente o con posterioridad a la resolución final que se dicte."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 70, "¿En cuántos capítulos se divide el Título preliminar de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público?", "En tres capítulos.", "En dos capítulos.", "En cinco capítulos.", "En seis capítulos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 71, "De acuerdo con el artículo 157 de la Ley 40/2015, de Régimen Jurídico del Sector Público, señale la respuesta correcta en relación con el directorio general de aplicaciones:", "Constarán tanto las aplicaciones disponibles de la Administración General del Estado como las disponibles en los directorios integrados de aplicaciones del resto de Administraciones.", "Constarán únicamente las aplicaciones disponibles de las Administraciones de las Comunidades Autónomas.", "Constarán las aplicaciones no disponibles de todas las Administraciones Públicas.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 72, "Según el artículo 93 de la Ley 40/2015 de 1 de octubre, de Régimen Jurídico del Sector Público, ¿qué regularán los estatutos de los organismos públicos estatales?", "Las funciones y competencias del organismo, con indicación de las potestades administrativas que pueda ostentar.", "El régimen relativo a recursos humanos, patrimonio, presupuesto y contratación.", "La facultad de participación en sociedades mercantiles cuando ello sea imprescindible para la consecución de los fines asignados.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 73, "Según el artículo 11 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público, cuando la encomienda de gestión se realice entre órganos administrativos o entidades de derecho público pertenecientes a la misma administración deberá formalizarse en los términos que establezca su normativa propia y, en su defecto, por acuerdo expreso de los órganos o entidades de derecho público intervinientes. En este sentido (señale la respuesta correcta):", "Cada Administración podrá regular los requisitos necesarios para la validez de tales acuerdos que incluirán, al menos, expresa mención de la actividad o actividades a las que afecten, pero no la justificación de la necesidad de la encomienda ni el plazo de vigencia.", "Cada Administración podrá regular los requisitos necesarios para la validez de tales acuerdos que incluirán, al menos, expresa mención de la actividad o actividades a las que afecten, el plazo de vigencia y la naturaleza y alcance de la gestión encomendada.", "Cada Administración debe dictar una disposición reglamentaria que regule los requisitos necesarios para la validez de tales acuerdos que incluirán, únicamente, expresa mención de la actividad o actividades a las que afecten.", "Las administraciones no pueden regular los requisitos necesarios para la validez de tales acuerdos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 74, "De acuerdo con la Ley 40/2015, de 1 de octubre de Régimen Jurídico del Sector Público, señale la respuesta correcta en relación con la estructura de la Administración General del Estado:", "En la organización territorial de la Administración General del Estado son órganos directivos tanto los delegados del Gobierno en las Comunidades Autónomas, que tendrán rango de secretario de Estado, como los subdelegados del Gobierno en las provincias, los cuales tendrán nivel de subdirector general.", "En la Administración General del Estado en el exterior son órganos directivos los embajadores y representantes permanentes ante Organizaciones internacionales.", "En la organización central de la Administración General del Estado son órganos directivos los secretarios de Estado y subsecretarios, los secretarios generales técnicos, directores generales y los subdirectores generales.", "Corresponde a los órganos directivos establecer los planes de actuación de la organización, así como su desarrollo y ejecución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 9, 75, "De conformidad al artículo 16 de la Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público señale la respuesta incorrecta en relación al secretario de un órgano colegiado:", "El secretario podrá ser un miembro del propio órgano.", "El secretario podrá ser una persona al servicio de la Administración Pública correspondiente.", "En caso de que el secretario no miembro sea suplido por un miembro del órgano colegiado, éste conservará todos sus derechos como tal.", "En caso de que el secretario no miembro sea suplido por un miembro del órgano colegiado, éste perderá todos sus derechos como tal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 1, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, ¿cuáles son los principios a los que están sometidas las entidades que integran el sector público institucional en su actuación?", "De legalidad, eficiencia, estabilidad presupuestaria y sostenibilidad financiera, y transparencia en su gestión.", "De legalidad, eficacia, estabilidad presupuestaria y sostenibilidad financiera.", "De legalidad, eficiencia, oportunidad, estabilidad financiera y transparencia en su gestión.", "De legalidad, eficiencia, eficacia, oportunidad, estabilidad presupuestaria y sostenibilidad financiera, y transparencia en su gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 2, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, indique la respuesta correcta:", "Todas las administraciones públicas deben establecer un sistema de supervisión continua de sus entidades dependientes.", "Todas las administraciones públicas deben establecer un sistema de supervisión continua de sus entidades dependientes que tengan personal empleado público temporal.", "Todas las administraciones públicas deben establecer un sistema de supervisión continua de sus entidades dependientes que tengan personal laboral.", "Todas las administraciones públicas deben establecer un sistema de supervisión anual de sus entidades dependientes con personal fijo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 3, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, no forman parte del sector público institucional:", "Los consejos insulares.", "Los consorcios.", "Las entidades públicas empresariales.", "Las fundaciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 4, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el Inventario de entidades del sector público estatal, autonómico y local se configura como un registro público administrativo que garantiza:", "La información pública y la ordenación de todas las entidades integrantes del sector público institucional independientemente de cuál sea su naturaleza jurídica.", "La ordenación de todas las entidades integrantes del sector público institucional al que será de aplicación al derecho administrativo.", "La información y ordenación de todas las entidades integrantes del sector público institucional de carácter fundacional con personal propio.", "La información pública de todas las entidades integrantes del sector público institucional independientemente de cuál sea su naturaleza jurídica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 5, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, debe inscribirse en el Inventario de entidades del sector público estatal, autonómico y local:", "La creación, transformación, fusión o extinción de cualquier entidad integrante del sector público institucional.", "La creación, transformación, fusión o extinción de cualquier entidad integrante del sector público institucional de carácter administrativo.", "La creación, transformación o fusión de cualquier entidad integrante del sector público institucional que tenga relación directa con los ciudadanos.", "La creación, fusión o extinción de cualquier entidad integrante del sector público institucional de naturaleza societaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 6, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, en materia de personal, las entidades que integran el sector público institucional se sujetan:", "A las limitaciones presupuestarias previstas en la normativa presupuestaria y en las previsiones anuales de los presupuestos generales.", "En las limitaciones presupuestarias previstas en la normativa presupuestaria y en las previsiones anuales de los presupuestos generales, con excepción del personal laboral.", "A las limitaciones presupuestarias previstas en el presupuesto de cada ente.", "A las limitaciones presupuestarias propias de la normativa societaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 7, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, corresponde notificar, a través de la intervención general de la Administración correspondiente, la información necesaria para la inscripción definitiva de  una entidad en el Inventario de entidades del sector público estatal, autonómico y local:", "Al titular del máximo órgano de dirección de la entidad.", "Al órgano competente en materia de hacienda y presupuestos de la Administración correspondiente.", "Al órgano competente en materia de personal de la Administración correspondiente.", "En el órgano de gobierno de la Administración correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 8, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el personal de los consorcios puede ser:", "Funcionario o laboral.", "Únicamente funcionario.", "No tienen personal.", "Funcionario, laboral o eventual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 9, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, los consorcios del sector público institucional pueden llevar a cabo:", "Actividades de fomento, prestacionales o de gestión común de servicios públicos y todas las demás que estén previstas en las leyes", "Actividades de fomento o gestión común de servicios públicos o de producción de bienes de interés público susceptibles de contraprestación.", "Actividades realizadas sin ánimo de lucro para cumplir los fines de interés general.", "Únicamente actividades de fomento y prestacionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 10, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el cambio de adscripción de una fundación del sector público institucional a una Administración pública supone:", "La modificación de los estatutos en un plazo no superior a tres meses, contados desde el inicio del ejercicio presupuestario siguiente a aquél en que se produjo el cambio de adscripción.", "La modificación de los estatutos en un plazo no superior a seis meses, contados desde el inicio del ejercicio presupuestario en el que se produjo el cambio de adscripción.", "La modificación de los estatutos en un plazo no superior a seis meses, contados desde el inicio del ejercicio presupuestario en el que se produjo el cambio de adscripción.", "La modificación de los estatutos en un plazo no superior a cuatro meses, contados desde el inicio del ejercicio presupuestario siguiente a aquél en que se produjo el cambio de adscripción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 11, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, la creación de los consorcios del sector público institucional se lleva a cabo mediante:", "Un convenio suscrito por las administraciones, los organismos públicos o las entidades participantes.", "Una ley habilitante.", "Un acuerdo conjunto del máximo órgano de gobierno de las entidades participantes.", "Un encargo de gestión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 12, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, el protectorado de las fundaciones del sector público debe ser ejercido:", "Por el órgano de la Administración de adscripción que tenga atribuida esta competencia.", "Por el ministerio competente en materia del sector público.", "Por el máximo órgano de gobierno de cada administración.", "Por el órgano de la Administración de adscripción competente en materia de hacienda y presupuestos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 13, "De acuerdo con la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público, las fundaciones del sector público institucional quedan adscritas, para cada ejercicio presupuestario y por todo este período, a la Administración pública:", "Que disponga de mayoría de patrones.", "Que tenga facultades para nombrar a un tercio de la mayoría del personal directivo.", "Que tenga mayoría para nombrar a un tercio de los miembros del patronato.", "Que tenga facultades para destituir a una cuarta parte de los miembros del patronato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 14, "No forman parte de la Administración corporativa:", "Las fundaciones públicas.", "Los colegios profesionales.", "Las cámaras de comercio, industria y navegación.", "Las cámaras de la propiedad urbana."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 15, "De acuerdo con el artículo 31.9 del Estatuto de Autonomía de las Illes Balears, en materia de corporaciones de derecho público, representativas de intereses económicos y sociales, a la Comunidad Autónoma de las Illes Balears le corresponde:", "El desarrollo legislativo y la ejecución.", "La función ejecutiva.", "La competencia exclusiva.", "No goza de ningún tipo de competencia sobre esta materia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 16, "De acuerdo con el artículo 36 de la Constitución española:", "La ley debe regular las peculiaridades propias del régimen jurídico de los colegios profesionales y el ejercicio de las profesiones tituladas.", "La ley regulará las peculiaridades propias del régimen jurídico de los colegios profesionales y el ejercicio de las profesiones tituladas y las organizaciones profesionales que contribuyan a la defensa de los intereses económicos que les sean propios.", "La ley regulará las organizaciones profesionales que contribuyan a la defensa de los intereses económicos que les sean propios.", "La ley debe regular las características y el funcionamiento de la administración corporativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 17, "De acuerdo con la Ley 2/1974, de 13 de febrero, de colegios profesionales, indique la respuesta correcta:", "Los colegios profesionales son corporaciones de derecho público, con personalidad jurídica propia y plena capacidad para el cumplimiento de sus fines.", "Los colegios profesionales son corporaciones de derecho privado.", "Los colegios profesionales se crean por real decreto.", "Los colegios profesionales carecen de personalidad jurídica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 18, "De acuerdo con la Ley 2/1974, de 13 de febrero, de colegios profesionales, indique la respuesta incorrecta:", "Para ser admitido en el colegio profesional que corresponda basta tener la titulación requerida.", "Es requisito indispensable para el ejercicio de las profesiones encontrarse incorporado en el colegio profesional que corresponda cuando así lo establezca una ley estatal.", "Los colegios profesionales se crean mediante ley.", "La fusión, absorción, segregación, cambio de denominación y disolución de los colegios profesionales de la misma profesión requiere la aprobación de un decreto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 19, "De acuerdo con el artículo 3.2 de la Ley 2/1974, de 13 de febrero, de colegios profesionales, la cuota de inscripción o colegiación en un colegio profesional:", "No puede superar los costes asociados a la tramitación de la inscripción.", "No está limitada.", "No podrá superar el triple de los costes asociados a la tramitación de la inscripción.", "La primera vez es gratuita."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 20, "De acuerdo con el artículo 4.6 de la Ley 2/1974, de 13 de febrero, de colegios profesionales, éstos adquieren personalidad jurídica:", "Desde el momento en que se constituyen sus órganos de gobierno.", "Desde la publicación de la norma de creación en el boletín oficial.", "Desde la publicación de la norma y de los estatutos en el boletín oficial.", "Desde el registro de los estatutos en el órgano competente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 21, "De acuerdo con el artículo 5 de la Ley 2/1974, de 13 de febrero, de colegios profesionales, no corresponde a los colegios profesionales:", "Aprobar la fusión y la absorción de colegios profesionales de la misma profesión.", "Informar en los procedimientos judiciales en los que se discutan honorarios profesionales.", "Participar en la elaboración de planes de estudio e informar sobre las normas de organización de los centros docentes correspondientes a las respectivas profesiones.", "Estar representados en los patronatos universitarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 22, "De acuerdo con el artículo 5 de la Ley 2/1974, de 13 de febrero, de colegios profesionales, en su ámbito territorial, es una función de los colegios profesionales:", "Adoptar las medidas que conducen a evitar el intrusismo profesional.", "Dirimir los conflictos que puedan suscitarse entre los distintos colegios.", "Aprobar los estatutos y visar los reglamentos de régimen interior de los colegios.", "Ejercer las funciones disciplinarias de los miembros de las juntas de gobierno de los colegios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 23, "De acuerdo con la Ley 1/2017, de 12 de mayo, de cámaras oficiales de comercio, industria, servicios y navegación de las Islas Baleares, las cámaras de comercio, industria y navegación son corporaciones de derecho público con personalidad jurídica que se configuran:", "Como órganos consultivos y de colaboración con las administraciones públicas.", "Como órganos consultivos, de participación y coordinación con las administraciones públicas.", "Como órganos consultivos y de coordinación con las administraciones públicas.", "Como órganos de participación, debate y coordinación con las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 24, "De acuerdo con la Ley 1/2017, de 12 de mayo, de cámaras oficiales de comercio, industria, servicios y navegación de las Islas Baleares, el personal de las cámaras de comercio, industria y navegación es:", "Personal laboral, sometido a la legislación laboral.", "Personal laboral, sometido a la legislación laboral ya la legislación de los empleados públicos.", "Personal funcionario.", "No tienen personal propio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 25, "La ley que regula el ente del sector público instrumental autonómico es:", "La Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Islas Baleares.", "La Ley 7/2011, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Islas Baleares.", "La Ley 7/2010, de 21 de julio, de los entes del sector público de la Comunidad Autónoma de las Islas Baleares.", "La ley 7/2010, de 21 de julio, del régimen jurídico del sector público instrumental de la Comunidad Autónoma de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 26, "De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Islas Baleares, las fundaciones del sector público instrumental forman parte:", "Del sector público instrumental fundacional.", "Del sector público instrumental empresarial.", "Del sector público instrumental administrativo.", "Del sector público instrumental corporativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 27, "De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Islas Baleares, los entes integrantes del sector público instrumental están sometidos:", "A los principios de legalidad, servicio al interés general, eficacia, eficiencia, estabilidad y transparencia.", "A los principios de legalidad, eficacia, estabilidad presupuestaria y eficiencia.", "A los principios de legalidad, evaluación y responsabilidad de la gestión, servicio al interés general, estabilidad y sostenibilidad financiera.", "A los principios de legalidad, servicio al interés general, eficiencia, transparencia y estabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 28, "Las entidades públicas empresariales del sector público instrumental de la Comunidad Autónoma de las Islas Baleares son:", "Organismos públicos de titularidad pública de naturaleza institucional con personificación pública.", "Organismos de titularidad pública de naturaleza institucional con personificación privada.", "Organismos de titularidad pública de naturaleza institucional con personificación pública.", "Ente de naturaleza corporativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 29, "De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Illes Balears, el nombramiento de las personas titulares de la gerencia y de los demás órganos unipersonales de dirección de los organismos autónomos corresponde :", "Al Consejo de Gobierno, mediante acuerdo.", "En la consejería de adscripción del organismo autónomo, mediante decreto.", "En la consejería de adscripción del organismo autónomo, mediante orden.", "En la consejería de dirección del organismo autónomo, mediante acuerdo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 30, "A los titulares de la gerencia y de los demás órganos de dirección de los entes del sector público instrumental de la Comunidad Autónoma de las Illes Balears les es de aplicación la normativa reguladora del régimen de incompatibilidades:", "De los miembros del Gobierno y de los altos cargos.", "Del personal al servicio de las administraciones públicas.", "Del personal alto cargo de la Administración general del Estado.", "Del Estatuto de los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 31, "Son organismos públicos del sector instrumental de la Comunidad Autónoma de las Islas Baleares:", "Los organismos autónomos y las entidades públicas empresariales.", "Los organismos autónomos y las fundaciones.", "Los organismos autónomos, las entidades públicas empresariales y los consorcios.", "Las entidades públicas empresariales y las agencias públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 32, "Los organismos públicos del sector instrumental de la Comunidad Autónoma de las Islas Baleares se crean mediante:", "Una ley.", "Un acuerdo del Consejo de Gobierno.", "Un decreto del Consejo de Gobierno, a propuesta de la consejería de adscripción del ente.", "Una orden de la consejería de adscripción del ente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 33, "De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Illes Balears, indique la respuesta correcta:", "El personal al servicio de los organismos autónomos del sector público instrumental de la Comunidad Autónoma de las Illes Balears depende orgánicamente de la persona titular de la consejería competente en materia de función pública y funcionalmente del órgano superior unipersonal de dirección del organismo autónomo.", "El personal al servicio de los organismos autónomos del sector público instrumental de la Comunidad Autónoma de las Illes Balears depende orgánica y funcionalmente de la persona titular de la consejería competente en materia de función pública.", "El personal al servicio de los organismos autónomos del sector público instrumental de la Comunidad Autónoma de las Illes Balears depende orgánica y funcionalmente del órgano superior unipersonal de dirección del organismo autónomo.", "El personal al servicio de los organismos autónomos del sector público instrumental de la Comunidad Autónoma de las Illes Balears depende orgánica y funcionalmente del consejero titular de la consejería de adscripción del ente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 34, "El personal al servicio de las sociedades mercantiles públicas del sector público instrumental de la Comunidad Autónoma de las Islas Baleares puede ser:", "Personal laboral propio.", "Personal laboral de otras administraciones que le sea adscrito.", "Personal funcionario y laboral de la Administración de la Comunidad Autónoma o de los organismos autónomos que le sea adscrito.", "Personal funcionario de cualquier administración pública que se incorpore por cualquier procedimiento de provisión u ocupación de puestos de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 35, "Los organismos de naturaleza privada de titularidad pública del sector público instrumental de la Comunidad Autónoma de las Islas Baleares:", "Tienen personalidad jurídica privada y en ningún caso pueden ejercer potestades administrativas.", "Tienen personalidad jurídica pública y en casos excepcionales pueden ejercer potestades administrativas.", "Tienen personalidad jurídica privada y pueden ejercer potestades administrativas cuando lo prevean los estatutos del ente.", "Tienen personalidad jurídica mixta sin que puedan ejercer potestades administrativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 36, "El acuerdo de creación de una sociedad mercantil pública del sector público instrumental de la Comunidad Autónoma de las Illes Balears debe adoptarse:", "A propuesta de la consejería interesada y con un informe preceptivo de la consejería competente en materia de hacienda y presupuestos", "A propuesta de la consejería interesada y con un informe vinculante de la consejería competente en materia de hacienda y presupuestos y de la Intervención General.", "A propuesta del Consejo de Gobierno y con un informe preceptivo y vinculante de la consejería competente en materia de hacienda y presupuestos.", "A propuesta de la consejería interesada y con un informe de la consejería competente en materia de hacienda y presupuestos y un informe de la consejería competente en materia del sector público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 37, "Indique la respuesta correcta respecto de los estatutos de las sociedades mercantiles públicas del sector público instrumental de la Comunidad Autónoma de las Illes Balears:", "Deben elevarse al Consejo de Gobierno junto con la propuesta de acuerdo por el que se autoriza su creación.", "Se elevarán al Consejo de Gobierno después de la publicación del acuerdo por el que se autoriza su creación.", "Los debe aprobar la Comisión de Análisis y Propuesta de Reestructuración del Sector Público.", "Se elevarán a la Comisión Interdepartamental de Retribuciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 38, "En las sociedades mercantiles públicas en las que la Administración de la Comunidad Autónoma de las Illes Balears sea titular del cien por cien del capital, las competencias de la junta general que, de acuerdo con la legislación societaria corresponden al socio único, las debe ejercer:", "El Consejo de Gobierno.", "El consejero titular de la consejería interesada.", "El consejero competente en materia de hacienda y presupuestos.", "El consejo de dirección del ente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 39, "La extinción de una sociedad mercantil pública del sector público instrumental de la Comunidad Autónoma de las Islas Baleares requiere:", "El acuerdo previo del Consejo de Gobierno, a propuesta de la consejería interesada y con un informe preceptivo de la consejería competente en materia de hacienda y presupuestos.", "El acuerdo previo del órgano de dirección del ente y un informe preceptivo de la consejería competente en materia de hacienda y presupuestos.", "El acuerdo previo del Consejo de Gobierno, a propuesta de la consejería interesada y con un informe preceptivo de la consejería competente en materia de hacienda y presupuestos y de la consejería competente en materia de función pública.", "El acuerdo previo del Consejo de Gobierno, a propuesta de la consejería interesada y con un informe vinculante de la consejería competente en materia de hacienda y presupuestos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 40, "De acuerdo con la disposición adicional cuarta de la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Illes Balears, la Agencia Tributaria de las Illes Balears debe regirse:", "Por su legislación específica y supletoriamente por las disposiciones de la Ley 7/2010, de 21 de julio, del sector público instrumental, aplicables a los organismos autónomos.", "Por las disposiciones de la Ley 7/2010, de 21 de julio, del sector público instrumental, aplicables a los organismos públicos.", "Por su legislación específica.", "Por su legislación específica y supletoriamente por las disposiciones de la Ley 7/2010, de 21 de julio, del sector público instrumental, aplicables a las entidades públicas empresariales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 41, "De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Illes Balears, indique la respuesta correcta respecto de la Mesa General del Sector Público Instrumental Autonómico:", "Se constituye como un órgano de desarrollo de las condiciones de trabajo comunes que puedan afectar al personal del conjunto de los entes del sector público instrumental de la Comunidad Autónoma de las Illes Balears.", "Se constituye como un órgano de consulta y coordinación de las condiciones de trabajo comunes que puedan afectar al personal del conjunto de los entes del sector público instrumental empresarial autonómico.", "Se constituye como un órgano de participación del personal en las cuestiones relativas a las condiciones de trabajo comunes que puedan afectar al personal del conjunto de los entes del sector público instrumental empresarial y fundacional autonómico.", "Se constituye como un órgano de consulta, vigilancia e interpretación del desarrollo de las condiciones de trabajo comunes que puedan afectar al personal del conjunto de los entes del sector público instrumental."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 42, "De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Islas Baleares, la Mesa General del Sector Público Instrumental Autonómico se adscribe:", "A la consejería competente en materia de función pública.", "En el Gabinete de la Presidencia.", "En la consejería competente en materia de hacienda y presupuestos.", "En la consejería competente en materia de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 43, "Los procedimientos relativos a la determinación de las condiciones retributivas del personal de los entes del sector público instrumental de la Comunidad Autónoma de las Illes Balears deben ajustarse:", "A las normas que contengan las leyes de presupuestos generales anuales de la Comunidad Autónoma de las Illes Balears.", "En las instrucciones que dicte la Comisión Interdepartamental de Retribuciones.", "A las directivos que marque la Comisión de Análisis y Propuesta de Reestructuración del Sector Público.", "A las propuestas aprobadas en la Comisión Paritaria del Sector Público Instrumental."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 44, "El consejo de administración, el patronato, la junta de gobierno o el órgano equivalente de los entes del sector público instrumental de la Comunidad Autónoma de las Illes Balears deben tener:", "Un mínimo de 7 miembros y un máximo de 13, según la dimensión de la entidad.", "Un mínimo de 5 miembros y un máximo de 13 miembros, según el tamaño de la entidad.", "La Ley 7/2010 no determina el mínimo y el máximo de miembros.", "El número de miembros que determinen entrega los estatutos de cada ente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 45, "Con carácter general, la mayoría de los miembros de la junta de gobierno de los entes del sector público instrumental de la Comunidad Autónoma de las Illes Balears deben ser designados, directa o indirectamente:", "Por órganos de la Administración de la Comunidad Autónoma o de entes del sector público instrumental.", "Por órganos de la Administración de la Comunidad Autónoma.", "Por órganos de ente del sector público instrumental o por órganos de ente de la Administración local.", "Por el Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 46, "Para la dirección, administración y gestión ordinaria, los entes del sector público instrumental de la Comunidad Autónoma de las Illes Balears pueden disponer:", "De una gerencia o de un órgano unipersonal equivalente.", "De un funcionario con rango de jefe de departamento.", "De personal directivo profesional.", "De personal eventual de gabinete."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 48, "El personal directivo profesional de las entidades de derecho público de la Comunidad Autónoma de las Islas Baleares tiene naturaleza funcionarial:", "En los casos en que tenga atribuidas funciones que impliquen la participación en el ejercicio de potestades administrativas.", "En ningún caso.", "En los casos en que lo determinen los estatutos del ente.", "En los casos de los entes del sector público instrumental empresarial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 49, "Indique la respuesta incorrecta. De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Illes Balears, los estatutos de los consorcios deben regular como mínimo:", "El órgano que ejerce el protectorado.", "La finalidad por la que el consorcio se constituye.", "El domicilio del consorcio.", "Las especialidades del régimen presupuestario, de contabilidad, de control y de tesorería."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 50, "Los entes incluidos en el sector público instrumental de la Comunidad Autónoma de las Islas Baleares están sometidos:", "Al control de eficacia y eficiencia que debe ejercer la consejería de adscripción.", "Al control de eficacia y eficiencia que deben ejercer conjuntamente la consejería de adscripción y la consejería competente en materia de hacienda y presupuestos.", "Al control de eficacia y eficiencia que debe ejercer la consejería competente en materia de hacienda y presupuestos, mediante la Intervención General.", "Al control de eficacia y eficiencia que debe ejercer la Sindicatura de Cuentas de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 51, "Indique la respuesta incorrecta:", "Las cuentas anuales de los entes del sector público instrumental de la Comunidad Autónoma de las Illes Balears deben enviarse a la Intervención General en los quince días posteriores a su formulación ya su aprobación.", "Las cuentas anuales de los entes del sector público instrumental de la Comunidad Autónoma de las Illes Balears deben enviarse a la Intervención General en los diez días posteriores a su formulación ya su aprobación.", "Los entes que conforman el sector público instrumental de la Comunidad Autónoma de las Illes Balears quedan sometidos al control de la Intervención General.", "Los estatutos de cada uno de los entes que conforman el sector público instrumental de la Comunidad Autónoma de las Illes Balears deben fijar los órganos obligados a formular y aprobar las cuentas anuales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 52, "Indique la respuesta correcta respecto de la coordinación y el control de la tesorería de los entes que integran el sector público instrumental de la Comunidad Autónoma de las Illes Balears:", "La llevará a cabo de forma centralizada la dirección general competente en materia de tesorería o el órgano que, en su caso, se establezca reglamentariamente.", "Corresponde a la dirección general competente en materia de presupuestos.", "Corresponde conjuntamente a la dirección general competente en materia de tesorería y a la Intervención General.", "Corresponde al Tribunal de Cuentas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 53, "Los entes que integran el sector público instrumental de la Comunidad Autónoma de las Illes Balears deben tener un plan financiero anual:", "En los términos y condiciones que reglamentariamente se establezcan.", "En los términos y condiciones que se establezcan por ley, aprobada por mayoría absoluta.", "En los términos y condiciones que determine un acuerdo del Consejo de Gobierno.", "En los términos y condiciones que fije el máximo órgano de dirección de cada ente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 54, "Para poder iniciar algún tipo de actividad con efectos económico-financieros, los entes que integran el sector público instrumental de la Comunidad Autónoma de las Illes Balears deben cumplir con el siguiente requisito:", "Haber aprobado el presupuesto del primer ejercicio.", "Haber nombrado a todos sus órganos directivos.", "Haber aprobado la relación de funciones de los puestos de trabajo del ente.", "Haberse adaptado a la disposición adicional decimoquinta de la Ley 15/2012, de 27 de diciembre, de presupuestos generales de la Comunidad Autónoma de las Illes Balears para el año 2013."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 55, "De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Illes Balears, indique el órgano competente para resolver los procedimientos de revisión de oficio de los actos nulos respecto de los actos dictados por el órgano superior de dirección de los organismos públicos:", "La persona titular de la consejería de adscripción del ente.", "La persona titular de la gerencia o el órgano unipersonal equivalente del ente.", "El consejo de dirección o el órgano equivalente del ente.", "La Comisión de Análisis y Propuesta de Reestructuración del Sector Público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 56, "La creación de un servicio específico de la Intervención General asignado a los entes del sector público instrumental de la Comunidad Autónoma de las Islas Baleares corresponde:", "Al Consejo de Gobierno.", "En la consejería competente en materia de hacienda y presupuestos.", "En la consejería competente en materia de función pública.", "Conjuntamente a la consejería competente en materia de hacienda y presupuestos ya la consejería competente en materia de función pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 57, "El asesoramiento jurídico de los entes del sector público instrumental de la Comunidad Autónoma de las Islas Baleares corresponde, en primer término:", "Al personal propio que tenga atribuida esta función en la relación de puestos de trabajo.", "A la Abogacía de la Comunidad Autónoma.", "Al personal de la Comisión de Análisis y Propuesta de Reestructuración del Sector Público.", "A los servicios jurídicos de la consejería competente en materia de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 58, "De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Islas Baleares, en los supuestos de extinción por desistimiento del empresario de los contratos de alta dirección de los entes del sector público instrumental autonómico, se tendrá derecho, en su caso, a una indemnización no superior:", "A siete días por año de servicio de la retribución anual en metálico, con un máximo de seis mensualidades.", "A seis días por año de servicio de la retribución anual en metálico, con un máximo de diez mensualidades.", "A siete días por año de servicio de la retribución anual en metálico, con un máximo de diez mensualidades.", "A doce días por año de servicio de la retribución anual en metálico, con un máximo de cuatro mensualidades."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 59, "Las competencias de dirección y supervisión centralizada de las nóminas del personal al servicio de los entes públicos del sector público instrumental de la Comunidad Autónoma de las Islas Baleares, las asume:", "La consejería competente en materia de coordinación del sector público instrumental.", "La consejería competente en materia de hacienda y presupuestos.", "La consejería competente en materia de registro de personal.", "La consejería competente en materia de trabajo y seguridad social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 60, "De acuerdo con la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Illes Balears, los estatutos de las fundaciones del sector público y sus modificaciones deben publicarse:", "En el Boletín Oficial de las Illes Balears.", "En el Boletín Oficial del Estado y en el Boletín Oficial de las Islas Baleares.", "En el Boletín Oficial del Registro Mercantil.", "En el portal de transparencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 7, 61, "De acuerdo con la disposición adicional décima de la Ley 7/2010, de 21 de julio, del sector público instrumental de la Comunidad Autónoma de las Illes Balears, antes de la aprobación de la norma que posibilite que las funciones desarrolladas por la Administración de la Comunidad Autónoma se atribuyan a otro ente, es necesario:", "Un informe previo y vinculante de la consejería competente en materia de función pública.", "Un informe preceptivo de la consejería competente en materia de función pública.", "Un informe previo y vinculante de la consejería competente en materia de hacienda y presupuestos.", "Un informe previo y vinculante de la consejería competente en materia de función pública y de la Intervención General."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 1, "En materia de actuación y funcionamiento del sector público por medios electrónicos, señale la respuesta incorrecta en relación al concepto de registro electrónico:", "Las Administraciones Públicas dispondrán de registros electrónicos para la recepción y remisión de solicitudes, escritos y comunicaciones, que deberán ser plenamente interoperables de manera que se garantice su compatibilidad informática e interconexión en los términos previstos en el artículo 16 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, y el artículo 60 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.", "Cada Administración dispondrá de un Registro Electrónico Central en el que hará asiento de todo documento que sea presentado o que se reciba en cualquier órgano administrativo, organismo público o entidad de derecho público vinculado o dependiente.", "Los organismos públicos y entidades de derechos público vinculados o dependientes de cada Administración podrán disponer de su propio registro electrónico plenamente interoperable e interconectado con el Registro Electrónico General de la Administración a la que estén vinculados o de la que dependan.", "Los registros electrónicos admitirám documentos electrónicos normalizados correspondientes a los servicios, procedimientos y trámites que se especifiquen conforme a lo dispuesto en la norma de creación del registro, cumplimentados de acuerdo con formatos preestablecidos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 2, "En materia de registro electrónico, el Registro Electrónico General es:", "Un registro electrónico del que dispondrá cada Administración Pública y en el que se realizará el asiento de cualquier documento que se presente o se reciba en cualquier órgano administrativo de esta administración. Aquellos organismos públicos o entidades de derecho público vinculado o dependiente de esta administración, dispondrán de su propio registro electrónico, plenamente interoperable e interconectado con el registro electrónico general de cuya administración dependan.", "Un registro electrónico del que dispondrá cada Administración Pública y en el que se realizará el asiento de cualquier documento que se presente o se reciba en cualquier órgano administrativo de esta administración, así como también en cualquier organismo público o entidad de derecho público vinculado o dependiente.", "Un registro electrónico del que dispondrá cada Administración Pública y en el que se realizará el asiento de cualquier documento que se presente o se reciba en cualquier órgano administrativo de esta administración. Aquellos organismos públicos o entidades de derecho público vinculado o dependiente de esta administración, podrán disponer de su propio registro electrónico, totalmente independiente del registro electrónico general de cuya administración dependan.", "Un registro electrónico del que dispondrá cada Administración Pública y en el que se realizará el asiento de cualquier documento que se presente o se reciba en cualquier órgano administrativo de esta administración, así como también en cualquier organismo público o entidad de derecho privado vinculado o dependiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 3, "Si un organismo público o entidad de derecho público opta por disponer de su propio registro electrónico, este registro debe ser:", "Plenamente interoperable e interconectado con el Registro Electrónico General de la Administración General del Estado.", "Plenamente interoperable, exportable en formato de datos abiertos e interconectado con el Registro Electrónico General de la Administración General del Estado.", "Plenamente interoperable e interconectado con el Registro Electrónico General de la Administración a la que esté vinculado o de la que dependa.", "Plenamente interoperable, exportable en formato de datos abiertos e interconectado con el Registro Electrónico General de la Administración a la que esté vinculado o de la que dependa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 4, "En materia de actuación y funcionamiento del sector público por medios electrónicos, ¿qué documentos admitirán los registros electrónicos?", "Documentos electrónicos interoperables correspondientes a los servicios, procedimientos y trámites que se especifiquen conforme a lo dispuesto en la norma de creación de registro, cumplimentados de acuerdo con formatos abiertos.", "Documentos electrónicos normalizados correspondientes a los servicios, procedimientos y trámites que se especifiquen conforme a lo dispuesto en la norma de creación de registro, cumplimentados de acuerdo con formatos abiertos.", "Documentos electrónicos digitalizados correspondientes a los servicios, procedimientos y trámites que se especifiquen  conforme a lo dispuesto en la norma de creación de registro, cumplimentados de acuerdo con formatos preestablecidos.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 5, "Si un interesado presenta en el Registro Electrónico General del Gobierno de las Illes Balears un documento, cuyo régimen especial establezca otra forma de presentación, ¿se tendrá por presentado?", "No, tal y como lo establecen el artículo 16.9 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, y el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.", "Sí, tal y como lo establecen el artículo 16.8 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, y el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.", "Sí, tal y como establece el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, que deroga el artículo 16.9 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas.", "No, tal y como establece el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 6, "De acuerdo con el artículo 37.4 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, no se tendrán por presentados en el registro aquellos documentos e información cuyo régimen especial establezca otra forma de presentación. En estos supuestos:", "El órgano ejecutivo competente para la tramitación del procedimiento notificará esta circunstancia al interesado y le informará de los requerimientos exigidos por la legislación específica aplicable.", "El órgano administrativo competente para la tramitación del procedimiento notificará esta circunstancia al interesado y le informará de los requisitos exigidos por la legislación específica aplicable.", "El órgano ejecutivo competente para la tramitación del procedimiento comunicará esta circunstancia al interesado y le informará de los requerimientos exigidos por la legislación específica aplicable.", "El órgano administrativo competente para la tramitación del procedimiento comunicará esta circunstancia al interesado y le informará de los requisitos exigidos por la legislación específica aplicable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 7, "¿Qué significa que los registros de todas y cada una de las Administraciones Públicas deben ser plenamente interoperables?", "Que garantizarán su compatibilidad informática e interconexión.", "Que garantizarán la transmisión telemática de los asientos registrales.", "Que garantizarán la transmisión telemática de los documentos que se presenten en cualquiera de los registros.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 8, "De acuerdo con el artículo 38 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, la presentación por medio del servicio electrónico para la presentación de solicitudes, escritos y comunicaciones que no dispongan de modelos normalizados de presentación, independientemente de las Administraciones Públicas u organismos públicos o entidades de derecho público vinculados o dependientes a las que vayan dirigidos:", "No genera ninguna anotación en el Registro Electrónico General de la Administración General del Estado. Este servicio electrónico es una pasarela de interconexión con el Registro Electrónico General de la administración u organismo al que va dirigido el asiento, registro al que se genera la anotación.", "Genera una anotación en el Registro Electrónico General de la Administración General del Estado.", "Este servicio electrónico debe ser accesible desde la sede electrónica del PAGe de la Administración General del Estado.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 9, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, ¿qué ámbito del sector público dispondrá de un registro electrónico de apoderamientos?", "El ámbito estatal.", "El ámbito autonómico.", "El ámbito local.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 10, "Los asientos que se efectúen en los registros electrónicos generales y particulares de apoderamientos deben tener un contenido mínimo de información. Señale cuál de las siguientes opciones no forma parte de este contenido mínimo obligatorio:", "Nombres y apellidos o la denominación o razón social, documento nacional de identidad, número de identificación fiscal o documento equivalente del apoderado.", "Tipo de poder.", "Archivo notarial.", "Periodo de tiempo por el que se otorga el poder."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 11, "De acuerdo con el artículo 6.3 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, uno de los datos obligatorios que deben contener los asientos que se realicen en los registros electrónicos generales y particulares de apoderamientos es:", "Fecha de caducidad del poder.", "Identificación del funcionario habilitado que registra el asiento.", "Fecha de inscripción.", "Número de días naturales por los que se otorga el poder."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 12, "¿Cuál es la actuación correcta en caso de que se detecte un código malicioso susceptible de afectar a la integridad o la seguridad del sistema en documentos que hayan sido registrados?", "Se anulará el asiento registral y se comunicará esta circunstancia al interesado para que pueda realizar la enmienda.", "No existe la posibilidad de registrar un código malicioso, ya que el registro electrónico general cumple con el Esquema Nacional de Seguridad, y no permite la recepción de documentos que no sigan formatos preestablecidos por la Norma Técnica de Interoperabilidad correspondiente.", "Se anulará el asiento registral y se notificará esta circunstancia al interesado para que pueda realizar la enmienda.", "Se debe requerir la subsanación al interesado que los haya aportado, de acuerdo con lo previsto en el artículo 14.3 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 13, "De acuerdo con el artículo 32 del Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos, la representación puede acreditarse mediante cualquier medio válido en Derecho que deje constancia fidedigna de su existencia, entre otros:", "Mediante el apoderamiento efectuado por comparecencia electrónica en las oficinas de asistencia en materia de registros o comparecencia personal en la correspondiente sede electrónica o sede electrónica asociada.", "Mediante la acreditación de su inscripción en el registro electrónico de apoderamientos de la Administración Pública competente o en sus registros particulares de apoderamientos.", "Mediante un certificado electrónico de representante.", "Mediante un documento privado cuya matriz conste en un archivo notarial o una inscripción practicada en un registro mercantil."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 14, "¿Qué reglamento regula el Registro Electrónico General de la Administración General del Estado?", "La Orden PCM/1382/2021, de 9 de diciembre.", "El Real Decreto 203/2021, de 30 de marzo, por el que se aprueba el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.", "El Real Decreto 113/2003, de 5 de noviembre.", "No existe ninguna normativa que lo regule."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 15, "Los registros electrónicos de todas y cada una de las Administraciones Públicas:", "Serán plenamente interoperables, de forma que se garantice su compatibilidad informática e interconexión, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en cualquiera de los registros.", "Estarán plenamente interconectados, de forma que se garantice su compatibilidad informática e intermediación, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en cualquiera de los registros.", "Serám plenamente interoperables, de forma que se garantice su compatibilidad informática e interconexión, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en un registro de la Administración u Organismo al que se dirijan.", "Estarán plenamente interconectados, de forma que se garantice su compatibilidad informática e intermediación, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en un registro de la Administración u Organismo al que se dirijan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 16, "El derecho a comunicarse con las administraciones públicas a través de un Punto de Acceso General electrónico de la Administración es propio de:", "Quienes de conformidad con el artículo 3 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, tienen capacidad jurídica frente a las administraciones públicas.", "Quienes de conformidad con el artículo 3 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, tienen capacidad de obrar ante las administraciones públicas.", "Quienes de conformidad con el artículo 3 de la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, tienen capacidad jurídica y capacidad de obrar ante las administraciones públicas.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 17, "El derecho a ser asistido en el uso de medios electrónicos en sus relaciones con las administraciones públicas es titularidad de:", "Las personas físicas, en general.", "Las personas físicas mayores de edad.", "Los ciudadanos y ciudadanas con capacidad jurídica.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 18, "¿Cuál de estos sujetos está obligado a recibir por medios electrónicos las notificaciones generadas por la Agencia Tributaria de las Illes Balears en el ejercicio de sus funciones?", "Las personas jurídicas.", "Los registradores de la propiedad, cuando deben relacionarse con la administración en ejercicio de su actividad profesional.", "Las comunidades de bienes.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 19, "Las notificaciones que la Consejería de Agricultura, Pesca y Alimentación debe practicar en el marco de un procedimiento administrativo a una comunidad de bienes, ¿se deben realizar por medios electrónicos?", "Verdadero.", "Sólo si el interesado lo solicita.", "Falso.", "Verdadero, dado que una comunidad de bienes tiene personalidad jurídica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 20, "¿Pueden las personas físicas elegir en todo momento si se comunican con las administraciones públicas para ejercer sus derechos y obligaciones a través de medios electrónicos?", "Sí, salvo en determinados casos.", "Sí, siempre.", "No siempre.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 21, "¿Está obligado un notario a relacionarse electrónicamente con las administraciones públicas?", "Sí, siempre.", "Sólo si debe realizar trámites en el ejercicio de su actividad profesional.", "Sí, siempre que esté colegiado.", "No."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 22, "Cuando una persona física no obligada a relacionarse electrónicamente con las administraciones públicas comunica su derecho a relacionarse por medios electrónicos, los efectos de la comunicación se producen:", "A partir del día siguiente a aquel en que el órgano competente para tramitar el procedimiento tenga constancia de la comunicación.", "A partir del quinto día hábil siguiente a aquel en que el órgano competente para tramitar el procedimiento tenga constancia de la comunicación.", "A partir del tercer día hábil siguiente a aquel en que el órgano competente para tramitar el procedimiento tenga constancia de la comunicación.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 23, "En caso de que una persona jurídica tenga que recibir una notificación de un procedimiento que debe iniciar de oficio la administración pública y ésta no tiene los datos de contacto electrónicos para hacer el aviso de la puesta a disposición, como debe efectuarse la notificación?", "En papel.", "Por medios electrónicos, poniendo la notificación a su disposición en la sede electrónica.", "Por medios electrónicos, poniendo la notificación a su disposición en la carpeta ciudadana.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 24, "En todo caso, están obligados a relacionarse a través de medios electrónicos con las administraciones públicas para realizar cualquier trámite de un procedimiento administrativo los siguientes sujetos:", "Quienes representan a un interesado que no esté obligado a relacionarse electrónicamente con la Administración.", "Las comunidades de propietarios.", "Los empleados de las administraciones públicas para realizar trámites y actuaciones personales.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 25, "De acuerdo con el artículo 14 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Las administraciones públicas pueden establecer la obligación de relacionarse con ellas a través de medios electrónicos para determinados procedimientos y para determinados colectivos de personas físicas que, por razón de su capacidad económica, técnica, dedicación profesional u otros motivos quede acreditado que tienen acceso y disponibilidad de los medios electrónicos necesarios.", "Las administraciones públicas pueden establecer reglamentariamente la obligación de relacionarse con ellas a través de medios electrónicos para determinados colectivos de personas físicas que, por razón de su capacidad económica, técnica y dedicación profesional quede acreditado que tienen acceso y disponibilidad de los medios electrónicos necesarios.", "Las administraciones públicas pueden establecer reglamentariamente la obligación de relacionarse con ellas a través de medios electrónicos para determinados procedimientos y para determinados colectivos de personas físicas que, por razón de su capacidad económica, técnica, dedicación profesional o otros motivos quede acreditado que tienen acceso y disponibilidad de los medios electrónicos necesarios.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 26, "¿En cuál de estas actividades profesionales es obligatorio relacionarse electrónicamente con las administraciones públicas en el ejercicio de sus funciones?", "Medicina.", "Farmacia.", "Notaría.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 27, "¿Las personas físicas están obligadas a relacionarse electrónicamente con las administraciones públicas?", "No, en general.", "En determinados casos sí.", "Algunos colectivos sí lo están.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 28, "Indique la respuesta correcta:", "Las personas interesadas que se relacionen con las administraciones públicas a través de medios electrónicos tienen derecho a consultar en el Punto de Acceso General electrónico el estado de la tramitación de los procedimientos.", "Las personas interesadas que se relacionen con las administraciones públicas a través de medios electrónicos tienen derecho a consultar en el Punto de Acceso General electrónico el órgano competente para instruir el procedimiento.", "Las personas interesadas que se relacionen con las administraciones públicas a través de medios electrónicos tienen derecho a consultar en el Punto de Acceso General electrónico los actos de trámite que se han dictado en el procedimiento.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 29, "¿Cuál de esta información tiene derecho a consultar en el Punto de Acceso General electrónico la persona interesada que se relaciona electrónicamente con las administraciones públicas?", "La identificación de las autoridades y personal al servicio de las administraciones públicas bajo cuya responsabilidad se tramita el procedimiento administrativo.", "Los actos de trámite dictados en el procedimiento.", "Los requisitos jurídicos o técnicos que las disposiciones vigentes impongan a los proyectos, actuaciones o solicitudes que se propongan realizar.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 30, "¿En qué caso la Administración puede obligar a las personas físicas a relacionarse con ella por medios electrónicos?", "En los procedimientos de concesión de subvenciones, para determinados colectivos, cuando esté previsto en un reglamento.", "Cuando lo establezca por ley para determinados colectivos de personas físicas.", "Cuando lo establezca por reglamento para determinados colectivos de personas físicas y procedimientos", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 31, "¿Cuál de estos principios generales no rige en las actuaciones y funcionamiento del sector público por medios electrónicos?", "El principio de facilidad de uso.", "El principio de personalización.", "El principio de planificación.", "El principio de proactividad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 32, "En relación con la actuación y funcionamiento del sector público por medios electrónicos, se entiende por el principio de personalización y proactividad:", "La capacidad de las administraciones públicas para proporcionar servicios precumplimentados y de anticiparse a las posibles necesidades de los usuarios finales del servicio, partiendo del conocimiento adquirido por éstos.", "La capacidad para diseñar los servicios electrónicos centrándose en las personas usuarias.", "No existe este principio general.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 33, "¿Están obligadas las comunidades autónomas a dar el servicio de información telefónica 012?", "Sí.", "No.", "Solo en el caso de los ayuntamientos.", "No, se trata de un servicio que debe ofrecer la Administración general del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 34, "¿Cuál de estas administraciones públicas no está obligada a ofrecer el servicio de información telefónica 012?", "No hay ninguna administración pública obligada a dar este servicio.", "Las comunidades autónomas.", "Los ayuntamientos.", "La Administración general del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 35, "¿Qué órgano directivo de la Administración de la Comunidad Autónoma de las Illes Balears desempeña las funciones en materia de atención a la ciudadanía?", "La Dirección General de Participación, Transparencia y Voluntariado.", "La Oficina de Atención en Materia de Registro.", "La Dirección General de Calidad y Servicios.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 36, "En relación con la atención a la ciudadanía, indique la respuesta correcta:", "La atención e información ciudadana es una competencia que ejerce la Consejería de Presidencia.", "La atención e información ciudadana es una competencia que ejerce la Dirección General de Calidad de los Servicios.", "La atención e información ciudadana es una competencia que ejerce la Consejería de Salud y Consumo.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 37, "Indique la respuesta correcta en relación con la asistencia en el uso de medios electrónicos:", "Las administraciones públicas deben garantizar que los interesados se puedan relacionar con la Administración a través de medios electrónicos, para lo que pondrán a su disposición los canales de acceso que sean necesarios.", "Las administraciones públicas deben garantizar que los ciudadanos puedan relacionarse con la Administración a través de medios electrónicos, para lo que pondrán a su disposición los canales de acceso que sean necesarios.", "Las administraciones públicas deben garantizar que las personas físicas puedan relacionarse con la Administración a través de medios electrónicos, para lo que pondrán a su disposición los canales de acceso que sean necesarios.", "Las administraciones públicas deben garantizar que las personas jurídicas se puedan relacionar con la Administración a través de medios electrónicos, para lo que pondrán a su disposición los canales de acceso que sean necesarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 38, "¿A quiénes deben asistir en el uso de medios electrónicos las administraciones públicas?", "A la ciudadanía.", "A los interesados, en determinados casos.", "A las personas físicas.", "A las personas jurídicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 39, "Indique la respuesta correcta. Si un ciudadano se presenta ante una oficina de asistencia en materia de registros para presentar una solicitud en una convocatoria de subvenciones:", "Será atendido en el uso de medios electrónicos, dependiendo del funcionario.", "Será asistido en el uso de medios electrónicos, especialmente en el caso de una empresa que carece de los medios electrónicos adecuados.", "Será asistido en el uso de medios electrónicos, salvo que el interesado sea una persona jurídica, entre otros casos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 40, "Si una persona presenta una solicitud en una convocatoria de ayudas ante una oficina de asistencia en materia de registros de la Administración autonómica y no dispone de firma electrónica:", "La oficina de asistencia en materia de registros no es un canal de atención a la ciudadanía si el procedimiento está publicado en la Sede Electrónica.", "La firma electrónica la podrá hacer cualquier funcionario, siempre que el interesado no sea una sociedad anónima.", "Las administraciones públicas deben garantizar que los interesados se puedan relacionar con la Administración a través de medios electrónicos.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 41, "Indique la respuesta correcta en relación con el Punto de Acceso General electrónico (PAGe):", "El PAGe dispondrá, al menos, de una sede electrónica, a través de la que se podrá acceder a determinados servicios.", "El PAGe debe facilitar el acceso a los servicios, trámites e información de los órganos, organismos públicos y entidades vinculados o dependientes de la Administración Pública correspondiente.", "La Sede Electrónica dispondrá de un Punto de Acceso General electrónico (PAGe), a través del que se podrán acceder a los servicios y trámites.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 42, "En relación con los canales de atención a la ciudadanía indique la respuesta correcta:", "Un canal es una estructura o medio de difusión de los contenidos y servicios, incluyendo el canal telefónico y el electrónico, así como otros que existan en la actualidad.", "Un canal es una estructura o medio de difusión de los contenidos y procedimientos, incluyendo el canal presencial y el electrónico, así como otros que existan en la actualidad o puedan existir en el futuro (dispositivos móviles, etc.).", "Un canal es una estructura o medio de difusión de los contenidos y servicios, incluyendo el canal presencial, el telefónico y el electrónico, así como otros que existan en la actualidad.", "Un canal es una estructura o medio de difusión de los contenidos y servicios, incluyendo el canal presencial, el telefónico y el electrónico, así como otros que existan en la actualidad o puedan existir en el futuro (dispositivos móviles, etc.)."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 43, "¿En qué tipo de canal debe ponerse a disposición de los interesados la información sujeta a las obligaciones de transparencia según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno?", "A través de los canales electrónicos, en particular en la página web.", "En la carpeta ciudadana.", "A través de los canales electrónicos, en particular la sede electrónica o página web.", "A través de los canales electrónicos, en particular la sede electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 44, "Indique la respuesta correcta en relación con la atención a la ciudadanía por medios electrónicos:", "Las administraciones públicas deben asistir en el uso de medios electrónicos a los interesados de un procedimiento administrativo si no disponen de los medios electrónicos necesarios.", "Las administraciones públicas deben asistir en el uso de medios electrónicos a la ciudadanía cuando así lo solicite.", "Las administraciones públicas deben asistir en el uso de medios electrónicos a determinados interesados de un procedimiento administrativo.", "Las administraciones públicas deben asistir en el uso de medios electrónicos a todos los interesados de un procedimiento administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 45, "¿La Administración pública debe asistir en el uso de medios electrónicos a una persona jurídica que tiene la condición de interesada en el procedimiento?", "Sí, dado que es una obligación de las administraciones públicas.", "Sólo si no dispone de los medios electrónicos necesarios.", "No.", "En determinados casos, como por ejemplo en lo referente a la identificación y firma electrónica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 46, "¿Qué hito marca la transformación de las oficinas de registro en oficinas de asistencia en materia de registros?", "La entrada en vigor de las previsiones de registro electrónico de apoderamientos, registro electrónico, registro de empleados públicos habilitados, punto de acceso general electrónico de la Administración y archivo único electrónico.", "El 2 de abril de 2002.", "La entrada en vigor de la Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 47, "Cuando un ciudadano comparece ante una oficina de asistencia en materia de registros (OAMR) para presentar una solicitud de una convocatoria de subvenciones:", "El empleado público digitalizará el documento.", "El OAMR no digitalizará el documento si la normativa aplicable exige que se presente el documento en un soporte específico no susceptible de digitalización.", "No se tendrán por presentados aquellos documentos cuyo régimen especial establezca otra forma de presentar los documentos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 48, "¿Qué órgano superior de la Administración de la Comunidad Autónoma de las Illes Balears tiene las funciones de ordenación y coordinación de las oficinas de asistencia en materia de registros (OAMR)?", "La Consejería de Presidencia, Función Pública e Igualdad.", "La Dirección General de Modernización y Administración Digital.", "La consejería competente en materia de administración digital.", "La Dirección General de Calidad de los Servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 49, "Según la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿qué nuevas funciones en materia de administración electrónica han pasado a asumir las oficinas de registro?", "La anotación electrónica de los asientos de entrada y salida.", "El cotejo y expedición de copias compulsadas de documentos originales.", "La digitalización de documentos presentados en papel.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 50, "En relación con las funciones de las oficinas de asistencia en materia de registros (OAMR), ¿qué debe hacerse si, una vez digitalizado un documento, éste no puede ser devuelto al interesado?", "Debe conservarse durante tres meses.", "Debe enviarse al interesado a través del NOTIB.", "Debe conservarse durante seis meses.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 51, "Cuando un documento se presenta ante una oficina de asistencia en materia de registros:", "Se hará el correspondiente asiento de todo documento que sea presentado. También se anotará la salida de documentos oficiales dirigidos a otros órganos o particulares.", "Se hará el correspondiente asiento de todo documento que sea presentado. También podrá anotarse la salida de los documentos oficiales dirigidos a otros órganos o particulares.", "Se hará el correspondiente asiento de todo documento que sea presentado. También se anotará la salida de documentos oficiales dirigidos a particulares.", "No se realizará ningún asentamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 52, "¿Cuál de estas funciones no está asignada a las oficinas de asistencia en materia de registros según el Real decreto 203/2021?", "La anotación, en su caso, de los asientos de salida de los documentos.", "La anotación de los documentos en el registro electrónico.", "La práctica de notificaciones mediante la aplicación NOTIB.", "La identificación o firma electrónica del interesado, salvo en el caso de personas jurídicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 53, "Indique la respuesta correcta. Los documentos en soporte no electrónico presentados a través de las oficinas de asistencia en materia de registros:", "Se digitalizarán y se devolverán los documentos originales.", "Se digitalizarán y se incorporarán al expediente administrativo electrónico.", "Se digitalizarán y se custodiarán si en ese momento no es posible devolver el documento original.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 54, "¿Qué debe hacer una oficina de asistencia en materia de registros si debe enviar un documento a otra Administración y el tamaño de éste excede la capacidad que permite el Sistema de Interconexión de Registros (SIR)?", "El envío puede sustituirse por la puesta a disposición de los documentos, previamente depositados en un repositorio de intercambio de ficheros.", "El documento debe archivarse dentro de un dispositivo interno de memoria USB (pen drive) y enviarse a través de un ordenanza.", "El envío debe sustituirse por la puesta a disposición de los documentos, previamente depositados en un repositorio de intercambio de ficheros.", "Todas las respuestas incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 55, "Entre las funciones de las nuevas oficinas de asistencia en materia de registros (OAMR), ¿se encuentra la de recibir la documentación presentada por una persona jurídica?", "No, porque las personas jurídicas no pueden presentar documentos en papel.", "Sí.", "No, sus funciones son las previstas en el artículo 16 de la Ley 39/2015, de 1 de octubre.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 56, "Si ante una oficina de asistencia en materia de registros (OAMR) alguno de los sujetos obligados a relacionarse electrónicamente con la Administración presenta su solicitud presencialmente:", "El OAMR no debe permitirle presentar documentación en papel.", "El OAMR le registrará la documentación, pero se le requerirá para que subsane la documentación.", "El OAMR tiene como función expresa asistir a los interesados en general.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 57, "¿Cuál de estas funciones es de las oficinas de asistencia en materia de registros (OAMR)?", "La digitalización de los documentos presentados de forma presencial.", "La asistencia en la identificación y firma electrónica a los interesados en general.", "La práctica de notificaciones a los interesados que comparecen espontáneamente en una OAMR y así lo soliciten.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 58, "Indique la respuesta correcta. Las administraciones públicas deben asistir en el uso de medios electrónicos a los interesados no incluidos en los apartados 2 y 3 del artículo 14 de la Ley 39/2015, de 1 de octubre:", "Cuando así lo soliciten, especialmente en lo referente a firma electrónica.", "Cuando así lo soliciten, especialmente en lo referente a obtener copias auténticas.", "Cuando así lo soliciten, especialmente en lo referente a digitalización de documentos.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 59, "Entre las funciones de las oficinas de asistencia en materia de registros (OAMR), ¿se encuentra la de practicar notificaciones electrónicas a las personas interesadas?", "En determinados casos, sí.", "No.", "Sí, a todos los efectos.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 60, "Una vez digitalizado un documento presentado por un interesado, ¿qué debe hacer la oficina de asistencia en materia de registros (OAMR)?", "Devolver una copia auténtica al interesado.", "Devolver el documento al interesado.", "Archivar el documento presentado.", "Destruir el documento presentado, en caso de que sea en papel."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 61, "La práctica de notificaciones electrónicas, ¿es una función de las oficinas de asistencia en materia de registros prevista en la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas?", "Sí.", "Siempre que dispongan de los medios electrónicos para su práctica.", "No.", "En determinados casos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 62, "Si después de registrar una queja o sugerencia se concluye que se refiere a otra administración o entidad pública del Estado español:", "La dirección general competente en materia de calidad de los servicios debe remitirla a la entidad objeto de la queja, comunicándoselo a la persona interesada.", "La unidad administrativa correspondiente debe remitirla a la entidad objeto de la queja y debe comunicarlo a la persona interesada.", "La unidad administrativa correspondiente inadmitirá la queja o sugerencia y lo comunicará a la persona interesada.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 63, "Cuáles de estos aspectos no regula la Orden de la consejera de Administraciones Públicas de 1 de agosto de 2014 por la que se desarrolla el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears:", "El modelo de la hoja de quejas y sugerencias.", "La forma y los medios de presentación de las quejas y sugerencias.", "La tramitación de las quejas y sugerencias mediante la aplicación de uso general QSSI.", "La información sobre el derecho y los sistemas de quejas y sugerencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 64, "Señale la respuesta incorrecta. La Orden de la consejera de Administraciones Públicas de 1 de agosto de 2014 por la que se desarrolla el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears se aplica a los servicios que prestan:", "Los consorcios en los que participa la Comunidad Autónoma de las Illes Balears.", "Las personas jurídicas adjudicatarias de contratos de servicios públicos.", "El sector público instrumental de la Comunidad Autónoma de las Illes Balears.", "Los ayuntamientos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 65, "En caso de que la respuesta a una queja o sugerencia presentados por un ciudadano no sea satisfactoria, este ciudadano puede:", "Interponer un recurso de alzada.", "Interponer una reclamación en vía administrativa.", "Dirigirse a la Inspección General de Calidad, Organización y Servicios.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 66, "El plazo de que dispone la Administración de la Comunidad Autónoma de las Illes Balears para resolver una queja o sugerencia es de:", "Quince días hábiles en el caso de las quejas; no existe plazo en el caso de las sugerencias.", "Quince días hábiles.", "Quince días naturales.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 67, "¿Es aplicable el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears a las personas jurídicas privadas?", "No.", "Sí, en determinados casos.", "Sí.", "Sólo en lo que se refiere a las quejas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 68, "Según el artículo 2 del Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears una queja es:", "Una manifestación o declaración efectuada por una persona física para hacer constar la disconformidad con la prestación de un servicio público.", "Una manifestación o declaración efectuada por una persona física o jurídica para hacer constar la disconformidad con la prestación de un servicio público o privado.", "Una manifestación o una declaración efectuada por los ciudadanos y ciudadanas para hacer constar la disconformidad con la prestación de un servicio público.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 69, "¿Quién es el órgano competente para resolver una queja o sugerencia dirigidas al Hospital Mateu Orfila?", "La Gerencia del IB-Salut.", "La Dirección del Hospital.", "La dirección general competente en materia de salud.", "El Departamento de Bienestar Social del Consejo Insular de Menorca."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 70, "¿Cuál es el órgano competente para resolver una queja o sugerencia según el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears?", "El órgano superior competente por razón de la materia, a excepción de quienes hagan referencia a la prestación de servicios sanitarios y asistenciales.", "La dirección general competente en materia de calidad de los servicios.", "La Dirección de los centros sanitarios, educativos, sociosanitarios y asistenciales en caso de que la queja o sugerencia haga referencia a la prestación de servicios de estos centros.", "Todas las respuestas son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 72, "Señale la respuesta correcta según indica el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de las quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears:", "Si transcurrido el plazo de quince días la persona interesada no ha obtenido una respuesta, puede dirigirse a la Inspección General de Calidad, Organización y Servicios, para que, como órgano inspector, lleve a cabo las actuaciones necesarias para conocer los motivos que hayan podido ocasionar falta de contestación y adoptar las medidas pertinentes.", "Si transcurrido el plazo de quince días naturales la persona interesada no ha obtenido una respuesta, puede dirigirse a la Inspección General de Calidad, Organización y Servicios, para que, como órgano inspector, lleve a cabo las actuaciones necesarias para conocer los motivos que hayan podido ocasionar la falta de contestación y adoptar las pertinentes medidas.", "Si transcurrido el plazo de quince días hábiles la persona interesada no ha obtenido una respuesta, puede dirigirse a la Inspección General de Calidad, Organización y Servicios, para que, como órgano inspector, lleve a cabo las actuaciones necesarias para conocer motivos que hayan podido ocasionar la falta de contestación y adoptar las medidas pertinentes.", "Si transcurrido el plazo de un mes la persona interesada no ha obtenido una respuesta, puede dirigirse a la Inspección General de Calidad, Organización y Servicios, para que, como órgano inspector, lleve a cabo las actuaciones necesarias para conocer los motivos que hayan podido ocasionar la falta de contestación y adoptar las pertinentes medidas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 73, "Señale la respuesta correcta en relación con las quejas y sugerencias relativas a servicios públicos de la Administración de la Comunidad Autónoma:", "La presentación de una queja no impide el ejercicio del derecho genérico de petición reconocido en el artículo 29 de la Constitución.", "La formulación de una queja tiene la calificación de recurso administrativo si cumple los requisitos del artículo 115 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas.", "La Ley orgánica 4/2001, de 12 de noviembre, reguladora del derecho de petición se aplica subsidiariamente en defecto de previsión del Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears.", "La formulación de una queja o sugerencia en ejercicio del derecho de petición se tramita de conformidad con la Ley orgánica 4/2001, de 12 de noviembre, reguladora del derecho de petición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 74, "En relación con las quejas y sugerencias, los órganos o entes que utilizan una aplicación distinta a la de uso general (QSSI) deben remitir a la dirección general competente en materia de atención e información ciudadana la siguiente información:", "Tiempo máximo de respuesta.", "Número de sugerencias que se han presentado.", "Materia o motivo de la queja o de la sugerencia.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 16, 75, "Indique la respuesta correcta en relación con las quejas y sugerencias:", "En cada consejería deben constituirse equipos de mejora encargados de analizar todas las quejas y sugerencias.", "En cada consejería y ente del sector público instrumental deben constituirse equipos de mejora encargados de analizar todas las quejas y sugerencias.", "Los equipos de mejora deben constituirse en el seno de los órganos y entes a los que les es de aplicación el Decreto 82/2009, de 13 de noviembre, por el que se regula la gestión de quejas y sugerencias sobre el funcionamiento de los servicios públicos de la Administración de la Comunidad Autónoma de las Illes Balears.", "En cada consejería y ente del sector público instrumental deben constituirse equipos de mejora o unidades administrativas especializadas encargados de analizar todas las quejas y sugerencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 1, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cuál de las siguientes respuestas no está incluida en el ámbito de aplicación de esta ley?", "La Administración General del Estado.", "La administración de la comunidad autónoma de las Illes Balears.", "Las sociedades mercantiles cuando, como mínimo, un 25% de su capital esté en manos de administraciones públicas.", "El Congreso de los diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 2, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso a la información pública cuando la información contuviera datos especialmente protegidos", "El derecho de acceso se ejercerá bajo declaración responsable de deber de sigilo.", "La publicidad sólo se llevará a cabo previa disociación de estos datos.", "La publicidad se llevará a cabo después del transcurso de 4 años.", "La publicidad se llevará a cabo en todo caso, dado que el derecho de acceso es preferente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 3, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las Administraciones Públicas publicarán:", "Los planes y programas anuales y plurianuales en los que se fijen objetivos concretos, aunque no las actividades y medios para su consecución.", "Los planes y programas anuales y plurianuales en los que se fijen objetivos genéricos, aunque no las actividades y medios para su consecución.", "Los planes y programas anuales y plurianuales en los que se fijen objetivos concretos, así como las actividades y medios para su consecución.", "Los planes y programas anuales y plurianuales en los que se fijen objetivos genéricos, así como las actividades y medios para su consecución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 4, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información de relevancia jurídica que deben publicar las administraciones públicas:", "La relación de los convenios suscritos.", "La información estadística necesaria para valorar el grado de cumplimiento y calidad de los servicios públicos que sean de su competencia.", "Las retribuciones percibidas anualmente por los altos cargos.", "Las directrices, instrucciones, acuerdos o circulares en la medida en que supongan una interpretación del Derecho o tengan efectos jurídicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 5, "De acuerdo con la Constitución Española, la ley regulará el acceso de los ciudadanos a los archivos y registros administrativos salvo:", "En lo que afecte a la seguridad y defensa del Estado, la averiguación de los delitos y la intimidad de las personas.", "En lo que afecte a los secretos de estado, la averiguación de los delitos y la intimidad de las personas.", "En lo que afecte a la seguridad y defensa del Estado, la averiguación de los delitos y al honor de las personas.", "En lo que afecte a los secretos de estado, la averiguación de los delitos y al honor de las personas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 6, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, entre los derechos de las personas en sus relaciones con las Administraciones Públicas se encuentra:", "El acceso a la información pública, archivos y registros.", "El derecho a solicitud y acceso a los expedientes y registros.", "El acceso a la información pública, expedientes y circulares.", "El derecho a solicitud y acceso a los archivos y circulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 7, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada contuviera datos personales que revelen la ideología, afiliación sindical, religión o creencias, y el afectado no hubiese hecho manifiestamente públicos los datos con anterioridad:", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y por escrito del afectado.", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso por cualquier medio del afectado.", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y en escritura pública del afectado.", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y por escrito del afectado o por comparecencia apud acta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 8, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada incluye datos personales que incluyesen datos genéticos o biométricos:", "El acceso únicamente se podrá autorizar en caso de tener el consentimiento expreso y por escrito del afectado, o que dicho afectado hubiese hecho manifiestamente públicos los datos con anterioridad.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso del afectado o si el acceso estuviera amparado por una norma con rango de ley.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso y por escrito del afectado.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso, por escrito o por comparecencia apud acta del afectado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 9, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿qué entidades están obligadas a publicar de forma periódica y actualizada la información relevante para garantizar la transparencia de su actividad?", "Cuando al menos el 50 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 10.000 euros.", "Cuando al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 10.000 euros.", "Cuando al menos el 50 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 5.000 euros.", "Cuando al menos el 40 % del total de sus ingresos anuales tengan carácter de ayuda o subvención pública, siempre que alcancen como mínimo la cantidad de 5.000 euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 10, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información institucional, organizativa y de planificación que deben publicar las administraciones públicas:", "Las cuentas anuales que deban rendirse.", "Información relativa a las funciones que desarrollan y la normativa que les sea de aplicación.", "La información estadística necesaria para valorar el grado de cumplimiento y calidad de los servicios públicos que sean de su competencia.", "La relación de los convenios suscritos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 11, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual de las siguientes respuestas no supondrá una limitación para ejercer el derecho de acceso.", "Los intereses económicos y comerciales.", "La política de alianzas militares.", "Las relaciones exteriores.", "La seguridad pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 12, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la aplicación de los límites al derecho de acceso:", "Siempre será justificada y se aplicará por igual a todos los casos, de acuerdo con el principio constitucional de igualdad.", "No siempre necesitará justificación y atenderá a las circunstancias del caso concreto.", "Siempre será justificada y atenderá a las circunstancias del caso concreto.", "No siempre necesitará justificación y se aplicará por igual a todos los casos, de acuerdo con el principio constitucional de igualdad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 13, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, cuando la información solicitada contenga datos personales pero estos datos no se encuentren especialmente protegidos, el órgano al que se dirija la solicitud:", "Concederá el acceso de inmediato sin posibilidad de recurso administrativo por parte de los afectados.", "Concederá el acceso si éste se efectúa previa disociación de los datos de carácter personal de modo que se impida la identificación de las personas afectadas.", "Concederá el acceso de inmediato con posibilidad de recurso administrativo por parte de los afectados.", "No concederá el acceso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 14, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el procedimiento para el ejercicio del derecho de acceso se iniciará con la presentación de la correspondiente solicitud, que deberá dirigirse:", "Al Portal de Transparencia de cada administración.", "Al Portal de Transparencia del Estado.", "Al Consejo de Transparencia y Buen Gobierno.", "Al titular del órgano administrativo o entidad que posea la información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 15, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Debe motivarse la solicitud de acceso a la información?", "Deberá estar motivada.", "No debe motivarse en ningún caso.", "No es obligatorio a motivar la solicitud, sin embargo, se puede motivar.", "La ausencia de motivación puede ser por si sola causa de rechazo de la solicitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 16, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la solicitud de información no identifica de forma suficiente la información solicitada:", "Se pedirá al solicitante que la concrete en un plazo de quince días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido, y de que no se suspende el plazo para dictar resolución.", "Se pedirá al solicitante que la concrete en un plazo de diez días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido, y de que no se suspende el plazo para dictar resolución.", "Se pedirá al solicitante que la concrete en un plazo de quince días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido, así como de la suspensión del plazo para dictar resolución.", "Se pedirá al solicitante que la concrete en un plazo de diez días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido, así como de la suspensión del plazo para dictar resolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 17, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso podrá ser limitado cuando acceder a la información suponga un perjuicio:", "Para la seguridad internacional.", "Para los intereses económicos y comerciales.", "Para los intereses políticos del gobierno.", "Para la igualdad de genero."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 18, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada pudiera afectar a derechos o intereses de terceros:", "Si están debidamente identificados, se les concederá un plazo de quince días para que puedan realizar las alegaciones que estimen oportunas.", "En todo caso, aun sin estar identificados, se les concederá un plazo de quince días para que puedan realizar las alegaciones que estimen oportunas.", "Si están debidamente identificados, se les concederá un plazo de diez días para que puedan realizar las alegaciones que estimen oportunas.", "En todo caso, aun sin estar identificados, se les concederá un plazo de diez días para que puedan realizar las alegaciones que estimen oportunas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 19, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, transcurrido el plazo máximo para resolver las solicitudes de información pública sin que se haya dictado y notificado resolución expresa:", "Se entenderá que la solicitud ha sido estimada.", "Se entenderá que la solicitud ha caducado.", "Se entenderá que la solicitud ha sido desestimada.", "Se entenderá que el solicitante ha renunciado a su solicitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 20, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la reclamación ante el Consejo de Transparencia y Buen Gobierno:", "Tendrá la consideración de sustitutiva de la rectificación de errores.", "Tendrá la consideración de sustitutiva del recurso de reposición.", "Tendrá la consideración de sustitutiva del recurso de alzada.", "Tendrá la consideración de sustitutiva del recurso extraordinario de revisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 21, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual de las siguientes solicitudes de información se inadmitirán a trámite?", "Las dirigidas a un órgano que no disponga de la información cuando se conozca el competente.", "Las relativas a información para cuya divulgación sea necesaria una acción previa de reelaboración.", "Las que contengan datos personales que incluyesen datos genéticos o biométricos.", "Las que contengan datos personales relativos a la comisión de infracciones penales o administrativas que no conllevasen la amonestación pública al infractor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 22, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la formalización del acceso a la información pública:", "Se realizará preferentemente por vía electrónica. Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a diez días.", "Se realizará preferentemente por vía electrónica. Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a un mes.", "Se realizará preferentemente por escrito en papel. Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a diez días.", "Se realizará preferentemente por escrito en papel. Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 23, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, a los efectos de la aplicación a sus responsables del régimen disciplinario, el incumplimiento de la obligación de resolver en plazo las resoluciones dictadas en materia de acceso a la información pública:", "Tendrá en todo caso la consideración de infracción muy grave.", "Tendrá en todo caso la consideración de infracción grave.", "Solo el incumplimiento reiterado se establece como infracción, que tendrá la consideración de grave.", "Tendrá la consideración de infracción grave pero si el incumplimiento es reiterado tendrá la consideración de infracción muy grave."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 24, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la reclamación ante el Consejo de Transparencia y Buen Gobierno se interpondrá:", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo.", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o de tres meses desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo.", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o de seis meses desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo.", "en el plazo de un mes a contar desde el día siguiente al de la notificación del acto impugnado o de dos meses desde el día siguiente a aquel en que se produzcan los efectos del silencio administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 25, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el plazo máximo para resolver y notificar la resolución de la reclamación ante el Consejo de Transparencia y Buen Gobierno:", "Será de dos meses, transcurrido el cual, la reclamación se entenderá estimada.", "Será de dos meses, transcurrido el cual, la reclamación se entenderá desestimada.", "Será de tres meses, transcurrido el cual, la reclamación se entenderá estimada.", "Será de tres meses, transcurrido el cual, la reclamación se entenderá desestimada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 26, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las resoluciones del Consejo de Transparencia y Buen Gobierno se publicarán:", "Por medios electrónicos y en los términos en que se establezca reglamentariamente.", "Por medios electrónicos y en los términos en que se establezca legalmente.", "En el diario oficial correspondiente y en los términos en que se establezca reglamentariamente.", "En el diario oficial correspondiente y en los términos en que se establezca legalmente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 27, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las resoluciones de las reclamaciones ante el Consejo de Transparencia y Buen Gobierno se comunicarán:", "Por el presidente del Consejo de Transparencia y Buen Gobierno al Defensor del Pueblo.", "Por el secretario del Consejo de Transparencia y Buen Gobierno al Gobierno.", "Por el presidente del Consejo de Transparencia y Buen Gobierno al Gobierno.", "Por el secretario del Consejo de Transparencia y Buen Gobierno al Defensor del Pueblo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 28, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las comunidades autónomas, para la resolución de la reclamación prevista en relación al derecho de acceso a la información pública:", "Deberán crear un órgano propio para resolverla.", "Podrán no ajustar su actuación a lo establecido en esta ley.", "Atribuirán esta competencia al Consejo de Transparencia y Buen Gobierno.", "Podrán atribuir esta competencia al Consejo de Transparencia y Buen Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 29, "De acuerdo con la Ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno de las Illes Balears, con relación al acceso de la ciudadanía a los archivos y registros de la Administración de la comunidad autónoma, ésta debe:", "Publicar en el BOIB las condiciones de acceso al conjunto de archivos y registros.", "Hacer públicas en el tablón de anuncios de cada consejería las condiciones de acceso al conjunto de archivos y registros.", "Hacer públicas en la página web de la administración, en un apartado específico, las condiciones de acceso al conjunto de archivos y registros.", "No tiene obligación de publicar las condiciones de acceso al conjunto de archivos y registros, dado que ya está regulado por ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 30, "¿Cual de las siguientes no es una actividad, de acuerdo con la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, que se deba llevar a cabo para conseguir el objetivo de garantizar la transparéncia del Gobierno abierto?", "Informar de forma clara y comprensible de los servicios, planes, programas y actividades que desarrollen.", "Publicar los proyectos de ley en el BOIB.", "Facilitar la rendición de cuentas.", "Garantizar la apertura y la publicitación de estadísticas y datos públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 31, "De acuerdo con la Ley 3/2003, de 26 de marzo, de Régimen Jurídico de la Administración de la Comunidad Autónoma de las Illes Balears, en relación al derecho de información:", "Cualquier ciudadano tiene derecho a ser informado de los asuntos que le afecten.", "Cualquier persona tiene derecho a ser informada de los asuntos que le afecten.", "Cualquier europeo tiene derecho a ser informado de los asuntos que le afecten.", "Cualquier interesado tiene derecho a ser informado de los asuntos que le afecten."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 32, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno,¿cuándo podrá ser limitado el derecho de acceso a la información pública relacionada con las relaciones exteriores?", "En ningún caso, prevaleciendo el derecho a la información.", "En todo caso, dado el carácter de las relaciones exteriores.", "Cuando la embajada del país afectado se oponga a ese derecho de acceso.", "Cuando acceder a la información suponga un perjuicio para las propias relaciones exteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 33, "De acuerdo con la Ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno de las Illes Balears, ¿Que supone incluir el principio de transparencia en el ejercicio de la gestión pública?", "Supone incluir la transparencia exclusivamente en el resultado de las políticas públicas.", "Supone incluir la transparencia tanto en la adopción de decisiones como en el desarrollo de la actividad pública.", "Supone incluir la transparencia en el desarrollo de la actividad pública pero no en la adopción de decisiones.", "Supone incluir la transparencia en el resultado de las políticas pero no en la adopción de decisiones ni en el desarrollo de la actividad pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 34, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso a la información pública se ejercerá:", "Sin límite dado que es un derecho constitucional.", "Tiene solo los límites regulados en la Constitución Española, ya que cualquier otra limitación vulneraría la Constitución.", "Tiene el límite derivado de la protección de datos de carácter personal.", "Tiene el límite temporal de 4 años desde que se resuelve el expediente al cual se pretende acceder."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 35, "De acuerdo con la Ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno de las Illes Balears, en relación a la publicidad activa de la contratación pública, cada órgano de contratación, una vez adjudicado el contrato,¿que información publicará en el Perfil del contratante?", "El adjudicatario", "El procedimiento de contratación utilizado.", "Las modificaciones del contrato adjudicado que representen un incremento igual o superior al 25% del precio inicial del contrato, si procede.", "El cuadro comparativo de las ofertas económicas y de las propuestas técnicas sin tener en cuenta las mejoras ofrecidas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 36, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada pudiera afectar a derechos o intereses de terceros, debidamente identificados, y se les ha concedido un plazo para presentar alegaciones:", "Se suspende el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de veinte días para su presentación.", "Se suspende el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de quince días para su presentación.", "No es obligatorio suspender el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de veinte días para su presentación.", "No es obligatorio suspender el plazo para dictar resolución hasta que se hayan recibido las alegaciones o haya transcurrido el plazo de quince días para su presentación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 37, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la resolución en la que se conceda o deniegue el acceso a la información pública deberá notificarse:", "Al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de tres meses desde la recepción de la solicitud.", "Unicamente al solicitante en el plazo máximo de tres meses desde la recepción de la solicitud.", "Unicamente al solicitante en el plazo máximo de un mes desde la recepción de la solicitud.", "Al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de un mes desde la recepción de la solicitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 38, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, las comunidades autónomas, para atribuir la competencia para la resolución de la reclamación prevista en relación al derecho de acceso al Consejo de Transparencia y Buen Gobierno:", "Deberán celebrar el correspondiente convenio con la Administración General del Estado.", "Deberán celebrar el correspondiente contrato con la Administración General del Estado.", "Deberán realizar la correspondiente encomienda de gestión con la Administración General del Estado.", "No pueden atribuir dicha competencia al Consejo de Transparencia y Buen Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 39, "De acuerdo con la Ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno de las Illes Balears, en relación a la publicidad activa de la contratación pública, ¿qué contratos se publicarán en el perfil del contratante?", "Todos los contratos cuya cuantía supere la cifra de 40.000 euros en los contratos de obras y de 12.000 euros en el resto de contratos.", "Todos los contratos cuya cuantía supere la cifra de 40.000 euros en los contratos de obras y de 9.000 euros en el resto de contratos.", "Todos los contratos cuya cuantía supere la cifra de 25.000 euros en los contratos de obras y de 12.000 euros en el resto de contratos.", "Todos los contratos cuya cuantía supere la cifra de 25.000 euros en los contratos de obras y de 9.000 euros en el resto de contratos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 40, "De acuerdo con la Ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno de las Illes Balears, el principio de responsabilidad y rendición de cuentas supone que la administración y el gobierno de las Illes Balears:", "Formarán las cuentas anuales de la Administración de la comunidad autónoma y se rendirán a la Sindicatura de Cuentas", "Deben informar sobre la ejecución del presupuesto al Parlamento Balear.", "Deben promocionar e impulsar la cultura de la evaluación y el ejercicio de rendición de cuentas en todas sus actuaciones", "Deben promocionar e impulsar la rendición de cuentas por la intervención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 41, "Según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, en relación a la protección de los datos de carácter personal, será necesario el consentimiento expreso y por escrito del afectado para datos relativos a:", "Origen racial.", "Salud.", "Ideología.", "Vida sexual"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 42, "Según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de las siguientes respuestas no indica un miembro de la Comisión de Transparencia y Buen Gobierno?", "Un representante de la Autoridad Independiente de Responsabilidad Fiscal.", "Un representante de la Agencia Española de Protección de Datos.", "Un representante del Instituto de las Mujeres.", "Un Senador."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 43, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique la respuesta falsa:", "La publicidad activa y el derecho de acceso fomentan la transparencia y la participación en la actividad pública.", "En la publicidad activa la Administración pone los datos a disposición de la ciudadanía, en portales y páginas web, siempre que los ciudadanos los demanden, proactivamente.", "En el derecho de acceso a la información pública la Administración responde a las demandas de información por parte de los ciudadanos.", "El derecho de acceso a la información pública podrá ser limitado de forma justificada y proporcionada a su objeto y finalidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 44, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el Consejo de Transparencia y Buen Gobierno, se configura como:", "Órgano incardinado en la estructura del Ministerio competente en Función Pública.", "Organismo público adscrito al actual Ministerio de Hacienda y Función Pública.", "Órgano previsto en el Título IV de la Constitución Española.", "Consejo interterritorial en el que están representados el Estado y las Comunidades Autónomas y las entidades locales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 45, "¿Qué Consejería gestiona el Portal de Transparéncia de la Comunidad Autónoma de las Illes Balears?", "Consejería de Presidencia, Función Pública e Igualdad.", "Consejería de Transición Energética, Sectores Productivos y Memoria Democrática.", "Consejería de Fondos Europeos, Universidad y Cultura.", "Consejería de Hacienda y Relaciones Exteriores"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 46, "De acuerdo con la Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas, entre los principios de buena regulación se encuentran:", "Els de transparencia y eficiencia.", "El de eficiencia pero no el de transparencia.", "El de transparencia pero no el de eficiencia.", "Ninguno de los dos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 47, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual de las siguientes respuestas no supondrá una limitación para ejercer el derecho de acceso.", "La política económica y monetaria.", "Las funciones administrativas de vigilancia, inspección y control.", "La protección del medio ambiente.", "La garantía de la confidencialidad en los procesos penales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 48, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de los siguientes datos personales se podrían revelar sin autorización del afectado si una norma con rango de ley lo amparara?", "Datos personales que hagan referencia a la salud.", "Datos personales que revelen la ideología.", "Datos personales que revelen la afiliación sindical.", "Datos personales que revelen la religión o creencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 49, "De acuerdo con la Ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno de las Illes Balears, en relación a la publicidad activa de la contratación pública, cada órgano de contratación, una vez adjudicado el contrato,¿que información publicará en el Perfil del contratante?", "Las modificaciones del contrato adjudicado que representen un incremento igual o superior al 10% del precio inicial del contrato, si procede.", "Las modificaciones del contrato adjudicado que representen un incremento igual o superior al 20% del precio inicial del contrato, si procede.", "Las modificaciones del contrato adjudicado que representen un incremento igual o superior al 30% del precio inicial del contrato, si procede.", "Las modificaciones del contrato adjudicado que representen un incremento igual o superior al 40% del precio inicial del contrato, si procede."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 50, "Señale la respuesta correcta respecto a la solicitud de acceso a la información pública según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno:", "La resolución en la que se conceda o deniegue el acceso a deberá notificarse al solicitante y a los terceros afectados que así lo hayan solicitado en el plazo máximo de un mes desde la recepción de la solicitud por el órgano competente para resolver.", "Transcurrido el plazo máximo para resolver sin que se haya dictado y notificado resolución expresa se entenderá que la solicitud ha sido estimada.", "Las resoluciones dictadas en materia de acceso a la información pública no son recurribles directamente ante la Jurisdicción Contencioso-administrativa.", "El incumplimiento reiterado de la obligación de resolver en plazo tendrá la consideración de infracción muy grave a los efectos de la aplicación a sus responsables del régimen disciplinario previsto en la correspondiente normativa reguladora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 51, "Si un ciudadano solicita información a la Administración y son de aplicación los límites de derecho de acceso previstos en el artículo 14 de la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno pero estos límites no afectan a la totalidad de la información:", "Se ofrecerá acceso parcial sin indicar al solicitante que parte de la información ha sido omitida.", "Nunca se concederá el acceso parcial a la información.", "Se concederá el acceso parcial previa omisión de la información afectada por el límite de acceso, salvo que de ello resulte una información distorsionada o que carezca de sentido.", "Siempre se concederá acceso parcial a la información a la que no le afecte la limitación prevista en el artículo 14."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 52, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el Consejo de Transparencia y Buen Gobierno:", "No tiene personalidad propia por ser un órgano dependiente del Ministerio competente en Función Pública.", "Tiene personalidad jurídica propia pero no plena capacidad de obrar", "Tiene personalidad jurídica propia y plena capacidad de obrar.", "No tiene personalidad jurídica propia pero sí independencia funcional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 53, "¿Qué Dirección General coordina y supervisa que los diferentes responsables de cada ámbito de información la publiquen y la revisen periódicamente la información en el Portal de Transparencia de la Comunidad Autónoma de las Illes Balears?", "La Dirección General de Coordinación, Relaciones con el Parlamento, Derechos y Diversidad.", "La Dirección General de Relaciones Exteriores.", "La Dirección General de Servicios Sociales.", "La Dirección General de Participación, Transparencia y Voluntariado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 54, "Si un ciudadano no encuentra la información que busca en el Portal de transparencia,¿qué puede hacer para obtenerla?", "Solicitar dicha información a la administración, ejerciendo el derecho de acceso a la información pública, mientras el procedimiento no haya finalizado.", "Presentar un recurso contencioso-administrativo.", "Solicitar dicha información a la administración, ejerciendo el derecho de acceso a la información pública.", "Presentar un recurso ante el Consejo de Transparencia y Buen Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 55, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique cual de las siguientes respuestas no supondrá una limitación para ejercer el derecho de acceso:", "La política económica y monetaria.", "Los intereses económicos y comerciales.", "Las funciones administrativas de vigilancia, inspección y control.", "La protección de la agricultura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 56, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la información solicitada incluyese datos personales que hagan referencia a datos relativos a la comisión de infracciones penales o administrativas que no conllevasen la amonestación pública al infractor:", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso del afectado o si aquel estuviera amparado por una norma con rango de ley.", "El acceso solo se podrá autorizar en caso de que se cuente con el consentimiento expreso y por escrito del afectado.", "El acceso solo se podrá autorizar en caso de que aquel estuviera amparado por una norma con rango de ley.", "El acceso no se podrá autorizar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 57, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual de las siguientes solicitudes de información se inadmitirán a trámite?", "Las que contengan datos personales relativos a la comisión de infracciones penales o administrativas que no conllevasen la amonestación pública al infractor.", "Las que sean manifiestamente repetitivas.", "Las que contengan datos personales que incluyesen datos genéticos o biométricos.", "Las que contengan datos personales que hagan referencia a la vida sexual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 58, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual es el plazo máximo para notificar la resolución en la que se conceda o deniegue el acceso a la información pública?", "Un mes desde la recepción de la solicitud por el órgano competente para resolver, sin posibilidad de ampliación de plazo.", "Tres meses desde la recepción de la solicitud por el órgano competente para resolver, sin posibilidad de ampliación de plazo.", "Un mes desde la recepción de la solicitud por el órgano competente para resolver, con posibilidad de ampliarse por otro mes de acuerdo con la ley.", "Tres meses desde la recepción de la solicitud por el órgano competente para resolver, con posibilidad de ampliarse por otros 3 meses de acuerdo con la ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 59, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿Cual de los siguientes es un motivo para ampliar el plazo máximo para notificar la resolución en la que se conceda o deniegue el acceso a la información pública?", "Falta de medios materiales para resolver en plazo.", "Tener acumulación de expedientes.", "Falta de medios personales.", "La complejidad de la información que se solicita."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 60, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la reclamación ante el Consejo de Transparencia y Buen Gobierno:", "Podrá interponerse con carácter obligatorio y previo a su impugnación en vía contencioso-administrativa.", "Podrá interponerse con carácter obligatorio y previo al recurso de alzada o de reposición que corresponda.", "Podrá interponerse con carácter potestativo y previo al recurso de alzada o de reposición que corresponda.", "Podrá interponerse con carácter potestativo y previo a su impugnación en vía contencioso-administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 61, "La Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, establece que el incumplimiento reiterado de las obligaciones de publicidad activa reguladas en el capitulo II del título I de la Ley, tendrá la consideración:", "De infracción muy grave a los efectos de aplicación, a sus responsables, del régimen disciplinario previsto en la correspondiente normativa reguladora.", "De infracción grave a los efectos de aplicación, a sus responsables, del régimen disciplinario previsto en la correspondiente normativa reguladora.", "De infracción leve a los efectos de aplicación, a sus responsables, del régimen disciplinario previsto en la correspondiente normativa reguladora.", "De amonestación a sus responsables, a los efectos del régimen disciplinario previsto en la correspondiente normativa reguladora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 62, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información económica, presupuestaria y estadística que deben publicar las administraciones públicas:", "Las resoluciones de autorización o reconocimiento de compatibilidad que afecten a los empleados públicos.", "Información relativa a las funciones que desarrollan.", "Los planes y programas anuales y plurianuales en los que se fijen objetivos concretos.", "Los Anteproyectos de Ley y los proyectos de Decretos Legislativos cuya iniciativa les corresponda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 63, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, indique la respuesta correcta:", "La publicidad activa responde a las demandas de información por parte de los ciudadanos.", "La Transparencia pública puede ser por publicidad activa y publicidad pasiva.", "La Transparencia pública puede ser por publicidad activa y por derecho de acceso a la información pública.", "La publicidad pasiva no responde a demandas de información, ya que la ciudadanía toma un papel pasivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 64, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la aplicación de los límites al derecho de acceso:", "Deberán aplicarse de la misma forma a todas las solicitudes por el principio de interdicción de la arbitrariedad de los poderes públicos.", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de interéses exclusivamente públicos.", "Atenderá a las circunstancias del caso concreto, especialmente a la concurrencia de un interés público o privado.", "Atenderá a las circunstancias del caso concreto, sin atender a otros posibles intereses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 65, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, la solicitud de acceso a la información deberá permitir tener constancia en todo caso de la siguiente información:", "La identidad del solicitante e información que se solicita.", "La identidad del solicitante, información que se solicita y una dirección de contacto.", "La identidad del solicitante, información que se solicita, motivación de la consulta y una dirección de contacto.", "La identidad del solicitante, información que se solicita, los afectados por la revelación de los datos y una dirección de contacto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 66, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de los siguientes datos personales se podrían revelar sin autorización del afectado si una norma con rango de ley lo amparara?", "Datos personales que revelen el origen racial.", "Datos personales que revelen la afiliación sindical.", "Datos personales que revelen la religión o creencias.", "Datos personales que revelen la ideología."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 67, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, el derecho de acceso a la información pública significa:", "Que todos los ciudadanos de la Unión Europea tienen derecho a acceder a la información pública.", "Que todos los españoles tienen derecho a acceder a la información pública.", "Que todas las personas tienen derecho a acceder a la información pública.", "Que todos los ciudadanos de la Unión Europea y de aquellos países, que hayan subscrito un convenio, tienen derecho a acceder a la información pública."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 68, "El derecho de acceso a la información pública regulado en la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, supone para las administraciones públicas la obligación:", "De hacer públicas determinadas informaciones de forma proactiva y gratuita.", "De atender las solicitudes de información que hagan los ciudadanos de forma gratuita.", "De hacer públicas determinadas informaciones de forma proactiva, pudiendo establecer una tasa.", "De atender las solicitudes de información que hagan los ciudadanos, pudiendo establecer una tasa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 69, "La Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, en su artículo 36 indica que en la composición de la Comisión de Transparencia y Buen Gobierno se incluye:", "Un representante de la Intervención General de la Administración del Estado.", "Un representante de la Abogacía del Estado.", "Un representante de la Secretaría de Estado de Políticas Públicas.", "Un representante de la Autoridad Independiente de Responsabilidad Fiscal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 70, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información económica, presupuestaria y estadística que deben publicar las administraciones públicas:", "Las subvenciones y ayudas públicas concedidas.", "Los proyectos de reglamentos cuya iniciativa les corresponda.", "Las memorias e informes que conformen los expedientes de elaboración de los textos normativos.", "Los anteproyectos de ley y los proyectos de decretos legislativos cuya iniciativa les corresponda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 71, "Según la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, en relación a la protección de los datos de carácter personal, se podrá acceder cuando este acceso estuviera amparado por una norma con rango de ley para datos relativos a:", "Afiliación sindical.", "Religión.", "Ideología.", "Vida sexual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 72, "De acuerdo con la Ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno de las Illes Balears, en relación a la publicidad activa de la contratación pública, ¿durante cuanto tiempo se mantendrá publicada la información en la web?", "Durante todo el ejercicio presupuestario, además de mantener la información de los 4 ejercicios inmediatamente anteriores.", "Durante 3 ejercicios presupuestarios.", "Durante todo el ejercicio presupuestario, además de mantener la información del ejercicio inmediatamente anterior.", "Durante todo el ejercicio presupuestario, además de mantener la información de los 3 ejercicios inmediatamente anteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 73, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, si la solicitud de información no identifica de forma suficiente la información solicitada:", "Se pedirá al solicitante que la concrete en un plazo de diez días.", "Se pedirá al solicitante que la concrete en un plazo de quince días.", "Se pedirá al solicitante que la concrete en un plazo de un mes.", "Se inadmitirá la solicitud, sin perjuicio de poder volver a presentarla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 74, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, ¿cual de los siguientes datos personales se podrían revelar si el afectado los hubiese hecho manifiestamente públicos con anterioridad?", "Datos personales que incluyesen datos genéticos o biométricos.", "Datos personales que hagan referencia a la vida sexual.", "Datos personales relativos a la comisión de infracciones penales o administrativas que no conllevasen la amonestación pública al infractor.", "Datos personales que revelen la religión o creencias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 15, 75, "De acuerdo con la Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno, señale que información pública se corresponde a Información de relevancia jurídica que deben publicar las administraciones públicas:", "Las memorias e informes que conformen los expedientes de elaboración de los textos normativos.", "Información relativa a su estructura organizativa.", "Las cuentas anuales que deban rendirse.", "Información relativa a las funciones que desarrollan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 1, "¿Quién dirige la acción del Gobierno y coordina las funciones de los demás miembros del Gobierno:", "El ministro de la Presidencia.", "El presidente del Gobierno.", "El Consejo de ministros.", "La Comisión General de Secretarios de Estado y Subsecretarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 2, "El Gobierno ejerce:", "La función legislativa y la potestad reglamentaria de acuerdo con la Constitución y las leyes.", "La función ejecutiva y la potestad legislativa de acuerdo con la Constitución y las leyes.", "La función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.", "La función ejecutiva y la potestad reglamentaria y administrativa de acuerdo con la Constitución y las leyes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 3, "El candidato a la Presidencia del Gobierno lo propone:", "El presidente del Congreso, previa consulta al rey y a los representantes designados por los grupos políticos con representación parlamentaria.", "El presidente del Congreso, previa consulta con los representantes designados por los grupos políticos con representación parlamentaria.", "El rey, previa consulta con los portavoces de los grupos políticos que concurrieron a las elecciones.", "El rey, previa consulta con los representantes designados por los grupos políticos con representación parlamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 4, "El candidato a la Presidencia del Gobierno propuesto conforme a lo previsto en el artículo 99.1 de la Constitución:", "Expondrá al rey el programa político del Gobierno que pretenda formar.", "Expondrá ante las Cortes Generales el programa político del Gobierno que pretenda formar.", "Expondrá al Congreso de los Diputados el programa político del Gobierno que pretenda formar.", "Expondrá ante las Mesas de las Cámaras el programa político del Gobierno que pretenda formar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 5, "El candidato a la Presidencia del Gobierno propuesto conforme a lo previsto en el artículo 99.1 de la Constitución:", "Solicitará la confianza del pueblo español.", "Solicitará la confianza de las Cortes Generales.", "Solicitará la confianza del Congreso de los Diputados.", "Solicitará la confianza de su Grupo Parlamentario."); 
