insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 7, "Si en segunda votación el candidato a la Presidencia del Gobierno no obtiene la confianza del Congreso de los Diputados:", "El rey nombrará presidente del Gobierno al representante del Grupo Parlamentario con mayor representación en el Congreso de los Diputados.", "Se disolverán las Cámaras y se procederá a la convocatoria de nuevas elecciones.", "Se tramitarán sucesivas propuestas en la forma prevista en la Constitución.", "Se procederá a una tercera y última votación, entendiéndose otorgada la confianza si obtiene la mayoría de los votos de los miembros presentes del Congreso de los Diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 8, "Los miembros del Gobierno distintos del presidente son nombrados y separados:", "Por el presidente del Congreso de los Diputados.", "Por el rey.", "Por el presidente del Gobierno.", "Por el Consejo de ministros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 9, "Conforme al artículo 101 de la Constitución, el Gobierno cesa:", "Por incapacidad de su presidente.", "Tras la convocatoria de elecciones generales.", "Tras la celebración de elecciones generales.", "Tras la proclamación de los resultados electorales."); 
