insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 12, "La Administración Pública actúa:", "Con sometimiento pleno a la Constitución, a la ley y al Derecho.", "Con sometimiento pleno a la ley y al Derecho.", "Con sometimiento único a la ley y al Derecho.", "Con sometimiento pleno a la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 13, "Según el artículo 103 de la Constitución, se regularán por ley:", "El régimen de nombramientos de los funcionarios públicos.", "Todas las respuestas son correctas.", "Las peculiaridades del régimen sanitario del personal laboral.", "El sistema de incompatibilidades y las garantías para la imparcialidad en el ejercicio de sus funciones de los funcionarios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 14, "Las Fuerzas y Cuerpos de Seguridad tienen como misión:", "Garantizar la soberanía e independencia de la Nación.", "Garantizar la seguridad de las instituciones.", "Todas las respuestas son correctas.", "Proteger el libre ejercicio de los derechos y libertades."); 
