insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 16, "Señala la respuesta correcta. Conforme al artículo 105 de la Constitución, la ley regulará:", "La audiencia de los ciudadanos y empresarios en el procedimiento de elaboración de las disposiciones administrativas que les afecten.", "La audiencia de los ciudadanos, directamente o a través de las organizaciones y asociaciones reconocidas por la ley en el procedimiento de elaboración de las disposiciones administrativas que les afecten.", "La audiencia de los ciudadanos en el procedimiento de elaboración de todo tipo de disposiciones administrativas.", "La audiencia de los empresarios en el procedimiento de elaboración de las disposiciones administrativas que les afecten."); 
