insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 40, "Según dispone el artículo 26 de la Ley 50/1997, la Memoria del Análisis de Impacto Normativo, en el procedimiento de elaboración de normas con rango de Ley y de los reglamentos, incluirá:", "El impacto por razón de género.", "El impacto sobre los derechos de la infancia.", "El análisis sobre la adecuación de la norma aprobada al orden legalmente establecido en base a criterios nacionales e internacionales.", "Todas las respuestas anteriores son correctas."); 
