insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 53, "De su gestión política, el Gobierno responde:", "Individualmente ante las Cámaras.", "Solidariamente ante las Cortes Generales.", "Solidariamente ante el Congreso de los Diputados.", "Mancomunadamente ante las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 54, "Según el artículo 109 de la Constitución podrán recabar la información y ayuda que precisen del Gobierno y de sus Departamentos:", "Únicamente el Congreso de los Diputados y sus Comisiones.", "Únicamente, las Cámaras y sus Comisiones.", "Únicamente las Cámaras.", "Únicamente el Senado y sus Comisiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 55, "En relación con los miembros del Gobierno y según el texto del artículo 110 de la Constitución Española:", "Tienen la facultad de hacerse oír en las Cámaras y sus Comisiones.", "Sólo tienen la facultad de hacerse oír en las Cámaras pero no en sus Comisiones.", "No podrán solicitar que informen ante las Cámaras el personal funcionario de sus Departamentos.", "Tienen derecho a voto en las Cámaras y en las Comisiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 56, "El Gobierno estará sometido a las interpelaciones y preguntas que se le formulen en las Cámaras. Para esta clase de debate:", "Los Reglamentos establecerán un tiempo mínimo en cada Sesión.", "Los Reglamentos establecerán un tiempo mŽínimo mensual.", "Los Reglamentos establecerán un tiempo mínimo semanal.", "Los Reglamentos establecerán un tiempo mínimo por cada período de sesiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 57, "¿Quién puede plantear la cuestión de confianza, conforme al artículo 112 de la Constitución?:", "El presidente del Gobierno, previa deliberación del Consejo de Estado.", "El presidente del Gobierno, previa deliberación del Consejo de ministros.", "El Consejo de ministros, a través del presidente del Gobierno.", "El presidente del Gobierno, bajo su exclusiva responsabilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 58, "El presidente del Gobierno puede plantear la cuestión de confianza:", "Sobre una situación política especial.", "Sobre una declaración de política especial.", "Sobre una declaración de política general.", "Sobre un asunto de interés público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 59, "De acuerdo con el artículo 113 de la Constitución, la moción de censura deberá incluir:", "Los candidatos a ocupar todos los Ministerios.", "Los candidatos a ocupar los puestos de vicepresidente o vicepresidentes, si existieran.", "Un candidato a la Presidencia del Gobierno.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 60, "De acuerdo con la Constitución, la moción de censura será votada:", "No antes de que transcurran tres días desde su presentación.", "A los cinco días de su presentación.", "No antes de que transcurran cinco días desde su presentación.", "A los tres días de su presentación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 61, "¿Qué ocurre si una moción de censura no fuera aprobada por el Congreso?:", "Sus signatarios no podrán presentar otra durante el mismo período de sesiones.", "Sus signatarios no podrán presentar otra durante la misma legislatura.", "No se podrá presentar otra durante el mismo período de sesiones.", "No se podrá presentar otra durante la misma legislatura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 62, "Señala la respuesta correcta. Si el Congreso de los Diputados adopta una moción de censura:", "El candidato incluido en la moción de censura se entenderá investido de la confianza de la Cámara a los efectos previstos en el artículo 99.", "El Gobierno presentará su dimisión al rey.", "Todas las respuestas son correctas.", "El rey nombrará presidente del Gobierno al candidato incluido en la moción de censura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 63, "¿Quién puede decretar la disolución del Congreso, del Senado o de las Cortes Generales, de acuerdo con el artículo 115 de la Constitución?:", "El presidente del Gobierno, previa deliberación del Consejo de ministros.", "El rey.", "El presidente del Gobierno, bajo su exclusiva responsabilidad.", "El Consejo de ministros, a propuesta del presidente del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 64, "Señala la respuesta correcta. En relación con la disolución del Congreso, del Senado o de las Cortes Generales del artículo 115 de la Constitución:", "No procederá una nueva disolución antes de que transcurra un año desde la anterior, salvo lo dispuesto en el artículo 99.5 o durante la vigencia de los estados de alarma, excepción o de sitio.", "En ningún caso procederá nueva disolución hasta que transcurra  antes de que transcurra un año desde la anterior.", "No procederá una nueva disolución antes de que transcurra un año desde la anterior, salvo lo dispuesto en el artículo 99.5.", "En ningún caso procederá nueva disolución antes de que transcurran seis meses desde la anterior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 65, "Los estados de alarma, de excepción y de sitio se regularán mediante una Ley orgánica, así como:", "La suspensión de alguno de los poderes del Estado.", "Las competencias y limitaciones correspondientes.", "Las funciones asumidas por los órganos estatales durante su vigencia.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 66, "El estado de alarma será declarado:", "Por un plazo máximo de veinte días.", "Por un plazo máximo de quince días.", "Por un plazo máximo de diez días.", "Sin plazo máximo de duración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 67, "El Decreto que acuerde el estado de alarma determinará:", "Los derechos y libertades que quedarán suspendidos durante el tiempo de la declaración.", "El ámbito territorial a que se extienden los efectos de la declaración.", "La autoridad que ejercerá los poderes del Estado en el ámbito territorial afectado.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 68, "La autorización y proclamación del estado de excepción deberá determinar expresamente:", "Los efectos del mismo.", "Todas las respuestas son correctas.", "Su duración.", "El ámbito territorial a que se extiende."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 69, "El estado de sitio será declarado:", "Por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno.", "Por la mayoría simple del Congreso de los Diputados, a iniciativa propia.", "Por el Gobierno, a propuesta del Congreso de los Diputados.", "Por la mayoría absoluta del Congreso de los Diputados, a iniciativa propia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 70, "Durante la vigencia de los estados definidos en el artículo 116 de la Constitución:", "El funcionamiento de todos los poderes constitucionales pasará a ser ejercido por el Congreso de los Diputados.", "No podrá interrumpirse el funcionamiento de ambas Cámaras ni el de los demás poderes constitucionales del Estado.", "El funcionamiento de todos los poderes constitucionales pasará a ser ejercido por el Senado.", "El funcionamiento de todos los poderes constitucionales pasará a ser ejercido por las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 71, "¿Qué órgano tiene competencia para mantener relaciones con las comunidades autónomas y convocar Conferencias Sectoriales?:", "El Delegado del Gobierno.", "El ministro.", "El Secretario de Estado.", "El Subsecretario de Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 72, "La Jefatura del Estado, ¿es un órgano de la Administración del Estado?:", "Si, es el órgano supremo.", "No, ya que es ejercida por la Corona.", "Si, pero jerárquicamente depende de la Presidencia del Gobierno.", "No, ya que es un órgano inexistente en la actualidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 74, "La creación o modificación de las Comisiones Delegadas del Gobierno se acordará mediante:", "Real Decreto acordado en Consejo de ministros.", "Ley ordinaria.", "Ley orgánica.", "Orden de Comisiones Delegadas de gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 75, "La representación de un Ministerio, por delegación de un ministro, corresponde:", "Al Subsecretario del Departamento.", "Al Secretario de Estado del Departamento.", "Al Director General del Departamento que designe el ministro.", "Al Secretario General Técnico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 76, "En la Administración General del Estado, pueden dictar circulares e instrucciones a los inferiores a su Departamento:", "Los Directores Generales.", "Los Subsecretarios.", "Los Secretarios de Estado.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 77, "Señala la respuesta correcta. El Subdelegado del Gobierno, donde exista:", "Asume la representación del Gobierno en el territorio de la Comunidad Autónoma.", "Depende directamente de la Presidencia del Gobierno.", "Es nombrado por un período máximo de dos años entre personas de reconocida competencia profesional.", "Todas las respuestas anteriores son incorrectas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 2, 78, "En las comunidades autónomas uniprovinciales, suple al Delegado del Gobierno en su ausencia:", "El Subdelegado del Gobierno más antiguo.", "El Subdelegado del Gobierno que designe el Delegado del Gobierno.", "El Secretario General si no existe el subdelegado.", "El Director Insular."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 1, "Indique la respuesta correcta en relación con el Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales) en vigor:", "En el título se indica la periodicidad: 2021-2024.", "En el título se indica la periodicidad: 2021-2025.", "En el título se indica la periodicidad: 2020-2023.", "No se indica ninguna periodicidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 2, "Indique la respuesta correcta en relación con el Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales) en vigor:", "Es el primer Plan de estas características aprobado en la Administración de la Comunidad Autónoma de las Illes Balears.", "Es el segundo Plan de estas características aprobado en la Administración de la Comunidad Autónoma de las Illes Balears.", "Es el tercer Plan de estas características aprobado en la Administración de la Comunidad Autónoma de las Illes Balears.", "Es el cuarto Plan de estas características aprobado en la Administración de la Comunidad Autónoma de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 3, "Aprobar el Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales) corresponde:", "A la persona titular de la consejería competente en materia de igualdad.", "A la persona titular de la consejería competente en materia de derechos laborales.", "A la persona titular de la consejería competente en materia de presidencia.", "Al Consejo de Gobierno por acuerdo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 4, "El ámbito de aplicación del Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales):", "Solo afecta el personal funcionario representado a Mesa Sectorial de Servicios Generales.", "Se hace extensivo a todo el personal funcionario representado a Mesa Sectorial de Servicios Generales y al personal laboral de servicios generales que presta servicios en la Administración de la Comunidad Autónoma de las Illes Balears.", "Se hace extensivo al personal docente.", "Se hace extensivo al personal estatutario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 5, "Indique la respuesta correcta en relación con la estructura del Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales):", "Los objetivos se despliegan en medidas, pero no en acciones.", "Los ejes se despliegan en objetivos, medidas y acciones.", "Los ejes se despliegan en acciones, pero no en medidas.", "Solo hay ejes y medidas, pero no objetivos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 6, "Indique la respuesta correcta en relación con la estructura del Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales) en vigor:", "Hay un total de cinco ejes.", "Hay un total de tres ejes.", "Hay un total de cuatro ejes.", "No hay ninguna respuesta correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 7, "Indique la respuesta correcta en relación con los ejes del Plan de Igualdad del personal de servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears:", "Dos de los ejes son el de cultura de igualdad y el de situaciones de especial protección.", "Dos de los ejes son el de cultura de igualdad y el de medidas de difusión del Pla.", "Dos de los ejes son el de salud y riesgos laborales y el de medidas de coordinación del Plan.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 8, "Indique la respuesta correcta en relación con las acciones del Plan de Igualdad del personal de servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears:", "Las acciones programadas tienen un carácter meramente organizacional.", "Las acciones programadas se tienen que ejecutar en su totalidad en cualquier caso.", "Se pueden aprobar nuevas acciones o introducir las modificaciones que se consideren pertinentes si durante la ejecución del Plan la Comisión Técnica lo considera conveniente.", "Se pueden aprobar nuevas acciones que tiene que ratificar el Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 9, "Son objetivos del Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales):", "Avanzar en la lucha contra la violencia de género.", "Integrar la perspectiva de género en la normativa y en la gestión de los recursos humanos.", "Fomentar la conciliación de la vida personal, familiar y laboral.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 10, "Indique la respuesta incorrecta en relación con las medidas del Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales):", "Se tienen que realizar estudios para saber si hay diferencias retributivas no fundamentadas en criterios objetivos.", "Campañas de sensibilización específicas para el personal docente y estatutario en materia de igualdad.", "Acciones de formación y sensibilización para fomentar la coresponsabilitat familiar.", "Revisión, mejora y difusión del Protocolo de movilidad en los casos de violencia de género."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 11, "Son acciones del Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales) en vigor las siguientes:", "Organizar una jornada dirigida a altos cargos y personal directivo para sensibilizarlos en materia de igualdad de género.", "Revisar el Protocolo para prevenir y actuar en caso de acoso y proponer modificaciones como resultado del análisis de su aplicación.", "Incorporar la perspectiva de género en todos los estudios y trabajos y en las evaluaciones de riesgos laborales que haga el Servicio de Prevención.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 12, "Una de las competencias que tiene que ejercer la Dirección General de Función Pública en esta legislatura es:", "La gestión, el impulso y la coordinación de los planes estratégicos del sector público instrumental autonómico.", "La gestión, el impulso y la coordinación de los planes sectoriales del sector público instrumental autonómico.", "La gestión, el impulso y la coordinación de las políticas y los planes de igualdad entre las mujeres y los hombres empleados públicos de los servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears y del sector público instrumental autonómico.", "La gestión, el impulso y la coordinación de las políticas y los planes de igualdad entre las mujeres y los hombres empleados públicos de los servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 13, "El Decreto 12/2014, de 28 de febrero, de la Comunidad Autónoma de las Illes Balears (modificado por el Decreto 12/2017 de 31 de marzo), creó:", "La Comisión Técnica de Seguimiento del Plan de Igualdad y la Comisión de Igualdad.", "La Comisión Técnica de Evaluación del Plan de Igualdad y la Comisión de Igualdad.", "La Comisión de Seguimiento de las Políticas de Igualdad.", "La Comisión de Evaluación de las Políticas de Igualdad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 14, "El seguimiento y la evaluación del Plan de Igualdad del personal de servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears se realizará:", "Mediante una evaluación externa formada por personas expertas.", "Mediante una auditoría externa constituida por personal cualificado.", "A partir de una batería de indicadores directamente relacionados con los objetivos que se pretenden lograr.", "A partir de una autoevaluación de los resultados logrados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 15, "El seguimiento y la evaluación del Plan de Igualdad del personal de servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears se realizará:", "Mediante una temporalización adecuada para conseguir una evaluación continua.", "Mediante una temporalización adecuada que permita hacer los ajustes y las modificaciones que sean necesarios.", "Mediante un informe de evaluación intermedia y un informe de evaluación final.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 16, "¿Se harán públicos los datos del seguimiento y la evaluación del Plan de Igualdad del personal de servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears?", "Sí, para dar transparencia a todo el proceso.", "Sí, aunque solo el informe final.", "No, los resultados son de carácter interno para facilitar la mejora de las políticas de igualdad.", "No, puesto que son datos sensibles que no se pueden publicar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 17, "¿Dónde hay personal con funciones específicas relacionadas con la igualdad de género que tiene que colaborar con la implantación de las medidas de igualdad aprobadas y con la evaluación de los objetivos programados en el Plan de Igualdad del personal de servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears?", "En cada consejería y dirección general.", "En cada dirección general y organismo autónomo.", "En cada consejería y organismo autónomo del ámbito de aplicación del Plan de Igualdad del personal de servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears.", "Solo en el Instituto Balear de la Mujer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 18, "Las áreas de mejora sobre las que debe incidir el Plan de Igualdad del personal de servicios generales de la Administración de la Comunidad Autónoma de las Illes Balears actualmente en vigor son:", "Aumentar la efectividad de las campañas de sensibilización contra la violencia de género con métodos nuevos.", "Favorecer la presencia de las mujeres en lugares singularizados, sobre todo de nivel alto.", "Continuar con la difusión de los protocolos de movilidad y de actuación en caso de acoso.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 19, "Indique la respuesta correcta en relación con la Guía para una comunicación no sexista de la Administración de la Comunidad Autónoma de las Illes Balears:", "Hay que tenerla en cuenta solo para redactar textos normativos.", "Hay que tenerla en cuenta solo para redactar textos administrativos.", "Hay que tenerla en cuenta porque contiene recomendaciones que pretenden visibilizar las mujeres en detrimento de los hombres.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 20, "Indique la respuesta incorrecta en relación con los tópicos sobre el lenguaje no sexista recogidos en la Guía para una comunicación no sexista de la Administración de la Comunidad Autónoma de las Illes Balears:", "El lenguaje no sexista genera un exceso de uso de determinadas palabras.", "El lenguaje no sexista es un hecho que solo afecta los hombres.", "El lenguaje no sexista no es necesario si no hay mala intención.", "El lenguaje no sexista es un hecho que solo afecta las mujeres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 21, "Indique la respuesta correcta en relación con las recomendaciones que recoge la Guía para una comunicación no sexista de la Administración de la Comunidad Autónoma de las Illes Balears:", "Tenemos que utilizar un lenguaje no sexista porque hay que evitar la ambigüedad que se produce cuando utilizamos términos masculinos a veces como genéricos y a veces como exclusivamente masculinos.", "Tenemos que utilizar un lenguaje no sexista porque los hombres y las mujeres somos diferentes.", "Tenemos que utilizar un lenguaje no sexista para luchar contra las discriminaciones de los hombres y de las mujeres.", "Tenemos que utilizar un lenguaje no sexista porque el sexismo perjudica la salud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 22, "Indique la respuesta correcta en relación con la vigencia del actual Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales):", "La vigencia de este Plan es desde la fecha que se apruebe hasta el día 31 de diciembre de 2024.", "La vigencia de este Plan es desde la fecha que se apruebe hasta el día 31 de diciembre de 2024, si bien se entenderá en vigor hasta que sea sustituido por un nuevo plan de igualdad.", "La vigencia de este Plan es desde la fecha que se apruebe hasta el día 31 de diciembre de 2023.", "La vigencia de este Plan es desde la fecha que se apruebe hasta el día 31 de diciembre de 2025."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 23, "Indique la respuesta incorrecta en relación con el Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales):", "El Eje de Salud y Riesgos Laborales es un eje completamente nuevo.", "En Planes anteriores sí que se habían programado acciones relacionadas con la introducción de la perspectiva de género en la prevención de riesgos laborales.", "Uno de los objetivos del Eje de Salud y Riesgos Laborales es mejorar la información disponible para conseguir más eficacia en la aplicación del Plan de Igualdad.", "Uno de los objetivos del Eje de Salud y Riesgos Laborales es reforzar la perspectiva de género en la salud física y psíquica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 24, "Indique la respuesta correcta en relación con el Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales):", "Prevé acciones de formación y campañas informativas para la prevención del acoso sexual y por razón de sexo o de orientación sexual y otras formas de violencia de género.", "Prevé acciones de formación de actualización dirigida a las personas que han realizado el curso de asesoría confidencial.", "Prevé acciones para incorporar a la Guía práctica de corresponsabilidad familiar un nuevo apartado destinado a combatir los estereotipos existentes en cuanto a la asunción de las responsabilidades de las tareas del hogar y de la cura de los hijos e hijas y otras personas en situación de dependencia.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 25, "Indique la respuesta incorrecta en relación con el Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales):", "Dispone de un objetivo para favorecer el empoderamiento de las mujeres.", "Dispone de un objetivo para dificultar el acceso de los hombres a lugares directivos.", "Dispone de un objetivo para integrar la perspectiva de género en la normativa y en la gestión de los recursos humanos.", "Dispone de un objetivo para conseguir el acceso y la promoción en igualdad entre los dos sexos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 26, "De conformidad con el artículo 3 de la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo.", "El principio de igualdad de trato entre mujeres y hombres supone un trato no igualitario y no discriminatorio entre mujeres y hombres.", "El principio de igualdad de trato entre mujeres y hombres supone un retroceso en la convivencia en nuestra sociedad.", "El principio de igualdad de trato entre mujeres y hombres supone un reto importante por nuestra sociedad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 27, "Indique la respuesta correcta en relación con las acciones positivas que establece la Ley orgánica3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "Los poderes públicos adoptarán medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres.", "Las medidas tienen que ser aplicables en tanto que subsistan las situaciones de desigualdad.", "Las medidas tienen que ser razonables y proporcionadas en relación con el objetivo perseguido en cada caso.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 28, "Indique la respuesta incorrecta en relación con el fomento de la igualdad, que regula el artículo 6 de la Ley orgánica1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "Las administraciones educativas velarán para que en todos los materiales educativos se eliminen los estereotipos sexistas.", "Las administraciones educativas velarán para que todos los materiales educativos fomenten el igual valor de hombres y de mujeres.", "Las administraciones educativas fomentarán la educación desagregada por sexos.", "Las administraciones educativas velarán para que en todos los materiales educativos se eliminen los estereotipos discriminatorios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 29, "Las acreditaciones de víctimas de violencia de género, que regula la Ley orgánica1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "Se podrán realizar mediante documentos sanitarios oficiales de comunicación a la Fiscalía o al órgano judicial.", "Se podrán realizar mediante declaraciones de otros menores de edad ante las fuerzas y cuerpos de seguridad del Estado.", "Se podrán realizar mediante declaraciones de familiares ante las fuerzas y cuerpos de seguridad del Estado.", "Las personas menores de edad no pueden ser víctimas de violencia de género."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 30, "Diseñar los procedimientos básicos que permiten poner en marcha los sistemas de acreditación de las situaciones de violencia de género regulados por la Ley orgánica1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género, es una competencia que corresponde:", "Al Gobierno central.", "A las administraciones autonómicas.", "A las comisiones de igualdad de cada administración autonómica.", "Al Gobierno central y a las comunidades autónomas, de mutuo acuerdo, en el marco de la conferencia sectorial de igualdad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 31, "De acuerdo con la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "Constituye discriminación directa por razón de sexo cualquier trato desfavorable relacionado con el embarazo o la maternidad.", "Constituye discriminación indirecta por razón de sexo cualquier trato desfavorable relacionado con el embarazo o la maternidad.", "Constituye acción directa cualquier trato favorable relacionado con el embarazo o la maternidad.", "El embarazo y la maternidad no tienen nada que ver con la discriminación por razón de sexo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 32, "Según la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Las mujeres víctimas de violencia de género serán consideradas colectivos prioritarios en el acceso a viviendas de protección oficial.", "Las mujeres víctimas de violencia de género serán consideradas colectivos prioritarios en el acceso a residencias públicas por gente mayor.", "Las mujeres víctimas de violencia de género solo tendrán prioridad para acceder a residencias privadas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 33, "De acuerdo con la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Las administraciones públicas de las Illes Balears tienen que tomar medidas con el objeto de fomentar la corresponsabilidad en la vida laboral, la familiar y la personal de las mujeres y los hombres.", "Las administraciones públicas de las Illes Balears tienen que tomar medidas con el objeto de fomentar la corrseponsabilitat en la vida laboral, la familiar y la personal de las mujeres y los hombres, teniendo en cuenta los nuevos modelos de familia.", "Las administraciones públicas tienen que tomar medidas de conciliación solo en casos de familias numerosas.", "Las administraciones públicas tienen que tomar medidas de conciliación solo en casos de familias monoparentales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 34, "Según la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "También se consideran víctimas de violencia las personas que convivan con la víctima.", "También se consideran víctimas de violencia las personas que tengan parentesco con la víctima.", "También se consideran víctimas las hijas y los hijos de la madre víctima de la violencia.", "solo se consideran víctimas las mujeres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 35, "Según la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres, ¿cuál es el máximo órgano de participación de carácter autonómico que tiene la finalidad de favorecer el asociacionismo y la participación de las mujeres en los temas que les puedan afectar?", "El Consejo de Participación de la Mujer Trabajadora.", "El Consejo de Participación de la Mujer.", "El Observatorio de Participación de las Mujeres.", "La Comisión de Participación de la Mujer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 36, "Indique la respuesta correcta en relación con el V Plan Estratégico de Igualdad entre Mujeres y Hombres de las Illes Balears (2021-2023):", "El Instituto Balear de la Mujer es el órgano encargado de elaborarlo, con la colaboración de las consejerías correspondientes.", "Tienen que participar en él los consejos insulares y las entidades locales.", "Tienen que participar en él los agentes sociales y económicos y las asociaciones en defensa de los derechos de las mujeres de las Illes Balears.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 37, "De acuerdo con la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Las administraciones públicas de las Illes Balears tienen que garantizar un uso no sexista del lenguaje.", "Las administraciones públicas de las Illes Balears podrán garantizar un uso no sexista del lenguaje.", "Las administraciones públicas de las Illes Balears podrán fomentar el uso del lenguaje sexista.", "Las administraciones públicas de las Illes Balears no pueden interferir en el uso del lenguaje sexista."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 38, "Verificar la incorporación de la perspectiva de género en las memorias de los programas presupuestarios de la Comunidad Autónoma corresponde:", "A la consejería competente en materia de hacienda, con la participación del Instituto Balear de la Mujer.", "A la consejería competente en materia de igualdad,con la participación del Instituto Balear de la Mujer.", "A la consejería competente en materia de fondos europeos.", "A la consejería competente en materia de coordinación del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 39, "Según la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres informará la actuación de todos los poderes públicos.", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres informará, con carácter transversal, la actuación de todos los poderes públicos.", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres no hace falta que se integre, de forma activa, en la adopción y la ejecución de disposiciones normativas.", "El principio de igualdad de trato y de oportunidades entre mujeres y hombres no está regulado en esta normativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 40, "Indique la respuesta correcta en relación con la definición de planes de igualdad de las empresas en conformidad con la Ley orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres:", "Son un conjunto ordenado de medidas, adoptadas después de realizar un diagnóstico de situación, con la intención de lograr la igualdad de trato y de oportunidades entre mujeres y hombres.", "Son un conjunto ordenado de medidas, adoptadas después de realizar un diagnóstico de situación, con la intención de eliminar la discriminación por razón de sexo.", "Son un conjunto ordenado de medidas con la intención de hacer una evaluación de las conductas sexistas de las empresas.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 41, "Indique la respuesta correcta en relación con la obligatoriedad de las empresas de disponer de un plan de igualdad según la normativa en vigor:", "Están obligadas a disponer de planes de igualdad las empresas de cincuenta o más personas trabajadoras.", "Están obligadas a disponer de planes de igualdad las empresas entre cien y ciento cincuenta personas trabajadoras.", "Están obligadas a disponer de planes de igualdad las empresas de más de ciento cincuenta personas trabajadoras.", "No existe ningún tramo relacionado con el número de personas trabajadoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 42, "Señale la respuesta incorrecta en relación con los derechos de las mujeres víctimas de violencia de género, que regula la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "Las mujeres víctimas de violencia de género tienen derecho a servicios sociales de atención.", "Las mujeres víctimas de violencia de género tienen derecho a servicios de apoyo, de acogida y de recuperación integral.", "Las mujeres víctimas de violencia de género no tienen derecho a servicios de emergencia.", "Las mujeres víctimas de violencia de género tienen derecho a recibir información plena y asesoramiento adecuado a su situación personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 43, "El Convenio del Consejo de Europa sobre prevención y lucha contra la violencia contra la mujer y la violencia doméstica:", "Se firmó en Estambul el 11 de mayo de 2011.", "Fue ratificado por España en marzo del 2014.", "Todavía no está ratificado por España.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 44, "La Carta de los Derechos Fundamentales de la Unión Europea:", "Contiene un artículo sobre no discriminación.", "Contiene un artículo sobre no estigmatización.", "Contiene un artículo sobre buen trato.", "No contiene ninguno de los artículos anteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 45, "La Directiva 2004/113/CE del Consejo, de 13 de diciembre de 2004, por la que se aplica el principio de igualdad de trato entre hombres y mujeres en el acceso a los bienes y servicios y a su suministro:", "Establece la distinción entre discriminación directa y discriminación indirecta.", "Establece la distinción entre discriminación múltiple y orden de discriminar.", "Establece la distinción entre acoso y acoso sexual.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 46, "Indique la respuesta incorrecta de acuerdo con el Estatuto de autonomía de las Illes Balears, cuando establece que las administraciones públicas de las Illes Balears se tienen que centrar, primordialmente, en los ámbitos siguientes:", "La igualdad de derechos de mujeres y hombres en todos los ámbitos.", "La protección social contra la violencia, especialmente contra la violencia de género.", "El desarrollo sostenible del turismo.", "La protección específica y la tutela social del menor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 47, "Según dispone el Estatuto de autonomía de las Illes Balears en el artículo 17 «no discriminación por razón de sexo»:", "Todas las mujeres y hombres tienen derecho al libre desarrollo de su personalidad y capacidad personal.", "Todas las mujeres y hombres tienen derecho a vivir con dignidad, seguridad y autonomía.", "Todas las personas tienen derecho a no ser discriminadas por razón de su orientación sexual.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 48, "¿Quién ejerce actualmente las competencias de coordinación en materia de igualdad y diversidad de Gobierno de las Illes Balears?", "La Dirección General de Función Pública.", "La Direcció General de Coordinación, Relaciones con el Parlamento, Derechos y Diversidad.", "El Consejo Rector del Instituto Balear de la Mujer.", "La directora del Instituto Balear de la Mujer."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 49, "Indique la respuesta correcta en relación con la definición de perspectiva de género que establece la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "Es la toma en consideración de las diferencias entre mujeres y hombres en un a?mbito o una actividad para el análisis, la planificación, el diseño y la ejecución de poli?ticas.", "Es la toma en consideración de las similitudes entre hombres y mujeres para la ejecución de las políticas.", "Es tener en cuenta la manera en que las diversas actuaciones, situaciones y necesidades afectan a los hombres.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 50, "Indique la respuesta incorrecta de acuerdo con lo que la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres establece como violencia machista:", "La violencia económica, que incluye la privación intencionada, y no justificada legalmente, de recursos para el bienestar físico o psicológico.", "La violencia simbólica, que incluye los iconos, representaciones, narrativas, imágenes, etc., que reproducen o transmiten relaciones de dominación de los hombres respecto de las mujeres, así como desigualdades de poder entre sexos y de segregación.", "La violencia institucional, producida desde los servicios públicos y que revictimitza las víctimas.", "El feminicidio, asesinato de mujeres por el hecho de ser mujeres, al margen de que haya o haya habido relacio?n de pareja."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 51, "Señale la respuesta correcta en relación con el informe de evaluación de impacto de género, regulado por la Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres:", "La Administración de la Comunidad Autónoma de las Illes Balears tiene que aprobar las directrices en que se establezcan las pautas que se deben seguir para realizar el informe de evaluación de impacto de género.", "La Administración de la Comunidad Autónoma de las Illes Balears, a propuesta del Instituto Balear de la Mujer, tiene que aprobar las directrices en que se establezcan las pautas que se deben seguir para realizar el informe de evaluación de impacto de género.", "La Comisión de Paridad tiene que aprobar las pautas que se deben seguir para realizar el informe de evaluación de impacto de género.", "El Observatorio para la Equidad tiene que aprobar las directrices que se deben seguir para realizar el informe de evaluación de impacto de género."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 52, "El Instituto Balear de la Mujer se rige por los órganos siguientes:", "La consejería competente en materia de igualdad.", "El Consejo Rector.", "La dirección del Instituto.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 53, "El órgano colegiado encargado de coordinar las poli?ticas y los programas que realizan las administraciones autonómica, insular y local en materia de igualdad de mujeres y hombres, es:", "La Comisión de Igualdad.", "El Observatorio para la Igualdad.", "La Comisión para la Igualdad de G èneres.", "La Comisión para la Igualdad de S exes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 54, "El Observatorio para la Igualdad, regulado por el Decreto 1/2018, de 2 de febrero, tiene, entre otras, las funciones siguientes:", "Proponer un sistema de indicadores para tomar conocimiento de manera actualizada de la evolución de las desigualdades entre hombres y mujeres y la violencia machista, y para realizar su seguimiento y su evaluación.", "Analizar la evolución y los motivos de la persistencia de las desigualdades entre sexos y sexualidades y la violencia machista.", "Promover la elaboración de estudios, informes técnicos y evaluaciones comparables.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 55, "Señale la respuesta incorrecta en relación con cuáles son las áreas de intervención del Observatorio para la Igualdad, regulado por el Decreto 1/2018, de 2 de febrero:", "La violencia machista.", "El techo de cristal en el acceso al mercado de trabajo.", "La imagen pública de las mujeres.", "La sexualidad y la salud de las mujeres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 56, "Señale la respuesta correcta en relación con el Decreto de traspaso de competencias en materia de políticas de género y mujer:", "Es el Decreto 26/2004, de 21 de diciembre, de traspaso a los consejos insulares de las funciones y los servicios inherentes a las competencias propias de estos consejos insulares que actualmente ejerce la Administración de la Comunidad Autónoma de las Illes Balears en materia de políticas de género y mujer.", "Es el Decreto 46/2018, de 21 de diciembre, de traspaso a los consejos insulares de las funciones y los servicios inherentes a las competencias propias de estos consejos insulares que actualmente ejerce la Administración de la Comunidad Autónoma de las Illes Balears en materia de políticas de género y mujer.", "Es el Decreto 46/2018, de 21de diciembre, de traspaso a los consejos insulares de las funciones y los servicios inherentes a las competencias propias de estos consejos insulares que actualmente ejerce la Administración de la Comunidad Autónoma de las Illes Balears en materia de políticas de corresponsabilidad.", "No se han transferido todavía estas competencias a los consejos insulares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 57, "Señale cuál de las normas de ámbito estatal siguientes se ha aprobado recientemente en materia de no discriminación:", "La Ley 15/2022, de 12 de julio, integral para la igualdad de trato y la no discriminación.", "La Ley 15/2022, de 12 de julio, para la discriminación y la igualdad de trato.", "La Ley 16/2022, de 18 de noviembre, para combatir la desigualdad de género y la no discriminación.", "La Ley 17/2021, de 20 de diciembre, para atender las desigualdades y las discriminaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 58, "Indique la respuesta correcta en relación con la Ley 6/2022, de 31 de marzo, de modificación del Texto refundido de la Ley general de derechos de las personas con discapacidad y de su inclusión social:", "Introduce un nuevo artículo para establecer las condiciones básicas de accesibilidad cognitiva, así como para prever su desarrollo normativo posterior mediante un reglamento específico.", "Establece las condiciones básicas de accesibilidad cognitiva sin prever ningún desarrollo normativo posterior.", "La modificación no prevé establecer ninguna condición básica de accesibilidad cognitiva.", "La modificación solo afecta el apartado de la inclusión social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 59, "El artículo 14 de la Constitución española proclama el derecho a la igualdad y a la no discriminación por motivos de:", "Nacimiento, raza, género, nacionalidad y opinión.", "Nacimiento raza, género, religión y opinión.", "Nacimiento, raza, sexo, religión, opinión y cualquier otra circunstancia personal o social.", "Lugar de origen, etnia, espiritualidad, opinión y cualquier otra circunstancia personal o social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 60, "Indique la respuesta correcta en relación con los derechos de las funcionarias públicas víctimas de violencia de género según el que establece la Ley orgánica 1/2004, de 28 de diciembre, de medidas de protección integral contra la violencia de género:", "La funcionaria víctima de violencia de género tendrá derecho a la reducción o a la reordenación de su tiempo de trabajo.", "La funcionaria víctima de violencia de género tendrá derecho a la movilidad geográfica del centro de trabajo.", "La funcionaria víctima de violencia de género tendrá acceso a servicios específicos de atención.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 61, "La Estrategia para la igualdad de las personas Lesbianas, Gays, Bisexuals, Trans, Intersexuales y Queer (LGTBIQ) de la Unión Europea:", "Tiene previsto integrar la lucha contra la discriminación que afecta a las personas LGTBIQ en todas las políticas que se realicen en la Unión Europea.", "Está pensada para el periodo 2020-2025.", "Está basada, entre otras fuentes, en el informe sobre los derechos fundamentales de la Agencia Europea de Derechos Fundamentales (FRA) del 2020.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 62, "Indique la respuesta correcta en relación con el objeto de la Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuales y para erradicar la LGTBI-fobia:", "Establecer y regular los principios, los medios y las medidas para garantizar plenamente la igualdad real y efectiva en el ejercicio de los derechos de las personas lesbianas, gays, trans (transexuales y transgèneres), bisexuales e intersexuales (LGTBI).", "Establecer y regular los principios para garantizar los derechos de las personas no heterosexuales.", "Establecer y regular los principios para fomentar los derechos de las personas gays y lesbianas.", "Establecer y regular los principios para promover los derechos de las personas trans e intersexuales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 63, "Indique la respuesta correcta en relación con la evaluación de impacto sobre orientación sexual e identidad de género que establece la Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuales y para erradicar la LGTBI-fobia:", "Esta evaluación se tiene que incorporar sobre todas las disposiciones legales o reglamentarias que se impulsen dentro del territorio de la comunidad autónoma.", "Esta evaluación se tiene que incorporar sobre algunas disposiciones legales o reglamentarias concretas que se impulsen dentro del territorio de la comunidad autónoma.", "Esta evaluación tiene que garantizar la integración del principio de igualdad y no discriminación de las personas LGTBI.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 64, "De acuerdo con la Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuales y para erradicar la LGTBI-fobia y la discriminación por asociación es:", "La situacio?n en que una persona o un grupo de personas son objeto de discriminación por orientación sexual, identidad de género o expresión de género como consecuencia de una apreciación errónea.", "La situación en que una persona es objeto de discriminación por orientación sexual, identidad de género o expresión de género como consecuencia de su relacio?n con una persona o un grupo LGTBI.", "La situación en que una persona activista por los derechos de las personas gays es discriminada.", "La situación en que un grupo de personas activistas por los derechos de las personas lesbianas son discriminadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 65, "¿Qué Tratado marcó un hito en la lucha contra la discriminación en la Unión Europea cuando empezó a vigir el 1 de mayo de 1999?", "El Tratado de Maastricht.", "El Tratado de Amsterdam.", "El Tratado de Oslo.", "El Tratado de Milán."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 66, "¿Qué directiva del Consejo prohíbe la discriminación por origen racial o étnico en cualquier ámbito?", "La Directiva 1998/53/CE, de 18 de mayo de 1996.", "La Directiva 2000/43/CE, de 29 de junio de 2000.", "La Directiva 2020/32/CE, de 29 de abril de 2019.", "No hay ninguna directiva que prohíba esta discriminación a la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 67, "¿En qué Ley se transpuso en España la Directiva del Consejo que prohíbe la discriminación por origen racial o étnico?", "Mediante la Ley 62/2003, de 30 de diciembre, de medidas fiscales, administrativas y de orden social.", "Mediante la Ley 62/2011, de 30 de diciembre, de medidas fiscales, administrativas y de orden social.", "Mediante la Ley 17/2014, de 30 de diciembre, de medidas fiscales, administrativas y de orden social.", "Mediante la Ley 19/2015, de 30 de diciembre, de medidas fiscales, administrativas y de orden social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 68, "La entrada en vigor del Tratado de Lisboa el 1 de diciembre de 2009 ha reforzado en la Unión Europea:", "La protección de los derechos fundamentales.", "La protección de los derechos sociales.", "La protección de los derechos civiles.", "La protección de los derechos a la infancia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 69, "El Consejo de la Unión Europea, por unanimidad, y previa aprobación del Parlamento Europeo, podrá adoptar acciones adecuadas para luchar:", "La discriminación por motivos de género, lugar de nacimiento, nacionalidad o discapacidad.", "La discriminación por motivos de sexo, país de origen, color de piel o capacidad.", "La discriminación por motivos de sexo, de origen racial o étnico, religión o convicciones, discapacidad, edad u orientación sexual.", "La discriminación por motivos de raza, religión, ideología y condición sexual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 70, "Indique la respuesta correcta en relación con lo que dispone la Recomendación CM/Rec (2019) del Comité de Ministros a los Estados miembros para prevenir y combatir el sexismo, adoptada el 27 de marzo de 2019:", "Afirma que el sexismo se refuerza por los estereotipos de género que afectan a mujeres y hombres, niñas y niños, e impide la consecución de la igualdad de género y el establecimiento de sociedades inclusivas.", "Recuerda que el sexismo es una manifestación de las relaciones de poder históricamente desiguales entre mujeres y hombres, que provoca discriminación y que impide el pleno avance de las mujeres en la sociedad.", "Observa que mujeres y niñas pueden ser objeto de discriminación múltiple e interseccional y que pueden enfrentarse a un sexismo combinado con otras normas o comportamientos discriminatorios, de odio o nocivos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 71, "¿En qué ley de ámbito autonómico está reconocido el derecho a la no discriminación de las personas menores de edad?", "En la Ley 9/2019, de 19 de febrero, de la atención y los derechos de la infancia y la adolescencia de las Illes Balears.", "En la Ley 9/2019, de 19 de febrero, de protección a jóvenes menores de edad de las Illes Balears.", "En la Ley 6/2018, de 18 de marzo, de no discriminación de niños y de adolescentes en las Illes Balears.", "Este derecho no está reconocido en ninguna normativa autonómica en vigor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 72, "¿Qué ley de ámbito autonómico tiene por objeto garantizar la igualdad de oportunidades, la no discriminación y la accesibilidad universal para permitir la autonomía personal de todas las personas y, particularmente, de las personas con discapacidad?", "La Ley 8/2017, de 3 de agosto, para la accesibilidad de las personas con discapacidades de las Illes Balears.", "La Ley 8/2017, de 3 de agosto, de accesibilidad universal de las Illes Balears.", "La Ley 4/2020, de 8 de mayo, para mejorar la accesibilidad de todas las personas de las Illes Balears.", "La Ley 5/2021, de 10 de abril, de no discriminación de las personas con diversidad funcional de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 73, "¿Qué ley de ámbito autonómico tiene un título de medidas para garantizar la igualdad real y efectiva de las personas atendiendo a su identidad y a la expresión de género?", "La Ley 11/2016, de 28 de julio, de igualdad de mujeres y hombres.", "La Ley 5/2003, de 4 de abril, de salud de las Illes Balears.", "La Ley 8/2016, de 30 de mayo, para garantizar los derechos de lesbianas, gays, trans, bisexuales e intersexuals y para erradicar la LGTBI-fobia.", "La Ley 8/2018, de 31 de julio, de apoyo a las familias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 74, "¿De qué ministerio depende el Pacto de Estado contra la Violencia de Género?", "Del Ministerio de Igualdad.", "Del Ministerio de Trabajo y Economía Social.", "Del Ministerio de Sanidad.", "Del Ministerio de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 75, "El Gobierno, mediante la Delegación del Gobierno para la Violencia de Género, desarrolla el Pacto de Estado contra la Violencia de Género impulsando:", "Medidas de coordinación con el resto de ministerios y organismos autónomos que dependen de estos.", "Medidas de coordinación con las comunidades autónomas.", "Medidas de coordinación con las entidades locales representadas por la Federación Española de Municipios y Provincias.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 76, "Son acciones para dar apoyo a las víctimas de violencia de género y prevención en el actual Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales) las siguientes:", "Aprobar y llevar a cabo acciones para garantizar el anonimato y para proteger a las víctimas de violencia de género cuando participen en procesos selectivos.", "Llevar a cabo acciones para garantizar el anonimato de las mujeres víctimas de violencia de género en sus relaciones con la Administración.", "Divulgar entre la plantilla los recursos de atención en materia de violencia de género existentes en la Administración.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 77, "Son acciones para impulsar la presencia y participación de las mujeres en los órganos de debate, propuesta y decisión y en los puestos de trabajo de carácter directivo en el actual Plan de Igualdad entre Mujeres y Hombres de la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales) las siguientes:", "Incluir la perspectiva de género aplicada a los estilos de dirección dentre del programa de formación de personal directivo.", "Recomendar que se incluya un apartado con las medidas de conciliación en los manuales de acogida.", "Actualitzar y difundir la Guía práctica de corresponsabilidad familiar.", "Ninguna de las anteriores respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 18, 78, "Las medias para eliminar las desigualdades por razón de sexo en materia retributiva del eje 2 del actual Plan de Igualdad entre Mujeres y Hombres de  la Administración de la Comunidad Autónoma de las Illes Balears (servicios generales) son:", "El impulso de medidas formativas para combatir los estereotipos existentes sobre las capacidades directivas de las mujeres y publicar el informe de la brecha salarial.", "Programar actuaciones dirigidas a mujeres directivas para empoderarlas en lo que se refiere a su intervención como ponenetes en jornadass, congresos y otros fórums y trasladar a la Comisión de Teletrabajo las conclusiones del estudio sobre el teletrabajo.", "La realización de estudios para saber si hay diferencias retributivas no fundamentadas en criterios objetivos y la realización de acciones de difusión sobre los estudios realizados en materia retributiva .", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 1, "La Constitución española de 1978 garantiza el derecho a la autonomía de las nacionalidades y regiones que integran la Nación española en:", "El artículo 148.", "El artículo 2.", "El artículo 146.", "El artículo 12."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 2, "De acuerdo con la Constitución española, pueden acceder al autogobierno y constituirse en comunidad autónoma:", "Las provincias limítrofes con características históricas, culturales y económicas comunes, los territorios insulares y las provincias con entidad regional histórica.", "Las provincias con características históricas comunes, los territorios insulares y las provincias con entidad regional histórica, cultural o económica.", "Las provincias limítrofes con características históricas, culturales o económicas comunes, los territorios insulares y las provincias con entidad cultural histórica.", "Las provincias, los territorios insulares y las provincias con características históricas, culturales y económicas comunes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 3, "¿En qué título de la Constitución se regula el acceso a la autonomía de las provincias y regiones de España y la distribución competencial entre el Estado y las comunidades autónomas?", "En el título VII.", "En el título VI.", "En el título VIII.", "En el título III."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 4, "La organización institucional de las comunidades autónomas constituidas de acuerdo con el artículo 152 de la Constitución se basa en:", "Un parlamento, un consejo de gobierno, un presidente y un tribunal de justicia.", "Una asamblea legislativa, un consejo de gobierno presidido por un presidente y un tribunal superior de justicia.", "Una asamblea legislativa, un consejo de gobierno y un presidente.", "Un parlamento, un consejo de Gobierno y un presidente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 5, "La Constitución española de 1978, respecto de las comunidades autónomas, prohíbe:", "El desarrollo de competencias atribuidas al Estado.", "La federación entre comunidades autónomas.", "La regulación de las instituciones propias.", "Los convenios entre comunidades autónomas para la gestión y la prestación de servicios propios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 6, "En cuanto a los convenios entre comunidades autónomas, la Constitución establece:", "Que es imprescindible la autorización de las Cortes Generales cuando se trate de convenios para la gestión y prestación de servicios propios de las comunidades que lleven a cabo el convenio.", "Que sólo se comunican al Congreso de los Diputados si se trata de convenios distintos de los de gestión y prestación de servicios propios.", "Que los ha de autorizar  el Congreso de los Diputados con independencia del objeto del convenio.", "Que han de comunicarse a las Cortes Generales cuando  se trate de convenios para la gestión y prestación de servicios propios de las comunidades que llevan a cabo el convenio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 7, "La delimitación del territorio de las comunidades autónomas se regula:", "En la Constitución española de 1978.", "En una ley aprobada por el Senado.", "En una ley aprobada por la asamblea legislativa correspondiente.", "En el Estatuto de autonomía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 8, "La Constitución española define los estatutos de autonomía:", "Como la norma fundacional básica de cada comunidad autónoma.", "Como la norma orgánica básica de cada comunidad autónoma.", "Como la norma institucional básica de cada comunidad autónoma.", "Como la norma institucional básica de las regiones y nacionalidades que han accedido a la autonomía por la vía del artículo 151 de la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 9, "De acuerdo con la Constitución española de 1978, las competencias que asume cada comunidad autónoma se establecen:", "En las leyes de transferencias de competencias.", "En las leyes de traspaso de competencias.", "En los estatutos de autonomía.", "En la Constitución española."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 10, "La distribución de competencias entre el Estado y las comunidades autónomas se establece:", "En los artículos 149 y 150 de la Constitución española, respectivamente.", "En los artículos 148 y 149 de la Constitución española, respectivamente.", "En los artículos 149 y 148 de la Constitución española, respectivamente.", "En los artículos 150 y 149 de la Constitución española, respectivamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 11, "De acuerdo con el sistema de distribución competencial entre el Estado y las comunidades autónomas, podemos distinguir las materias siguientes:", "Materias que corresponden exclusivamente al Estado; materias en que el Estado legisla y las comunidades autónomas ejecutan esta legislación, y materias que corresponden exclusivamente a las comunidades autónomas.", "Materias que corresponden exclusivamente al Estado; materias en que el Estado legisla y las comunidades autónomas ejecutan esta legislación; materias en que el Estado aprueba la legislación básica, mientras que el desarrollo legislativo y la ejecución corresponde a las comunidades autónomas, y materias que corresponden exclusivamente a las comunidades autónomas.", "Hay materias en que el Estado y las comunidades autónomas tienen indistintamente competencias legislativas y ejecutivas.", "Las respuestas b) y c)  son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 12, "Se entiende que una competencia es concurrente:", "Cuando el Estado ostenta la facultad de dictar las bases sobre una materia y la comunidad autónoma puede asumir la legislación de desarrollo.", "Cuando el Estado y la comunidad autónoma tienen la posibilidad de concurrir con idénticas facultades en la regulación de una materia.", "Cuando el Estado ostenta todas las facultades sobre una materia, excepto la de ejecución, que corresponde a las comunidades autónomas.", "Cuando los estatutos de autonomía les atribuye ese carácter."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 13, "Respecto de las competencias exclusivas del Estado que establece el artículo 149:", "Las comunidades autónomas no pueden ostentar ninguna facultad.", "Las comunidades autónomas pueden dictar normas legislativas, para sí mismas, en el marco de los principios, bases y directrices fijadas por una ley estatal, siempre que las Cortes Generales les atribuya esta facultad.", "Las comunidades autónomas tienen competencias de desarrollo normativo, si la competencia estatal exclusiva es sobre las bases.", "Los estatutos de autonomía pueden asumir algunas de ellas en virtud del principio dispositivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 14, "En cuanto al sistema de distribución de competencias entre el Estado y las comunidades autónomas encontramos:", "Las competencias exclusivas del Estado, de acuerdo con el artículo 148 de la Constitución.", "Las competencias que pueden ser asumidas por las comunidades autónomas, según el artículo 149 de la Constitución.", "El resto de competencias, de las que la facultad o la materia no se menciona expresamente como exclusiva del Estado, que pueden ser asumidas por las comunidades autónomas, según el apartado 3 del artículo 149 de la Constitución.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 15, "Di cuál de las competencias siguientes es concurrente entre el Estado y las comunidades autónomas:", "Defensa.", "Medio ambiente.", "Cultura.", "Legislación sobre productos farmacéuticos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 16, "En los Estatutos aprobados por el procedimiento del artículo 151, la organización institucional autonómica se basa, entre otros, en una asamblea legislativa elegida por sufragio:", "Universal, con arreglo a un sistema de representación proporcional que asegure, además, la representación de las diversas zonas del territorio.", "Universal, con arreglo a un sistema de representación proporcional que asegure, además, la representación de las diversas culturas del territorio.", "Proporcional, con arreglo a un sistema de representación universal que asegure, además, la representación de las diversas zonas del territorio.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 17, "¿Por qué una comunidad autónoma puede tener competencia exclusiva en materias que no están incluidas en la lista del artículo 148 de la Constitución española?", "Las comunidades autónomas no pueden tener competencia exclusiva en materias que no están incluidas en el artículo 148.", "Porque el sistema de distribución de competencias en la Constitución no es un sistema cerrado, por lo que las comunidades autónomas pueden asumir competencias en aquellas materias no atribuidas al Estado.", "Porque la Constitución prevé que el Senado, por mayoría absoluta, puede atribuir a las comunidades autónomas competencias no incluidas en el artículo 148.", "Porque la Constitución prevé que el Congreso de los Diputados, en materias de competencia estatal, atribuya a las Comunidades Autónomas la facultad de dictar, para sí mismas, normas legislativas en del marco de los principios, las bases y las  directrices fijados por una ley estatal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 18, "Son competencias compartidas:", "Aquellas en las que las facultades de Estado y las de las comunidades autónomas son coincidentes.", "Aquellas que los estatutos de autonomía les atribuya ese carácter.", "Aquellas que la Constitución atribuye al Estado la función legislativa y a las comunidades autónomas únicamente la función ejecutiva.", "Aquellas en las que determinadas facultades corresponden al Estado y otras corresponden a las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 19, "Según la doctrina, una competencia es exclusiva:", "Cuando un ente aglutina todas las facultades posibles sobre una materia determinada.", "Cuando un ente se atribuye con exclusividad una facultad sobre una materia.", "Cuando un ente conserva todas las facultades de la misma calidad sobre una materia.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 20, "La tenencia y el uso de armas y explosivos:", "Es competencia exclusiva de las comunidades autónomas en su territorio.", "Se trata de una competencia compartida entre el Estado y las comunidades autónomas.", "Es competencia de la Administración local.", "Es competencia exclusiva del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 21, "¿Cuál de las siguientes competencias es exclusiva del Estado?:", "La asistencia social.", "La determinación de las fuentes del derecho, con respeto a las normas de derecho foral o especial.", "La determinación de las fuentes del derecho, excepto las normas autonómicas, en cuyo caso la competencia corresponde a la comunidad autónoma.", "Los puertos y aeropuertos deportivos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 22, "¿Cuál de las siguientes competencias corresponde al Estado, según la Constitución española?", "Las alteraciones de los términos municipales comprendidos en el territorio de las comunidades autónomas.", "El fomento y la coordinación general de la búsqueda científica y técnica.", "La ordenación del territorio, el urbanismo y la vivienda.", "La agricultura y la ganadería, de acuerdo con la ordenación general de la economía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 23, "¿Cuál de las siguientes competencias pueden asumir las comunidades autónomas?:", "Las bases y la coordinación de la planificación general de la actividad económica.", "La iluminación de costas y señales marítimas.", "Las obras públicas de interés general.", "Los aprovechamientos forestales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 24, "¿Es posible que las comunidades autónomas legislen sobre las relaciones laborales de trabajadores y empresarios radicados en el territorio respectivo?", "Sí, porque se trata de una competencia compartida entre el Estado y las comunidades autónomas.", "Sí, porque las comunidades autónomas tienen competencias de desarrollo en materia laboral.", "No, se trata de una competencia exclusiva del Estado; las comunidades autónomas sólo tienen competencias de ejecución.", "No, salvo que lo hayan asumido en los estatutos de autonomía correspondientes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 25, "¿A quien corresponde la competencia en materia de legislación procesal?", "Al Estado, como competencia exclusiva, incluida la ejecución en el territorio de las comunidades autónomas.", "Al Estado, como competencia exclusiva.", "A las comunidades autónomas en caso de haberse recogido en los respectivos estatutos de autonomía.", "A las comunidades autónomas en cuanto a la normativa de desarrollo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 26, "¿Mediante qué instrumento del Estado puede una comunidad autónoma  asumir competencias en materia de justicia?", "Mediante una ley marco.", "Mediante una ley ordinaria.", "Mediante una ley de armonización.", "Mediante una ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 27, "En el supuesto de que una comunidad autónoma no cumpla las obligaciones que la Constitución u otras leyes le imponen, o bien actúe de forma que atente gravemente contra el interés general de España:", "El Gobierno, previo requerimiento al presidente de la comunidad autónoma, puede adoptar las medidas necesarias para obligarla al cumplimiento forzoso de dichas obligaciones o para la protección del interés general mencionado.", "El Gobierno, con requerimiento previo al presidente de la asamblea legislativa de la comunidad autónoma, con la mayoría absoluta del Senado, puede adoptar las medidas necesarias para obligar a la comunidad autónoma al cumplimiento de dichas obligaciones o para la protección del interés general mencionado.", "El Gobierno, previo requerimiento al presidente de la comunidad autónoma y, en el caso de no ser atendido, con la aprobación por mayoría absoluta del Senado, puede adoptar las medidas necesarias para obligarla al cumplimiento forzoso de dichas obligaciones o para la protección del mencionado interés general.", "El Gobierno, con requerimiento previo al presidente de la comunidad autónoma y, en el caso de no ser atendido, con la aprobación por mayoría absoluta del Congreso de los Diputados, puede adoptar las medidas necesarias para obligarla al cumplimiento forzoso de dichas obligaciones o para la protección del mencionado interés general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 28, "Señala la respuesta correcta:", "Las comunidades autónomas pueden convocar referéndums en su territorio.", "Las comunidades autónomas pueden convocar referéndums siempre que la consulta no afecte a las instituciones de autogobierno.", "La competencia para autorizar convocatorias de consultas populares por vía de un referéndum corresponde siempre al Estado.", "La Constitución no prevé esta competencia en su título VIII."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 29, "De acuerdo con el artículo 155 de la Constitución, cuando el Gobierno adopte las medidas que corresponda:", "Puede dar instrucciones exclusivamente a la administración de la comunidad autónoma afectada.", "Puede dar instrucciones exclusivamente al personal de la Delegación del Gobierno en la comunidad autónoma afectada.", "Sólo puede dar instrucciones al gobierno de la comunidad autónoma afectada.", "Puede dar instrucciones a todas las autoridades de la comunidad autónoma afectada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 30, "La finalidad del Fondo de Compensación que prevé el título VIII de la Constitución es:", "Garantizar un nivel mínimo en la prestación de servicios públicos.", "Compensar servicios estatales asumidos por las comunidades autónomas.", "Corregir desequilibrios económicos interterritoriales y hacer efectivo el principio de solidaridad.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 31, "¿Qué ley regula el Fondo de Compensación previsto en el artículo 158 de la Constitución?", "La Ley 22/2003, de 26 de diciembre, reguladora de los Fondos de Compensación Interterritorial.", "La Ley 21/2004, de 27 de diciembre, reguladora de los Fondos de Compensación Constitucional.", "La Ley 22/2001, de 27 de diciembre, reguladora de los Fondos de Compensación Interterritorial.", "No hay ninguna ley que regule el Fondo de Compensación previsto en la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 32, "El artículo 147 de la Constitución indica que los estatutos de autonomía deberán contener:", "La denominación de la comunidad que acuerden las entidades que hayan iniciado el procedimiento de autonomía.", "La denominación de la comunidad que mejor corresponda a su identidad histórica.", "La denominación, organización y sede de las instituciones estatales en su territorio.", "Las competencias asumidas y asumibles dentro del marco establecido en la Constitución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 33, "Indica cuál de las respuestas siguientes no forma parte del contenido que el artículo 147 de la Constitución establece para los estatutos de autonomía.", "Las competencias asumidas dentro del marco que establece la Constitución.", "Las competencias asumidas por el Estado dentro del marco que establece la Constitución.", "Las bases para el traspaso de los servicios correspondientes a estas competencias.", "La delimitación del territorio de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 34, "De acuerdo con la Constitución española, los recursos de las comunidades autónomas están constituidos:", "Por sus propios impuestos, tasas y contribuciones especiales.", "Por las transferencias de un fondo de compensación interterritorial y otras asignaciones con cargo a los Presupuestos Generales del Estado.", "El producto de las operaciones de crédito.", "Todas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 35, "Con el fin de corregir desequilibrios económicos interterritoriales y hacer efectivo el principio de solidaridad, la Constitución prevé un Fondo de Compensación con destino a gastos de inversión, cuyos recursos serán distribuidos:", "Por las Cortes Generales entre las comunidades autónomas y provincias, en su caso.", "Por el Gobierno entre las comunidades autónomas.", "Por el Gobierno entre las comunidades autónomas y provincias, en su caso.", "Por las Cortes Generales entre las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 36, "De acuerdo con la Constitución, el Estado puede dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas:", "En materias atribuidas a la competencia del Estado, cuando así lo exija el interés general.", "Incluso en el caso de materias atribuidas a la competencia de las comunidades autónomas, cuando así lo exija el interés general.", "En materias atribuidas a la competencia del Estado, cuando así lo exija la seguridad del Estado.", "Incluso en el caso de materias atribuidas a la competencia de las comunidades autónomas, cuando así lo exija la seguridad del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 37, "El artículo 150 de la Constitución dispone que el Estado puede dictar leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas cuando así lo exija el interés general. ¿A quien corresponde apreciar esta necesidad?", "Al Congreso de los Diputados, por mayoría absoluta.", "A las Cortes Generales, por mayoría absoluta de cada Cámara.", "A las Cortes Generales, por mayoría de dos tercios de los miembros de cada Cámara.", "Al Congreso de los Diputados, por mayoría de dos tercios de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 38, "Señala la respuesta incorrecta:", "Las diferencias entre los estatutos de las diferentes comunidades autónomas no pueden implicar privilegios económicos o sociales.", "Todos los españoles tienen los mismos derechos y obligaciones en cualquier parte del territorio del Estado.", "Ninguna autoridad, excepto el Gobierno de la nación, puede adoptar medidas que directa o indirectamente obstaculicen la libertad de circulación y el establecimiento de las personas y la libre circulación de bienes en todo el territorio español.", "Los municipios disfrutan de autonomía para gestionar sus respectivos intereses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 39, "De acuerdo con la Constitución española, ¿quién puede adoptar medidas que obstaculicen la libertad de circulación y de establecimiento de las personas y la libre circulación de bienes en todo el territorio nacional?", "Las Cortes Generales, en cualquier caso.", "El Gobierno, mediante la correspondiente delegación legislativa.", "Ninguna autoridad puede adoptar medidas que directa o indirectamente lo obstaculicen.", "Las asambleas legislativas u órganos colegiados superiores de las diferentes comunidades autónomas"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 40, "¿Cuál de las siguientes competencias corresponde al Estado, según la Constitución española?", "Las alteraciones de los términos municipales comprendidos en el territorio de las comunidades autónomas.", "El fomento y la coordinación general de la búsqueda científica y técnica.", "La ordenación del territorio, el urbanismo y la vivienda.", "La agricultura y la ganadería, de acuerdo con la ordenación general de la economía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 41, "La Constitución atribuye al Estado la competencia exclusiva sobre contratos. Esto implica:", "Que las comunidades autónomas no pueden regular la contratación pública que lleven a cabo sus instituciones.", "Que las comunidades autónomas tendrán que regular mediante un reglamento aquellos aspectos no considerados básicos por la normativa estatal.", "Que las comunidades autónomas pueden regular mediante una ley aquellos aspectos no considerados básicos por la normativa estatal.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 42, "¿Cuál de las siguientes competencias pueden asumir las comunidades autónomas?", "Bases y coordinación de la planificación general de la actividad económica.", "Iluminación de costas y señales marítimas.", "Obras públicas de interés general.", "Sanidad e higiene."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 43, "Una de las siguientes fuentes no constituye un recurso económico de las comunidades autónomas:", "Los ingresos de derecho privado.", "Los rendimientos procedentes de su patrimonio.", "El producto de las operaciones bursátiles.", "El producto de las operaciones de crédito."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 44, "Indica cuál de las siguientes competencias no es exclusiva del Estado:", "La legislación laboral, en todas sus manifestaciones, incluso las de ejecución.", "Las bases y la coordinación de la planificación general de la actividad económica.", "La defensa y las fuerzas armadas.", "La hacienda general y la deuda del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 45, "¿Cómo denomina la Constitución al órgano de gobierno de la comunidad autónoma?", "Consejo colegiado.", "Consejo.", "Consejo ejecutivo.", "Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 46, "De acuerdo con la Constitución, los Estatutos pueden establecer circunscripciones territoriales propias:", "Mediante la agrupación de municipios, aunque no sean limítrofes.", "Sin personalidad jurídica propia.", "Mediante la agrupación de municipios limítrofes.", "En ningún caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 47, "Según la Constitución española, las comunidades autónomas no pueden en ningún caso adoptar medidas tributarias:", "Sobre bienes situados en el interior de su territorio de propiedad privada.", "Sobre bienes situados fuera de su territorio, o que supongan un obstáculo para la libre circulación de mercancias o servicios.", "Que supongan un obstáculo para la competencia regulada.", "Que impidan la creación de multinacionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 48, "¿Qué facultades pueden asumir las comunidades autónomas en materia de derecho de asilo?", "Ninguna.", "Legislación de desarrollo.", "De ejecución.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 49, "La organización judicial en el ámbito de las comunidades autónomas la culminan:", "Las audiencias provinciales correspondientes, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo.", "Un Tribunal Superior de Justicia, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo.", "Un Tribunal Superior de Justicia, que asumirá en el ámbito territorial de la Comunidad Autónoma la jurisdicción que sobre este mismo tribunal ejercía el Tribunal Supremo.", "Por una audiencia territorial, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 50, "¿Cuál de las materias siguientes no pueden asumir inicialmente las comunidades autónomas?", "La artesanía.", "La administración de justicia.", "El ordenamiento del territorio, el urbanismo y la vivienda.", "La organización de las instituciones básicas de autogobierno de las comunidades autónomas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 51, "Las comunidades autónomas, respecto de los recursos tributarios del Estado:", "No pueden asumir ningún tipo de competencias.", "Pueden actuar como delegados del Estado en cuanto a la recaudación y la gestión, pero no la liquidación.", "Pueden actuar como delegados o colaboradores del Estado en cuanto a la recaudación, la gestión y la liquidación.", "Pueden actuar como delegados o colaboradores del Estado exclusivamente para la recaudación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 52, "Para garantizar, entre otros, un nivel mínimo en la prestación de servicios públicos fundamentales en todo el territorio español:", "El Estado y las comunidades autónomas pueden establecer tributos especiales.", "Una ley orgánica establecerá el nivel mínimo y la forma de financiación para conseguirlo.", "Puede establecerse una asignación a las comunidades autónomas en los presupuestos generales del Estado.", "El Estado puede asumir directamente el ejercicio de competencias autonómicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 53, "En cuanto a la organización territorial del poder judicial, las comunidades autónomas:", "Pueden participar en la organización de las demarcaciones judiciales de su territorio al margen de lo que dispone la Ley Orgánica del Poder Judicial, en aquellas instancias procesales que se agoten en el ámbito territorial de las comunidades autónomas.", "No pueden proponer al gobierno la fijación de los partidos judiciales de su ámbito territorial, de acuerdo con la independencia del poder judicial.", "No pueden participar en la organización de las demarcaciones judiciales de su territorio porque es una competencia reservada al Estado.", "Pueden participar en la organización de las demarcaciones judiciales de su territorio, de acuerdo con los supuestos y en las formas que indiquen en sus estatutos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 54, "En materia de propiedad intelectual e industrial corresponde a las comunidades autónomas:", "El desarrollo legislativo y la ejecución.", "La legislación y la ejecución.", "La ejecución.", "Las bases."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 55, "Las leyes marco que atribuyen a las comunidades autónomas la facultad de dictar, para sí mismas, normas legislativas en materias de competencia estatal:", "Establecen la modalidad de control que los tribunales tienen que ejercer sobre las normas que dicten las comunidades.", "Establecen la modalidad de control que las Cortes Generales tienen que ejercer sobre las normas que dicten las comunidades autónomas, sin perjuicio de la competencia de los tribunales.", "Fijan los principios, las bases y las directrices a los cuales han de someterse las normas que dicten las comunidades autónomas.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 56, "Las comunidades autónomas disfrutarán de autonomía financiera para el desarrollo y la ejecución de sus competencias de acuerdo con los principios de:", "Solidaridad entre todas las comunidades autónomas.", "Progresividad, reparto equitativo de la riqueza y justicia distributiva.", "Coordinación con las haciendas locales.", "Coordinación con la hacienda estatal y solidaridad entre todos los españoles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 57, "La armonización de las disposiciones normativas de las comunidades autónomas:", "Se efectuará sólo en el caso de materias atribuidas al Estado que hayan sido transferidas o delegadas a las comunidades autónomas.", "Esta armonización no afectará las normas dictadas para el desarrollo de las materias atribuidas a la competencia de las comunidades autónomas.", "Corresponderá al Estado, que dictará leyes en las que se establecerán los principios necesarios para conseguir esta armonía.", "La armonización se efectuará cuando así lo exija el interés de la seguridad nacional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 58, "De acuerdo con el artículo 149.1.27 de la Constitución, el Estado tiene competencia exclusiva sobre normas básicas del régimen de prensa, radio y televisión. Esto implica:", "Que corresponde al Estado el establecimiento de los criterios generales de regulación de esta materia, que han de comunes a todo el Estado.", "Un límite dentro del cual han de moverse los órganos de las comunidades autónomas en el ejercicio de sus competencias.", "La posibilidad de que el Estado atribuya esta competencia en la comunidad autónoma mediante una ley de transferencia.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 60, "¿Es posible que el Estado transfiera o delegue en las comunidades autónomas funciones correspondientes a materias de titularidad estatal?", "Sí, mediante un Real Decreto Ley, el Estado puede transferir materias de su competencia.", "No; si una materia es competencia del Estado, éste ejerce todas las funciones.", "No; la Constitución lo prohíbe.", "Sí, pero sólo en aquellas materias cuya naturaleza las haga susceptibles de transferencia o delegación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 61, "¿Qué ocurre con las materias no atribuidas expresamente al Estado por la Constitución española?", "Corresponden en todo caso a las comunidades autónomas.", "Corresponden en todo caso al Estado.", "Podrán corresponder a las comunidades autónomas en virtud de los estatutos respectivos.", "Corresponderán al Estado o a las comunidades autónomas según que la materia tenga o no interés general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 62, "¿A quien corresponde la competencia sobre las materias que no hayan asumido los estatutos de autonomía?", "Corresponde al Estado o a las comunidades autónomas según si la materia tiene interés general o no.", "Corresponde al Estado.", "Corresponde a las comunidades autónomas en caso de tratarse de materias de ámbito autonómico.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 63, "La cláusula residual que establece el artículo 149.3 de la Constitución:", "Opera a favor de las comunidades autónomas sólo en el supuesto de que el Estado no asuma expresamente las competencias.", "Opera a favor del Estado sólo en el caso de que las comunidades autónomas no asuman expresamente las competencias.", "Atribuye a las comunidades autónomas las funciones legislativas y ejecutivas.", "Atribuye al Estado únicamente la función legislativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 64, "En caso de conflicto entre las normas estatales y las de las comunidades autónomas, el artículo 149.3 de la Constitución establece que:", "Las normas estatales prevalecen sobre las de las comunidades autónomas.", "Las normas estatales prevalecen sobre las de las comunidades autónomas siempre que no se trate de competencias atribuidas en exclusiva a las comunidades autónomas.", "Es una manifestación de la supremacía del derecho estatal sobre el autonómico.", "Debe atenderse al sistema competencial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 65, "La cláusula de supletoriedad que establece el artículo 149.3 de la Constitución dispone expresamente que:", "En cualquier caso, el derecho estatal será supletorio del derecho de las comunidades autónomas.", "El derecho estatal será supletorio del derecho de las comunidades autónomas sólo en las materias que estas no hayan regulado.", "Las respuestas a) y b) son correctas.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 66, "El principio de prevalencia que establece el artículo 149.3 de la Constitución española:", "No atribuye superioridad natural del derecho estatal sobre el de las comunidades autónomas.", "No supone que en todos los conflictos entre una norma estatal y una norma autonómica tenga que aplicarse siempre el derecho estatal por ser prevalente.", "Opera junto al principio de competencia, respetándolo.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 67, "Puede una comunidad autónoma atribuirse funciones legislativas sobre las instituciones de crédito cooperativo público y territorial:", "No, porque se trata de una competencia exclusiva del Estado, de acuerdo con el artículo 149 de la Constitución.", "No, sólo puede tener competencias de ejecución.", "Sí, porque la exclusividad del Estado sólo está referida en las bases de la ordenación del crédito.", "Sí; es una materia sobre la cual la Constitución no atribuye ninguna competencia en el Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 69, "¿El Estado y las comunidades autónomas pueden compartir funciones legislativas sobre una determinada materia de la competencia exclusiva del Estado?", "No, se trata de una competencia exclusiva; si la tiene el Estado, ya no pueden tenerla las comunidades autónomas.", "Sí, cuando las comunidades autónomas tienen competencias de desarrollo en el marco de la legislación básica del Estado.", "No, cuando el Estado tiene la competencia legislativa, las comunidades autónomas sólo pueden tener la potestad reglamentaria.", "No, esta posibilidad resultaría contradictoria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 70, "En el supuesto de que una comunidad autónoma no haya asumido como propia la competencia sobre una de las materias que prevé el artículo 148 de la Constitución:", "La asunción de las competencias del artículo 148 por parte de las comunidades autónomas es obligatoria.", "No tiene competencia sobre la materia de que se trate, dado que rige el principio dispositivo.", "La competencia corresponderá en el Estado.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 71, "Indica cuál de las respuestas es la correcta en relación a la cláusula de supletoriedad:", "La cláusula de supletoriedad permite al Estado dictar normas sobre materias competencia de las comunidades autónomas a efectos de ser aplicadas por aquellas comunidades que no hayan regulado la materia de su competencia o estén pendientes de regularla.", "La supletoriedad sólo es predicable de las normas dictadas por el Estado en materias de su competencia.", "La supletoriedad permite al legislador estatal, en materias en las que tiene atribuidas competencias sobre lo básico, elaborar ex profeso una regulación sobre el desarrollo que, si se tercia, pueda completar supletoriamente las lagunas provocadas por una inactividad autonómica en el ejercicio de estas competencias.", "Ninguna de las respuestas es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 72, "El Estado puede transferir o delegar en las comunidades autónomas, mediante una ley orgánica, facultades correspondientes a materias  de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación. En este caso:", "La ley preverá en cada caso la correspondiente transferencia de medios financieros y de personal, así como las formas de control que reserve a los tribunales.", "La ley preverá en cada caso la correspondiente transferencia de medios financieros, así como las formas de control que se reserve el Estado.", "El Estado no podrá reservarse medidas de control, y tendrá que prever en cada caso la correspondiente transferencia de medios financieros y de personal.", "El Estado tendrá que dictar las leyes que establezcan los principios necesarios para armonizar las disposiciones normativas de las comunidades autónomas con las estatales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 73, "Indica la respuesta incorrecta:", "Las comunidades autónomas no tienen funciones legislativas en aquellas materias de las que el artículo 149 de la Constitución atribuye la competencia exclusiva al Estado.", "Las comunidades autónomas tienen funciones legislativas si la competencia exclusiva del Estado es sobre las bases de una materia determinada.", "Las comunidades autónomas no pueden dictar leyes orgánicas.", "La competencia exclusiva del Estado sobre el procedimiento administrativo común permite a las comunidades autónomas legislar sobre las especialidades derivadas de la organización propia.."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 74, "Señala la respuesta incorrecta. El control de la actividad de los órganos de las comunidades autónomas lo ejerce:", "El Tribunal Constitucional.", "El Gobierno de la nación.", "La jurisdicción contenciosa administrativa.", "Las Cortes Generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 3, 75, "¿Qué órgano es el competente para conocer los conflictos de competencias entre el Estado y las comunidades autónomas?:", "El Tribunal Supremo.", "El Consejo de Estado.", "El Tribunal Constitucional,", "La Comisión Constitucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 1, "¿De cuántos títulos consta la Constitución española de 1978?", "De un título preliminar y VIII títulos.", "De un título preliminar y IX títulos.", "De un título preliminar y X títulos.", "De un título preliminar y XI títulos."); 
