insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 4, "¿Qué título de la Constitución española regula la reforma constitucional?", "El título X.", "El título IX.", "El título VIII.", "El título VII."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 5, "¿Dónde se regula que España se constituye en un Estado social y democrático de derecho?", "En el preámbulo de la Constitución española.", "En el título preliminar de la Constitución española.", "En el título I de la Constitución española.", "En el título II de la Constitución española."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 6, "Según el artículo 1 de la Constitución española, la soberanía nacional reside :", "En las Cortes Generales.", "En el rey.", "En el pueblo español.", "En los ciudadanos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 7, "Según el artículo 1 de la Constitución española, ¿cuál es la forma política del Estado español?", "La monarquía parlamentaria.", "La democracia popular.", "La monarquía presidencialista.", "La democracia parlamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 8, "Según el artículo 2 de la Constitución española, ¿en qué se fundamenta la Constitución?", "En los principios de libertad, la justicia y la igualdad.", "En la indisoluble unidad de la nación española.", "En la soberanía nacional.", "En el principio democrático."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 9, "Según el artículo 3 de la Constitución española, las diferentes modalidades lingüísticas de España son:", "Un valor fundamental de protección.", "Un patrimonio cultural.", "Objeto de especial respeto y protección", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 10, "Según el artículo 8 de la Constitución española, ¿qué norma ha de regular las bases de la organización militar?", "Una ley ordinaria.", "Un reglamento del ministerio competente en materia de defensa.", "Una ley orgánica.", "Un decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 11, "Según el artículo 10 de la Constitución española, las normas relativas a los derechos fundamentales y a las libertades que la Constitución reconoce se interpretan de conformidad:", "Con la Carta de derechos sociales.", "Con la Declaración universal de derechos humanos.", "Con los tratados y los acuerdos internacionales sobre estas materias ratificados por España.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 12, "Según el artículo 11 de la Constitución española, ¿el Estado español puede  concertar tratados de doble nacionalidad con los países iberoamericanos?", "No.", "Sí.", "Sólo con los que hayan tenido una vinculación histórica con España.", "Sólo con los que tengan una vinculación histórica con España."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 13, "Según el artículo 18 de la Constitución española, se garantiza:", "El derecho al honor y a la intimidad.", "El derecho al honor, a la intimidad personal y a la propia imagen.", "El derecho al honor, a la intimidad personal y familiar y a la propia imagen.", "El derecho al honor y a la propia imagen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 14, "Según el artículo 20 de la Constitución española, ¿se puede acordar el secuestro de publicaciones, grabaciones y otros medios de información?", "No, nunca.", "Sólo en virtud de resolución judicial.", "Sólo en virtud de resolución policial.", "Sólo en virtud del interés general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 15, "Según el artículo 22 de la Constitución española, ¿se reconoce el derecho de asociación?", "Sí, sin excepciones.", "No.", "Sí, pero se prohíben las asociaciones secretas y las de carácter paramilitar.", "Sí, sólo se prohíben las de carácter paramilitar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 16, "Según el artículo 25 de la Constitución española, ¿a qué están orientadas las penas privativas de libertad?", "Al castigo.", "A la reeducación.", "A la reinserción social.", "Las respuestas b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 17, "Según el artículo 28 de la Constitución española, se reconoce a los trabajadores:", "El derecho a la huelga.", "El derecho a fundar sindicatos.", "El derecho a sindicarse libremente.", "Las respuestas a) b) y c) son correctas."); 
