insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 19, "Según el artículo 37 de la Constitución española, sobre el derecho a la negociación colectiva del trabajo, se garantiza:", "La fuerza vinculante de los convenios.", "La fuerza vinculante del Estatuto de los trabajadores.", "La fuerza vinculante de los contratos de trabajo.", "La revisión anual de los convenios."); 
