insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 59, "Según el artículo 161 de la Constitución española, ¿qué órgano jurisdiccional el competente para conocer de los conflictos de competencia entre las comunidades autónomas?", "El Tribunal Supremo.", "El Tribunal Constitucional.", "La Audiencia Provincial.", "El Tribunal Superior de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 60, "Según el artículo 161 de la Constitución española, ¿qué órgano jurisdiccional es competente para conocer de los recursos de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley?", "El Tribunal Supremo.", "El Tribunal Constitucional.", "La Audiencia Provincial.", "El Tribunal Superior de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 61, "Según el artículo 162 de la Constitución española, ¿las Cortes Generales tienen legitimidad para interponer un recurso de inconstitucionalidad?", "No.", "Sí. Se requieren cincuenta diputados o cincuenta senadores.", "Sí, con mayoría simple del Congreso.", "Sí, con mayoría absoluta del Congreso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 62, "Según el artículo 162 de la Constitución española, ¿quién tiene legitimidad para interponer un recurso de inconstitucionalidad?", "El presidente del Gobierno.", "Treinta diputados.", "Treinta senadores.", "El ministerio fiscal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 63, "Según el artículo 162 de la Constitución española, ¿quién tiene legitimidad para interponer un recurso de amparo ante el Tribunal Constitucional?", "Toda persona natural o jurídica.", "Toda persona natural o jurídica que invoque un interés particular.", "Toda persona natural o jurídica que invoque un interés legítimo.", "Toda persona natural o jurídica que invoque un interés común."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 64, "Según el artículo 162 de la Constitución española, ¿quién tiene legitimidad para interponer un recurso de amparo ante el Tribunal Constitucional?", "El Defensor del Pueblo.", "El ministerio fiscal.", "Toda persona natural o jurídica que invoque un interés legítimo.", "Las respuestas a) b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 65, "Según el artículo 164 de la Constitución española, ¿dónde se publican las sentencias del Tribunal Constitucional?", "En el Boletín Oficial del Estado.", "No se publican.", "En el boletín oficial de la comunidad autónoma.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 66, "Según el artículo 165 de la Constitución española, ¿qué norma regula el funcionamiento del Tribunal Constitucional?", "Un reglamento del Tribunal Constitucional.", "Una ley ordinaria del Gobierno.", "Una ley orgánica.", "Un reglamento del Consejo General del Poder Judicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 67, "Según el artículo 164 de la Constitución española, ¿es posible interponer un recurso contra una sentencia del Tribunal Constitucional?", "No.", "Sí, ante el Tribunal Supremo.", "No, con alguna excepción.", "Sí, un recurso de amparo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 68, "Según el artículo 166 de la Constitución española, ¿a quién corresponde la iniciativa de reforma constitucional?", "Al Gobierno.", "Al Congreso y al Senado.", "A les asambleas legislativas autonómicas.", "Las respuestas a) b) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 69, "Según el artículo 167 de la Constitución española, ¿qué mayoría de cada una de las cámaras se requiere para aprobar un proyecto de reforma constitucional no esencial?", "Mayoría absoluta.", "Mayoría de las tres quintas partes.", "Mayoría de las dos terceras partes.", "Mayoría simple."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 70, "Según el artículo 168 de la Constitución española, ¿es obligatorio un referéndum para ratificar una reforma total constitucional una vez que haya sido aprobada por las Cortes Generales?", "No.", "No, salvo excepciones.", "Sí.", "Sí, salvo excepciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 71, "Según el artículo 169 de la Constitución española, ¿cuándo no se puede iniciar una reforma constitucional?", "Durante los  estados de alarma, de excepción o de sitio vigentes.", "Durante un proceso electoral.", "En tiempos de guerra.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 72, "Según el artículo 168 de la Constitución española, si se propone la revisión total de la Constitución, se ha de proceder:", "A la aprobación por mayoría de los dos tercios de cada cámara.", "A la aprobación por mayoría absoluta de cada cámara.", "A la disolución inmediata de las Cortes.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 73, "Según el artículo 168 de la Constitución española, si se propone una revisión parcial de la Constitución que afecta al título II, se procede:", "A la aprobación por mayoría de los dos tercios de cada cámara.", "A la aprobación por mayoría absoluta de cada cámara.", "A la disolución inmediata de las Cortes.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 74, "Según el artículo 167 de la Constitución española, ¿la reforma de partes no esenciales de la Constitución se ha de someter a referéndum?", "No, nunca.", "Sí, siempre que lo pida una décima parte de los miembros de cualquiera de las cámaras.", "Sí, siempre que lo pida una tercera parte de los miembros de cualquiera de las cámaras.", "Sí, siempre que lo pida una quinta parte de los miembros de cualquiera de las cámaras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 1, 75, "Según el artículo 168 de la Constitución española, sobre la reforma constitucional ,no se considera una parte esencial de la misma:", "El título preliminar.", "El capítulo II, sección primera del título I.", "El título II.", "El título III."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 1, "La Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, tiene por objeto adaptar el ordenamiento jurídico español al:", "Reglamento (UE) 2016/679 del Parlamento Europeo y el Consejo, de 27 de abril de 2016 relativo a la protección de las personas físicas y jurídicas en lo que respecta al tratamiento de sus datos personales y a la libre circulación de estos datos.", "Reglamento (UE) 2016/679 del Parlamento Europeo y el Consejo, de 27 de abril de 2016 relativo a la protección de las personas físicas en lo que respecta al tratamiento de sus datos personales y a la libre circulación de estos datos.", "Reglamento (UE) 2016/679 del Parlamento Europeo y el Consejo, de 27 de abril de 2016 relativo a la protección de las personas físicas en lo que respecta al tratamiento de sus datos personales y a la libre circulación de estos datos, y completar sus disposiciones.", "Reglamento (UE) 2016/679 del Parlamento Europeo y el Consejo, de 27 de abril de 2016 relativo a la protección de las personas físicas y jurídicas en lo que respecta al tratamiento de sus datos personales y a la libre circulación de estos datos, y completar sus disposiciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 2, "¿Cuál de los siguientes tratamientos de datos no le es de aplicación directa el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), por afectar a actividades no comprendidas en el ámbito de aplicación del Derecho de la Unión Europea?", "Tratamiento de datos de alumnos de un centro educativo.", "Tratamientos realizados en el ámbito de instituciones penitenciarias.", "Tratamiento de datos para fines comerciales.", "Tratamiento de datos realizado por empresas de telecomunicaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 3, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, en relación a los derechos y libertades consagrados en la Constitución y en los tratados y convenios internacionales en que España sea parte, ¿quién contribuirá a garantizar su aplicación?", "Los prestadores de servicios de la sociedad de la información y los proveedores de servicios de Internet.", "Las personas que autoricen el tratamiento de sus datos personales.", "Exclusivamente los proveedores de servicios de Internet.", "Exclusivamente los prestadores de servicios de la sociedad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 4, "Indique cuál de los siguientes no es un derecho digital reconocido en la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales:", "Derecho a la intimidad frente al uso de dispositivos de videovigilancia y de grabación de sonidos en el hogar.", "Derecho a la intimidad ante la utilización de sistemas de geolocalización en el ámbito laboral.", "Derechos digitales en la negociación colectiva.", "Derecho al olvido en búsquedas de Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 5, "Lo dispuesto en los títulos I a IX y en los artículos 89 a 94 de la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, se aplica a:", "Cualquier tratamiento totalmente automatizado de datos personales, así como al tratamiento automatizado de datos personales contenidos o destinados a ser incluidos en un fichero.", "Cualquier tratamiento total o parcialmente automatizado de datos personales, así como al tratamiento no automatizado de datos personales contenidos o destinados a ser incluidos en un fichero.", "Cualquier tratamiento totalmente automatizado de datos personales, así como al tratamiento no automatizado de datos personales contenidos o destinados a ser incluidos en un fichero.", "Cualquier tratamiento total o parcialmente automatizado de datos personales, así como al tratamiento automatizado de datos personales contenidos o destinados a ser incluidos en un fichero."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 6, "Indique cuál de las siguientes respuestas no es un principio de la protección de datos de acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales.", "Exactitud de los datos, siendo actualizados si fuera necesario.", "Deber de confidencialidad de los responsables y encargados del tratamiento de datos así como todas las personas que intervengan en cualquier fase de este.", "Tratamiento basado en el consentimiento del afectado, siendo aceptado la no existencia de una declaración negativa.", "Consentimiento de los menores de edad, cuando éstos sean mayores de catorce años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 7, "Indique cual de las siguientes respuestas no es un principio de la protección de datos de acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos).", "Minimización de datos.", "Limitación de la finalidad.", "Licitud, lealtad y opacidad.", "Exactitud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 8, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando la supresión derive del ejercicio del derecho de oposición con arreglo al artículo 21.2 del Reglamento (UE) 2016/679, el responsable:", "Podrá conservar los datos identificativos del afectado necesarios con el fin de impedir tratamientos futuros para fines de mercadotecnia indirecta.", "No podrá conservar los datos identificativos del afectado necesarios con el fin de impedir tratamientos futuros para fines de mercadotecnia indirecta.", "Podrá conservar los datos identificativos del afectado necesarios con el fin de impedir tratamientos futuros para fines de mercadotecnia directa.", "No podrá conservar los datos identificativos del afectado necesarios con el fin de impedir tratamientos futuros para fines de mercadotecnia directa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 9, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), ¿cuando no se aplicará el derecho de supresión?", "Cuando el tratamiento de datos personales afecte a menores.", "Cuando el tratamiento sea necesario para ejercer el derecho a la libertad de expresión e información.", "Cuando los datos personales hayan sido tratados ilícitamente.", "Cuando los datos personales ya no sean necesarios en relación con los fines para los que fueron recogidos o tratados de otro modo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 10, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, entre otras exigencias ¿Qué implica el Derecho de acceso universal a Internet?", "Todos tienen derecho a acceder a Internet independientemente de su condición personal, social, económica o geográfica.", "Los proveedores de servicios de Internet proporcionarán una oferta transparente de servicios sin discriminación por motivos técnicos o económicos.", "Se garantizará un acceso universal, gratuito y no discriminatorio para toda la población.", "Todos tienen derecho a la libertad de expresión en Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 11, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el encargado del tratamiento puede recurrir a otro encargado:", "En ningún caso.", "Siempre que se lo comunique dentro del siguiente mes natural al responsable, teniendo éste la oportunidad de autorizarlo u oponerse.", "Solo si tiene la autorización previa por escrito del responsable,y siempre que le informe de cualquier cambio previsto en la incorporación o sustitución de otros encargados, dando así al responsable la oportunidad de oponerse.", "Siempre que lo considere oportuno, dado que este reglamento autoriza al encargado a disponer de los recursos que considere mejores para cumplir con su función de acuerdo con la normativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 12, "De acuerdo con el Título V de la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados del tratamiento deberán designar un delegado de protección de datos (señale la respuesta incorrecta):", "Los distribuidores y comercializadores de energía eléctrica y los distribuidores y comercializadores de gas natural.", "Las empresas de servicios de inversión, reguladas por la legislación del Mercado de Valores.", "Los tribunales que actúen en ejercicio de su función judicial.", "Las entidades aseguradoras y reaseguradoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 13, "De acuerdo con el Título V de la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados del tratamiento comunicarán a la Agencia Española de Protección de Datos o, en su caso, a las autoridades autonómicas de protección de datos, las designaciones, nombramientos y ceses de los delegados de protección de datos:", "En el plazo de diez días, tanto en los supuestos en que se encuentren obligadas a su designación como en el caso en que sea voluntaria.", "En el plazo de diez días en los supuestos en que se encuentren obligadas a su designación pero no en el caso en que sea voluntaria.", "En el plazo de quince días, tanto en los supuestos en que se encuentren obligadas a su designación como en el caso en que sea voluntaria.", "En el plazo de quince días en los supuestos en que se encuentren obligadas a su designación pero no en el caso en que sea voluntaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 14, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el principio de minimización de datos en el tratamiento de datos supone que los datos personales serán:", "Adecuados, pertinentes y limitados a lo necesario en relación con los fines para los que son tratados.", "Exactos y, si fuera necesario, actualizados.", "Recogidos con fines determinados, explícitos y legítimos, y no serán tratados ulteriormente de manera incompatible con dichos fines.", "Tratados de manera lícita, leal y transparente en relación con el interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 15, "Indique cuál de las siguientes respuestas no está incluida entre las exigencias establecidas por la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, para garantizar el Derecho de acceso universal a Internet:", "Todos tienen derecho a acceder a Internet independientemente de su condición personal, social, económica o geográfica.", "El acceso a Internet de hombres y mujeres procurará la superación de la brecha de género tanto en el ámbito personal como laboral.", "La garantía efectiva del derecho de acceso a Internet atenderá la realidad específica de los entornos rurales.", "Todos tienen derecho a la libertad de expresión en Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 16, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el derecho a la portabilidad de los datos supone que el interesado tendrá derecho a recibir los datos personales que le incumban, que haya facilitado a un responsable del tratamiento, en un formato estructurado, de uso común y lectura mecánica:", "Para su supresión o modificación sin que lo impida el responsable al que se los hubiera facilitado.", "Y a transmitirlos a otro responsable del tratamiento pudiéndolo impedir el responsable al que se los hubiera facilitado.", "Para su supresión o modificación pudiéndolo impedir el responsable al que se los hubiera facilitado.", "Y a transmitirlos a otro responsable del tratamiento sin que lo impida el responsable al que se los hubiera facilitado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 17, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Agencia Española de Protección de Datos tendrá la condición de representante común de las autoridades de protección de datos del Reino de España en:", "el Parlamento Europeo.", "la Comisión Europea.", "el Comité Europeo de Protección de Datos.", "el Consejo Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 18, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el Derecho a la educación digital?", "Que el acceso a Internet deberá garantizar condiciones de igualdad para las personas que cuenten con necesidades especiales.", "Que se garantizará un acceso universal, asequible, de calidad y no discriminatorio para toda la población.", "Que el sistema educativo garantizará la plena inserción del alumnado en la sociedad digital y el aprendizaje de un consumo responsable y un uso crítico y seguro de los medios digitales.", "Que los usuarios tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 19, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el tratamiento de los datos de los menores de catorce años, fundado en su propio consentimiento:", "No será lícito en ningún caso, teniendo especial protección.", "Solo será lícito si consta el del titular de la patria potestad o tutela.", "Será lícito en todo caso.", "Solo será lícito si consta el del titular de la patria potestad o tutela y el del responsable del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 20, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el resultado positivo de sus ingresos se destinará por la Agencia Española de Protección de Datos a:", "La caja única de la Administración del Estado.", "La dotación de sus reservas con el fin de garantizar su plena independencia.", "La dotación de reservas para financiar a las autoridades de control autonómicas.", "El mantenimiento de los registros de actividades de tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 21, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los actos y disposiciones dictados por la Presidencia de la Agencia Española de Protección de Datos:", "No ponen fin a la vía administrativa, siendo recurribles mediante un recurso de alzada ante el Ministerio de Justicia.", "No ponen fin a la vía administrativa, siendo recurribles mediante un recurso de alzada ante el Ministerio de Asuntos Económicos y Transformación Digital.", "Ponen fin a la vía administrativa, siendo recurribles, directamente, ante la Sala de lo Contencioso-administrativo de la Audiencia Nacional.", "Ponen fin a la vía administrativa, siendo recurribles, directamente, ante la Sala de lo Social de la Audiencia Nacional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 22, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el tratamiento de datos personales tenga por objeto la mercadotecnia directa:", "El interesado tendrá derecho a oponerse en todo momento al tratamiento de los datos personales que le conciernan, incluida la elaboración de perfiles.", "El interesado tendrá derecho a oponerse en todo momento al tratamiento de los datos personales que le conciernan, excepto la elaboración de perfiles.", "La autoridad de control tendrá derecho a oponerse en todo momento al tratamiento de los datos personales que le conciernan, incluida la elaboración de perfiles.", "La autoridad de control tendrá derecho a oponerse en todo momento al tratamiento de los datos personales que le conciernan, excepto la elaboración de perfiles."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 23, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el derecho a la protección de los menores en Internet?", "La utilización o difusión de imágenes o información personal de menores en las redes sociales y servicios de la sociedad de la información equivalentes que puedan implicar una intromisión ilegítima en sus derechos fundamentales y determinará la intervención del Ministerio Fiscal.", "El sistema educativo garantizará la plena inserción del alumnado en la sociedad digital y el aprendizaje de un consumo responsable y un uso crítico y seguro de los medios digitales.", "Se garantizará un acceso universal, asequible, de calidad y no discriminatorio para toda la población, incluidos los menores.", "Los usuarios menores de edad tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 24, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Agencia Española de Protección Datos elaborará y aprobará su relación de puestos de trabajo:", "En el marco de los criterios establecidos por el Ministerio de Hacienda.", "En el marco de los criterios establecidos por el Ministerio de Presidencia.", "En el marco de los criterios establecidos por el Ministerio de Justicia.", "En el marco de los criterios establecidos por el Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 25, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, las autoridades autonómicas de protección de datos personales podrán ejercer, las funciones y potestades establecidas en los artículos 57 y 58 del Reglamento (UE) 2016/679, de acuerdo con la normativa autonómica, cuando se refieran a (señala la respuesta incorrecta):", "Tratamientos de los que sean responsables las entidades integrantes del sector público de la correspondiente Comunidad Autónoma o de las Entidades Locales incluidas en su ámbito territorial.", "Tratamientos llevados a cabo por personas físicas o jurídicas para el ejercicio de las funciones públicas en materias que sean competencia de la correspondiente Administración Autonómica o Local.", "Tratamientos llevados a cabo por personas físicas o jurídicas para fines de mercadotecnia directa.", "Tratamientos que se encuentren expresamente previstos, en su caso, en los respectivos Estatutos de Autonomía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 26, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el tratamiento de datos personales solo podrá considerarse fundado en el cumplimiento de una misión realizada en interés público o en el ejercicio de poderes públicos conferidos al responsable, en los términos previstos en el artículo 6.1 e) del Reglamento (UE) 2016/679:", "Cuando derive de una competencia atribuida por una norma de Derecho de la Unión Europea o una norma con rango de ley.", "Cuando derive una competencia atribuida por una norma reglamentaria de desarrollo de esta ley.", "Cuando derive de una competencia atribuida por una norma de Derecho de la Unión Europea.", "Cuando derive de una competencia atribuida por una norma con rango de ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 27, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el Derecho a la actualización de informaciones en medios de comunicación digitales?", "Los responsables de redes sociales y servicios equivalentes adoptarán protocolos adecuados para posibilitar el ejercicio del derecho de rectificación ante los usuarios que difundan contenidos que atenten contra el derecho al honor, la intimidad personal y familiar en Internet y el derecho a comunicar o recibir libremente información veraz.", "Toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran tras una búsqueda efectuada a partir de su nombre.", "Toda persona tiene derecho a solicitar motivadamente de los medios de comunicación digitales la inclusión de un aviso de actualización suficientemente visible junto a las noticias que le conciernan cuando la información contenida en la noticia original no refleje su situación actual como consecuencia de circunstancias que hubieran tenido lugar después de la publicación, causándole un perjuicio.", "Los usuarios tienen derecho a la seguridad de las comunicaciones que transmitan y reciban a través de Internet. Los proveedores de servicios de Internet informarán a los usuarios de sus derechos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 28, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), ¿cuál de las siguientes condiciones no suponen la licitud del tratamiento de datos personales?", "El tratamiento es necesario para la ejecución de un contrato en el que el interesado es parte o para la aplicación a petición de este de medidas precontractuales.", "El tratamiento es necesario para el cumplimiento de una obligación legal aplicable al particular.", "El tratamiento es necesario para proteger intereses vitales del interesado o de otra persona física.", "El interesado dio su consentimiento para el tratamiento de sus datos personales para uno o varios fines específicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 29, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el interesado es objeto de una decisión basada únicamente en el tratamiento automatizado y la decisión se basa en el consentimiento explícito del interesado, éste tendrá como mínimo el derecho a:", "Obtener intervención humana por parte del responsable, a expresar su punto de vista y a impugnar la decisión.", "Sin obtener intervención humana por parte del responsable, a expresar su punto de vista y a impugnar la decisión.", "Obtener intervención humana por parte del responsable, a expresar su punto de vista pero no a impugnar la decisión.", "Sin obtener intervención humana por parte del responsable, a expresar su punto de vista pero no a impugnar la decisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 30, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cuál de las siguientes es una infracción muy grave:", "La resistencia u obstrucción del ejercicio de la función inspectora por la autoridad de protección de datos competente.", "El tratamiento de datos personales de un menor de edad sin recabar su consentimiento, cuando tenga capacidad para ello, o el del titular de su patria potestad o tutela, conforme al artículo 8 del Reglamento (UE) 2016/679.", "El quebrantamiento, como consecuencia de la falta de la debida diligencia, de las medidas técnicas y organizativas que se hubiesen implantado conforme a lo exigido por el artículo 32.1 del Reglamento (UE) 2016/679.", "No cooperar con las autoridades de control en el desempeño de sus funciones en los supuestos no previstos en el artículo 72 de esta ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 31, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el tratamiento se base en el consentimiento del interesado:", "El interesado tendrá derecho a retirar su consentimiento a partir de un año desde la concesión.", "El interesado tendrá derecho a retirar su consentimiento a partir de los dos años desde la concesión.", "El interesado tendrá derecho a retirar su consentimiento a partir de los seis meses desde la concesión.", "El interesado tendrá derecho a retirar su consentimiento en cualquier momento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 32, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el derecho a la intimidad y uso de dispositivos digitales en el ámbito laboral?", "En ningún caso se admitirá la instalación de sistemas de grabación de sonidos ni de videovigilancia en lugares destinados al descanso o esparcimiento de los trabajadores o los empleados públicos, tales como vestuarios, aseos, comedores y análogos.", "Los empleadores podrán tratar los datos obtenidos a través de sistemas de geolocalización para el ejercicio de las funciones de control de los trabajadores o los empleados públicos previstas, respectivamente, en el artículo 20.3 del Estatuto de los Trabajadores y en la legislación de función pública, siempre que estas funciones se ejerzan dentro de su marco legal y con los límites inherentes al mismo.", "El empleador podrá acceder a los contenidos derivados del uso de medios digitales facilitados a los trabajadores a los solos efectos de controlar el cumplimiento de las obligaciones laborales o estatutarias y de garantizar la integridad de dichos dispositivos", "Los trabajadores y los empleados públicos tendrán derecho a la desconexión digital a fin de garantizar, fuera del tiempo de trabajo legal o convencionalmente establecido, el respeto de su tiempo de descanso, permisos y vacaciones, así como de su intimidad personal y familiar."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 33, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cuál de las siguientes es una infracción grave:", "La reversión deliberada de un procedimiento de anonimización a fin de permitir la reidentificación de los afectados.", "El incumplimiento del deber del encargado del tratamiento de notificar al responsable del tratamiento las violaciones de seguridad de las que tuviera conocimiento.", "El impedimento o la obstaculización o la no atención reiterada del ejercicio de los derechos establecidos en los artículos 15 a 22 del Reglamento (UE) 2016/679.", "El incumplimiento de la obligación de bloqueo de los datos establecida en el artículo 32 de esta ley orgánica cuando la misma sea exigible."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 34, "De acuerdo con el artículo 7 del Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), al evaluar si el consentimiento se ha dado libremente, se tendrá en cuenta en la mayor medida posible si:", "La ejecución de un contrato, se supedita al consentimiento al tratamiento de datos personales que no son necesarios para la ejecución de dicho contrato.", "El particular interesado es mayor de 65 años.", "La ejecución de un contrato se realiza fuera de la Unión Europea.", "El particular interesado es menor de 18 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 35, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el derecho a la intimidad frente al uso de dispositivos de videovigilancia y de grabación de sonidos en el lugar de trabajo?", "Los empleadores podrán tratar las imágenes obtenidas a través de sistemas de cámaras o videocámaras para el ejercicio de las funciones de control de los trabajadores o los empleados públicos previstas, respectivamente, en el artículo 20.3 del Estatuto de los Trabajadores y en la legislación de función pública, siempre que estas funciones se ejerzan dentro de su marco legal y con los límites inherentes al mismo.", "Se permitirá la instalación de sistemas de grabación de sonidos y de videovigilancia en lugares destinados al descanso o esparcimiento de los trabajadores o los empleados públicos, tales como vestuarios, aseos, comedores y análogos.", "Los empleadores no están obligados a informar a los trabajadores o los empleados públicos y, en su caso, a sus representantes, acerca de la medida de tratar las imágenes obtenidas a través de sistemas de cámaras o videocámaras para el ejercicio de las funciones de control de los trabajadores o los empleados públicos.", "Se preservará el derecho a la desconexión digital en los supuestos de realización total o parcial del trabajo a distancia así como en el domicilio del empleado vinculado al uso con fines laborales de herramientas tecnológicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 36, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados, teniendo en cuenta los elementos enumerados en los artículos 24 y 25 del Reglamento (UE) 2016/679, determinarán las medidas técnicas y organizativas apropiadas que deben aplicar a fin de garantizar y acreditar que el tratamiento es conforme, entre otros:", "A la presente ley orgánica y sus normas de desarrollo.", "Al estado de la técnica.", "Al contrato que regule las obligaciones de ambos.", "A la legislación local."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 37, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cual de las siguientes es una infracción leve:", "El tratamiento de datos personales sin llevar a cabo una previa valoración de los elementos mencionados en el artículo 28 de esta ley orgánica.", "No disponer del registro de actividades de tratamiento establecido en el artículo 30 del Reglamento (UE) 2016/679.", "La falta de atención por el representante en la Unión del responsable o del encargado del tratamiento de las solicitudes efectuadas por la autoridad de protección de datos o por los afectados.", "El incumplimiento de la obligación de notificación relativa a la rectificación o supresión de datos personales o la limitación del tratamiento exigida por el artículo 19 del Reglamento (UE) 2016/679."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 38, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, ¿Qué implica el Derecho a la intimidad frente al uso de dispositivos de videovigilancia y de grabación de sonidos en el lugar de trabajo?", "Los trabajadores y los empleados públicos tendrán derecho a la protección de su intimidad en el uso de los dispositivos digitales puestos a su disposición por su empleador.", "Se permitirá la instalación de sistemas de grabación de sonidos y de videovigilancia en lugares destinados al descanso o esparcimiento de los trabajadores o los empleados públicos, tales como vestuarios, aseos, comedores y análogos.", "Los empleadores podrán tratar los datos obtenidos a través de sistemas de geolocalización para el ejercicio de las funciones de control de los trabajadores o los empleados públicos.", "Los empleadores podrán tratar las imágenes obtenidas a través de sistemas de cámaras o videocámaras para el ejercicio de las funciones de control de los trabajadores o los empleados públicos previstas, respectivamente, en el artículo 20.3 del Estatuto de los Trabajadores y en la legislación de función pública, siempre que estas funciones se ejerzan dentro de su marco legal y con los límites inherentes al mismo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 39, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el tratamiento de los datos personales de un niño menor de 16 años, únicamente se considerará lícito:", "Si lo consiente el menor mayor de 14 años.", "Si el consentimiento lo dio o autorizó el titular de la patria potestad o tutela sobre el niño.", "Si lo consiente el menor mayor de 12 años.", "No puede realizarse tratamiento de datos personales de menores de 16 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 40, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, interrumpirá la prescripción de la infracción:", "La iniciación, aun sin el conocimiento del interesado, del procedimiento sancionador.", "La iniciación, con conocimiento del interesado, del procedimiento sancionador.", "La iniciación, con conocimiento del interesado, del procedimiento de cobro ejecutivo de la sanción.", "La iniciación, aun sin el conocimiento del interesado, del procedimiento de cobro ejecutivo de la sanción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 41, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, una vez interrumpida la prescripción de la infracción por la iniciación, con conocimiento del interesado, del procedimiento sancionador, se reinicirá el plazo de prescripción:", "Si el expediente sancionador estuviere paralizado durante más de nueve meses por causas no imputables al presunto infractor.", "Si el expediente sancionador estuviere paralizado durante más de tres meses por causas no imputables al presunto infractor.", "Si el expediente sancionador estuviere paralizado durante más de seis meses por causas no imputables al presunto infractor.", "Si el expediente sancionador estuviere paralizado durante más de nueve meses, siempre que lo solicite el interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 42, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indique la respuesta incorrecta en relación al derecho digital de protección de datos de los menores en Internet:", "Los centros educativos garantizarán la protección del interés superior del menor y sus derechos fundamentales.", "La publicación o difusión de datos personales del menor a través de servicios de la sociedad de la información deberán contar con el consentimiento del Ministerio Fiscal.", "Cualesquiera personas físicas o jurídicas que desarrollen actividades en las que participen menores de edad garantizarán la protección del interés superior del menor y sus derechos fundamentales.", "Cualesquiera personas físicas o jurídicas que desarrollen actividades en las que participen menores de edad garantizarán especialmente el derecho a la protección de datos personales, en la publicación o difusión de sus datos personales a través de servicios de la sociedad de la información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 43, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, para la adopción de las medidas técnicas y organizativas apropiadas que deben aplicar los responsables y encargados del tratamiento tendrán en cuenta, en particular, los mayores riesgos que podrían producirse cuando (señala la incorrecta):", "Cuando el tratamiento implicase una evaluación de aspectos personales de los afectados con el fin de crear o utilizar perfiles personales de los mismos.", "Cuando se produzca un tratamiento masivo que implique a un gran número de afectados.", "Cuando los datos personales fuesen a ser objeto de transferencia, con carácter habitual, a Estados de la Unión respecto de los que no se hubiese declarado un nivel adecuado de protección", "Cuando el tratamiento pudiera generar situaciones de discriminación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 44, "Cuando los datos personales sean obtenidos del afectado, el responsable del tratamiento podrá dar cumplimiento al deber de información establecido en el artículo 13 del Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos):", "Facilitando al afectado la información básica del tratamiento de esos datos.", "Indicando al afectado una dirección electrónica u otro medio que permita acceder de forma sencilla e inmediata a la información básica.", "Indicando al afectado un correo postal que permita acceder de forma inmediata a la información básica.", "Facilitando al afectado una dirección electrónica que permita acceder en el futuro a la información básica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 45, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica cual de las siguientes es una infracción leve:", "No cooperar con las autoridades de control en el desempeño de sus funciones en los supuestos no previstos en el artículo 72 de esta ley orgánica.", "No disponer del registro de actividades de tratamiento establecido en el artículo 30 del Reglamento (UE) 2016/679.", "No posibilitar la efectiva participación del delegado de protección de datos en todas las cuestiones relativas a la protección de datos personales, no respaldarlo o interferir en el desempeño de sus funciones.", "El incumplimiento de la obligación de suprimir los datos referidos a una persona fallecida cuando ello fuera exigible conforme al artículo 3 de esta ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 46, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando los datos personales sean obtenidos del afectado, el responsable del tratamiento deberá facilitar al afectado la información básica del tratamiento de esos datos, que debe contener:", "La identidad del responsable del tratamiento y de su representante, en su caso.", "La posibilidad de ejercer los principios de protección de datos establecidos en los artículos 15 a 22 del Reglamento (UE) 2016/679.", "Los resultados del tratamiento.", "Los medios de consentimiento del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 47, "Indique cuál de las siguientes respuestas no está incluida entre las exigencias establecidas por la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, para garantizar el derecho al olvido en búsquedas de Internet.", "El ejercicio del derecho al olvido en búsquedas de Internet debe impedir el acceso a la información publicada en el sitio web a través de la utilización de otros criterios de búsqueda distintos del nombre de quien ejerciera el derecho.", "El Derecho al olvido en búsquedas de Internet subsistirá aun cuando fuera lícita la conservación de la información publicada en el sitio web al que se dirigiera el enlace y no se procediese por la misma a su borrado previo o simultáneo", "Toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran tras una búsqueda efectuada a partir de su nombre cuando las circunstancias personales que invocase el afectado evidenciasen la prevalencia de sus derechos sobre el mantenimiento de los enlaces por el servicio de búsqueda en Internet.", "Toda persona tiene derecho a que los motores de búsqueda en Internet eliminen de las listas de resultados que se obtuvieran tras una búsqueda efectuada a partir de su nombre los enlaces publicados que contuvieran información relativa a esa persona cuando fuesen no pertinentes, entre otros motivos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 48, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el registro de actividades, deberá especificar, según sus finalidades:", "Los perfiles llevados a cabo y las demás circunstancias establecidas en el citado reglamento.", "Los datos personales tratados y las demás circunstancias establecidas en el citado reglamento.", "Las personas cuyos datos personales han sido tratados y las demás circunstancias establecidas en el citado reglamento.", "Las actividades de tratamiento llevadas a cabo y las demás circunstancias establecidas en el citado reglamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 49, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cada autoridad de control garantizará que la imposición de las multas administrativas con arreglo al presente Reglamento sean en cada caso individual:", "Eficientes, justas y disuasorias.", "Justas, disuasorias y correctivas.", "Efectivas, proporcionadas y disuasorias.", "Eficientes, proporcionadas y correctivas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 50, "Cuando el responsable o encargado de un tratamiento sea la administración de una comunidad autónoma y cometiesen alguna de las infracciones a las que se refiere la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, siendo la infracción imputable a autoridades o directivos y se acredite la existencia de informes técnicos o recomendaciones para el tratamiento que no hubieran sido debidamente atendidos:", "En la resolución en la que se imponga la sanción se incluirá una amonestación con denominación del cargo responsable y se ordenará la publicación en el Boletín Oficial autonómico que corresponda.", "En la resolución en la que se imponga la sanción se incluirá el cese del cargo responsable y se ordenará la publicación en el Boletín Oficial autonómico que corresponda.", "En la resolución se impondrá la sanción directamente al cargo responsable y se ordenará la publicación en el Boletín Oficial autonómico que corresponda.", "En la resolución en la que se imponga la sanción se incluirá el cese del cargo responsable pero no se publicará para no vulnerar la propia ley orgánica de protección de datos personales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 51, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica la respuesta incorrecta en relación a las disposiciones generales sobre ejercicio de los derechos de las personas en relación al tratamiento de sus datos personales.", "Los medios deberán ser fácilmente accesibles para el afectado.", "El encargado del tratamiento deberá facilitar un e-mail de contacto.", "El responsable del tratamiento estará obligado a informar al afectado sobre los medios a su disposición para ejercer los derechos que le corresponden.", "El ejercicio del derecho no podrá ser denegado por el solo motivo de optar el afectado por otro medio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 52, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, indica la respuesta correcta en relación a la prescripción de las sanciones impuestas en aplicación del Reglamento (UE) 2016/679 y de esta ley orgánica:", "Las sanciones por importe comprendido entre 40.001 y 300.000 euros prescriben a los tres años.", "Las sanciones impuestas por infracciones graves prescriben en el plazo de 2 años.", "Las sanciones por importe comprendido entre 40.001 y 300.000 euros prescriben a los dos años.", "Las sanciones impuestas por infracciones graves prescriben en el plazo de 3 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 53, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, los responsables y encargados del tratamiento de datos así como todas las personas que intervengan en cualquier fase de este estarán sujetas:", "Al deber de custodia.", "Al deber de confianza.", "Al deber de confidencialidad.", "Al deber de sigilo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 54, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el responsable del tratamiento estará obligado a bloquear los datos cuando:", "Cuando proceda a realizar actuaciones de mantenimiento.", "Cuando contrate a otro encargado.", "Cuando contrate a otro delegado de protección de datos.", "Cuando lleve a cabo la rectificación o supresión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 55, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el tratamiento de datos personales relativos a condenas e infracciones penales, solo podrá llevarse a cabo cuando se encuentre amparado en:", "Una norma de Derecho de la Unión o en esta ley orgánica.", "Esta ley orgánica o en otras normas de rango legal.", "En esta ley orgánica..", "Una norma de Derecho de la Unión, en esta ley orgánica o en otras normas de rango legal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 56, "El derecho a la transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), establece las formas en que puede ser facilitada la información (indica la incorrecta):", "Por escrito.", "Por medios electrónicos.", "Verbalmente, si lo ha solicitado el interesado y se identifica por otro medio.", "Verbalmente, si es el medio elegido por el encargado del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 57, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, y en relación al Derecho al testamento digital, indica la respuesta correcta.", "Las personas legitimadas al acceso a contenidos gestionados por prestadores de servicios de la sociedad de la información sobre personas fallecidas podrán decidir en cualquier caso acerca del mantenimiento o eliminación de los perfiles personales de personas fallecidas en redes sociales o servicios equivalentes.", "La persona fallecida no puede prohibir el acceso, por parte de personas vinculadas al fallecido o herederos, a contenidos gestionados por prestadores de servicios de la sociedad de la información.", "En caso de personas fallecidas menores de edad, las facultades de acceso a contenidos gestionados por prestadores de servicios de la sociedad de la información  podrán ejercerse también por el Ministerio Fiscal, que siempre actuará de oficio.", "Las personas legitimadas al acceso a contenidos gestionados por prestadores de servicios de la sociedad de la información sobre personas fallecidas podrán decidir acerca del mantenimiento o eliminación de los perfiles personales de personas fallecidas en redes sociales o servicios equivalentes, a menos que el fallecido hubiera decidido acerca de esta circunstancia, en cuyo caso se estará a sus instrucciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 58, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), el tratamiento de los datos personales de un niño se considerará lícito cuando tenga como mínimo:", "14 años, pudiendo los Estados miembros establecer por ley una edad inferior a tales fines, siempre que esta no sea inferior a 12 años.", "16 años, pudiendo los Estados miembros establecer por ley una edad inferior a tales fines, siempre que esta no sea inferior a 12 años.", "14 años, pudiendo los Estados miembros establecer por ley una edad inferior a tales fines, siempre que esta no sea inferior a 13 años.", "16 años, pudiendo los Estados miembros establecer por ley una edad inferior a tales fines, siempre que esta no sea inferior a 13 años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 59, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, al decidir la imposición de una multa administrativa y su cuantía se tendrá en cuenta (indica la respuesta incorrecta):", "La existencia de un proceso de fusión por absorción posterior a la comisión de la infracción, que no puede imputarse a la entidad absorbente.", "La afectación a los derechos de las personas vulnerables y de edad avanzada.", "Disponer, cuando no fuere obligatorio, de un delegado de protección de datos.", "La posibilidad de que la conducta del afectado hubiera podido inducir a la comisión de la infracción."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 60, "De acuerdo con el derecho a la transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), si el responsable del tratamiento no da curso a la solicitud del interesado:", "Le informará sin dilación, y a más tardar transcurridos 15 días de la recepción de la solicitud, de las razones de su no actuación y de la posibilidad de presentar otra solicitud.", "Le informará sin dilación, y a más tardar transcurridos 15 días de la recepción de la solicitud, de las razones de su no actuación y de la posibilidad de presentar una reclamación ante una autoridad de control y de ejercitar acciones judiciales.", "Le informará sin dilación, y a más tardar transcurrido un mes de la recepción de la solicitud, de las razones de su no actuación y de la posibilidad de presentar otra solicitud.", "Le informará sin dilación, y a más tardar transcurrido un mes de la recepción de la solicitud, de las razones de su no actuación y de la posibilidad de presentar una reclamación ante una autoridad de control y de ejercitar acciones judiciales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 61, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Presidencia y el Adjunto de la Agencia Española de Protección de Datos serán nombrados por el Consejo de Ministros mediante:", "Un real decreto.", "Una ley ordinaria", "Una orden ministerial.", "Un acuerdo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 62, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el acceso por parte de un encargado de tratamiento a los datos personales que resulten necesarios para la prestación de un servicio al responsable:", "No se considerará comunicación de datos en todo caso.", "No se considerará comunicación de datos siempre que se cumpla lo establecido en el Reglamento (UE) 2016/679, en la presente ley orgánica y en sus normas de desarrollo.", "Se considerará comunicación de datos en todo caso.", "Se considerará comunicación de datos siempre que se cumpla lo establecido en el Reglamento (UE) 2016/679, en la presente ley orgánica y en sus normas de desarrollo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 63, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la Presidencia de la Agencia Española de Protección de Datos estará asesorada por un Consejo Consultivo compuesto por los siguientes miembros (señala la incorrecta):", "Un experto propuesto por la Federación Española de Municipios y Provincias.", "Dos expertos propuestos por las Organizaciones Empresariales.", "Dos expertos propuestos por el Consejo de Consumidores y Usuarios.", "Un Diputado, propuesto por el Congreso de los Diputados"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 64, "De acuerdo con el derecho a la transparencia de la información regulado en el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), cuando el responsable del tratamiento tenga dudas razonables en relación con la identidad de la persona física que cursa la solicitud de acceso a los datos personales:", "Puede cobrar por facilitar dicha información.", "Puede dar respuesta a dicha solicitud en un plazo mas amplio.", "Tendrá que comunicar con el afectado para que de su consentimiento.", "Podrá solicitar que se facilite la información adicional necesaria para confirmar la identidad del interesado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 65, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), si un responsable o un encargado del tratamiento incumpliera de forma intencionada o negligente, para las mismas operaciones de tratamiento u operaciones vinculadas, diversas disposiciones del presente Reglamento, la cuantía total de la multa administrativa:", "No será superior a la cuantía prevista para las infracciones más graves.", "No será superior al doble de la cuantía prevista para todas las infracciones.", "Será la suma de las cuantías previstas para todas las infracciones.", "No será superior al triple de la cuantía prevista para todas las infracciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 66, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el derecho de acceso se entenderá otorgado si el responsable del tratamiento facilita al afectado un sistema de acceso remoto, directo y seguro a los datos personales:", "Que garantice de modo temporal por un mínimo de 6 meses, el acceso a su totalidad.", "Que garantice de modo permanente, el acceso a su totalidad.", "Que garantice de modo temporal por el plazo solicitado con un mínimo de 6 meses, el acceso a su totalidad.", "Que garantice de modo temporal, el acceso parcial a la información."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 67, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), al decidir la imposición de una multa administrativa y su cuantía en cada caso individual se tendrá debidamente en cuenta (indica la respuesta incorrecta):", "Cualquier medida tomada por el responsable o encargado del tratamiento para paliar los daños y perjuicios sufridos por los interesados.", "La intencionalidad o negligencia en la infracción.", "Toda infracción anterior cometida por el responsable o el encargado del tratamiento.", "El grado de responsabilidad del delegado de protección de datos del tratamiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 68, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, el responsable del tratamiento determinará si, cuando finalice la prestación de los servicios del encargado, los datos personales deben ser (indica la incorrecta):", "Destruidos.", "Devueltos al responsable.", "Entregados a un nuevo encargado.", "Devueltos a los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 69, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, a los efectos establecidos en el artículo 12.5 del Reglamento (UE) 2016/679 se podrá considerar repetitivo el ejercicio del derecho de acceso:", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de tres meses, a menos que exista causa legítima para ello.", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de cuatro meses, a menos que exista causa legítima para ello.", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de seis meses, a menos que exista causa legítima para ello.", "Cuando del derecho de acceso sea ejercido en más de una ocasión durante el plazo de un año, a menos que exista causa legítima para ello."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 70, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, y en relación a las políticas de impulso de los derechos digitales:", "El Gobierno, mediante decreto del Consejo de Gobierno, elaborará un plan de acceso a Internet.", "El Gobierno, en colaboración con las comunidades autónomas, elaborará un plan de acceso a Internet.", "El Consejo Consultivo de la Agencia Española de Protección de Datos elaborará un plan de acceso a Internet.", "La Agencia Española de Protección de Datos, en colaboración con las Autoridades autonómicas de protección de datos, elaborará un plan de acceso a Internet."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 71, "De acuerdo con el Reglamento (UE) 2016/679 del Parlamento Europeo y del Consejo, de 27 de abril de 2016 (Reglamento general de protección de datos), al decidir la imposición de una multa administrativa y su cuantía en cada caso individual se tendrá debidamente en cuenta (indica la respuesta incorrecta):", "La intencionalidad o negligencia en la infracción.", "Cualquier medida tomada por el responsable o encargado del tratamiento para paliar los daños y perjuicios sufridos por los interesados.", "Cualquier medida tomada por el delegado de protección de datos para paliar los daños y perjuicios sufridos por los interesados.", "La adhesión a códigos de conducta en virtud del artículo 40 o a mecanismos de certificación aprobados con arreglo al artículo 42."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 72, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando finalice la prestación de los servicios del encargado, no procederá la destrucción de los datos:", "Cuando exista una previsión legal que obligue a su conservación.", "Cuando la situación de la tecnología no lo permita.", "Cuando exista una previsión de poder reutilizar estos datos por parte del encargado.", "Cuando exista una previsión de poder reutilizar estos datos por parte del responsable de protección de datos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 73, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, la actividad de investigación de la Agencia Española de Protección de Datos se llevará a cabo por:", "Los funcionarios de la Agencia Española de Protección de Datos o por funcionarios ajenos a ella habilitados expresamente por su Presidencia.", "Exclusivamente por los funcionarios de la Agencia Española de Protección de Datos.", "Los funcionarios de la Agencia Española de Protección de Datos o por funcionarios ajenos a ella habilitados expresamente por el Ministerio de Justicia.", "Exclusivamente por funcionarios ajenos a ella habilitados expresamente por su Presidencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 74, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, estarán obligados a proporcionar a la Agencia Española de Protección de Datos los datos, informes, antecedentes y justificantes necesarios para llevar a cabo su actividad de investigación:", "Las Administraciones Públicas, excluidas las tributarias y de la Seguridad Social, y los particulares.", "Las Administraciones Públicas, incluidas las tributarias y de la Seguridad Social, y los particulares.", "Solo los particulares.", "Solo las Administraciones  Públicas, incluidas las tributarias y de la Seguridad Social."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 20, 75, "De acuerdo con la Ley Orgánica 3/2018, de 5 de diciembre, de protección de datos personales y garantía de los derechos digitales, cuando el afectado elija un medio distinto al que se le ofrece, que suponga un coste desproporcionado, para ejercer el derecho de acceso:", "La solicitud será considerada excesiva, por lo que dicho afectado asumirá el exceso de costes que su elección comporte.", "La solicitud será considerada excesiva, por lo que dicho afectado asumirá el 50% del exceso de costes que su elección comporte.", "La solicitud será considerada excesiva, por lo que el responsable del tratamiento debe informarle de los medios disponibles para ejercer su derecho.", "La solicitud será considerada excesiva, por lo que  el responsable del tratamiento está facultado a no responderla."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 1, "De acuerdo con el artículo 39 del Estatuto de Autonomía de las Illes Balears vigente, el sistema institucional autonómico está integrado:", "Por el Parlamento, el Gobierno y el presidente de la comunidad autónoma.", "Por el Parlamento y el Gobierno.", "Por el Parlamento, el Gobierno, el Presidente de la Comunidad Autónoma y los Consejos Insulares de Mallorca, Menorca, Eivissa y Formentera.", "Por el Parlamento, el Gobierno y el presidente de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 2, "Pueden ser elegidos diputados del Parlamento de las Illes Balears:", "Los ciudadanos españoles mayores de edad residentes en las Illes Balears, inscritos en el censo electoral y en pleno ejercicio de sus derechos civiles y políticos.", "Los ciudadanos españoles mayores de edad y en pleno ejercicio de sus derechos civiles y políticos.", "Los ciudadanos españoles mayores de edad, inscritos en el censo electoral y en pleno ejercicio de sus derechos civiles y políticos.", "Los ciudadanos españoles mayores de edad residentes en las Islas Baleares, inscritos en el censo electoral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 3, "El Parlamento de las Islas Baleares se reúne:", "Durante ocho meses al año en dos períodos de sesiones.", "Durante seis meses al año en dos períodos de sesiones.", "Durante cuatro meses al año en dos períodos de sesiones.", "Durante diez meses al año en un único período de sesiones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 4, "El Parlamento de las Illes Balears se reúne en sesión extraordinaria:", "A petición del Gobierno o por acuerdo de la Diputación Permanente o del Pleno, a propuesta de una quinta parte de los diputados.", "Por acuerdo del Pleno, a propuesta de dos terceras partes de los diputados.", "A petición del Gobierno o a petición de un grupo parlamentario.", "A petición del Gobierno o por acuerdo de la Diputación Permanente o del Pleno, a propuesta de una tercera parte de los diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 5, "Los diputados del Congreso elegidos en las Islas Baleares pueden asistir:", "En las sesiones del Pleno y de las comisiones que no tengan carácter secreto.", "En todas las sesiones del Pleno.", "En todas las sesiones del Pleno y de las comisiones.", "En las sesiones del Pleno, de la Diputación Permanente y de las comisiones que no tengan carácter secreto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 6, "La aprobación y la reforma del Reglamento del Parlamento de las Illes Balears requieren:", "La mayoría absoluta de los componentes del Parlamento.", "La mayoría de dos tercios de los componentes del Parlamento.", "La mayoría simple de los componentes del Parlamento.", "La mayoría absoluta de los presentes en la votación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 7, "La Diputación Permanente de las Illes Balears, en la que están representados todos los grupos parlamentarios, se elige:", "En proporción a la importancia numérica respectiva.", "En proporción a los resultados electorales obtenidos por cada grupo parlamentario.", "De acuerdo con los criterios establecidos en la Junta de Portavoces.", "En proporción a la importancia numérica ya la representatividad por islas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 8, "¿Cuál de estas funciones corresponde al Parlamento de las Islas Baleares?", "Designar el senador o los senadores que deben representar a la comunidad autónoma de las Illes Balears en el Senado.", "Dictar decretos ley.", "Deliberar sobre la decisión del presidente de disolver de forma anticipada el Parlamento.", "Proponer transferencias o delegaciones de competencias a favor de los consejos insulares y de otros entes locales de la comunidad autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 9, "El Parlamento de las Illes Balears, mediante ley, crea la institución de la Sindicatura de Greuges:", "Para la defensa de las libertades y de los derechos fundamentales de los ciudadanos, así como para supervisar e investigar las actividades de la Administración de la Comunidad Autónoma de las Illes Balears.", "Para examinar y aprobar la contabilidad de la Comunidad Autónoma.", "Por supervisar e investigar actividades contrarias a la ética pública.", "Para controlar la actividad del Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 10, "Indique la respuesta incorrecta. De acuerdo con el Reglamento del Parlamento de las Illes Balears, en el Parlamento de las Illes Balears:", "En la votación secreta mediante papeleta, los diputados son llamados con el criterio de más a menos edad para depositar la papeleta.", "La votación telemática puede ser ordinaria o secreta.", "La votación para la investidura del presidente del Gobierno siempre es pública por llamamiento.", "El voto de los diputados es personal e indelegable."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 11, "Las circunscripciones electorales para la elección del Parlamento de las Illes Balears son:", "Mallorca, Menorca, Ibiza y Formentera.", "Dos en Mallorca, una en Menorca y una en Eivissa.", "Una sola circunscripción.", "Dos: una por Mallorca y la otra por las demás islas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 12, "La ley que regula el total de diputados que deben integrar el Parlamento de las Illes Balears debe ser aprobada:", "Por una mayoría calificada de dos tercios.", "Por una mayoría calificada de tres cuartas partes.", "Por mayoría simple.", "Por una mayoría calificada de tres cuartas partes y la aprobación de las Cortes Generales mediante ley orgánica."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 13, "Para adoptar acuerdos, el Parlamento de las Islas Baleares y sus órganos:", "Deben estar reunidos reglamentariamente y con la asistencia de la mayoría de sus miembros.", "Deben estar reunidos con la asistencia de la mayoría de los grupos políticos.", "Deben estar reunidos con la asistencia mínima de un representado por grupo político.", "Deben estar reunidos reglamentariamente y con la asistencia de todos sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 14, "El orden del día del Pleno del Parlamento de las Illes Balears lo fija la Presidencia:", "Oída la Mesa, y de acuerdo con la Junta de Portavoces.", "Oído la Mesa.", "De acuerdo con la Junta de Portavoces.", "Sin necesidad de consulta previa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 15, "Las sesiones del Parlamento de las Illes Balears son públicas, excepto en los siguientes supuestos:", "Cuando así lo marque el Reglamento del Parlamento.", "Sólo cuando se traten cuestiones concernientes al decoro de la cámara.", "Sólo cuando se traten cuestiones concernientes a la suspensión de un diputado.", "Sólo cuando lo proponga el Pleno del Parlamento por mayoría absoluta de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 16, "Indique la respuesta incorrecta. De acuerdo con el Estatuto de Autonomía, en relación con el Parlamento de las Islas Baleares:", "Una ley del Parlamento, aprobada por mayoría absoluta, regula el total de diputados que deben integrarla.", "La duración del mandato de los diputados del Parlamento será de cuatro años.", "El Parlamento se constituye dentro del plazo máximo de treinta días después de la celebración de las elecciones.", "Los diputados del Parlamento de las Illes Balears no están vinculados por ningún mandato imperativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 17, "La Diputación Permanente tiene por función velar por el poder del Parlamento de las Illes Balears:", "Cuando no esté reunido, haya sido disuelto o haya expirado su mandato.", "Cuando haya sido disuelto.", "Cuando haya expirado su mandato.", "Cuando haya sido disuelto o haya expirado su mandato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 18, "La Mesa del Parlamento de las Islas Baleares:", "Es el órgano de gobierno y gestión del Parlamento.", "Está integrada por representantes de todos los grupos parlamentarios.", "Está integrada por un presidente, tres vicepresidentes y tres secretarios.", "Elije al presidente del Parlamento entre sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 19, "La Mesa del Parlamento de las Illes Balears puede acordar que un asunto se tramite por el procedimiento de urgencia:", "A petición motivada del Gobierno, de un grupo parlamentario o de una quinta parte de los diputados.", "A petición motivada del Gobierno o de un grupo parlamentario.", "A petición de un grupo parlamentario o de una quinta parte de los diputados.", "A petición motivada del Gobierno, de un grupo parlamentario o de un tercio de los diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 20, "Indique la respuesta incorrecta. De acuerdo con el Reglamento del Parlamento de las Illes Balears:", "El Pleno del Parlamento, a propuesta de dos grupos parlamentarios o de la cuarta parte de los miembros de la cámara, puede acordar la creación de una comisión de investigación.", "El presidente del Parlamento tiene el tratamiento de señor.", "Los miembros de la Mesa del Parlamento cesan por la pérdida de la condición de diputado.", "Son comisiones no permanentes las que se creen para un trabajo concreto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 21, "Corresponde al Parlamento de las Islas Baleares:", "Aprobar y decidir transferencias o delegaciones de competencias a favor de los consejos insulares y de otros entes locales de la comunidad autónoma.", "Dictar decretos ley.", "Aprobar el proyecto de ley de presupuestos generales de la Comunidad Autónoma.", "Deliberar sobre la decisión del presidente de disolver de forma anticipada el Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 22, "Corresponde al Parlamento de las Islas Baleares:", "Controlar la acción de gobierno.", "Fiscalizar la cuenta general de la Administración de la Comunidad Autónoma.", "Velar por el régimen de incompatibilidades de los cargos públicos.", "Dirimir los casos de conflicto de intereses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 23, "Indique la respuesta correcta. De acuerdo con el Estatuto de Autonomía de las Islas Baleares:", "La sede del Parlamento es la ciudad de Palma.", "La lengua catalana, propia de las Islas Baleares, es la lengua oficial del Parlamento de las Islas Baleares.", "Los diputados pueden invocar su condición de parlamentarios en el ejercicio de una actividad mercantil o profesional.", "Los miembros del Gobierno que no sean diputados no pueden asistir a las comisiones parlamentarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 24, "Aprobar el estatuto que regula la ordenación del régimen jurídico del personal al servicio del Parlamento de las Illes Balears corresponde:", "En la Mesa del Parlamento.", "En el Pleno del Parlamento.", "En la Comisión de Asuntos Institucionales.", "Al presidente del Parlamento, oída la Junta de Portavoces."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 25, "En el Parlamento de las Illes Balears, la sesión solemne de apertura de la legislatura tendrá lugar dentro del plazo:", "De los quince días hábiles siguientes al de la celebración de la sesión constitutiva.", "De los cuatro meses siguientes al de la convocatoria de las elecciones.", "De los treinta días hábiles siguientes al de la celebración de la sesión constitutiva.", "De los dos meses siguientes a la celebración de las elecciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 26, "No es una función de la Mesa del Parlamento de las Islas Baleares:", "Dirigir los debates del Pleno.", "Ordenar los gastos de la cámara.", "Calificar los escritos y la documentación de índole parlamentaria.", "Coordinar los trabajos de los distintos órganos del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 27, "Las decisiones de la Junta de Portavoces se adoptarán:", "En función del criterio del voto ponderado.", "Por mayoría de tres quintas partes de sus miembros.", "Por mayoría absoluta de sus miembros.", "Por mayoría simple de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 28, "En el Parlamento de las Illes Balears, el número de senadores que corresponden proporcionalmente a cada grupo parlamentario lo fija:", "La Mesa del Parlamento, de acuerdo con la Junta de Portavoces.", "El Pleno del Parlamento, a propuesta del Gobierno.", "El presidente del Parlamento.", "La Comisión de Asuntos Institucionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 29, "Indique la respuesta incorrecta sobre el Parlamento de las Illes Balears:", "En la sesión constitutiva elige al presidente de las Illes Balears.", "En la sesión constitutiva elige a la Mesa del Parlamento.", "Aprueba los presupuestos de la Comunidad Autónoma.", "Elije los síndicos de la Sindicatura de Cuentas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 30, "La organización del Gobierno, las atribuciones y el estatuto personal de cada uno de sus miembros se establecerá mediante:", "Una ley del Parlamento aprobada por mayoría absoluta.", "Una ley del Parlamento aprobada por mayoría de dos terceras partes de sus miembros.", "Una ley del Parlamento aprobada por mayoría simple.", "Una ley del Parlamento aprobada por tres cuartas partes de sus miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 31, "El presidente de las Illes Balears recibe el tratamiento de:", "Señor.", "Excelentísimo.", "Muy Honorable.", "Ilustrísimo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 32, "El presidente de las Illes Balears debe ser elegido por el Parlamento entre:", "Sus miembros.", "Los candidatos propuestos entrega por los distintos grupos parlamentarios.", "Los ciudadanos españoles mayores de edad residentes en las Islas Baleares, inscritos en el censo electoral.", "Los secretarios generales de los partidos con representación parlamentaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 33, "En caso de fallecimiento del presidente de las Illes Balears, el Gobierno debe ser presidido interinamente:", "Por el vicepresidente, si existe, siempre que tenga la condición de diputado del Parlamento de las Illes Balears.", "Por el consejero sin cartera.", "Por el presidente del Consejo Consultivo.", "Por el consejero de mayor edad, siempre que pertenezca al mismo grupo político."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 34, "El presidente de las Illes Balears le nombra:", "El rey.", "El Pleno del Parlamento de las Islas Baleares.", "El presidente del Gobierno del Estado.", "El Gobierno de las Islas Baleares, oída la Mesa del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 35, "De acuerdo con la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, al presidente de las Illes Balears le corresponden atribuciones:", "De representación y de dirección.", "De representación, gestión y dirección.", "De gestión y asesoramiento.", "De representación, asesoramiento y planificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 36, "El presidente de las Illes Balears debe tomar posesión del cargo:", "En el plazo de cinco días a contar desde el día en que se haya publicado el real decreto de nombramiento en el Boletín Oficial del Estado.", "En el plazo de quince días a contar desde el día en que se haya publicado el Real Decreto de nombramiento en el Boletín Oficial del Estado.", "En el plazo de cinco días a contar desde el día en que se haya publicado el real decreto de nombramiento en el Boletín Oficial de las Illes Balears.", "En el plazo de quince días a contar desde el día en que se haya publicado el real decreto de nombramiento, de forma simultánea, en el Boletín Oficial de las Illes Balears y en el Boletín Oficial del Estado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 37, "El acto de toma de posesión del cargo de presidente de las Islas Baleares consiste:", "En la aceptación del cargo y el acatamiento de la Constitución y del Estatuto de autonomía.", "En la aceptación del cargo y el acatamiento de la Constitución.", "En el acatamiento de la Constitución y del Estatuto de Autonomía.", "La aceptación del cargo y la promesa de cumplir la Constitución y el Estatuto de Autonomía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 38, "Indique la respuesta incorrecta. El presidente y el Gobierno de las Islas baleares en funciones no pueden llevar a cabo las siguientes actuaciones:", "Adoptar las medidas que resulten necesarias en casos de urgencia o por razones de interés general.", "Presentar el proyecto de ley de presupuestos generales de la Comunidad Autónoma.", "Plantear una cuestión de confianza.", "Nombrar nuevos consejeros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 39, "Corresponde al presidente de las Islas Baleares:", "Suscribir instrumentos de colaboración y cooperación con el Estado.", "Autorizar la firma de instrumentos de colaboración y cooperación con el Estado.", "Establecer la política general de la comunidad autónoma.", "Ejercer facultades de coordinación de los consejos insulares de acuerdo con la legislación vigente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 40, "El planteamiento de la moción de censura en las Illes Balears debe llevarse a cabo de acuerdo con lo que disponen:", "El Estatuto de autonomía y el Reglamento del Parlamento.", "El Estatuto de Autonomía y la Ley reguladora del Gobierno de las Illes Balears.", "La Ley reguladora del régimen jurídico de la Comunidad Autónoma.", "La Ley reguladora del buen gobierno y el Reglamento del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 41, "Los acuerdos del Consejo de Gobierno de las Illes Balears se adoptan:", "Por mayoría de los miembros presentes, física o telemáticamente.", "Por mayoría simple de los miembros presentes físicamente.", "Por mayor absoluta de los miembros presentes, físicamente.", "Por unanimidad de los miembros presentes, física o telemáticamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 42, "No son órganos de apoyo y de colaboración del Gobierno de las Islas Baleares:", "La Comisión Interdepartamental de Retribuciones.", "La Comisión de Secretarios Generales.", "Los gabinetes.", "Los comisionados autonómicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 43, "En la Comunidad Autónoma de las Islas Baleares, los gabinetes constituyen estructuras de apoyo político y técnico de asistencia y de asesoramiento directo:", "De la Presidencia y de los miembros del Gobierno.", "De la Presidencia y del vicepresidente.", "De la Presidencia, los miembros del Gobierno y los entes del sector público instrumental", "De la Presidencia, los miembros del Gobierno y los entes del sector público instrumental administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 44, "En la Comunidad Autónoma de las Illes Balears, la duración y el alcance específico del mandato de los comisionados autonómicos debe establecerse:", "Mediante un decreto del Consejo de Gobierno.", "Mediante decreto de la Presidencia.", "Mediante orden del consejero encargado de la secretaría del Consejo de Gobierno.", "Mediante decreto ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 45, "El portavoz del Gobierno de las Islas Baleares:", "Debe ser miembro del Consejo de Gobierno.", "Es el vicepresidente.", "No es necesario que sea miembro del Consejo de Gobierno.", "Debe ser miembro del Consejo de Gobierno y diputado del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 46, "La ley que tiene por objeto establecer, de acuerdo con el Estatuto de Autonomía, el régimen jurídico aplicable al presidente, al Gobierno de las Illes Balears ya sus miembros, así como regular el ejercicio de la iniciativa legislativa y de las potestades normativas del Gobierno es:", "La Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears.", "La Ley 4/2001, de 14 de marzo, del Gobierno de las Islas Baleares.", "la Ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno.", "La Ley 3/2003, de 26 de marzo, de régimen jurídico de la Administración de la Comunidad Autónoma de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 47, "En el Gobierno de las Illes Balears, los comisionados autonómicos:", "Son órganos que desarrollan con carácter temporal funciones concretas de representación.", "Se incorporan al Gobierno como un consejero más.", "La Ley 1/2019, de 31 de enero, del Gobierno de las Islas Baleares, los prohíbe expresamente.", "Son órganos superiores de la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 48, "El número máximo de consejeros sin cartera:", "No viene determinado en la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears.", "Es un cuarto de los miembros del Gobierno.", "La Ley 1/2019, de 31 de enero, del Gobierno de las Islas Baleares los prohíbe expresamente.", "Son tres."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 49, "Para ser consejeros en el Gobierno de las Illes Balears, además de ser mayor de edad y disfrutar de los derechos de sufragio activo y pasivo, se requiere:", "Tener la nacionalidad española y no estar inhabilitado para el ejercicio de cargo u empleo público por sentencia firme.", "b)Ser diputado del Parlamento y no estar inhabilitado para el ejercicio de cargo u empleo público por sentencia firme.", "c)Estar empadronado en las Islas Baleares y no estar inhabilitado para el ejercicio de cargo público por sentencia firme.", "d)Tener la nacionalidad española y estar empadronado en las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 50, "Las órdenes que afectan a más de una consejería del Gobierno de las Illes Balears son firmadas:", "Por el consejero encargado de la secretaría del Consejo de Gobierno.", "Por los consejeros competentes en materia de régimen jurídico.", "Por el presidente del Gobierno.", "Por todos los miembros del Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 51, "Los miembros del Gobierno de las Illes Balears deben ejercer sus funciones:", "Con dedicación exclusiva.", "Con dedicación parcial.", "Con lealtad política.", "Sin ningún tipo de limitación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 52, "La adscripción a las consejerías del Gobierno de las Illes Balears de los entes del sector público instrumental corresponde:", "Al presidente del Gobierno, mediante decreto.", "Al consejero competente en materia del sector público.", "Al consejero competente en materia de hacienda y presupuestos.", "Al consejero competente en la materia, mediante orden."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 53, "Los consejeros del Gobierno de las Islas Baleares reciben el tratamiento de:", "Señor o Señora.", "Excelentísimo o Excelentísima.", "Muy Honorable.", "Muy Ilustrísimo o Muy Ilustrísima."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 54, "Indique la respuesta incorrecta:", "Los consejeros son órganos directivos de la Administración de la Comunidad Autónoma.", "En el Gobierno de las Illes Balears, los consejeros sin cartera carecen de responsabilidades ejecutivas.", "El cese de los consejeros del Gobierno de las Illes Balears surtirá efectos desde el momento de la publicación del correspondiente decreto del presidente en el Boletín Oficial de las Illes Balears.", "Los consejeros del Gobierno de las Illes Balears cesan por la decisión del presidente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 55, "En el Gobierno de las Illes Balears, en caso de vacante del cargo de consejero:", "El presidente, mediante decreto, debe encomendar transitoriamente a otro miembro del Gobierno el despacho de los asuntos de la consejería.", "El presidente, mediante resolución, debe encomendar transitoriamente a otro miembro del Gobierno el despacho de los asuntos de la consejería.", "Asume el cargo el consejero de mayor edad.", "El vicepresidente asume el despacho de los asuntos de la consejería."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 56, "Corresponde a los órganos directivos la Administración de la Comunidad Autónoma de las Islas Baleares:", "Ejecutar y desarrollar los planes de actuación.", "Establecer los planes de actuación.", "Dirigir los recursos humanos de su consejería.", "Asignar los recursos necesarios para la ejecución de los planes de actuación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 57, "Indique la respuesta incorrecta. En el Gobierno de las Islas Baleares:", "La estructura básica de cada consejería debe aprobarse mediante decreto del Consejo de Gobierno.", "Corresponde a los consejeros suscribir contratos en nombre de la Administración autonómica.", "Los secretarios generales controlan la gestión del presupuesto de la consejería.", "Corresponde al secretario general la gestión del registro general, medios materiales y servicios auxiliares de cada consejería."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 58, "De acuerdo con el artículo 48 de la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, las disposiciones generales se ajustan a la siguiente jerarquía:", "Primero, los decretos aprobados por el Consejo de Gobierno o por el presidente, y segundo, las órdenes de los consejeros.", "Primero, los decretos por el presidente; segundo, los decretos aprobados por el Consejo de Gobierno, y tercero, las órdenes de los consejeros.", "Primero, los decretos por el presidente; segundo, los decretos aprobados por el Consejo de Gobierno; tercero, las órdenes de los consejeros, y cuarto, los acuerdos del Consejo de Gobierno.", "Primero, los decretos aprobados por el Consejo de Gobierno, y según los acuerdos del Consejo de Gobierno y los decretos del presidente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 59, "En el Gobierno de las Illes Balears, corresponde al Consejo de Gobierno:", "Aprobar el proyecto de ley de presupuestos generales de la Comunidad Autónoma.", "Disolver el Parlamento y convocar anticipadamente elecciones.", "Ejercer la potestad reglamentaria mediante la aprobación de órdenes.", "Designar al representante de las Illes Balears en el Patronato del Archivo de la Corona de Aragón."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 60, "El presidente de las Illes Balears cesa:", "Por la denegación de la cuestión de confianza.", "Por acuerdo unánime de los miembros del Consejo de Gobierno.", "Por petición del Gobierno del Estado.", "Por la presentación de una moción de censura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 61, "¿En qué supuesto de cese del presidente de las Illes Balears éste no puede continuar en el cargo hasta que su sucesor haya tomado posesión?", "La pérdida de la condición de diputado del Parlamento.", "La aprobación de la moción de censura.", "La dimisión comunicada por escrito al presidente del Parlamento.", "Después de las elecciones al Parlamento de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 62, "El presidente del Parlamento, en el supuesto del cese del presidente de las Illes Balears como consecuencia de la incompatibilidad declarada y publicada:", "En el plazo máximo de dos meses debe reunir la cámara para elegir un nuevo presidente.", "Asume interinamente la presidencia por un plazo máximo de tres meses.", "En el plazo máximo de un mes debe reunir la cámara para elegir a un nuevo presidente.", "Asume interinamente la presidencia hasta la convocatoria de nuevas elecciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 63, "Durante el tiempo en que el cargo de presidente esté vacante, debe ejercer las atribuciones de representación de las Illes Balears:", "El presidente del Parlamento.", "El vicepresidente del Gobierno.", "El consejero más antiguo en el cargo.", "El presidente del Consejo Consultivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 64, "En la Comunidad Autónoma de las Islas Baleares, el Gobierno reunido para el ejercicio de sus funciones constituye:", "El Consejo de Gobierno.", "El Gobierno de las Islas Baleares.", "El Consejo de Ministros.", "El Consejo Ejecutivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 65, "En la Comunidad Autónoma de las Illes Balears, las deliberaciones del Consejo de Gobierno tienen el carácter secreto, y sus miembros están obligados a observar el deber de reserva:", "Incluso después de su cese.", "Hasta el día de su cese.", "En los supuestos que pueden afectar al honor de los miembros del gobierno.", "Hasta tres años después de su cese."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 66, "En la Comunidad Autónoma de las Islas Baleares, corresponde al Consejo de Gobierno:", "Solicitar que el Parlamento de las Illes Balears se reúna en sesión extraordinaria.", "Designar al representante de las Illes Balears en el Patronato del Archivo de la Corona de Aragón.", "Mantener las relaciones institucionales con los órganos superiores de la Administración General del Estado, de las comunidades autónomas y del resto de administraciones públicas.", "Solicitar el dictamen del Consejo Consultivo, en los supuestos previstos en la legislación vigente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 67, "En la Comunidad Autónoma de las Illes Balears, de las sesiones del Consejo de Gobierno se extenderá un acta en formato electrónico en la que deben constar, como mínimo:", "Las circunstancias relativas al tiempo, lugar y asistentes, así como los acuerdos adoptados y, en su caso, si han comparecido de forma presencial oa distancia, con indicación de las razones por las que la asistencia no ha podido ser presencial .", "Las circunstancias relativas al tiempo, lugar y asistentes, así como los acuerdos adoptados.", "Las circunstancias relativas al tiempo, lugar y asistentes, así como los acuerdos adoptados y, en su caso, si han comparecido de forma presencial oa distancia.", "De las sesiones del Consejo de Gobierno no se extiende acta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 68, "En el Gobierno de las Illes Balears, los principios y las reglas de actuación del gobierno en funciones vienen regulados:", "En el capítulo V del título II de la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears.", "En el capítulo IV del título II de la Ley 4/2001, de 14 de marzo, del Gobierno de las Islas Baleares.", "En el capítulo V del título II de la Ley 4/2011, de 31 de marzo, de la buena administración y del buen gobierno.", "En el capítulo V del título I de la Ley 1/2019, de 31 de enero, del Gobierno de las Islas Baleares."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 69, "En el Gobierno de las Illes Balears, en la última sesión antes de la celebración de las elecciones, el Consejo de Gobierno debe aprobar una memoria que incluya:", "El importe de los compromisos que afecten a los dos ejercicios siguientes.", "El importe de las operaciones de endeudamiento concertadas en las tres últimas anualidades.", "La falta de liquidez existente en la Tesorería.", "El estado de ejecución del presupuesto del ejercicio en curso y la liquidación de los anteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 70, "Los consejeros del Gobierno de las Illes Balears cesan:", "Por la decisión del presidente.", "Por ausencia temporal.", "Por vacaciones.", "Por impedimento temporal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 71, "Indique la respuesta incorrecta. El Consejo de Gobierno puede aprobar el código de conducta del Gobierno y de sus miembros, que, en todo caso, deben cumplir los siguientes deberes:", "Ejercer sus funciones con dedicación parcial y subjetividad.", "Mantener una conducta digna y tratar a los ciudadanos con corrección.", "Ejercer los poderes atribuidos con la finalidad exclusiva para la que les fueron otorgados.", "Desempeñar las funciones con imparcialidad, responsabilidad y lealtad institucional, velando siempre por la consecución de los intereses generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 72, "Se produce conflicto de intereses cuando los miembros del Gobierno de las Islas Baleares intervienen:", "En decisiones relacionadas con asuntos en los que concurren intereses del cargo o empleo públicos e intereses privados personales, de familiares directos o compartidos con terceras personas.", "En decisiones relacionadas con asuntos en los que concurren intereses del cargo o empleo públicos e intereses privados personales.", "En decisiones relacionadas con asuntos en los que concurren intereses del cargo o empleo públicos e intereses privados personales o de familiares en primer grado de consanguinidad.", "En decisiones relacionadas con asuntos en los que concurren intereses del cargo o empleo públicos e intereses de familiares directos hasta segundo grado de consanguinidad o compartidos con terceras personas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 73, "El Consejo de Gobierno debe comunicar al Parlamento de las Illes Balears:", "El nombramiento de los miembros del Gobierno de las Illes Balears.", "El nombramiento de los órganos de dirección y de los directivos públicos profesionales del sector público autonómico.", "La declaración patrimonial, que abarque la totalidad de sus derechos y obligaciones, de los miembros del Gobierno y de sus órganos directivos del mismo.", "El nombramiento del personal eventual de gabinete."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 74, "Los principios y las normas de conducta que establece la Ley 1/2019, de 31 de enero, del Gobierno de las Illes Balears, será también de aplicación:", "A los altos cargos, al personal eventual ya todo el personal que ocupe puestos de naturaleza directiva de la Administración autonómica, independientemente de su denominación.", "A los altos cargos, personal eventual y personal que ocupe puestos de órganos unipersonales de dirección de la Administración autonómica, independientemente de su denominación.", "A los altos cargos y miembros de la Mesa del Parlamento de las Illes Balears.", "A los altos cargos ya todo el personal que ocupe puestos de naturaleza directiva de la Administración autonómica, independientemente de su denominación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 75, "Son órganos directivos de la Administración de la Comunidad Autónoma de las Islas Baleares:", "Los secretarios generales, los directores generales y los demás órganos a los que se asimilen en rango.", "Los secretarios generales técnicos, los directores generales y los demás órganos a los que se asimilen en rango.", "Los secretarios generales, los directores generales y los gerentes de los organismos públicos.", "Los secretarios generales, los directores ejecutivos y los órganos unipersonales de dirección de los entes del sector público autonómico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 76, "Indique la respuesta correcta. Corresponde a los consejeros, como miembros del Gobierno de las Islas Baleares:", "Proponer al Consejo de Gobierno el nombramiento y cese de los cargos públicos que dependen de su consejería.", "Ejercer la presidencia de los consejos de dirección de los entes de su consejería.", "Informar de los proyectos de disposiciones generales tramitados por su consejería.", "Velar por la utilización racional y eficiente de los medios materiales de su consejería."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 77, "Indique la respuesta incorrecta. Corresponde a los consejeros del Gobierno de las Illes Balears, en el ámbito de las competencias materiales atribuidas a su consejería, las siguientes funciones de gestión:", "Ejercer el control de la eficacia y de la eficiencia de los órganos y de las unidades administrativas de la consejería.", "Dirigir los recursos humanos de la consejería.", "Nombrar, o en su caso, proponer, al representante de la consejería en los órganos colegiados, si no lo regula la normativa aplicable.", "Gestionar los créditos para gastos de sus secciones presupuestarias y proponer sus modificaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 78, "Las consejerías del Gobierno de las Illes Balears, para el ejercicio de sus funciones, se estructuran:", "En Secretaría General y direcciones generales.", "En Secretaría General Técnica y direcciones generales.", "En Secretaría General, direcciones generales, gabinetes y comisionados autonómicos.", "En Secretaría General, direcciones generales, gabinetes, departamentos y servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 79, "El nombramiento de los titulares de los órganos directivos de la Administración de la Comunidad Autónoma de las Illes Balears se hace atendiendo a criterios:", "De competencia profesional y experiencia.", "De competencia profesional, experiencia y confianza personal.", "De confianza personal, experiencia, responsabilidad y lealtad política", "De confianza personal y lealtad política."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 80, "Los secretarios generales son:", "Órganos directivos encargados de la gestión de los servicios comunes, y de las funciones de asesoramiento jurídico y de soporte técnico.", "Órganos superiores encargados de la gestión de los servicios comunes, y de las funciones de asesoramiento jurídico y de soporte técnico.", "Órganos superiores encargados de la gestión de los servicios comunes, de las funciones de asesoramiento jurídico y de la dirección de la ejecución de los planes de actuación.", "Órganos directivos encargados de la gestión de los servicios comunes, de las funciones de impulso normativo y del control de la ejecución de los planes de actuación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 81, "Corresponde a los consejeros del Gobierno de las Illes Balears:", "Dirigir los recursos humanos de su consejería.", "Controlar la gestión racional del presupuesto de la consejería.", "Solicitar el dictamen del Consejo Consultivo en asuntos de la consejería.", "Nombrar a los órganos superiores de su consejería."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 82, "Es un órgano superior de la Administración de la Comunidad Autónoma de las Islas Baleares:", "El consejero competente en materia de salud.", "El presidente del Parlamento de las Illes Balears.", "La Secretaría Autonómica.", "El Pleno de la Sindicatura de Cuentas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 6, 83, "En el Gobierno de las Illes Balears, los secretarios generales se nombran y se separan:", "Mediante decreto del Consejo de Gobierno a propuesta del titular de la consejería.", "Mediante resolución del consejero titular de la consejería, oído el Consejo de Gobierno.", "Mediante decreto del presidente de las Illes Balears a propuesta del Consejo de Gobierno.", "Mediante orden del consejero titular de la consejería."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 1, "El Tribunal de Justicia de la Unión Europea establecerá su Reglamento de Procedimiento, el cual requerirá la aprobación:", "Del Consejo.", "Del Parlamento Europeo.", "Del Consejo Europeo.", "De la Comisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 2, "De acuerdo con el artículo 288 del Tratado de Funcionamiento de la Unión Europea, ¿qué norma tendrá un alcance general, será obligatoria en todos sus elementos y directamente aplicable en cada estado miembro?", "La directiva.", "El dictamen.", "El reglamento.", "La decisión cuando designe destinatarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 3, "Un miembro de la Comisión Europea presentará su dimisión si se lo pide:", "El presidente del Parlamento Europeo.", "El presidente del Consejo Europeo.", "El presidente de la Comisión Europea.", "El presidente del Consejo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 4, "¿En qué fecha se firmó el Tratado de Roma?", "2 de setiembre de 1951.", "25 de marzo de 1957.", "8 de abril de 1964.", "1 de julio de 1987"); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 5, "Respecto de la Unión Europea, es incorrecto afirmar lo siguiente:", "Los reglamentos tendrán un alcance general. Serán obligatorios en todos sus elementos y directamente aplicables en cada estado miembro.", "Las directivas obligarán al estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando, sin embargo, a las autoridades nacionales la elección de la forma y de los medios.", "Las recomendaciones son vinculantes.", "Los dictámenes no son vinculantes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 6, "El Tratado de la Unión Europea se firmó en Maastricht:", "El 15 de abril de 1988.", "El 7 de septiembre de 1990.", "El 15 de octubre de 1960.", "El 7 de febrero de 1992."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 7, "Es correcto afirmar que los reglamentos de la Unión Europea:", "Son no vinculantes.", "Son derecho comunitario primario.", "Son derecho derivado.", "Son recomendaciones y dictámenes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 8, "Es correcto afirmar que las directivas de la Unión Europea:", "Tienen un alcance general. Son obligatorias en todos sus elementos y directamente aplicables en cada estado miembro.", "Obligan al estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando, sin embargo, a las autoridades nacionales la elección de la forma y de los medios.", "No son vinculantes.", "Son derecho comunitario primario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 9, "El Tratado de París que crea la Comunidad Europea del Carbón y el Acero entró en vigor:", "El 16 de abril de 1948.", "El 18 de abril de 1961.", "El 23 de julio de 1952.", "El 2 de junio de 1960."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 10, "El Consejo Europeo está formado:", "Únicamente por los jefes de estado o de gobierno de los estados miembros de la Unión Europea.", "Por los jefes de estado o de gobierno de los estados miembros de la Unión Europea y por el presidente del Parlamento Europeo.", "Por los jefes de estado o de gobierno de los Estados Miembros de la Unión Europea, por el presidente del Consejo Europeo y por el presidente del Parlamento Europeo.", "Por los jefes de estado o de gobierno de los estados miembros de la Unión Europea, por el presidente del Consejo Europeo y por el presidente de la Comisión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 11, "¿Qué organismo de la Unión Europea elabora el anteproyecto del presupuesto?", "El Defensor del Pueblo europeo.", "El Consejo Europeo.", "La Comisión Europea.", "El Parlamento Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 12, "¿En qué tratado aparece por primera vez la posibilidad de que un estado miembro pueda abandonar la Unión Europea?", "En el Tratado de Lisboa.", "En el Tratado de Ámsterdam.", "En el Tratado de Niza.", "En el Tratado de Roma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 13, "¿Dónde se firmó la última reforma del Tratado de la Unión Europea?", "En Ámsterdam.", "No se ha producido ninguna reforma del Tratado de la Unión Europea.", "En Niza.", "En Lisboa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 14, "El 18 de abril de 1951 se firmó en París el Tratado constitutivo de la Unión Europea del Carbón y del Acero, ¿qué países firmaron dicho Tratado?", "Alemania occidental, Bélgica, Francia, Italia, Luxemburgo y los Países Bajos.", "Alemania occidental, Bélgica, Francia, Italia, Gran Bretaña y los Países Bajos.", "Alemania occidental, Francia, Gran Bretaña, Italia, Luxemburgo y Países Bajos.", "Alemania occidental, Dinamarca, Francia, Italia, Luxemburgo y Países Bajos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 15, "Los Reglamentos Europeos se caracterizan:", "Por su carácter no obligatorio, su alcance individual y su aplicabilidad directa.", "Por su carácter obligatorio, su alcance individual y su aplicación directa.", "Por su carácter vinculante, su alcance general y su no aplicabilidad directa.", "Por su carácter obligatorio, su alcance general y su aplicación directa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 16, "En relación con la Unión Europea, las recomendaciones y los dictámenes:", "No son vinculantes y van dirigidos tanto a estados miembros como a personas físicas o jurídicas.", "Son vinculantes y van dirigidos tanto a estados miembros como a personas físicas o jurídicas.", "Son vinculantes y van dirigidos a todos los estados miembros.", "No son vinculantes y solo van dirigidos a personas físicas o jurídicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 17, "Una de las siguientes no es una función de la Comisión Europea:", "Ejecutar el presupuesto y gestionar los programas.", "Velar por la aplicación de los tratados de la UE.", "La potestad legislativa.", "La iniciativa legislativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 18, "Señale la respuesta correcta. El Parlamento Europeo:", "Solo tiene funciones de consulta.", "Solo es un órgano de control.", "Se elige por sufragio universal directo.", "Es el órgano encargado de ejecutar el presupuesto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 19, "La Mesa del Parlamento Europeo estará compuesta:", "Por el presidente, doce vicepresidentes y los cuestores.", "Por el presidente, diez vicepresidentes y los cuestores.", "Por el presidente, dos vicepresidentes y los cuestores.", "Por el presidente, catorce vicepresidentes y los cuestores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 20, "Los derechos, libertades y principios reconocidos en la Unión Europea están enunciados en:", "El Tratado de Tallin.", "El Reglamento Europeo de la Ciudadanía Europea.", "La Constitución Europea.", "La Carta de los Derechos Fundamentales de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 21, "El Tribunal de Justicia de la Unión Europea se creó mediante:", "El Tratado de la CECA.", "El Tratado de Niza.", "El Tratado de Ámsterdam.", "El Tratado de Lisboa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 22, "Señale la respuesta correcta respecto de las relaciones internacionales de la Unión Europea con terceros países:", "El Consejo negocia los tratados internacionales y la Comisión los aprueba.", "La Comisión negocia los tratados internacionales y el Parlamento Europeo los sanciona.", "La Comisión negocia los tratados internacionales y el Consejo los aprueba.", "Un número indeterminado de diputados europeos negocia los tratados internacionales y la Comisión los aprueba."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 23, "De acuerdo con lo previsto en el Tratado de la Unión Europea, señale la respuesta correcta en relación a las instituciones de la Unión:", "El Consejo Europeo elige al presidente de la Comisión.", "El Consejo está compuesto por un representante de cada estado miembro, de rango ministerial.", "El Parlamento Europeo está compuesto por representantes de los ciudadanos de la Unión. Su número no debe exceder de 850, más el presidente.", "El mandato de la Comisión es de cuatro años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 24, "Con respecto al procedimiento de revisión ordinario establecido en el Tratado de la Unión Europea para modificar los Tratados (señale la respuesta correcta):", "El Gobierno de cualquier estado miembro, el Parlamento Europeo o la Comisión pueden presentar al Consejo proyectos de revisión.", "Tiene por finalidad revisar la totalidad o parte de las disposiciones relativas a las políticas y acciones internas de la Unión.", "Tiene por finalidad solo la de aumentar competencias atribuidas a la Unión en los Tratados.", "El Gobierno de cualquier estado miembro puede presentar al Parlamento proyectos de revisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 25, "La delimitación de las competencias de la Unión Europea se rige:", "Por el principio de atribución.", "Por los principios de subsidiaridad y proporcionalidad.", "Por el principio de jerarquía.", "Por el principio de eficacia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 26, "Los actos legislativos de la Unión Europea podrán adoptarse únicamente a propuesta:", "De la Comisión Europea.", "Del Consejo Europeo y la Comisión Europea.", "Del Consejo de Europa.", "Del Consejo de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 27, "El proceso de integración europea comenzó:", "Con la creación de la CECA y el EURATOM.", "Con la creación de la Comunidad Económica Europea (CEE), en 1960.", "Con los Tratados de Roma de 1957.", "Con la creación de la CECA, en 1951."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 28, "El mandato de los miembros de la Comisión se establece por un período de:", "Cinco años.", "Seis años.", "Cuatro años.", "Tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 29, "Ejecutar el presupuesto y gestionar los programas es una función que corresponde:", "Al Parlamento Europeo.", "A la Comisión.", "Al Consejo y al Parlamento Europeo.", "Al Consejo Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 30, "La Institución de la Unión Europea que está compuesta por un ministro de cada país de la Unión Europea es:", "La Comisión Europea.", "El Comité de las Regiones.", "El Parlamento Europeo.", "El Consejo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 31, "¿Qué estados firmaron el Tratado de Roma?", "Alemania, Bélgica, Francia, Italia, Luxemburgo y los Países Bajos.", "Alemania, el Reino Unido, Bélgica, Francia, Italia y Luxemburgo.", "Alemania, Austria, Bélgica, Francia, Luxemburgo y los Países Bajos.", "Alemania, Bélgica, Francia, Dinamarca, Luxemburgo y los Países Bajos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 32, "Respecto al Consejo Europeo:", "También recibe la denominación de Consejo de Europa, pero no es el mismo órgano que el Consejo de la Unión Europea.", "Representa a los gobiernos de los Estados miembros a través de representantes de rango ministerial para adoptar legislación y coordinar políticas.", "Está integrado por los jefes de Estado o de gobierno de los Estados miembros de la Unión Europea, y se encarga de determinar la dirección y las prioridades políticas generales.", "Cada estado miembro ejerce la presidencia en turnos de seis meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 33, "¿A partir de qué Tratado se establece la Unión Económica y Monetaria en la Unión Europea?", "El Tratado de Roma.", "Tratado de la Unión Europea.", "Tratado de Ámsterdam.", "Tratado de París."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 34, "¿Qué órgano posee el derecho a la iniciativa legislativa en la Unión Europea?", "Los países miembros.", "El Comité de las Regiones.", "El presidente del Parlamento.", "La Comisión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 35, "De las siguientes afirmaciones relativas a la Comisión Europea, señale la correcta:", "La Comisión está integrada por 27 miembros.", "España tiene designados tres comisarios.", "La Comisión es un órgano colegiado y está integrada por 27 miembros.", "La Comisión representa los intereses de los estados miembros de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 36, "De acuerdo con el artículo 17.2 del Tratado de la Unión Europea, los actos legislativos de la Unión:", "Se adoptan por mayoría cualificada de tres quintas partes del Parlamento Europeo.", "Sólo podrán adoptarse a propuesta de la Comisión, excepto cuando los tratados dispongan otra cosa", "Únicamente podrán adoptarse a propuesta de la Comisión o de uno de los países miembros.", "Se adoptarán a propuesta del Consejo por mayoría cualificada de tres quintas partes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 37, "De acuerdo con lo establecido en el artículo 48.2 del Tratado de la Unión Europea, pueden presentar proyectos de revisión de los tratados al Consejo:", "El ministro de asuntos exteriores de cualquier estado miembro.", "El presidente de cualquier estado miembro.", "El consejo de ministros de cualquier estado miembro.", "El gobierno de cualquier estado miembro, el Parlamento Europeo o la Comisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 38, "¿A qué órgano debe presentar una solicitud de adhesión un país que solicite ingresar en la Unión Europea?", "Al Consejo Europeo.", "Al Parlamento Europeo.", "Al Consejo.", "A la Comisión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 39, "¿En qué Tratado se creó la ciudadanía europea?", "En el de Ámsterdam.", "En el de la constitución de la CECA.", "En el Niza.", "En el de Maastricht."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 40, "Según el Tratado de la Unión Europea, el presidente del Consejo Europeo es elegido:", "Por el Consejo Europeo, por mayoría cualificada para un mandato de dos años y medio, que podrá renovarse una sola vez.", "Por el Parlamento Europeo por mayoría cualificada.", "Por el Parlamento Europeo por mayoría simple, que podrá renovarse una sola vez.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 41, "De conformidad con el Tratado de la Funcionamiento de la Unión Europea, señale cuál de los siguientes actos no tiene carácter vinculante:", "El reglamento.", "La directiva.", "La decisión.", "El dictamen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 42, "De conformidad con el Tratado de la Unión Europea, señale la opción correcta respecto de las sesiones o reuniones del Consejo:", "Deben ser públicas cuando delibere y vote sobre un proyecto de acto legislativo.", "No deben ser públicas en ningún caso.", "Deben ser públicas a excepción de las que se deliberen sobre un proyecto de acto legislativo.", "Ninguna de las anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 43, "¿Cuál es la duración del mandato del presidente del Tribunal General del Tribunal de Justicia de la Unión Europea?", "Un año, renovable.", "Dos años, renovables.", "Tres años, renovables.", "Cuatro años, renovables."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 44, "Una de las funciones del Parlamento Europeo es:", "Definir las prioridades políticas generales.", "Velar por la coherencia exterior de la Unión Europea.", "Ejercer funciones de control político y consultivas.", "Adoptar iniciativas de la programación anual y plurianual de la Unión Europea con el fin de alcanzar acuerdos institucionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 45, "¿Cuántos estados miembros tiene actualmente la Unión Europea?:", "50.", "37.", "27.", "20."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 46, "Indique el órgano del Parlamento Europeo que es responsable de los asuntos administrativos y económicos que afectan directamente a los diputados y a sus condiciones de trabajo:", "Los cuestores.", "La Conferencia de Presidentes.", "La Mesa.", "La Secretaría General."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 47, "Los actos legislativos de la Unión Europea, podrán adoptarse únicamente a propuesta:", "De la Comisión Europea.", "Del Consejo Europeo y la Comisión Europea.", "Del Consejo de Europa.", "Del Consejo de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 48, "De acuerdo con el Tratado de la Unión Europea, la Unión Europea sustituirá y sucederá a:", "La OTAN.", "La CECA.", "La Comunidad Económica Europea.", "A ninguna de las anteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 49, "¿Cómo se agrupan los diputados en el Parlamento Europeo?", "Por países.", "Por ideologías políticas.", "Por regiones.", "Por el idioma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 50, "¿Cómo son elegidos los diputados del Parlamento europeo?", "Por sufragio universal directo, libre y secreto.", "Por sufragio universal indirecto de los países miembros.", "Por sufragio universal de los diputados del congreso.", "Por sufragio universal directo de los funcionarios de los países miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 51, "El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión, con un número máximo de:", "705 más el presidente.", "705, incluido el presidente.", "649 diputados.", "Representantes en una proporción igual a cada estado miembro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 52, "¿Cuál de estas afirmaciones es verdadera?", "La Comisión Europea decide sobre todas las nuevas leyes y actuaciones de la Unión Europea.", "La Comisión Europea propone nueva legislación, mientras que el Consejo de la Unión Europea y el Parlamento Europeo toman la decisión final sobre toda la legislación de la Unión Europea.", "El Consejo Europeo, compuesto por los presidentes y primeros ministros de los países de la Unión Europea, adopta la legislación de la Unión Europea.", "La Comisión Europea decide unilateralmente sobre la normativa de la Unión Europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 53, "Señale la afirmación correcta en relación a los Comisarios de la Unión Europea:", "Los comisarios representan los puntos de vista de sus respectivos países.", "Para ser comisario hay que ser primero funcionario en el propio país.", "Los comisarios son propuestos por sus gobiernos nacionales y deben ser aprobados por el Parlamento Europeo.", "Los comisarios son escogidos de entre los ministros de los gobiernos nacionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 54, "Los miembros del Comité Económico y Social y del Comité de las Regiones asisten:", "Al Consejo Europeo y al Consejo.", "Al Parlamento, al Consejo Europeo y a la Comisión.", "A la Comisión y al Consejo.", "Al Parlamento, al Consejo y a la Comisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 55, "La renovación parcial de los jueces y abogados generales del Tribunal de Justicia tiene lugar:", "Cada dos años.", "Cada seis años.", "Cada tres años.", "Cada cuatro años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 56, "Los diputados al Parlamento Europeo son elegidos para un mandato:", "De cuatro años.", "De cinco años.", "De siete años.", "De seis años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 57, "El Consejo Europeo se reúne:", "Dos veces por semestre.", "Una vez por trimestre.", "Tres veces por semestre.", "Dos veces por año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 58, "Según el Tratado de la Unión Europea, ¿cuál de los siguientes cargos no forma parte del Consejo Europeo?", "El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.", "El jefe de estado o de gobierno de un estado miembro.", "El presidente de la Comisión.", "El presidente del Consejo Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 59, "La Presidencia del Consejo, con excepción de la formación de Asuntos Exteriores, se ejerce por cada estado miembro durante un período:", "De un año.", "De seis meses.", "De dieciocho meses.", "De nueve meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 60, "Garantizar el respeto del derecho en la interpretación y aplicación de los Tratados es función:", "Del Tribunal de Justicia de la Unión Europea.", "Del Defensor del Pueblo Europeo.", "Del Tribunal de Justicia y el Tribunal General.", "De los tribunales de justicia de cada estado miembro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 61, "El Parlamento Europeo puede constituir una comisión temporal de investigación a petición:", "De una décima parte de los diputados.", "De una cuarta parte de los diputados.", "De una cuarta parte de los grupos políticos.", "De una quinta parte de los diputados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 62, "La preparación de los trabajos del Consejo corresponde:", "A la Secretaría General del Consejo.", "Al presidente del Consejo.", "A la Mesa del Consejo.", "Al comité compuesto por los representantes permanentes de los Gobiernos de los estados miembros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 63, "Por disposición del Tratado de Funcionamiento de la Unión Europea, el cese de un miembro de la Comisión Europea, en caso de haber dejado de reunir las condiciones necesarias para el ejercicio de sus funciones, puede ser declarado:", "Por la Comisión, mediante acuerdo adoptado por mayoría absoluta de sus miembros.", "Por el Tribunal de Justicia de la Unión Europea, a propuesta del Consejo exclusivamente.", "A instancia del Consejo o de la Comisión, por el Tribunal de Justicia.", "Por el Consejo Europeo, a propuesta de la Comisión."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 64, "El órgano de la Unión Europea que representa a los estados miembros es:", "El Parlamento Europeo.", "La Comisión.", "El Consejo.", "El Tribunal de Justicia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 65, "¿Quién preside el Consejo de Asuntos Exteriores?", "El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.", "El presidente de la Comisión.", "El presidente del Consejo a propuesta del Parlamento.", "El presidente del Parlamento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 66, "El Tribunal de Justicia de la Unión Europea tiene su sede en:", "Estrasburgo.", "París.", "Bruselas.", "Luxemburgo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 67, "El Defensor del Pueblo Europeo presentará al Parlamento Europeo un informe sobre el resultado de sus investigaciones:", "Anualmente.", "Semestralmente.", "Trianualmente.", "Al término de su mandato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 68, "¿Quién elige al Defensor del Pueblo Europeo?", "El Parlamento Europeo.", "La Comisión.", "El Consejo.", "El Parlamento a propuesta del Consejo Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 69, "La moción de censura de la Comisión ha de ser aprobada:", "Por mayoría de un tercio de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo", "Por mayoría de dos tercios de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo", "Por mayoría de tres quintos de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo", "Por mayoría de un quinto de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 70, "¿Cuántos escaños le corresponden a España en el Parlamento Europeo en la actualidad?", "54.", "59.", "60.", "65."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 71, "Actualmente la Comisión Europea está compuesta por:", "28 comisarios.", "27 comisarios.", "26 comisarios.", "25 comisarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 72, "¿Cómo se denomina el principio que implica que, en caso de conflicto y en ciertas condiciones, las normas que no tienen atribuida una aplicabilidad directa pueden ser invocadas por los particulares ante los Tribunales Nacionales?", "Principio de supremacía del derecho comunitario.", "Principio de efecto directo.", "Principio de legalidad.", "Ninguno de los anteriores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 73, "Cuál de los siguientes actos normativos de la Unión Europea es obligatorio en todos sus elementos:", "La decisión.", "La recomendación.", "El dictamen.", "El acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 74, "El Tribunal de Justicia Europeo está compuesto:", "Por 15 jueces de reconocido prestigio.", "Por un juez por cada Estado miembro.", "Por dos jueces por cada Estado miembro.", "Por 12 jueces."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 4, 75, "Indique cuál de las siguientes no es una de las competencias exclusivas de la Unión Europea:", "La unión aduanera.", "El mercado interior.", "El establecimiento de las normas sobre competencias necesarias para el funcionamiento del mercado interior.", "La política monetaria de los estados miembros cuya moneda es el euro."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 1, "Según el art. 35.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, deben ser motivados:", "Los actos que se separen del criterio seguido en actuaciones precedentes o del dictamen de órganos consultivos.", "Los actos que propongan pruebas propuestas por los interesados.", "Los acuerdos de aplicación de la tramitación ordinaria.", "Los actos que reconozcan derechos subjetivos o intereses legítimos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 2, "Indique cuál de las siguientes afirmaciones es correcta según el art. 36.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los actos administrativos no pueden refundirse en un único acto.", "Los órganos administrativos pueden ejercer su competencia de forma verbal.", "Los actos administrativos se producirán siempre por escrito.", "Los actos administrativos de distinta naturaleza podrán refundirse en un único acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 3, "Según el art. 37.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la inderogabilidad singular implica que las resoluciones administrativa de carácter particular:", "No podrán vulnerar lo establecido en una disposición de carácter general, aunque aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Podrán vulnerar lo establecido en una disposición de carácter general cuando provengan de un órgano de superior jerarquía al que dictó la disposición general.", "No podrán vulnerar lo establecido en una disposición de carácter general, salvo que aquéllas procedan de un órgano de igual o superior jerarquía al que dictó la disposición general.", "Podrán vulnerar lo establecido en una disposición de carácter general cuando procedan del mismo órgano que dictó la disposición general."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 4, "Según el art. 39.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la eficacia de un acto quedará demorada:", "Cuando así lo disponga el órgano competente.", "Cuando así lo exija el contenido del acto o esté supeditada a su notificación, publicación o aprobación superior.", "Cuando lo soliciten las personas interesadas en el procedimiento.", "Cuando el acto sea firme."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 5, "Según el art. 40.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las notificaciones deben contener:", "Un extracto de la resolución, con indicación de si pone fin o no a la vía administrativa.", "La expresión de los recursos que procedan, en su caso, en vía administrativa y judicial, el órgano ante el que hubieran de presentarse, y el plazo para interponerlos.", "Los medios de pago que se establezcan a favor de los administrados.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 6, "Según el art. 42.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando la notificación se practica en el domicilio del interesado y el primer intento de notificación resulta infructuoso:", "Se repetirá el intento por una sola vez en una hora distinta dentro de los tres días siguientes.", "Se repetirá el intento dentro de las quince horas siguientes.", "Se publicará el acto de la forma prevista en el art. 44.", "Se repetirá el intento dentro de las tres horas siguientes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 7, "Indique cuál de las siguientes afirmaciones es correcta según el art. 42.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al segundo intento de notificación administrativa en el domicilio del interesado:", "El segundo intento deberá realizarse siempre después de las quince horas.", "El segundo intento deberá realizarse siempre antes de las quince horas.", "Se dejará un margen de diferencia de menos de doce horas entre ambos intentos de notificación.", "Se dejará en todo caso al menos un margen de diferencia de tres horas entre ambos intentos de notificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 8, "Según el art. 43.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando la notificación por medios electrónicos sea de carácter obligatorio, o haya sido expresamente elegida por el interesado, se entenderá rechazada cuando:", "Hayan transcurrido diez días naturales desde la puesta a disposición de la notificación sin que se acceda a su contenido.", "Haya transcurrido un mes desde la puesta a disposición de la notificación sin que se acceda a su contenido.", "Hayan transcurrido diez días hábiles desde la puesta a disposición de la notificación sin que se acceda a su contenido.", "Hayan transcurrido cinco días hábiles desde la puesta a disposición de la notificación sin que se acceda a su contenido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 9, "Indique cuál de las siguientes afirmaciones es correcta según el art. 45.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la publicación de actos administrativos:", "Se publicarán en el Diario Oficial de la Unión Europea los actos y comunicaciones que, por disposición legal o reglamentaria, deban publicarse en el «Boletín Oficial del Estado».", "La publicación de una convocatoria de un procedimiento selectivo en el tablón de edictos sustituye la publicación en el boletín oficial correspondiente.", "En los supuestos de publicaciones de actos que contengan elementos comunes, podrán publicarse de forma conjunta los aspectos coincidentes, especificándose solamente los aspectos individuales de cada acto.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 10, "Según el art. 47.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos que tengan un contenido imposible son:", "Nulos de pleno derecho.", "Anulables.", "Anulables cuando sean dictados por el órgano competente y nulos cuando sean dictados por un órgano manifiestamente incompetente.", "Nulos o anulables en función de la jerarquía del órgano que haya dictado la disposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 11, "El art. 49.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que:", "La nulidad o anulabilidad de un acto no implicará la de los sucesivos en el procedimiento que sean independientes del primero.", "La nulidad o anulabilidad de un acto implicará la de los sucesivos en el procedimiento que sean independientes del primero.", "La nulidad de un acto no implicará la de los sucesivos en el procedimiento que sean independientes del primero.", "La anulabilidad de un acto no implicará la de los sucesivos en el procedimiento que sean independientes del primero."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 12, "El art. 49.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que:", "La nulidad o anulabilidad en parte del acto administrativo implicará en todo caso la de las partes del mismo independientes de aquélla.", "La nulidad del acto administrativo no implicará la de las partes del mismo independientes de aquélla, salvo que la parte viciada sea de tal importancia que sin ella el acto administrativo no hubiera sido dictado.", "La nulidad o anulabilidad en parte del acto administrativo no implicará la de las partes del mismo independientes de aquélla, salvo que la parte viciada sea de tal importancia que sin ella el acto administrativo no hubiera sido dictado.", "La anulabilidad del acto administrativo no implicará la de las partes del mismo independientes de aquélla, salvo que la parte viciada sea de tal importancia que sin ella el acto administrativo no hubiera sido dictado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 13, "Según el art. 55.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el objetivo del período de información o actuaciones previas es:", "Conocer las circunstancias del caso concreto, la conveniencia o no de iniciar el procedimiento y asegurar la eficacia de la resolución que pudiera recaer.", "Conocer las circunstancias del caso concreto y la conveniencia o no de iniciar el procedimiento.", "Conocer las circunstancias del caso concreto y la conveniencia o no de dictar una resolución sancionadora.", "Conocer las circunstancias del caso concreto, asegurar la eficacia de la resolución que pudiera recaer, y la conveniencia o no de dictar una resolución sancionadora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 14, "Según el art. 56.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, las medidas provisionales deberán ser confirmadas, modificadas o levantadas:", "En el acuerdo de finalización del procedimiento, que deberá efectuarse dentro de los quince días siguientes a su adopción, el cual podrá ser objeto del recurso que proceda.", "En el acuerdo de iniciación del procedimiento, que deberá efectuarse dentro de los quince días siguientes a su adopción, contra el cual no será procedente ningún recurso administrativo.", "En el acuerdo de finalización del procedimiento, que deberá efectuarse dentro de los quince días siguientes a su adopción, contra el cual no será procedente ningún recurso administrativo.", "En el acuerdo de iniciación del procedimiento, que deberá efectuarse dentro de los quince días siguientes a su adopción, el cual podrá ser objeto del recurso que proceda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 15, "Indique cuál de las siguientes respuestas es correcta según el art. 56.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Las medidas provisionales no pueden ser modificadas a instancia de parte.", "Se prohíbe la adopción de la medida provisional de suspensión temporal de actividades.", "Las medidas provisionales solo se extinguen cuando la resolución es firme en vía administrativa.", "Las medidas provisionales adoptadas antes de la iniciación del procedimiento quedarán sin efecto cuando el acuerdo de iniciación no contenga un pronunciamiento expreso acerca de las mismas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 16, "Según el art. 57 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿qué recurso es procedente contra el acuerdo de acumulación de procedimientos?", "Recurso de reposición.", "No es procedente ningún recurso.", "Recurso administrativo o bien recurso contencioso administrativo.", "Recurso de alzada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 17, "El art. 58 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que los procedimientos se iniciarán:", "De oficio por acuerdo del órgano competente, como consecuencia de orden superior, a petición razonada de otros órganos o por denuncia.", "De oficio o a instancia de parte por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de orden superior, a petición razonada de otros órganos o por denuncia.", "De oficio por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de orden superior, a petición razonada de otros órganos o por denuncia.", "De oficio o a instancia de parte por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de una orden de otros órganos, o por denuncia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 18, "Según el art. 61.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se entiende por petición razonada de otros órganos:", "La propuesta de iniciación del procedimiento formulada por cualquier órgano administrativo que no tiene competencia para iniciar el mismo y que ha tenido conocimiento de las circunstancias, conductas o hechos objeto del procedimiento, bien ocasionalmente o bien por tener atribuidas funciones de inspección, averiguación o investigación.", "La orden emitida por un órgano administrativo superior jerárquico del competente para la iniciación del procedimiento.", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo la existencia de un determinado hecho que pudiera justificar la iniciación de oficio de un procedimiento administrativo.", "La actuación derivada del conocimiento directo o indirecto de las circunstancias, conductas o hechos objeto del procedimiento por el órgano que tiene atribuida la competencia de iniciación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 19, "El art. 61.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al inicio del procedimiento por petición razonada de otros órganos, dispone que:", "La petición vincula al órgano competente para iniciar el procedimiento, si bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, procede la iniciación.", "La petición no vincula al órgano competente para iniciar el procedimiento, si bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, no procede la iniciación.", "La petición vincula al órgano competente para iniciar el procedimiento, si bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, no procede la iniciación.", "La petición no vincula al órgano competente para iniciar el procedimiento, si bien deberá comunicar al órgano que la hubiera formulado los motivos por los que, en su caso, procede la iniciación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 20, "Según el art. 62.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el denunciante que haya participado en la comisión de una infracción quedará eximido de la sanción:", "Cuando no existan otros infractores y aporte elementos de prueba que permitan iniciar el procedimiento o comprobar la infracción, siempre y cuando en el momento de aportarse aquellos no se disponga de elementos suficientes para ordenar la misma y se repare el perjuicio causado.", "Cuando existan otros infractores y el denunciante facilite elementos de prueba que aporten un valor añadido significativo.", "Cuando existan otros infractores y sea el primero en aportar elementos de prueba que permitan iniciar el procedimiento o comprobar la infracción, siempre y cuando en el momento de aportarse aquellos no se disponga de elementos suficientes para ordenar la misma y se repare el perjuicio causado.", "Cuando no existan otros infractores y el denunciante facilite elementos de prueba que aporten un valor añadido significativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 21, "Indique cuál de las siguientes afirmaciones es correcta según el art. 63.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los procedimientos sancionadores se iniciarán de oficio o a instancia de parte y establecerán la debida separación entre la fase instructora y la sancionadora.", "No se podrán iniciar nuevos procedimientos de carácter sancionador por hechos o conductas tipificadas como infracciones en cuya comisión el infractor persista de forma continuada, en tanto no haya recaído una primera resolución sancionadora, con carácter ejecutivo.", "La calificación jurídica definitiva de la infracción siempre debe quedar fijada en la resolución de inicio.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 22, "Según el art. 64.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando en el momento de dictar el acuerdo de iniciación de un procedimiento sancionador no existan elementos suficientes para la calificación inicial de los hechos:", "La calificación podrá realizarse en una fase posterior mediante la elaboración de un Pliego de cargos, que deberá ser notificado a los interesados.", "Se deberá abrir una fase de información previa con la finalidad de determinar los hechos que motivan la instrucción del procedimiento.", "La calificación podrá realizarse en el acuerdo de apertura del período de prueba, que deberá ser notificado a los interesados.", "Se deberá archivar el procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 23, "Indique cuál de las siguientes respuestas es correcta según el art. 65.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, que regula las especialidades en el inicio de oficio de los procedimientos de responsabilidad patrimonial:", "Es un requisito para iniciar un procedimiento de responsabilidad patrimonial que haya prescrito el derecho a la reclamación del interesado.", "Se deberá archivar el procedimiento cuando los particulares presuntamente lesionados no se personen en el plazo establecido.", "El acuerdo de iniciación del procedimiento se comunicará a los interesados concediéndoles un plazo de quince días para que presenten alegaciones.", "El procedimiento iniciado se instruirá aunque los particulares presuntamente lesionados no se personen en el plazo establecido."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 24, "Según el art. 68.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el plazo de subsanación y mejora de la solicitud:", "Deberá ser ampliado prudencialmente, hasta cinco días, siempre que no se trate de procedimientos selectivos o de concurrencia competitiva.", "Podrá ser ampliado prudencialmente, hasta cinco días, siempre que no se trate de procedimientos selectivos o de concurrencia competitiva.", "Deberá ser ampliado en cinco días en los procedimientos selectivos o de concurrencia competitiva.", "Podrá ser ampliado prudencialmente, hasta cinco días, en los procedimientos selectivos o de concurrencia competitiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 25, "Indique cuál de las siguientes afirmaciones es correcta según el art. 69.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, que regula la declaración responsable y la comunicación:", "Se entenderá por declaración responsable aquel documento mediante el que los interesados ponen en conocimiento de la Administración Pública competente sus datos identificativos o cualquier otro dato relevante para el inicio de una actividad o el ejercicio de un derecho.", "La comunicación deberá presentarse dentro de un plazo posterior al inicio de la actividad.", "Las declaraciones responsables y las comunicaciones permitirán, el reconocimiento o ejercicio de un derecho o bien el inicio de una actividad, desde el día de su presentación.", "Debe exigirse la presentación simultánea de la declaración responsable y la comunicación salvo que la legislación sectorial lo prohíba."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 26, "Indique cuál de las siguientes afirmaciones es correcta según el art. 69.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común:", "Las declaraciones responsables y las comunicaciones permitirán, el reconocimiento o ejercicio de un derecho o bien el inicio de una actividad, desde el día de la autorización.", "La declaración responsable podrá presentarse dentro de un plazo posterior al inicio de la actividad cuando la legislación correspondiente lo prevea expresamente.", "Como regla general la comunicación se presentará después del inicio de la actividad.", "La comunicación podrá presentarse dentro de un plazo posterior al inicio de la actividad cuando la legislación correspondiente lo prevea expresamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 27, "Según el art. 70.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, formará parte del expediente administrativo:", "La información contenida en aplicaciones, ficheros y bases de datos informáticas.", "Las diligencias encaminadas a ejecutar la resolución administrativa.", "Las notas, borradores, opiniones y resúmenes.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 28, "De acuerdo con el principio de simplificación administrativa consagrado en el art. 72.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Se acordarán en un solo acto todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo.", "Se podrán acordar en un solo acto todos los trámites que, por su naturaleza, admitan un impulso simultáneo y sea obligado su cumplimiento sucesivo.", "Se acordarán en un solo acto todos los trámites que, por su naturaleza, admitan un impulso simultáneo y sea obligado su cumplimiento sucesivo.", "Se podrán acordar en un solo acto todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 29, "Según el art. 72.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, al solicitar los trámites que deban ser cumplidos por otros órganos:", "Podrá consignarse en la comunicación cursada el plazo legal establecido al efecto.", "Deberá consignarse en la comunicación cursada el plazo legal establecido al efecto.", "Se consignará en la comunicación cursada la suspensión del plazo para dictar y notificar la resolución.", "Podrá consignarse en la comunicación cursada la suspensión del plazo para dictar y notificar la resolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 30, "Según el art. 73.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los trámites que deban ser cumplimentados por los interesados:", "Deberán realizarse en el plazo de diez días a partir del siguiente al de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto.", "Deberán realizarse en el plazo de diez días a partir del siguiente al de la notificación del correspondiente acto.", "Deberán realizarse en el plazo de quince días a partir del siguiente al de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto.", "Deberán realizarse en el plazo de quince días a partir del siguiente al de la notificación del correspondiente acto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 31, "Según el art. 73.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en cualquier momento del procedimiento, cuando la Administración considere que alguno de los actos de los interesados no reúne los requisitos necesarios:", "Lo pondrá en conocimiento de su autor, concediéndole un plazo no inferior a diez días ni superior a quince para cumplimentarlo.", "Se considerará que el interesado desiste de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21.", "Lo pondrá en conocimiento de su autor, concediéndole un plazo de diez días para cumplimentarlo.", "Se considerará que el interesado desiste de su petición, previa resolución que deberá ser dictada en el plazo de diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 32, "Según el art. 75.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos de instrucción:", "Se realizarán de oficio o a instancia de parte.", "Se realizarán de oficio o a instancia de parte y a través de medios electrónicos.", "Se realizarán de oficio y a través de medios electrónicos.", "Se realizarán de oficio o a instancia de parte, en papel y a través de medios electrónicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 33, "Según el art. 77.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, se podrán rechazar las pruebas propuestas por los interesados:", "Cuando el órgano instructor lo considere oportuno.", "Cuando sean manifiestamente improcedentes o innecesarias.", "Cuando haya razones imperiosas de interés general.", "Cuando sean manifiestamente pertinentes y necesarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 34, "Según el art. 80.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, si el informe debiera ser emitido por una Administración Pública distinta de la que tramita el procedimiento en orden a expresar el punto de vista correspondiente a sus competencias respectivas, y transcurriera el plazo sin que aquél se hubiera emitido:", "Deberán proseguir las actuaciones.", "Se podrán proseguir las actuaciones.", "No deben proseguir las actuaciones.", "Se deberá suspender la instrucción del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 35, "Según el art. 81.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, en los procedimientos de responsabilidad patrimonial el plazo para la emisión del informe del servicio cuyo funcionamiento haya ocasionado la presunta lesión indemnizable:", "No podrá exceder de diez días.", "No podrá ser inferior a diez días ni superior a quince.", "No podrá ser inferior a diez días ni superior a treinta.", "No podrá ser inferior a diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 36, "Según el art. 83.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cómo se lleva a cabo el trámite de información pública?", "Se notificará a los interesados y se publicará un anuncio en el Diario oficial correspondiente a fin de que puedan presentar alegaciones en un plazo no inferior a treinta días.", "Se publicará un anuncio en el Diario oficial correspondiente a fin de que cualquier persona física o jurídica pueda examinar el expediente.", "Se publicará un anuncio en el Diario oficial correspondiente a fin de que los interesados puedan examinar el expediente.", "Se publicará un anuncio en el Diario oficial correspondiente a fin de que cualquier persona física o jurídica pueda examinar el expediente en un plazo no inferior a diez días ni superior a quince."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 37, "Según el art. 86.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los pactos y acuerdos que suscriban las Administraciones Públicas:", "Requerirán siempre la aprobación expresa del Consejo de Ministros u órgano equivalente de las Comunidades Autónomas.", "Se publicarán en el Boletín Oficial del Estado o en el diario oficial correspondiente.", "Podrán establecer el ámbito personal, funcional y territorial, y el plazo de vigencia.", "Se deberán publicar o no según su naturaleza y las personas a las que estuvieran destinados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 38, "Indique cuál de las siguientes afirmaciones es correcta según el art. 87 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la práctica de actuaciones complementarias:", "Las actuaciones complementarias serán acordadas por el instructor del procedimiento.", "Se concederá un plazo no superior a quince días para formular alegaciones.", "Las actuaciones complementarias deberán practicarse en un plazo no superior a quince días.", "El órgano instructor podrá suspender el plazo para resolver el procedimiento hasta la terminación de las actuaciones complementarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 39, "Según el art. 87 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Antes de dictar resolución, el órgano competente para resolver debe realizar las actuaciones complementarias indispensables para resolver el procedimiento.", "Antes de dictar resolución, el órgano instructor podrá decidir, mediante acuerdo motivado, la realización de las actuaciones complementarias indispensables para resolver el procedimiento.", "Antes de dictar resolución, el órgano competente para resolver podrá decidir, mediante acuerdo motivado, la realización de las actuaciones complementarias indispensables para resolver el procedimiento.", "Antes de dictar resolución, el órgano instructor debe realizar las actuaciones complementarias indispensables para resolver el procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 40, "Indique cuál de las siguientes afirmaciones es correcta según el art. 88.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo al contenido de la resolución:", "La aceptación de informes o dictámenes no servirá de motivación a la resolución aunque se incorporen al texto de la misma.", "La resolución del procedimiento se podrá dictar electrónicamente.", "Podrá acordarse la inadmisión de las solicitudes de reconocimiento de derechos no previstos en el ordenamiento jurídico o manifiestamente carentes de fundamento.", "La resolución que ponga fin al procedimiento solo podrá decidir sobre las cuestiones planteadas por los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 41, "Según el art. 89.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, el órgano instructor resolverá la finalización del procedimiento sancionador con archivo de las actuaciones:", "Cuando no figuren en el procedimiento ni sean tenidos en cuenta en la resolución otros hechos ni otras alegaciones y pruebas que las aducidas por el interesado.", "Cuando la sanción tenga carácter pecuniario y se haya repuesto la situación alterada.", "Cuando los hechos probados no constituyan, de modo manifiesto, infracción administrativa.", "Cuando considere que la infracción o la sanción revisten mayor gravedad que la determinada en resolución de inicio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 42, "Según el art. 94.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la Administración podrá limitar los efectos del desistimiento o la renuncia al interesado:", "Cuando se personen en el procedimiento terceros interesados e insten su continuación en el plazo de diez días.", "Cuando la cuestión suscitada por la incoación del procedimiento entrañase interés general o fuera conveniente sustanciarla para su definición y esclarecimiento.", "Cuando se produzca la paralización del procedimiento por causa imputable al interesado.", "Cuando razones de interés público o la falta de complejidad del procedimiento así lo aconsejen."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 43, "El art. 95.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que:", "Deberá acordarse la caducidad por la simple inactividad del interesado en la cumplimentación de trámites, siempre que no sean indispensables para dictar resolución.", "No podrá acordarse la caducidad por la simple inactividad del interesado en la cumplimentación de trámites, siempre que no sean indispensables para dictar resolución.", "Podrá acordarse la caducidad por la simple inactividad del interesado en la cumplimentación de trámites, siempre que no sean indispensables para dictar resolución.", "No deberá acordarse la caducidad por la simple inactividad del interesado en la cumplimentación de trámites, siempre que sean indispensables para dictar resolución."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 44, "Según el art. 96.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuándo se podrá acordar el procedimiento de tramitación simplificada?", "Cuando así lo autoricen las Leyes, y en la forma y cuantía que éstas determinen.", "Cuando razones de interés público o la falta de complejidad del procedimiento así lo aconsejen.", "Cuando no exista o no se haya podido identificar a la persona o personas responsables.", "Cuando lo requiera la naturaleza del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 45, "Según el art. 96.6 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál es el plazo para resolver el procedimiento de tramitación simplificada?", "Tres meses, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.", "Tres meses, a contar desde la fecha que se dicta la resolución de inicio del procedimiento.", "Treinta días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento.", "Treinta días, a contar desde la fecha que se dicta la resolución de inicio del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 46, "Según el art. 100.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando las Administraciones Públicas necesiten entrar en el domicilio del afectado:", "Deberán obtener siempre la oportuna autorización judicial.", "Deberán obtener el consentimiento del mismo o, en su defecto, la oportuna autorización judicial.", "Deberán obtener el consentimiento del mismo y la oportuna autorización judicial.", "Deberán instruir el procedimiento que corresponda de acuerdo con el Título IV de esta Ley."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 47, "Según el art. 102.4 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la exigencia de los gastos de la ejecución subsidiaria:", "Se deberá liquidar de forma definitiva una vez ejecutado el acto, a través del procedimiento de apremio.", "Podrá liquidarse de forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva.", "Deberá liquidarse de forma provisional y podrá realizarse antes de la ejecución, a reserva de la liquidación definitiva.", "Se deberá liquidar de forma definitiva una vez ejecutado el acto, con la autorización judicial previa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 48, "¿En cuál de los supuestos siguientes puede imponerse la multa coercitiva según el art. 103.1, letra a), de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas?", "Actos personalísimos en que no proceda la compulsión directa sobre la persona del obligado.", "Cuando en virtud de acto administrativo hubiera de satisfacerse cantidad líquida.", "Actos cuya ejecución no se pueda encargar a otra persona.", "Cuando así lo exija el contenido del acto o esté supeditada a su notificación, publicación o aprobación superior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 49, "Según el art. 106 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, es necesario solicitar el dictamen del Consejo de Estado:", "En los procesos de revisión de actos nulos.", "En los procesos de revisión de disposiciones nulas.", "En los procesos de revisión de actos nulos y disposiciones nulas.", "En los procesos de revisión de actos nulos, de disposiciones nulas y de declaración de lesividad de disposiciones anulables."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 50, "Según el art. 106.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿qué carácter tiene el dictamen del Consejo de Estado en los procedimientos de revisión de actos nulos?", "Facultativo y no vinculante.", "Preceptivo y vinculante.", "Preceptivo y no vinculante.", "Facultativo y vinculante."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 51, "Según el art. 106.5 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuándo se produce la caducidad de los procedimientos de revisión de disposiciones y actos nulos iniciados de oficio?", "Transcurrido el plazo de seis meses desde su inicio sin dictarse resolución.", "Transcurrido el plazo de tres meses desde su inicio sin dictarse resolución.", "Transcurrido el plazo de seis meses desde que se dictó el acto o la disposición nula.", "Transcurrido el plazo de tres meses desde que se dictó el acto o la disposición nula."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 52, "Según el art. 107.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la declaración de lesividad afecta a:", "Los actos favorables para los interesados que sean anulables.", "Los actos desfavorables para los interesados que sean anulables.", "Los actos favorables para los interesados que sean nulos.", "Los actos desfavorables para los interesados que sean nulos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 53, "El art. 107.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, dispone que:", "Transcurrido el plazo de cuatro años desde la iniciación del procedimiento sin que se hubiera declarado la lesividad, se producirá la caducidad del mismo.", "Transcurrido el plazo de seis meses desde la iniciación del procedimiento sin que se hubiera declarado la lesividad, se producirá la caducidad del mismo.", "Transcurrido el plazo de cuatro años desde la iniciación del procedimiento sin que se hubiera declarado la lesividad, se podrá entender la misma desestimada por silencio administrativo.", "Transcurrido el plazo de seis meses desde la iniciación del procedimiento sin que se hubiera declarado la lesividad, se podrá entender la misma desestimada por silencio administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 54, "¿Qué limite temporal establece el art. 109.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, para rectificar los errores materiales, de hecho o aritméticos?", "No se establece ningún límite.", "Cuatro años desde que se dictó el acto administrativo.", "Un mes desde que se dictó el acto administrativo.", "Seis meses desde que se dictó el acto administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 55, "Según el art. 112.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los recursos administrativos contra una disposición general que se funden únicamente en la nulidad de la misma podrán interponerse directamente ante el órgano que dictó dicha disposición.", "Los recursos contra un acto administrativo que se funden únicamente en la nulidad de alguna disposición administrativa de carácter general podrán interponerse directamente ante el órgano que dictó dicha disposición.", "Los recursos contra un acto administrativo que se funden únicamente en la nulidad de alguna disposición administrativa de carácter general deberán interponerse ante el órgano que dictó dicha disposición.", "Los recursos administrativos contra una disposición general que se funden únicamente en la nulidad de la misma deberán interponerse directamente ante el órgano que dictó dicha disposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 56, "Indique cuál de las siguientes afirmaciones sobre los recursos administrativos es correcta según el art. 115.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los vicios y defectos que hagan anulable un acto no podrán ser alegados por quienes los hubieren causado.", "El error o la ausencia de la calificación del recurso por parte del recurrente es siempre una causa de inadmisión.", "La falta de legitimación no es una causa de inadmisión del recurso.", "Si ha transcurrido el plazo para interponer el recurso, la Administración debe requerir al interesado para que subsane su escrito."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 57, "Según el art. 116 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿cuál de las siguientes es una causa de inadmisión de los recursos administrativos?", "Tener legitimación.", "Que el acto sea susceptible de recurso.", "Carecer el recurso manifiestamente de fundamento.", "Que el órgano disponga de competencia para resolver el recurso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 58, "Según el art. 117.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, cuando la impugnación se fundamente en alguna de las causas de nulidad de pleno derecho previstas en el artículo 47.1 de esta Ley, el órgano a quien competa resolver el recurso:", "Podrá dejar sin efecto el acto impugnado.", "Deberá suspender la ejecución del acto impugnado.", "Podrá suspender la ejecución del acto impugnado.", "Deberá dejar sin efecto la ejecución del acto impugnado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 59, "Según el art. 119.3 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, la resolución de un recurso administrativo:", "Requiere un trámite de audiencia por un plazo no inferior a diez días ni superior a quince cuando deba agravarse la situación del recurrente.", "Debe ir precedida siempre de un trámite de audiencia.", "Será congruente con las peticiones formuladas por el recurrente, sin que en ningún caso pueda agravarse su situación inicial.", "Solo debe resolver las cuestiones de fondo planteadas por los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 60, "Indique cuál de las siguientes afirmaciones es correcta según el art. 120.2 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, relativo a la suspensión del plazo para resolver un recurso administrativo hasta que recaiga pronunciamiento judicial:", "El acuerdo de suspensión podrá ser notificado a los interesados.", "El acuerdo de suspensión deberá ser notificado a los interesados, quienes podrán recurrirlo.", "El acuerdo de suspensión, contra el cuál no podrá interponerse ningún recurso, deberá ser notificado a los interesados.", "El acuerdo de suspensión no debe notificarse a los interesados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 61, "Indique cuál de las siguientes afirmaciones es correcta según el art. 121.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas:", "Los actos que no pongan fin a la vía administrativa pueden ser recurridos en alzada y en reposición.", "Puede interponerse recurso de reposición y recurso extraordinario de revisión contra los actos firmes en vía administrativa.", "Los actos que pongan fin a la vía administrativa pueden ser recurridos en alzada.", "Los actos que no pongan fin a la vía administrativa podrán ser recurridos en alzada ante el órgano superior jerárquico del que los dictó."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 62, "Según el art. 123.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, los actos administrativos que pongan fin a la vía administrativa:", "Deberán ser recurridos en reposición ante el mismo órgano que los hubiera dictado como requisito previo para la impugnación ante el orden jurisdiccional contencioso-administrativo.", "Podrán ser recurridos potestativamente en reposición ante el mismo órgano que los hubiera dictado o ser impugnados directamente ante el orden jurisdiccional contencioso-administrativo.", "Deberán ser recurridos en alzada ante el órgano superior jerárquico como requisito previo para la impugnación ante el orden jurisdiccional contencioso-administrativo.", "Podrán ser recurridos potestativamente en reposición ante el órgano superior jerárquico o ser impugnados directamente ante el orden jurisdiccional contencioso-administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 63, "Según el art. 125.1 de la Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas, ¿contra qué actos se puede interponer el recurso extraordinario de revisión?", "Contra las disposiciones generales, los actos definitivos, los actos de trámite cualificados y los actos firmes en vía administrativa.", "Contra los actos definitivos, los actos de trámite cualificados y los actos firmes en vía administrativa.", "Contra los actos definitivos y los actos firmes en vía administrativa.", "Contra los actos firmes en vía administrativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 64, "Según el art. 42 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, los actos dictados por el vicepresidente adoptan la forma de:", "Decreto.", "Resolución", "Acuerdo.", "Orden."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 65, "Según el art. 42 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, adoptan la forma de decreto:", "Los actos dictados por el presidente.", "Los actos dictados por el presidente y por el Gobierno.", "Los actos dictados por el presidente y por las comisiones delegadas.", "Los actos dictados por el presidente, por el Gobierno y por las comisiones delegadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 66, "Según el art. 48.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, las actuaciones que sean de interés para la tramitación del expediente se harán constar mediante:", "Resolución.", "Acuerdo.", "Diligencia.", "Orden."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 67, "Según el art. 50.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, los plazos máximos para dictar y notificar la resolución expresa en los procedimientos de competencia de la comunidad autónoma:", "Son los que fije la norma reguladora del procedimiento correspondiente y no podrán exceder de seis meses.", "Son los que fije la norma reguladora del procedimiento correspondiente y no podrán exceder de seis meses, salvo que una ley establezca uno más amplio o así se prevea en la normativa comunitaria europea.", "Son los que fije la norma reguladora del procedimiento correspondiente y no podrán exceder de tres meses.", "Son los que fije la norma reguladora del procedimiento correspondiente y no podrán exceder de tres meses, salvo que una ley establezca uno más amplio o así se prevea en la normativa comunitaria europea."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 68, "Según el art. 50.3.b de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, el plazo máximo para dictar y notificar la resolución expresa en los procedimientos sancionadores abreviados respecto de los cuales la comunidad autónoma dispone de competencia normativa es de:", "Un año.", "Seis meses.", "Tres meses.", "Un mes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 69, "Según el art. 53.1.a de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, agotan la vía administrativa:", "Los actos dictados por el presidente.", "Los actos dictados por el presidente y por el Consejo de Gobierno.", "Los actos dictados por el presidente, por el Consejo de Gobierno y por los órganos directivos de las Consejerías.", "Los actos dictados por el presidente y por el Consejo de Gobierno, salvo que una ley establezca lo contrario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 70, "Según el art. 53.1.b de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, los acuerdos de las comisiones delegadas del Gobierno:", "Agotan la vía administrativa.", "Agotan la vía administrativa, salvo que una ley establezca lo contrario.", "No agotan la vía administrativa.", "No agotan la vía administrativa, salvo que una ley establezca lo contrario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 71, "Indique cuál de las siguientes afirmaciones es correcta según el art. 54.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears:", "La competencia para resolver los procedimientos de revisión de actos nulos corresponde siempre al órgano que haya dictado el acto.", "La declaración de nulidad requerirá el dictamen previo y favorable del Consejo Económico y Social de las Islas Baleares.", "La competencia para resolver los procedimientos de revisión de actos nulos corresponde al Consejo de Gobierno.", "Los procedimientos de revisión de actos nulos se iniciarán de oficio por el órgano autor del acto o a solicitud de persona interesada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 72, "Según el art. 54.2 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, en los procedimientos de revisión de oficio de disposiciones administrativas:", "La competencia para su inicio corresponde al órgano que las hubiera aprobado y la resolución al órgano superior jerárquico.", "La competencia para su inicio y resolución corresponde al superior jerárquico del órgano que las hubiera aprobado.", "La competencia para su inicio y resolución corresponderá al órgano que las hubiera aprobado.", "La competencia para su inicio corresponde al órgano superior jerárquico y la resolución al órgano que las hubiera aprobado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 73, "De acuerdo con el art. 55.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, ¿qué órgano es el competente para iniciar los procedimientos para la declaración de lesividad?", "El órgano autor del acto.", "El consejero competente por razón de la materia, salvo que el acto provenga de una comisión delegada o del Consejo de Gobierno, en cuyo caso corresponderá a éste último su declaración.", "El consejero competente por razón de la materia.", "El órgano autor del acto, salvo que el acto provenga del Presidente, en cuyo caso la declaración corresponderá al Consejo de Gobierno."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 74, "Según el art. 56.1 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, ¿cuál es el órgano competente para revocar los actos de gravamen o desfavorables?", "El consejero competente por razón de la materia.", "El órgano que hubiera dictado el acto o la disposición.", "El consejero competente por razón de la materia, salvo que el acto provenga de una comisión delegada o del Consejo de Gobierno, en cuyo caso corresponderá a éste último su declaración.", "El superior jerárquico del órgano que hubiera dictado el acto o la disposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 10, 75, "Según el art. 56.3 de la Ley 3/2003, de 26 de marzo, de régimen jurídico de la administración de la Comunidad Autónoma de las Illes Balears, las erratas en el texto publicado, respecto del texto recibido, en el Butlletí Oficial de les Illes Balears:", "Podrán ser corregidas por el órgano encargado del boletín, aunque previamente lo debe comunicar al Consejo de Gobierno.", "Podrán ser corregidas por Consejo de Gobierno, aunque previamente lo debe comunicar al órgano encargado del boletín.", "Podrán ser corregidas por el órgano encargado del boletín, que deberá comunicarlo posteriormente al órgano del cual haya emanado el acto o la disposición objeto de corrección.", "Podrán ser corregidas por el órgano encargado del boletín, aunque previamente lo debe comunicar al órgano del cual haya emanado el acto o la disposición objeto de corrección."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 1, "El personal laboral al servicio de las Administraciones públicas se rige:", "Por la legislación laboral.", "Por los preceptos del Estatuto básico del empleado público que así lo dispongan.", "En materia de permisos de nacimiento, adopción, del progenitor diferente de la madre biológica y lactancia, se regirá por lo previsto en el Estatuto básico del empleado público.", "Las respuestas a), b), y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 2, "Quienes, al servicios de los intereses generales, desempeñan funciones retribuidas en las administraciones públicas, son:", "Los altos cargos de la administración.", "Los empleados públicos.", "Los intereses generales no tienen servicios.", "El personal retribuido por arancel."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 3, "Los empleados públicos se clasifican:", "En funcionarios de carrera.", "En funcionarios interinos y funcionarios de carrera.", "En personal laboral, funcionarios interinos, personal eventual y funcionarios de carrera.", "En personal eventual, funcionarios de carrera y funcionarios interinos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 4, "Quienes, en virtud de un nombramiento legal, están vinculados a una administración pública por una relación estatutaria regulada por el derecho administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente, son:", "Personal eventual.", "Funcionarios de carrera.", "Funcionarios interinos.", "Personal laboral fijo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 5, "Son funcionarios interinos:", "Quienes, por razones expresamente justificadas de necesidad, son nombrados como tales con carácter temporal.", "Quienes, por razones de necesidad y urgencia, son nombrados como tales con carácter temporal.", "Quienes, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales con carácter temporal.", "Quienes, por razones expresamente justificadas de necesidad y urgencia, son nombrados como tales con carácter permanente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 6, "Es personal laboral el que en virtud de un contrato de trabajo presta servicios para el desempeño de puestos de trabajo:", "Cuyas funciones no implican la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales.", "Cuyas funciones implican la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales.", "Cuyas funciones implican la participación indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales.", "Cuyas funciones implican la participación directa en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 7, "Quién, en virtud de nombramiento y con carácter no permanente, solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial:", "Su condición no podrá constituir mérito para el acceso a la función pública o para la promoción interna.", "Le será aplicable el régimen del personal laboral temporal.", "El nombramiento y cese tendrán lugar cuando así lo solicite.", "Le será aplicable el régimen general de los funcionarios interinos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 8, "Quién desarrolla funciones directivas profesionales y es designado atendiendo a principios de mérito y capacidad y a criterios de idoneidad:", "Ocupa plazas cuyo sistema de provisión es la libre designación.", "Es un alto cargo de la Administración.", "Estará sujeto a evaluación con arreglo a los criterios de eficacia y eficiencia, responsabilidad por su gestión y control de resultados en relación con los objetivos que le hayan sido fijados .", "La determinación de sus condiciones de empleo tendrá la consideración de materia objeto de negociación colectiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 9, "La Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, consta:", "De un título preliminar y 145 artículos organizados en diez títulos.", "De un preámbulo y 145 artículos organizados en diez títulos.", "De un título preliminar y 145 artículos organizados en once títulos.", "De un preámbulo y 145 artículos organizados en once títulos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 10, "La Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, consta:", "De 19 disposiciones adicionales y 8 disposiciones transitorias, de las cuales hay 2 séptimas.", "De 18 disposiciones adicionales y 9 disposiciones transitorias, de las cuales hay 2 séptimas.", "De 19 disposiciones adicionales y 9 disposiciones transitorias, de las cuales hay 2 séptimas.", "De 18 disposiciones adicionales y 8 disposiciones transitorias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 11, "Queda excluido de la aplicación de la Ley de la función pública de la comunidad autónoma de las Illes Balears el siguiente personal:", "Personal del Consejo Consultivo y del Consejo Económico y Social.", "Personal de la Sindicatura de Greuges y de la Sindicatura de Cuentas de las Illes Balears.", "Personal de las universidades públicas radicadas en la comunidad autónoma de las Illes Balears que no forme parte de los cuerpos docentes e investigadores.", "Personal de la Agencia Tributaria de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 12, "Indique la respuesta incorrecta. La Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, es de aplicación:", "Al personal laboral al servicio de la Administración de la Comunidad Autónoma de les Illes Balears.", "Al personal docente y al personal estatutario al servicio la sanidad pública autonómica.", "Al personal laboral de las empresas públicas.", "Al personal de las entidades locales radicadas en la comunidad autónoma de las Illes Balears."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 13, "Los órganos de la Administración de la Comunidad Autónoma competentes en materia de función pública se clasifican:", "En órganos ejecutivos y órganos consultivos.", "En órganos ejecutivos, órganos consultivos y órgano de control.", "En órganos consultivos y órgano de control.", "En órganos directivos, órganos consultivos y órgano de control."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 14, "Corresponde al Consejo de Gobierno de la Comunidad Autónoma de las Illes Balears:", "Establecer la política general de la Administración autonómica en materia de función pública y ejercer la iniciativa legislativa y la potestad reglamentaria en esta materia.", "El control y la ejecución de la política establecida en materia de personal al servicio de la Administración de la Comunidad Autónoma.", "Cuidar del cumplimiento de las normas de aplicación general en materia de función pública por parte de los órganos de la Administración.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 15, "No es una competencia del consejero del Gobierno de las Illes Balears competente en materia de función pública:", "Cuidar del cumplimiento de las normas de aplicación general en materia de función pública por parte de los órganos de la Administración.", "Determinar los requisitos de los procedimientos o de los cursos que habiliten para obtener grados personales superiores a los consolidados.", "Ejercer la inspección general sobre todo el personal.", "Otorgar las recompensas y las distinciones que se determinen reglamentariamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 16, "La Administración de la Comunidad Autónoma de las Illes Balears selecciona al personal a su servicio con criterios de objetividad, mediante convocatoria pública, de conformidad con los principios constitucionales de igualdad, mérito y capacidad, y con los principios informadores siguientes:", "La dependencia de la Escuela Balear de Administración Pública (EBAP) del órgano de selección y de la imparcialidad de cada uno de sus miembros.", "La especialización y la profesionalidad de los miembros de los órganos de selección.", "La eficacia, la celeridad y la agilidad de los procedimientos selectivos.", "La eficiencia de los procedimientos de selección para asegurar la idoneidad de los aspirantes seleccionados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 17, "El acceso a los cuerpos, las escalas y las especialidades funcionariales o a las categorías profesionales de personal laboral fijo al servicio de la Administración de la Comunidad Autónoma de las Illes Balears, con carácter ordinario no se realizará mediante:", "El sistema de oposición, que consiste en realizar una o más pruebas de capacidad para determinar la aptitud de los aspirantes.", "El sistema de concurso-oposición, que consiste en llevar a cabo, como partes del procedimiento de selección, una fase de oposición y una de concurso. La puntuación que pueda obtenerse en la fase de concurso no dispensa en ningún caso de la necesidad de superar las pruebas selectivas de la fase de oposición.", "El sistema de concurso, que consiste en calificar los méritos alegados y acreditados por los aspirantes, de acuerdo con el baremo incluido en la convocatoria.", "Cualquiera de los sistemas anteriores es un sistema válido, con carácter ordinario, para el acceso a los cuerpos, las escalas y las especialidades funcionariales o a las categorías profesionales de personal laboral fijo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 18, "Los procedimientos selectivos para el acceso a los cuerpos, las escalas y las especialidades funcionariales o a las categorías profesionales de personal laboral fijo se realizarán a través de uno de los sistemas de selección:", "Previstos en el artículo 45 de la Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, y las convocatorias de selección pueden incluir cursos que constituyan parte del procedimiento selectivo, pero en ningún caso existirá período de prueba.", "Previstos en el artículo 45 de la Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, y las convocatorias de selección pueden incluir cursos o periodos de prueba que constituyan parte del procedimiento selectivo.", "Previstos en el artículo 46 de la Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, y las convocatorias de selección pueden incluir cursos que constituyan parte del procedimiento selectivo, pero en ningún caso existirá período de prueba.", "Previstos en el artículo 46 de la Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, y las convocatorias de selección pueden incluir cursos o periodos de prueba que constituyan parte del procedimiento selectivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 19, "Constituye la oferta de empleo público anual de la Comunidad Autónoma de las Illes Balears:", "El conjunto de plazas vacantes de personal funcionario y de personal laboral cuya cobertura resulta necesaria y no es posible con el personal existente.", "El conjunto de plazas vacantes que se aprueba por acuerdo del Consejo de Gobierno, y puede incluir otras medidas o disposiciones derivadas de la planificación de los recursos humanos.", "El conjunto de plazas vacantes de personal funcionario y de personal laboral, con dotación presupuestaria, cuya cobertura resulta necesaria y no es posible con el personal existente.", "El conjunto de plazas vacantes, y debe indicar el cuerpo, la escala y la especialidad o el nivel y la categoría profesional a la que correspondan las plazas vacantes, y la isla de destino."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 20, "Las convocatorias de selección para el acceso a un empleo público de la Comunidad Autónoma de las Illes Balears:", "Deben incluir el porcentaje del 5 % reservado para personas con discapacidad, en su caso.", "Deben incluir el porcentaje reservado para la promoción interna, en su caso, con indicación expresa de si incluye plazas que han de ser objeto de reclasificación, al amparo del artículo 68.3 de la Ley de la función pública de la comunidad autónoma de las Illes Balears.", "Deben incluir los requisitos y las condiciones que tienen que cumplir los aspirantes, que podrán ser distintos en función de la situación administrativa de cada uno de ellos.", "Se publicarán en el Boletín Oficial de las Illes Balears o en el portal del opositor de la Escuela Balear de Administración Pública (EBAP)."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 21, "Son requisitos generales de acceso a la función pública autonómica los siguientes:", "Tener la titulación académica que se requiere en cada caso o estar en condición de obtenerla en la fecha de finalización del plazo de presentación de solicitudes de participación; no obstante, podrá eximirse de dicho requisito en determinados casos.", "Acreditar el conocimiento de la lengua catalana que se determine reglamentariamente, respetando el principio de proporcionalidad y adecuación entre el nivel de exigencia y las funciones correspondientes.", "Tener la edad mínima establecida en la legislación de la función pública de la Comunidad Autónoma de las Illes Balears y no exceder de la edad que, en su caso, establezca la correspondiente convocatoria.", "Cada convocatoria puede establecer requisitos específicos de acceso, siempre y cuando se formulen de manera clara y concisa y tengan una relación objetiva y proporcionada con las funciones correspondientes."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 22, "De acuerdo con lo dispuesto en la Ley de la función pública de la comunidad autónoma de las Illes Balears, los órganos de selección actúan con autonomía funcional, y los acuerdos que adopten vinculan al órgano del que dependen:", "Y pueden declarar que ha superado los procedimientos selectivos un número de aspirantes superior al de plazas convocadas.", "Y sus miembros son responsables de la objetividad del procedimiento, del contenido y de la confidencialidad de las pruebas.", "Y sus miembros son responsables de la adecuación de las bases de la convocatoria.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 23, "La condición de personal funcionario al servicio de la Administración de la Comunidad Autónoma de las Illes Balears se adquiere por el cumplimiento sucesivo de los siguientes requisitos:", "Superación del procedimiento selectivo de acceso al empleo público; juramento o promesa de cumplir la Constitución, el Estatuto de autonomía de las Illes Balears y el ordenamiento vigente, en el ejercicio de la función pública; nombramiento y publicación del mismo por parte del órgano competente, y toma de posesión en el plazo establecido reglamentariamente.", "Superación del procedimiento selectivo de acceso al empleo público; nombramiento y publicación del mismo por parte del órgano competente; juramento o promesa de cumplir la Constitución, el Estatuto de autonomía de las Illes Balears y el ordenamiento vigente, en el ejercicio de la función pública.", "Superación del procedimiento selectivo de acceso al empleo público; nombramiento y publicación del mismo por parte del órgano competente; juramento o promesa de cumplir la Constitución, el Estatuto de autonomía de las Illes Balears y el ordenamiento vigente, en el ejercicio de la función pública, y toma de posesión en el plazo establecido reglamentariamente.", "Superación del procedimiento selectivo de acceso al empleo público, nombramiento y publicación del mismo por parte del órgano competente, y toma de posesión en el plazo establecido reglamentariamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 24, "Se garantiza el derecho a la movilidad del personal funcionario al servicio de la Administración de la Comunidad Autónoma de las Illes Balears:", "Falso. Lo que se garantiza es la inamovilidad de su condición al efecto de mantener su independencia.", "De acuerdo con los sistemas de ocupación de puestos de trabajo que se regulan en la Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, siempre que no se halle ocupado por un funcionario interino.", "De acuerdo con los sistemas de ocupación de puestos de trabajo que se regulan en la Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears.", "De acuerdo con los sistemas de ocupación de puestos de trabajo que se regulan en la Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, si bien desde la aprobación de la Ley de presupuestos para el 2012 queda restringida al sistema de comisión de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 25, "Los sistemas ordinarios de provisión de puestos previstos en la Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, son:", "El concurso.", "El concurso y la libre designación.", "El concurso, la libre designación y la comisión de servicios.", "El concurso, la libre designación, la adscripción provisional y la comisión de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 26, "No es un sistema de provisión o de ocupación:", "La comisión de servicios de atribución temporal de funciones.", "La permuta.", "La oposición.", "El nombramiento provisional por mejora de empleo en un grupo o un subgrupo superior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 27, "La redistribución de efectivos y la reasignación de efectivos son:", "Un sistema ordinario de provisión de puestos de trabajo.", "Se consideran otros sistemas de provisión o de ocupación.", "Es el sistema en el que se toma posesión del puesto de trabajo obtenido por concurso pero se continúan realizando las funciones del puesto de trabajo previo.", "Ninguna de las respuestas anteriores es correcta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 28, "El concurso puede ser:", "Concurso abierto y permanente de méritos o concurso abierto y permanente específico.", "Concurso abierto de méritos o concurso abierto específico.", "Concurso restringido y permanente de méritos o concurso restringido y permanente específico.", "Concurso abierto y permanente de méritos o concurso restringido y permanente específico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 29, "El baremo de la convocatoria de concurso recogerá, en los términos que se establezcan reglamentariamente, la valoración de los siguientes méritos generales:", "La prestación de servicios mediante una comisión de servicios forzosa, una comisión de servicios en atribución temporal de funciones y la prestación de servicios en la Unidad de Apoyo Coyuntural de la dirección general competente en materia de función pública.", "La permanencia en el puesto de trabajo con destino definitivo.", "El trabajo desarrollado.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 30, "El concurso abierto y permanente específico es el sistema de provisión de los puestos de trabajo singularizados que tienen establecida esta forma de provisión en la relación de puestos de trabajo:", "Y la convocatoria incluirá la realización de pruebas de carácter práctico, memorias, entrevistas y tests profesionales, la valoración de informes de evaluación u otros sistemas similares.", "Además de los méritos generales, la convocatoria debe recoger la valoración de méritos específicos relacionados con el puesto de trabajo convocado. La valoración global de los méritos supondrá como mínimo el 55 % de la puntuación máxima alcanzable.", "Los puestos singularizados tienen como sistema de provisión la libre designación, y puede incluir la realización de pruebas de carácter práctico, memorias, entrevistas y tests profesionales, la valoración de informes de evaluación u otros sistemas similares.", "Los puestos de trabajo singularizados no podrán ser cubiertos por funcionarios interinos ni por personal funcionario de carrera de nuevo ingreso que haya accedido por el sistema de oposición."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 31, "Las convocatorias, tanto de concurso abierto y permanente de méritos o específico como de libre designación, incluirán, como mínimo:", "La denominación, el nivel, el complemento específico y la isla de destino del puesto de trabajo.", "Los requisitos exigidos para ocuparlo, incluido el nivel de conocimientos de lengua catalana, en su caso.", "La puntuación máxima para la adjudicación de las vacantes convocadas, en el caso del concurso.", "La relación de méritos en el caso del concurso, y de las capacidades, los conocimientos o las aptitudes cuando el concurso sea específico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 32, "Los efectos de la adjudicación mediante los sistemas de provisión tienen carácter definitivo:", "El personal funcionario que haya obtenido un puesto de trabajo mediante un sistema de provisión ordinaria debe permanecer en él un mínimo de dos años.", "La adjudicación de un puesto de trabajo adscrito a más de un cuerpo, escala o especialidad y/o a más de un grupo de clasificación no implica la integración en el cuerpo, la escala o la especialidad ni en el grupo de clasificación superior o diferente al de ingreso, aunque la persona adjudicataria tenga la titulación requerida, ni tampoco la aplicación de las retribuciones ligadas al grupo de clasificación superior.", "La obligación de permanecer en el puesto, como titular, un mínimo de dos años antes de participar en un procedimiento de provisión ordinaria no es de aplicación en los supuestos de remoción o supresión del puesto de trabajo, de movilidad forzosa a que se refiere el apartado 5 del artículo 74 de la Ley de la función pública de la comunidad autónoma de las Illes Balears, o de participación en convocatorias de provisión ordinaria de puestos de trabajo de la misma consejería.", "Todas las respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 33, "Causas de finalización de la comisión de servicios ordinaria voluntaria, forzosa y de atribución temporal de funciones:", "Finalizan por el transcurso del tiempo para el que se concedieron, que no puede ser superior a dos años. Excepcionalmente, cuando las necesidades del servicio lo requieran, el Consejo de Gobierno puede prorrogar este plazo.", "Finalizan por el transcurso del tiempo para el que se concedieron, que no puede ser superior a dos años. Excepcionalmente, cuando las necesidades del servicio lo requieran, y solo con respecto a la comisión de servicios ordinaria voluntaria, el Consejo de Gobierno puede prorrogar este plazo.", "Finalizan por el transcurso del tiempo para el que se concedieron. Excepcionalmente, cuando las necesidades del servicio lo requieran, el Consejo de Gobierno puede prorrogar este plazo.", "Finalizan si el titular de la comisión manifiesta un cumplimiento adecuado, un rendimiento suficiente o una falta de adecuación al puesto de trabajo que impide llevar a cabo con eficacia las funciones atribuidas al puesto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 34, "El personal funcionario que ocupe con carácter definitivo puestos de trabajo genéricos puede ser trasladado, por necesidades del servicio:", "Falso. Si ocupa el puesto con carácter definitivo, no puede ser trasladado salvo que exprese su conformidad.", "Solamente a otros puestos de la misma naturaleza, nivel de complemento de destino y complemento específico, siempre y cuando para la provisión de los mencionados puestos esté previsto el mismo procedimiento.", "Nunca, si el traslado supone un cambio de municipio que implique desplazamiento de más de 25 kilómetros.", "Sí se puede; es la reasignación de efectivos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 35, "El personal funcionario puede ser destinado a otro puesto de trabajo por el procedimiento de reasignación de efectivos:", "Si su puesto de trabajo se amortiza como consecuencia de que así se apruebe por ley.", "Si su puesto de trabajo se suprime como consecuencia de un plan de ordenación de recursos humanos de los previstos en la ley.", "La inamovilidad en la condición de funcionario de carrera está garantizada por el artículo 1 del Estatuto básico del empleado público.", "El Consejo de Gobierno, por reestructuración de la Administración, podrá acordar la adscripción de puestos de trabajo y del personal que provisional o definitivamente los ocupa a unidades, consejerías o entes del sector público instrumental con personificación pública, distintos de aquellos a los que estaba adscrito."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 36, "El Consejo de Gobierno, por reestructuración de la Administración o por necesidades del servicio o funcionales, y a efectos de asignar de manera eficiente los recursos humanos, podrá acordar la adscripción de puestos de trabajo y del personal que provisional o definitivamente los ocupa a unidades, consejerías o entes del sector público instrumental con personificación pública, distintos de aquellos a los que estaba adscrito:", "Cierto, se denomina reasignación de efectivos.", "Cierto, es la redistribución de efectivos.", "Cierto, es el cambio de adscripción del puesto de trabajo.", "Cierto, pero los funcionarios solo podrán ser adscritos a consejerías."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 37, "De acuerdo con lo previsto en la Ley de la función pública de la comunidad autónoma de las Illes Balears, el personal funcionario de carrera, durante su relación de servicio, puede encontrarse, entre otras, en situación:", "De expectativa de destino, excedencia forzosa y jubilación parcial, en los términos que establezca la legislación básica estatal.", "La excedencia forzosa en el caso de funcionarios se denomina servicios especiales.", "De servicios en otras administraciones públicas, excedencia voluntaria y jubilación parcial, en los términos que establezca la legislación básica estatal.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 38, "El personal funcionario de la Comunidad Autónoma, cuando adquiera la condición de personal funcionario al servicio de organizaciones internacionales o de carácter supranacional, será declarado en situación:", "De excedencia forzosa.", "De servicios especiales.", "De servicio en otras administraciones públicas.", "de excedencia voluntaria por prestación de servicios en el sector público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 39, "El personal funcionario de la Comunidad Autónoma removido de un puesto de trabajo que todavía no ha obtenido destino está en situación:", "De expectativa de destino.", "De excedencia forzosa.", "De servicio activo.", "de servicios especiales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 40, "El personal funcionario de la Comunidad Autónoma, cuando pase a ocupar por el sistema de libre designación puestos de trabajo del Gabinete de la Presidencia, será declarado en situación:", "De servicio activo.", "De servicios especiales.", "De Servicio en otras administraciones públicas.", "De excedencia voluntaria por prestación de servicios en el sector público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 41, "Se declarará la excedencia voluntaria por prestación de servicios en el sector público:", "Cuando los funcionarios de carrera accedan, por promoción interna u otros sistemas de acceso, a otros cuerpos o escalas de cualquier administración pública, y no les corresponda quedar en otra situación.", "Cuando pasen a prestar servicios en administraciones, organismos o entidades del sector público y no les corresponda quedar en la situación de servicios especiales.", "Cuando los funcionarios de carrera ocupen un puesto mediante nombramiento de personal funcionario interino o como personal laboral con contrato temporal.", "Las respuestas a), b) y c) corresponden a supuestos para ser declarados en situación de excedencia voluntaria por nombramiento provisional en un grupo o subgrupo superior."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 42, "Para el cuidado de un familiar a cargo directo, el personal funcionario puede solicitar:", "Excedencia voluntaria para cuidado de familiares, por un periodo no superior a tres años.", "Excedencia voluntaria para cuidado de familiares, por un periodo no superior a dos años.", "Excedencia voluntaria para cuidado de familiares, por un periodo no superior a un año.", "Excedencia voluntaria para cuidado de familiares, únicamente en el caso que sea para la atención de los hijos, por naturaleza, adopción o acogimiento permanente o preadoptivo y por un periodo no superior a tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 43, "¿Cuál de las siguientes situaciones administrativas precisa desarrollo normativo para su aplicación?", "Excedencia voluntaria por motivos de salud y excedencia voluntaria incentivada.", "Excedencia forzosa y excedencia voluntaria por motivos de salud.", "Excedencia voluntaria incentivada y excedencia forzosa.", "Únicamente la excedencia voluntaria incentivada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 44, "En el caso de que el funcionario procedente de la situación de suspensión solicite el reingreso y este no sea posible por falta de puesto vacante con dotación presupuestaria, se declarará en situación:", "De expectativa de destino.", "De excedencia voluntaria por interés particular.", "De excedencia forzosa.", "Permanecerá en la situación de suspenso hasta que exista una vacante con dotación presupuestaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 45, "El personal funcionario al que se le ha suprimido el puesto de trabajo a consecuencia de una redistribución de efectivos, de un plan general de ordenación o de otras medidas de racionalización de la organización administrativa y de personal reguladas por la presente ley, y que no haya obtenido destino, puede ser declarado en situación:", "De expectativa de destino.", "De Excedencia voluntaria por interés particular.", "De excedencia forzosa.", "La inamovilidad en la condición de funcionario de carrera está garantizada por el artículo 1 del Estatuto básico del empleado público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 46, "El reingreso se llevará a cabo respetando el siguiente orden de prelación: quien proviene de la situación de expectativa de destino, quien proviene de la situación de excedencia forzosa, quien proviene de la situación de suspensión, y quien proviene de la situación de excedencia voluntaria:", "Cierto.", "Falso, la prelación correcta es la siguiente: quien proviene de la situación de expectativa de destino, quien proviene de la situación de excedencia forzosa, quien proviene de la situación de excedencia voluntaria, y quien proviene de la situación de suspensión.", "Falso, la prelación correcta es la siguiente: quien proviene de la situación de excedencia forzosa, quien proviene de la situación de expectativa de destino, quien proviene de la situación de excedencia voluntaria, y quien proviene de la situación de suspensión.", "El reingreso en el servicio activo del personal funcionario que no tiene reserva de puesto de trabajo se efectúa ordinariamente a través de la participación en las convocatorias de provisión excepto en el caso de excedencia voluntaria, por ello, el excedente voluntario, al solicitar el reingreso fuera de la participación de un sistema de provisión, tiene una prelación mayor."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 47, "El personal funcionario tiene derecho a disfrutar de vacaciones anuales retribuidas por un período:", "De un mes natural o veintidós días laborables.", "De un mes natural o veintitrés días laborables dentro de cada año natural completo de servicio activo.", "De un mes natural o veinticuatro días laborables dentro de cada año natural completo de servicio activo o bien de los días que correspondan en proporción al tiempo de servicio, en el caso de que este sea inferior al año natural.", "De un mes natural o veinticinco días laborables dentro de cada año natural completo de servicio activo o bien de los días que correspondan en proporción al tiempo de servicio, en el caso de que este sea inferior al año natural."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 48, "El personal funcionario al servicio de la Administración autonómica tiene, entre otros, los siguientes derechos:", "A la movilidad en la condición de personal funcionario público y al ejercicio efectivo de las funciones propias de su condición profesional.", "A la consecución de los objetivos de la unidad administrativa donde prestan servicios y a ser informados por el personal superior de las tareas a realizar.", "A la solución extrajudicial de conflictos en los términos que se establezcan reglamentariamente, de conformidad con la legislación básica estatal.", "A los premios y las recompensas que se establezcan reglamentariamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 49, "El personal funcionario puede disfrutar de los permisos horarios y permisos por días, por causas justificadas, de acuerdo con los requisitos y las condiciones que se establezcan reglamentariamente, que deben permitir:", "La conciliación de la vida familiar y laboral.", "La conciliación de la vida personal y familiar.", "La conciliación de la vida familiar y la participación en asuntos públicos.", "Las tres respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 50, "Para la realización de estudios sobre materias directamente relacionadas con el puesto de trabajo que desarrolla, el personal funcionario puede solicitar una licencia, que podrá ser por interés exclusivo del personal o por interés de la administración, si cumple los requisitos siguientes:", "Que las necesidades del servicio no lo impidan.", "La duración máxima será de dieciocho meses cada tres años, si es por interés personal.", "En cualquier caso, se mantiene el derecho a percibir la retribución y el alta en el régimen de la seguridad social.", "De cualquier licencia para la realización de estudios se debe informar a la Junta de Personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 51, "¿Cuál de los siguientes supuestos no da derecho a la reducción de jornada de un máximo de la mitad de la jornada?", "Ser personal funcionario y tener más de sesenta años, sin necesidad de acreditar ninguna otra circunstancia.", "Tener la guarda legal de un hijo o una hija menor de doce años.", "Padecer problemas de salud que pueden dar lugar a una incapacidad temporal o permanente.", "Encargarse de un familiar de primer grado por razones de enfermedad muy grave."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 52, "No es una retribución complementaria del personal funcionario de la Administración de la Comunidad Autónoma de las Illes Balears:", "El complemento de destino.", "El complemento de residencia.", "El complemento específico.", "Las gratificaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 53, "El sistema retributivo de la Administración de la Comunidad Autónoma de las Illes Balears, de acuerdo con lo dispuesto en la normativa básica estatal, no se rige por uno de los siguientes criterios:", "Las retribuciones del personal se ajustarán, en la medida de lo posible, al entorno socioeconómico de las Illes Balears, con especial atención al hecho diferenciador de la insularidad.", "Se establecerán sistemas que permitan la retribución del grado de voluntad en el cumplimiento de las funciones o tareas encomendadas.", "Se tendrán en cuenta las diferencias derivadas de la especial dificultad, la responsabilidad y las distintas condiciones de trabajo, con atención especial al horario de trabajo.", "El personal funcionario no puede ser retribuido por conceptos diferentes a los que establece la normativa vigente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 54, "De las siguientes retribuciones complementarias, ¿cuál es el único complemento retributivo que puede percibir el personal funcionario de la Administración de la Comunidad Autónoma de las Illes Balears?", "El complemento de nocturnidad, que es aquel que retribuye la parte de la jornada que se realiza en horario nocturno, entre las 22 horas y las 06 horas del día siguiente.", "El complemento por turno de disponibilidad, que retribuye el tiempo en el que un trabajador que presta servicios con horario especial se encuentra localizable y con plena capacidad de desplazamiento para presentarse con prontitud cuando se le requiera para atender, en una localización determinada, las necesidades puntuales o especiales fuera de su horario habitual de trabajo y del puesto de trabajo.", "El complemento de turnos, que retribuye aquellos puestos de trabajo cuya jornada y horario se realiza en régimen de turnos, podrán ser turnos.", "El complemento de peligrosidad, también conocido como plus de peligrosidad, que trata de compensar el riesgo adicional al que tiene que exponerse de forma habitual quien desarrolla las funciones del puesto de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 55, "¿Cuál de los siguientes no es un deber del personal funcionario al servicio de la Administración de la Comunidad Autónoma?", "Conocer las lenguas oficiales en el nivel que se determine reglamentariamente, y facilitar a los ciudadanos el ejercicio del derecho de utilizarlas en las relaciones con la Administración autonómica.", "Cumplir el régimen de incompatibilidades.", "Guardar secreto respecto a la información que tenga.", "No utilizar en provecho propio o de terceras personas los bienes y los recursos de la Administración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 56, "¿Cuál de los siguientes no es un deber del personal funcionario al servicio de la Administración de la Comunidad Autónoma?", "Velar por el propio perfeccionamiento profesional y participar en los cursos de formación que sean obligatorios.", "Observar las medidas de salud laboral y de prevención de riesgos que se adopten legal y reglamentariamente.", "Recibir protección eficaz en materia de prevención, seguridad y salud en el trabajo.", "Actuar de conformidad con los principios éticos y de conducta establecidos por la normativa vigente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 57, "Indique cuál de las respuestas es falsa. El personal funcionario al servicio de la Administración de la Comunidad Autónoma tiene el deber de cumplir las instrucciones y las órdenes recibidas del personal superior jerárquico:", "Sin perjuicio de que el personal pueda formular las sugerencias que considere oportunas para mejorar la ejecución de las tareas encomendadas.", "Si considera que la orden recibida es contraria a la legalidad, puede solicitarla por escrito.", "En cualquier caso las órdenes se cumplirán.", "Aunque exija la ejecución de tareas fuera de la jornada ordinaria."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 58, "El personal al servicio de la Administración de la Comunidad Autónoma de las Illes Balears esta obligado a residir en la localidad donde trabaja:", "Nunca.", "solo en los casos en los que, por razón del servicio, el deber de residencia sea necesario.", "Cierto, de ahí el abono de la indemnización por residencia.", "Depende de la dificultad para el acceso a la vivienda."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 59, "Respecto de la responsabilidad patrimonial, sin perjuicio de la responsabilidad por el funcionamiento de los servicios públicos regulada en el artículo 106.2 de la Constitución y del deber de resarcir los daños causados a las personas particulares, la Administración autonómica, una vez que las haya indemnizado:", "Se dirigirá de oficio contra el funcionario causante de los daños en acción de regreso, mediante la instrucción del procedimiento correspondiente.", "Se dirigirá de oficio contra el funcionario causante de los daños por dolo, culpa o negligencia graves, en acción de regreso, mediante la instrucción del procedimiento correspondiente.", "Se dirigirá contra el funcionario que por dolo, culpa o negligencia graves produzca daños o perjuicios a los bienes o derechos de la Comunidad Autónoma.", "Una vez resarcidos los daños causados a las personas particulares derivados por el funcionamiento de los servicios públicos, salvo que derive una responsabilidad penal, se da el supuesto de terminación del procedimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 60, "El cumplimiento de la función pública es incompatible con el ejercicio de cualquier:", "Cargo, profesión o actividad públicos, por cuenta ajena, retribuido o meramente honorífico, si impide o menoscaba el exacto cumplimiento de los deberes del funcionario, compromete su imparcialidad o independencia o perjudica los intereses generales", "Cargo, profesión o actividad privada, por cuenta propia o ajena, retribuidos o meramente honoríficos, si impide o menoscaba el exacto cumplimiento de los deberes del funcionario, compromete su imparcialidad o independencia o perjudica los intereses generales.", "Cargo, profesión o actividad, públicos o privados, por cuenta propia o ajena, retribuidos o meramente honoríficos, si impide o menoscaba el exacto cumplimiento de los deberes del funcionario, compromete su imparcialidad o independencia o perjudica los intereses generales.", "Cargo, profesión o actividad, públicos o privados, por cuenta propia o ajena, retribuidos o meramente honoríficos, únicamente en el supuesto de que las retribuciones complementarias del puesto de trabajo incluyan el factor de incompatibilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 61, "De acuerdo con lo previsto en la Ley 3/2007, de 27 de marzo, de la función pública de la comunidad autónoma de las Illes Balears, las faltas disciplinarias se clasifican:", "En muy graves, menos graves y leves.", "En muy graves, graves y leves.", "En muy graves, graves y menos graves.", "Las tres respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 62, "Se considera falta muy grave:", "La tolerancia del personal superior jerárquico respecto a la comisión de faltas muy graves o graves del personal que depende de él.", "La producción de daños graves a los locales, al material o a los documentos de los servicios.", "El exceso arbitrario en el uso de la autoridad que cause perjuicio al servicio o al personal que depende de él.", "Las acciones u omisiones dirigidas a evadir los sistemas de control de horarios o a impedir que sean detectados los incumplimientos injustificados de la jornada de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 63, "La falta notoria de rendimiento que suponga inhibición del cumplimiento de las tareas encomendadas se considera:", "Falta muy grave.", "Depende, y guardará relación con la gravedad de los daños causados, el grado de intencionalidad de la conducta, el grado de participación de la persona responsable y la eventual reiteración; en función de ello, podrá ser falta muy grave o falta grave.", "Falta grave.", "Podría ser leve, grave o muy grave, en función de la gravedad de los daños causados, el grado de intencionalidad de la conducta, el grado de participación de la persona responsable y la eventual reiteración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 64, "El abuso de autoridad en el ejercicio del cargo será considerado:", "Falta muy grave.", "Falta grave.", "Será falta grave cuando no constituya falta muy grave.", "El abuso de autoridad es un delito, y la responsabilidad penal y la civil derivada del delito se exigen de acuerdo con lo establecido en la legislación correspondiente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 65, "Son faltas graves:", "La falta de obediencia debida al personal superior jerárquico y a las autoridades que no constituya falta muy grave.", "Las conductas constitutivas de delito doloso relacionadas con el servicio o que causen daño a la Administración o a la ciudadanía y no constituyan falta muy grave.", "La emisión de informes y la adopción de acuerdos manifiestamente ilegales cuando causen perjuicio a la Administración o a la ciudadanía, y no constituyan falta muy grave.", "Ninguna de las respuestas anteriores es incorrecta."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 66, "No cumplir con exactitud la jornada y el horario de trabajo establecidos, excepto si es por causa justificada:", "Es una falta leve.", "Es una falta leve que puede ser grave si el cumplimiento injustificado de la jornada de trabajo acumulada suponga un determinado número mínimo de horas.", "Es una falta leve, que no debe confundirse con la falta injustificada de asistencia, que sí es falta grave.", "Es el incumplimiento de un deber que no tiene consideración de falta, pero da lugar a la deducción de retribuciones correspondiente a la diferencia en cómputo mensual entre la jornada reglamentaria de trabajo y la efectivamente desarrollada."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 67, "Son faltas leves:", "Las acciones u omisiones dirigidas a evadir los sistemas de control de horarios o a impedir que sean detectados los incumplimientos injustificados de la jornada de trabajo.", "La falta de asistencia injustificada de un día.", "No guardar la discreción profesional respecto a los asuntos que conozca por razón de sus funciones.", "Las tres respuestas anteriores son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 68, "La sanción de separación del servicio o la revocación del nombramiento del personal funcionario interino puede imponerse por la comisión de faltas:", "Graves.", "Muy graves.", "Muy graves y graves.", "Únicamente puede imponerse dicha sanción a resultas de un proceso penal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 69, "La suspensión de funciones y retribuciones por un determinado periodo podrá imponerse por la comisión de faltas:", "Muy graves.", "Graves.", "Leves", "En función de la duración del período de suspensión, se impondrá para faltas muy graves, graves o leves."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 70, "La prescripción de faltas y sanciones:", "Las faltas muy graves prescriben a los seis años, las graves a los tres años y las leves al año. Las sanciones impuestas por faltas muy graves prescriben a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves a los seis meses.", "Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los seis meses. Las sanciones impuestas por faltas muy graves prescriben a los dos años, las impuestas por faltas graves al año y las impuestas por faltas leves a los tres meses.", "Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los seis meses. Las sanciones impuestas por faltas muy graves prescriben a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves a los seis meses.", "Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los tres meses. Las sanciones impuestas por faltas muy graves prescriben a los tres años, las impuestas por faltas graves a los dos años y las impuestas por faltas leves a los tres meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 71, "Como instrumento para la mejora de la motivación, del rendimiento y de la calidad de los servicios públicos, las administraciones públicas de las Illes Balears implantarán progresivamente:", "Sistemas de carrera profesional para el personal a su servicio.", "Sistemas de evaluación del cumplimiento del personal a su servicio.", "La progresión en el seno de la Administración conforme a los principios de igualdad, mérito y capacidad.", "La carrera profesional horizontal, que consiste en la consolidación del grado personal, de la promoción interna y de la movilidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 72, "La progresión de nivel o escalón, sin necesidad de cambiar de puesto de trabajo como consecuencia de la valoración del desempeño y la actuación profesional, de la calidad de los trabajos realizados y los conocimientos adquiridos y transferidos:", "Es el grado personal.", "Se denomina promoción interna horizontal.", "Es la carrera profesional horizontal.", "Esta progresión no existe en la Administración de la Comunidad Autónoma."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 73, "La oferta de empleo público correspondiente al turno de promoción interna:", "Solo incluirá las plazas vacantes correspondientes a los puestos singularizados que se determinan reglamentariamente.", "Se aprobará en la primera quincena del mes de enero de cada año, y las convocatorias de su desarrollo deberán publicarse antes del día 31 de enero del mismo año.", "Es el sistema para el acceso del personal funcionario y del personal laboral fijo a otros cuerpos, escalas, especialidades o categorías profesionales.", "Se aprobará en el mes de enero de cada año, y las convocatorias de su desarrollo deberán publicarse antes del día 31 de diciembre del mismo año."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 74, "Las modalidades de promoción interna deben permitir:", "Las respuestas b), c) y d) son correctas.", "El acceso del personal funcionario a cuerpos del grupo inmediatamente superior, siempre y cuando sean de la misma naturaleza, general o especial.", "El acceso del personal funcionario de los cuerpos generales a los cuerpos especiales o al revés, del mismo grupo o del grupo inmediatamente superior.", "El acceso del personal funcionario de los cuerpos y las escalas de un grupo a otros cuerpos o escalas del mismo grupo, que tengan la misma naturaleza, general o especial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 13, 75, "El grado personal:", "El personal de nuevo ingreso adquiere, dos años continuado o tres con interrupción después de adquirir la condición de personal funcionario y con carácter automático, un grado personal inicial que corresponde al nivel mínimo del intervalo establecido para el cuerpo o la escala de acceso, con independencia del puesto de trabajo que ocupe y de la forma de provisión del mismo.", "El personal de nuevo ingreso adquiere, juntamente con la condición de personal funcionario y con carácter automático, un grado personal inicial que corresponde al nivel mínimo del intervalo establecido para el cuerpo o la escala de acceso, con independencia del puesto de trabajo que ocupe y de la forma de provisión del mismo.", "El grado personal superior al adquirido se consolida por la ocupación de un puesto del nivel correspondiente durante dos años continuados o tres con interrupción.", "El grado personal no puede adquirirse, con independencia del nivel del puesto de trabajo que se ocupa, mediante la permanencia en un puesto con carácter definitivo junto con la superación de cursos y la evaluación del cumplimiento."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 1, "La normativa sobre prevención de riesgos laborales queda constituida por:", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales y las disposiciones de desarrollo o complementarias.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales, las disposiciones de desarrollo o complementarias, y las normas internacionales.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales, disposiciones de desarrollo o complementarias, y todas aquellas otras normas legales o convencionales, que contengan prescripciones relativas a la adopción de medidas preventivas en el ámbito laboral."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 2, "La Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales tiene por objeto:", "Mejorar las condiciones laborales de los trabajadores.", "Promover la seguridad y la salud de las personas trabajadoras.", "Disponer las medidas preventivas adecuadas a los puestos de trabajo.", "Establecer la forma de evaluación de los riesgos en los puestos de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 3, "Las disposiciones de carácter laboral que contiene la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales tendrán el carácter de:", "De derecho necesario mínimo indisponible, y pueden ser mejoradas y desarrolladas en los convenios colectivos.", "De derecho mínimo indisponible, pero no se pueden desarrollar con los convenios colectivos.", "Carecen de carácter de derecho mínimo.", "Tienen carácter de máximo derecho."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 4, "La Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales es de aplicación en el ámbito de:", "Policía, seguridad y resguardo aduanero.", "Las relaciones laborales reguladas por el Estatuto de los trabajadores y en las relaciones de carácter administrativo o estatutario del personal al servicio de las administraciones públicas.", "Servicios operativos de protección civil y peritaje forense en los casos de grave riesgo, catástrofe y calamidad pública.", "Fuerzas Armadas y actividades militares de la Guardia Civil."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 5, "De acuerdo con el artículo 4 de la Ley de Prevención de riesgos laborales, el riesgo laboral es:", "Las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo.", "El conjunto de actividades o medidas adoptadas o previstas en todas las fases de actividad de la empresa.", "La posibilidad de que un trabajador sufra un determinado daño derivado del trabajo.", "Cualquier máquina, aparato, instrumento o instalación que se utiliza en el trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 6, "La Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales no es aplicable en las actividades cuyas particularidades lo impidan en el ámbito de las funciones públicas de:", "Policía, seguridad y resguardo aduanero.", "Servicios operativos de protección civil, peritaje forense en los casos de grave riesgo, catástrofe y calamidad pública.", "Fuerzas armadas y actividades militares de la Guardia Civil.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 7, "¿Cuál es la definición de daños derivados del trabajo según la Ley de Prevención de riesgos laborales?", "Los problemas de salud relacionados con las condiciones de trabajo.", "Las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo.", "Cualquier alteración de la salud relacionada, causada o agravada por las condiciones de trabajo.", "Las lesiones corporales y psíquicas que el trabajador sufra con ocasión o por consecuencia del trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 8, "¿Cuál es la definición de prevención según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "El conjunto de actividades o medidas adoptadas o previstas en todas las fases de la actividad de la empresa con el fin de evitar o disminuir los riesgos derivados del trabajo.", "El conjunto de medios disponibles para ayudar en el desarrollo de la labor laboral.", "El conjunto de medios auxiliares y equipos de protección individual.", "Los procedimientos de trabajo y normativas derivadas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 9, "¿Cuál es la definición de riesgo laboral según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "Es el foco de emisión de gases y vapores.", "Es la casualidad de que una persona trabajadora sufra un accidente.", "Es la gravedad de un daño en la salud.", "Es la posibilidad de que un trabajador sufra un determinado daño derivado del trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 10, "Para calificar un riesgo laboral desde el punto de vista de su gravedad debe valorarse conjuntamente:", "El grado de afectación a la persona trabajadora.", "La probabilidad de que se produzca el daño y su severidad.", "Sólo se valora la severidad.", "La probabilidad de que haya sufrimiento físico y no psicológico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 11, "¿Cuál es la definición de riesgo laboral grave e inminente según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "Es aquél en el que las consecuencias y el daño tienen lugar a corto plazo.", "Es el hecho en el que la gravedad hace que el riesgo sea imposible prevenir.", "Es aquel que racionalmente se materializa en un futuro inmediato y pueda suponer un grave daño para la salud de la persona trabajadora.", "Es la situación inesperada que tiene graves consecuencias para la seguridad y salud de los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 12, "¿Cuál es la definición de equipo de trabajo según la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales?", "Es cualquier máquina, aparato, instrumento o instalación utilizada en el trabajo.", "Es todo aparato con el que se desarrolla el trabajo diario.", "Es todo sistema con el que se desarrolla el trabajo.", "Son las instalaciones de los centros de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 13, "¿Cuál es la definición de condición de trabajo según la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales?", "Son todas las circunstancias derivadas del trabajo.", "Es la situación más habitual en el entorno laboral.", "Son las características inherentes al desarrollo de la labor diaria.", "Es cualquier característica del trabajo que pueda tener una influencia significativa en la generación de riesgos para la seguridad y salud del trabajador o trabajadora."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 14, "¿Cuál es la definición de equipo de protección individual según la Ley 31/1995 de Prevención de riesgos laborales?", "Es todo ese equipamiento destinado a proteger la seguridad y salud del personal.", "Es cualquier equipo destinado a ser llevado o sujetado por el trabajador o trabajadora para que lo proteja de uno o varios riesgos que puedan amenazar su seguridad o salud en el trabajo, así como cualquier complemento o accesorio destinado a tal fin.", "Es cualquier elemento que protege de un riesgo laboral a varios trabajadores.", "Todo sistema de sujeción individual con el fin de evitar las caídas a nivel."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 15, "La política en materia de prevención de riesgos laborales tiene como objetivo:", "Promover la mejora de las condiciones de trabajo a fin de elevar el nivel de protección de la seguridad y la salud de los trabajadores en el trabajo.", "Mejorar las condiciones salariales y sociales de los trabajadores afiliados a la seguridad social.", "Alcanzar unas condiciones dignas de trabajo.", "Respetar la salud de los trabajadores en el trabajo adoptando medidas preventivas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 16, "Las administraciones públicas competentes en materia laboral deben llevar a cabo las funciones de:", "Promoción de la seguridad y asesoramiento jurídico en su ámbito de aplicación.", "Prevención de accidentes laborales y enfermedades profesionales.", "Promoción de la prevención, asesoramiento técnico, vigilancia y control del cumplimiento por los sujetos comprendidos en su ámbito de aplicación de la normativa de prevención de riesgos laborales, y sanción de las infracciones en caso necesario.", "Sanción de las infracciones administrativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 17, "En relación al Instituto Nacional de Seguridad y Salud en el Trabajo (anteriormente, Instituto Nacional de Seguridad e Higiene en el Trabajo), cuál no es una función de este organismo:", "Apoyo técnico y colaboración con la Inspección de Trabajo y Seguridad Social.", "Promoción y, en su caso, realización de actividades de formación, información, investigación, estudio y divulgación en materia de prevención de riesgos laborales.", "Asesoramiento técnico en la elaboración de la normativa legal y en el desarrollo de la normalización, tanto en el ámbito nacional como internacional.", "Vigilancia del cumplimiento de la normativa sobre prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 18, "De acuerdo con la Ley 31/1995, de 8 de noviembre, de prevención de riesgo laborales, la función de la Inspección de Trabajo y Seguridad Social es:", "Desarrollar la normativa que incide en las condiciones de trabajo.", "Evaluar las condiciones de seguridad y salud.", "Vigilar y controlar el cumplimiento de la normativa en prevención de riesgos laborales.", "Sancionar en temas relativos a la seguridad social exclusivamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 19, "Es un principio básico de la política de prevención de riesgos laborales", "La participación de empresarios y de trabajadores, mediante las organizaciones empresariales y sindicales más representativas, en la planificación, programación, organización y control de la gestión relacionadas con la mejora de las condiciones de trabajo y la protección de la seguridad y salud de los trabajadores.", "La elaboración de normativa laboral.", "La conciliación de la vida familiar y laboral.", "Sólo la mejora de las condiciones de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 20, "El artículo 14 de la Ley de Prevención de Riesgos Laborales establece:", "Que cuando se haya producido un daño para la salud (física o psíquica) debe investigarse.", "Que el empresario debe garantizar la seguridad y la salud de los trabajadores en todos los aspectos relacionados con el trabajo.", "Que como acción preventiva debe promocionarse la salud.", "Que debe atenuarse el trabajo monótono y repetitivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 21, "Señale la respuesta correcta en relación al Plan de Prevención de riesgos laborales:", "Deben realizarlo aquellas empresas de más de cincuenta trabajadores.", "Las empresas, según el número de trabajadores y la naturaleza y peligrosidad de las actividades realizadas, pueden realizar el Plan de prevención de riesgos laborales de forma simplificada.", "Deben realizarlo aquellas empresas de más de cien trabajadores.", "Las empresas, según el número de trabajadores y la naturaleza y peligrosidad de las actividades realizadas, pueden realizar el Plan de prevención de riesgos laborales de forma extensa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 22, "El artículo 15 de la Ley 31/1995, de 8 de noviembre, de Prevención de riesgos laborales establece que:", "El empresario no tendrá en cuenta la capacitación profesional de los trabajadores.", "Las empresas de más de 150 empleados deben disponer de plan de emergencias.", "El diseño del puesto de trabajo no se contempla en la prevención de riesgos laborales.", "El empresario debe aplicar los principios de la acción preventiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 23, "El principio de sustituir lo que sea peligroso por lo que comporte poco peligro o no comporte ninguno es:", "Un principio de la acción preventiva.", "Una acción del estudio inicial.", "Un caso aplicable a productos químicos.", "No es un principio de acción preventiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 24, "De acuerdo con el artículo 16 de la Ley de Prevención de Riesgos Laborales, cuando se haya producido un daño para la salud de los trabajadores, el empresario:", "Debe realizar un nuevo Plan de Prevención que incluya los daños de los trabajadores.", "Debe llevar a cabo una investigación sobre el caso, a fin de detectar las causas de los hechos.", "Debe comunicar los hechos a la fiscalía.", "Debe llevar a cabo el seguimiento de la actividad preventiva a fin de perfeccionar de forma continua las actividades de identificación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 25, "El artículo 17 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales dice que:", "El empresario debe proporcionar a sus empleados sólo equipos de protección individual.", "El empresario debe velar para que se haga un uso efectivo de los equipos de protección individual.", "El empresario debe proporcionar a sus empleados equipos de protección individual adecuados para el ejercicio de sus funciones y velar para que se haga un uso efectivo cuando sea necesario.", "Son necesarios los equipos de trabajo y los equipos de protección individual."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 26, "De acuerdo con el artículo 18 de la Ley de Prevención de Riesgos Laborales, el empresario debe adoptar las medidas adecuadas para que los trabajadores reciban todas las informaciones necesarias en relación con:", "Los derechos laborales que les corresponden.", "Las obligaciones en referencia a la prevención de riesgos laborales.", "Los riesgos, las medidas y las actividades de protección y prevención y las medidas adoptadas.", "El empresario no tiene ninguna obligación de informar a los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 27, "En relación a la información a la que se refiere el artículo 18 de la Ley de Prevención de Riesgos Laborales establece que:", "Si hay representantes de los trabajadores, debe proporcionarlo el empresario a los trabajadores a través de los representantes; no obstante, se informará directamente a cada trabajador de los riesgos específicos que afecten a su puesto de trabajo o función y de las medidas de protección y prevención aplicables a los riesgos.", "El empresario únicamente debe darlo a los representantes de los trabajadores que la harán llegar a los trabajadores.", "El empresario siempre debe darlo a los trabajadores sin la intermediación de los representantes de los trabajadores.", "La información se establece en el artículo 23 de la Ley de prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 28, "La formación en el ámbito de la prevención de riesgos laborales debe ser:", "Voluntaria para el empresario, pero obligatoria por el personal.", "Voluntaria para el empresario y voluntaria por el personal.", "El empresario debe garantizar para todo el personal la formación teórica y práctica en materia preventiva.", "La formación no debe centrarse específicamente en el puesto de trabajo o la función del personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 29, "La formación en materia preventiva de riesgos laborales debe impartirse:", "Dentro de la jornada laboral siempre que sea posible, o si no fuera posible en otras horas descontándolas de la jornada laboral.", "Fuera de la jornada laboral.", "En el período de vacaciones.", "Los cuatro primeros meses del año en curso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 30, "Indique la afirmación correcta en relación con las situaciones de emergencia:", "Sobre las medidas de emergencia el empresario no debe hacer nada porque es competencia exclusiva de los servicios de emergencia de la Comunidad Autónoma.", "El empresario encargará siempre a una empresa la evaluación de las situaciones de emergencia, independientemente de las dimensiones y la actividad de la empresa y de la presencia de personas ajenas a la misma.", "Las situaciones de emergencia quedan fuera de las obligaciones del empresario establecidas en la Ley de Prevención de Riesgos Laborales", "El empresario, teniendo en cuenta las dimensiones y la actividad de la empresa, así como la posible presencia de personas ajenas a la misma, debe analizar las posibles situaciones de emergencia y adoptar las medidas necesarias en materia de primeros auxilios, lucha contra incendios y evacuación de los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 31, "Cuando el personal esté o puedan estar expuesto a un riesgo grave e inminente a causa de su trabajo, el empresario está obligado a:", "A dar aviso a la Inspección de trabajo y a la seguridad social.", "Informar de esta situación a todo el personal afectado lo antes posible, adoptar las medidas para que se pueda interrumpir la actividad laboral inmediatamente y disponer de lo necesario para adoptar las medidas necesarias para evitar las consecuencias de dicho peligro.", "Precintar el centro de trabajo.", "Dar aviso con el tiempo suficiente para aplicar las medidas preventivas necesarias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 32, "En referencia a lo establecido en el artículo 22 de la Ley de Prevención de Riesgos Laborales en cuanto a la vigilancia de la salud, señale la respuesta incorrecta:", "Los datos relativos a la vigilancia de la salud de los trabajadores no se pueden realizar servir con fines discriminatorios ni en perjuicio del trabajador.", "El empresario debe garantizar a los trabajadores a su servicio la vigilancia periódica de su estado de salud en función de los riesgos inherentes al trabajo.", "Los resultados de la vigilancia se comunicarán a los trabajadores afectados, al empresario ya los representantes de los trabajadores.", "Las medidas de vigilancia y control de la salud deben llevarse a cabo respetando siempre el derecho a la intimidad ya la dignidad de la persona y la confidencialidad de toda la información relacionada con su estado de salud."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 33, "En relación al derecho a la vigilancia de la salud:", "Siempre debe prolongarse más allá de la finalización de la relación laboral.", "Se prolongará más allá de la finalización de la relación laboral sólo cuando el trabajador lo solicite expresamente.", "En ningún caso debe prolongarse más allá de la finalización de la relación laboral.", "Se debe prolongar en los supuestos en los que la naturaleza de los riesgos inherentes al trabajo lo haga necesario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 34, "¿Qué documentación debe elaborar y conservar el empresario de acuerdo con la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales?", "La evaluación de riesgos laborales de cada puesto de trabajo específico y la documentación relativa al estado de salud del personal.", "El plan de prevención y la relación de accidentes laborales, pero no la de enfermedades profesionales.", "El plan de prevención y la relación de accidentes laborales y la de enfermedades profesionales.", "El plan de prevención, la evaluación de riesgos para la seguridad y la salud del personal, la planificación preventiva, la práctica de los controles del estado de salud del personal y la relación de accidentes de trabajo y enfermedades profesionales que hayan causado al trabajador una incapacidad laboral superior a un día de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 35, "De acuerdo con el artículo 26 de la Ley de Prevención de Riesgos Laborales, las mujeres embarazadas tienen derecho:", "A ausentarse del trabajo, con derecho a remuneración, para realizar exámenes prenatales y técnicas de preparación al parto, con aviso previo al empresario y justificando la necesidad de hacerlo dentro de la jornada de trabajo.", "A ausentarse del trabajo, sin derecho a remuneración, para realizar exámenes prenatales y técnicas de preparación al parto, con aviso previo al empresario y con la justificación de la necesidad de hacerlo dentro de la jornada de trabajo.", "A ausentarse del trabajo, con derecho a remuneración, para realizar exámenes prenatales y técnicas de preparación al parto, sin la obligación de avisar previamente al empresario.", "No tienen derecho a ausentarse del trabajo, para realizar exámenes prenatales y técnicas de preparación al parto."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 36, "La coordinación de actividades empresariales implica que:", "En uno o más centros de trabajo haya más de dos empresas implicadas en el desarrollo laboral.", "En un centro de trabajo hay más de tres empresas trabajando a la vez, pero no implica ninguna responsabilidad al titular del centro.", "Cuando en un mismo centro de trabajo lleven a cabo actividades el personal de dos o más empresas, éstas deben cooperar en la aplicación de la normativa sobre prevención de riesgo laborales.", "Sólo es necesaria la cooperación documental del plan de prevención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 37, "El artículo 25 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales establece que:", "El plan de prevención debe revisarse anualmente.", "La evaluación de riesgos laborales debe revisarse anualmente.", "El plan de prevención y la evaluación de riesgos laborales caducan a los tres años.", "El empresario debe garantizar específicamente la protección del personal que por sus características personales o su estado biológico conocido sean especialmente sensibles a los riesgos derivados del trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 38, "¿Qué actuaciones preventivas deben realizarse antes de la incorporación al trabajo de jóvenes menores de dieciocho años?", "Se realizará una evaluación del puesto de trabajo que éstos deban ocupar con el fin de determinar la naturaleza, el grado y la duración de su exposición a los riesgos específicos, a agentes, procesos o condiciones de trabajo que puedan poner en peligro la seguridad o salud de este trabajador.", "Deben incluirse en el plan de prevención y establecer formación específica.", "Se debe hacer una evaluación global del puesto de trabajo.", "Se tendrán sólo en cuenta las condiciones de seguridad del puesto de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 39, "¿Cuándo es necesaria la presencia de los recursos preventivos?", "Cuando se realicen actividades o procesos que por reglamento sean considerados como peligrosos o con riesgos especiales.", "Cuando los riesgos puedan verse agravados o modificados en el desarrollo del proceso o la actividad, por la concurrencia de operaciones diversas que se llevan a cabo sucesiva o simultáneamente y que hagan necesario el control de la aplicación correcta de los métodos de trabajo.", "Cuando la necesidad de esta presencia sea requerida por la Inspección de Trabajo y Seguridad Social, si las circunstancias del caso así lo exigen debido a las condiciones de trabajo detectadas.", "Todas las anteriores respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 40, "Las obligaciones del personal en materia de prevención de riesgos laborales son:", "Velar por la seguridad y salud de uno mismo.", "Velar por su propia seguridad y salud en el trabajo y por la de aquellas otras personas cuya actividad profesional pueda afectar, debido a sus actos y omisiones en el trabajo.", "Adoptar las medidas preventivas necesarias del plan de prevención.", "Implantar las instrucciones de seguridad y salud en el puesto de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 41, "El derecho de participación regulado en el Capítulo V de la Ley de Prevención de Riesgos Laborales:", "Se ejerce en el ámbito de las administraciones públicas con las adaptaciones que sean procedentes atendiendo a la diversidad de las actividades que llevan a cabo y las diferentes condiciones en que éstas se realizan, la complejidad y dispersión de la estructura organizativa y sus peculiaridades en materia de representación colectiva.", "Se ejerce de igual forma en el ámbito de la empresa privada y en el ámbito de las administraciones públicas sin adaptaciones particulares en ninguno de ambos ámbitos.", "Se ejerce siempre y únicamente a través de los representantes de los trabajadores, tanto en el ámbito de la empresa privada como en el ámbito de las administraciones públicas.", "Se ejerce siempre y únicamente a través de los trabajadores, tanto en el ámbito de la empresa privada como en el ámbito de las administraciones públicas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 42, "¿Cuál de las siguientes no es una competencia de los delegados de prevención?", "Ejercer una labor de vigilancia y control sobre el cumplimiento de la normativa de prevención de riesgos laborales.", "Promover y fomentar la cooperación de los trabajadores en la ejecución de la normativa sobre prevención de riesgos laborales", "Informar a la autoridad laboral sobre los accidentes de trabajo.", "Colaborar con la dirección de la empresa en la mejora de la acción preventiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 43, "Los delegados de prevención están facultados para:", "Realizar visitas a los puestos de trabajo para desempeñar una tarea de vigilancia y control del estado de las condiciones de trabajo.", "Ser informados por las autoridades laborales sobre los daños producidos en la salud de los trabajadores.", "Paralizar la actividad laboral cuando se detecten riesgos muy graves para la salud de los trabajadores", "Tener acceso, sin limitación alguna, a la información y la documentación relativa a las condiciones de trabajo y de los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 44, "El comité de seguridad y salud:", "Es el órgano científico y técnico especializado cuya misión es el análisis y estudio de las condiciones de seguridad y salud en el trabajo.", "Es el órgano paritario y colegiado de participación destinado a la consulta regular y periódica de las actuaciones de la empresa en materia de prevención de riesgos.", "Es el órgano al que le corresponde la función de la vigilancia y el control de la normativa sobre prevención de riesgos laborales.", "Es el órgano colegiado asesor de las administraciones públicas en la formulación de las políticas de prevención."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 45, "Indique la respuesta incorrecta en referencia al Comité de Seguridad y Salud:", "Se debe constituir un comité de seguridad y salud en todas las empresas o centros de trabajo que dispongan de cincuenta o más trabajadores.", "El Comité está formado por los delegados de prevención, por un lado, y por el empresario y/o sus representantes en número igual al de los delegados de prevención, por otro.", "El comité de seguridad y salud debe reunirse trimestralmente y siempre que lo solicite alguna de las representaciones en el mismo Comité.", "Las normas de funcionamiento del Comité de Seguridad y Salud las adopta el empresario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 46, "El incumplimiento por parte de los empresarios de las obligaciones en materia de prevención de riesgos laborales, ¿a qué tipo de responsabilidades puede dar lugar?", "Administrativas, penales y civiles.", "Sólo penales y civiles.", "Sólo penales y administrativas.", "Sólo civiles y administrativas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 47, "¿Qué es un servicio de prevención de acuerdo con el artículo 31 de la Ley de Prevención de riesgos laborales?", "Es el conjunto de medios humanos y materiales necesarios para llevar a cabo las actividades preventivas a fin de garantizar la protección adecuada de la seguridad y la salud del personal.", "Es una empresa que se contrata para gestionar los reconocimientos médicos y la asistencia a accidentes de trabajo y enfermedades profesionales.", "Es un conjunto de medios auxiliares para establecer el plan de prevención.", "Es la empresa que se encarga de la gestión de accidentes y enfermedades profesionales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 48, "De acuerdo con el artículo 32 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales, las mutuas de accidentes de trabajo y enfermedades profesionales", "Tienen prohibido la participación en actividades mercantiles de prevención.", "Pueden ejercer actividades preventivas sólo en casos concretos.", "Ejercen sus funciones de acuerdo con lo establecido en la ley.", "Las mutuas y los servicios de prevención son lo mismo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 49, "El empresario debe consultar a los trabajadores de acuerdo con:", "El artículo 1 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales.", "El artículo 33 de consulta de los trabajadores de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales.", "El artículo 55 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales.", "El artículo 2 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 50, "¿Qué son los delegados de prevención?", "Son elegidos en las elecciones sindicales.", "Son los representantes de los trabajadores con funciones específicas en materia de prevención de riesgos en el trabajo.", "Son las personas que realizan las evaluaciones de riesgos laborales.", "Los elige el empresario entre los representantes sindicales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 51, "¿Cuántos delegados de prevención son necesarios en la Administración Autonómica de las Islas Baleares con más de 5000 trabajadores?", "Al menos un delegado de prevención.", "Entre cuatro a cinco delegados de prevención.", "Ocho delegados de prevención.", "Sólo es necesario un delegado de personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 52, "¿A qué están obligados los delegados de prevención con arreglo al artículo 37 de la Ley 31/1995, de prevención de riesgos laborales?", "A cumplir el deber de ejecución de las medidas preventivas.", "A cumplir con secreto profesional respecto a las informaciones a las que tengan acceso como consecuencia de su actuación en la empresa.", "Están obligados a formarse por cuenta propia.", "A seguir las indicaciones y instrucciones del empresario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 53, "¿Cuáles son las competencias y facultades del Comité de Seguridad y Salud?", "Elaborar el plan de prevención y evaluar las consecuencias en la aplicación.", "Evaluar los riesgos inherentes a los puestos de trabajo.", "Promover la aplicación de medidas correctoras.", "Participar en la elaboración, puesta en práctica y evaluación de los planes y programas de prevención de riesgos de la empresa, y promover iniciativas sobre métodos y procedimientos para la prevención de los riesgos en la empresa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 54, "¿Cuándo podrá el personal y sus representantes acudir a la Inspección de trabajo y seguridad social?", "Cuando consideren que las medidas adoptadas y los medios utilizados por el empresario no son suficientes para garantizar la seguridad y salud en el trabajo.", "No pueden recurrir porque no es función de la Inspección de trabajo y seguridad social.", "Cuando hayan pasado tres días desde el último día sometidos a riesgo grave e inminente.", "Siempre que aporten el plan de prevención implementado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 55, "¿Qué establece el artículo 41 de la Ley 31/1995, de 8 de noviembre, de Prevención de Riesgos Laborales?", "Los fabricantes, pero no los importadores deben cumplir con la Ley 31/1995, de 8 de noviembre, de prevención de riesgo laborales.", "Los fabricantes, los importadores y suministradores de maquinaria, equipos, productos y útiles de trabajo están obligados a asegurar que éstos no constituyan una fuente de peligro para el trabajador.", "Los fabricantes y suministradores deben cumplir con las disposiciones reglamentarias.", "El empresario debe hacer cumplir la ley a los fabricantes, importadores y suministradores de herramientas y servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 56, "El Real decreto 486/1997, de 14 de abril, por el que se establecen las disposiciones mínimas de seguridad y salud en los puestos de trabajo no es aplicable:", "A los medios de transporte, las obras de construcción, temporales o móviles, las industrias de extracción, los buques de pesca ni campos de cultivo, bosques u otros terrenos que se encuentren fuera de la zona edificada de estos terrenos.", "A los centros de trabajo de la administración pública.", "A los centros de trabajo del ámbito hospitalario.", "A los centros de trabajo de hostelería y restauración."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 57, "¿Qué se entiende por puesto de trabajo?", "El espacio que hay de 2 metros cuadrados libres de objetos en torno al trabajador.", "Se entiende por puesto de trabajo las áreas del centro de trabajo, edificadas o no, en las que los trabajadores deben permanecer o a las que pueden acceder por razón de su trabajo.", "Sólo es el espacio en torno a la maquinaria móvil.", "Se entiende por puesto de trabajo el espacio mínimo para trabajar con una mesa y un ordenador."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 58, "¿Cómo deben ser las puertas de emergencia de un centro de trabajo?", "Las puertas de emergencia deben abrirse hacia el interior y deben estar cerradas con cerradura.", "El Real decreto 486/1997, no regula cómo son las puertas de emergencia.", "Las puertas de emergencia deben abrirse hacia el exterior y no deben estar cerradas, por lo que cualquier persona que necesite usarlas en caso de urgencia pueda abrirlas fácil e inmediatamente.", "Tienen que ser de color rojo y pueden ser correderas o giratorias."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 59, "En cuanto al orden, limpieza y mantenimiento de un centro de trabajo debe tenerse en cuenta que:", "El mantenimiento preventivo será realizado por el personal no especializado.", "Las zonas de paso, salidas y vías de circulación de los puestos de trabajo y, en especial, las salidas y vías de circulación previstas para la evacuación en casos de emergencia, deben permanecer libres de obstáculos de forma que sea posible utilizarlas en todo momento sin dificultades.", "La instalación eléctrica no debe revisarse periódicamente.", "La limpieza de centros de trabajo no es ámbito de aplicación de la ley de prevención de riesgo laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 60, "¿A qué riesgos laborales se ve sometido al personal que utiliza pantallas de visualización de datos?", "Solo fatiga visual.", "Fatiga física y visual.", "Somnolencia y sordera.", "Las principales alteraciones de la salud se deben, básicamente, a riesgos para la vista y los problemas físicos y de carga mental, así como el posible efecto combinado de los mismos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 61, "La iluminación de los puestos de trabajo debe cumplir con las condiciones siguientes:", "La distribución de los niveles de iluminación debe ser lo más uniforme posible y adecuado a la exigencia visual.", "No existen condiciones mínimas de iluminación.", "Con 500 lux es insuficiente para sitios administrativos.", "No es necesario tener en cuenta la iluminación en los puestos de trabajo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 62, "¿Cómo debe ser el material de primeros auxilios de un centro de trabajo?", "No es necesario el material porque el trabajador accidentado debe dirigirse a la Mutua de trabajo.", "Si el acceso al centro de asistencia médica es cercano no es necesario disponer de material de primeros auxilios.", "Debe ser adecuado, en cuanto a su cantidad y características, al número de trabajadores, a los riesgos a los que estén expuestos ya las facilidades de acceso al centro de asistencia médica más cercano.", "La Mutua de trabajo no proporciona el material necesario para actuar en caso de primeros auxilios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 63, "En la manipulación manual de cargas, ¿que características del medio laboral pueden aumentar el riesgo dorsolumbar?", "El estado de salud del personal.", "El espacio de trabajo es insuficiente, el terreno es irregular y la iluminación es escasa.", "La carga a trasladar.", "La carencia de información y formación al personal."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 64, "¿Qué condiciones deben cumplir los equipos de protección individual?", "Deben de adecuarse al portador, después de los ajustes necesarios.", "Deben de tener en cuenta las condiciones anatómicas y fisiológicas y el estado de salud del trabajador", "Tienen que cumplir con la normativa vigente.", "Deben responder a las condiciones existentes en el puesto de trabajo, tener en cuenta las condiciones anatómicas y fisiológicas y el estado de salud del trabajador y adecuarse al portador, después de los ajustes necesarios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 65, "¿Qué disposiciones mínimas deben cumplir los puestos de trabajo?", "Las de orden y limpieza.", "Las condiciones constructivas, orden, limpieza y mantenimiento, señalización, instalaciones de servicio o protección, condiciones ambientales, iluminación, servicios higiénicos y locales de descanso; y material y locales de primeros auxilios.", "La iluminación y puertas de emergencia.", "Las condiciones ambientales y sonoras."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 66, "El diseño y las características constructivas de los puestos de trabajo deben ofrecer seguridad frente a los riesgos:", "Sólo por riesgos higiénicos.", "De fatiga visual y postural.", "De trauma auditivo.", "De los riesgos de resbalones o caídas, choques o golpes contra objetos y derrumbes o caída de materiales sobre los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 67, "La exposición a los agentes físicos, químicos y biológicos del ambiente de trabajo se rige:", "Por normativa específica.", "Sólo por normativa internacional.", "Por normativa autonómica.", "Por la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 68, "Las condiciones ambientales y termo higrométricas de los puestos de trabajo:", "Son valores mínimos y máximos sólo de humedad.", "No pueden ocasionar ningún riesgo para la seguridad y salud del personal.", "Son la temperatura absoluta.", "Son la humedad relativa."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 69, "¿Qué aspectos de los puestos de trabajo deben tenerse en cuenta para que el personal con diversidad funcional se incorpore al puesto de trabajo teniendo en cuenta su seguridad y salud?", "Sólo se tienen en cuenta las rampas de acceso.", "Los servicios higiénicos deben estar adaptados.", "Las puertas, las vías de circulación, las escaleras, los servicios higiénicos y los puestos de trabajo, utilizados u ocupados por personal con diversidad funcional, deben estar condicionados para que estos trabajadores puedan utilizarlos.", "No es necesario realizar adaptaciones."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 70, "La instalación de ventilación de un centro de trabajo debe:", "No es necesario realizar ninguna actuación.", "Sólo debe actuar después de una avería.", "Mantener en buen estado de funcionamiento y un sistema de control debe indicar cualquier avería, siempre que sea necesario para la salud de los trabajadores.", "Cambiar anualmente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 71, "¿Deben los puestos de trabajo disponer de vestuarios cuando los trabajadores tengan que llevar ropa especial de trabajo?", "No.", "Sí.", "Nunca porque no es necesario.", "La ropa especial de trabajo no es ámbito de la prevención de riesgos laborales."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 72, "¿Qué artículo de la Ley 31/1995, de prevención de riesgos laborales establece la información, consulta y participación del personal?", "El artículo 118.", "Los artículos 5 y 8.", "Los artículos 1 y 3.", "El artículo 18."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 73, "El artículo 17 de la Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales hace referencia:", "A los equipos de trabajo y medios de protección.", "A la promoción de la salud.", "Al personal sensible.", "A la formación e información a los trabajadores."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 74, "¿Es necesario disponer de servicios externos a la empresa para aplicar las medidas de emergencia?", "Sí. En particular en materia de primeros auxilios, asistencia médica de urgencia, salvamento y lucha contra incendios para garantizar la rapidez y eficacia de las mismas.", "No es necesario.", "Se establece en el artículo 22 de la Ley 31/1995, de Prevención de Riesgos Laborales.", "Sí pero no es necesario tener en cuenta ninguna particularidad."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 19, 75, "La vigilancia y el control de la salud del personal se llevará a cabo:", "Al finalizar la relación laboral con la empresa.", "Respetando siempre el derecho a la intimidad, a la dignidad de la persona y confidencialidad de la información relacionada con su estado de salud.", "La Ley 31/1995, de prevención de riesgos laborales no establece ningún criterio.", "A criterio técnico."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 1, "De acuerdo con el artículo 116.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los pliegos de cláusulas administrativas y de prescripciones técnicas serán sustituidos por el documento descriptivo:", "En el caso de que el procedimiento elegido para adjudicar el contrato sea el procedimiento abierto simplificado.", "En el caso de que el procedimiento elegido para adjudicar el contrato sea el de negociado sin publicidad.", "En el caso de que el procedimiento elegido para adjudicar el contrato sea el  de negociación con publicidad.", "En el caso de que el procedimiento elegido para adjudicar el contrato sea el de diálogo competitivo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 2, "De acuerdo con el artículo 3.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, se considera que no forman parte del sector público las siguientes entidades:", "La Administración General del Estado, las Administraciones de las Comunidades Autónomas, las Ciudades Autónomas de Ceuta y Melilla y las Entidades que integran la Administración Local.", "Las Entidades Gestoras y los Servicios Comunes de la Seguridad Social.", "Los Organismos Autónomos, las Universidades Públicas y las autoridades administrativas independientes.", "Los consorcios sin personalidad jurídica propia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 3, "Son competencia del orden jurisdiccional contencioso-administrativo las siguientes cuestiones:", "Las relativas a la preparación, adjudicación, efectos, modificación y extinción de los contratos administrativos.", "Las que se susciten en relación con la preparación y la adjudicación de los contratos privados de las Administraciones Públicas.", "Las relativas a la preparación y la adjudicación de los contratos de entidades del sector público que no tengan el carácter de poderes adjudicadores.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 4, "Los contratos menores, de acuerdo con el artículo 29.8 de la  Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "No podrán tener una duración superior a dos años.", "No podrán tener una duración superior a un año.", "No podrán tener una duración superior a un año, pero pueden ser objeto de prórroga por un año más.", "No podrán tener una duración superior a seis meses, prorrogables por seis meses más."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 5, "Se consideran contratos menores, de acuerdo con el artículo 118 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "Los de valor estimado inferior a 15.000 euros cuando se trate de suministros.", "Los de valor estimado inferior a 45.000 euros cuando se trate de obras.", "Los de valor estimado inferior a 50.000 euros cuando se trate de obras.", "Los de valor estimado inferior a 20.000 euros cuando se trate de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 6, "Los contratos  administrativos se califican en:", "Contratos de obras , servicios y gestión de servicios públicos.", "Contratos de obras, servicios , suministros, concesión de obras y concesión de servicios.", "Contratos de servicios , suministros y concesión de obras.", "Contratos de obras, servicios, concesión de obras y concesión de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 7, "Tendrán carácter privado, de acuerdo con el artículo 25 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los siguientes contratos:", "Los contratos de servicios que tengan por objeto servicios financieros con número de referencia CPV de 66100000-1 a 66720000-3.", "Los que tengan por objeto la creación e interpretación artística y literaria  y los de espectáculos con número de referencia CPV de 79995000-5 a 79995200-7, y de 92000000-1 a 92700000-8, excepto 92230000-2, 92231000-9 y 92232000-6.", "Aquellos cuyo objeto sea la suscripción a revistas, publicaciones periódicas y bases de datos.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 8, "De acuerdo con el artículo 25.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los contratos administrativos se regirán:", "En cuanto a su preparación, adjudicación, efectos, modificación y extinción, por esta Ley y sus disposiciones de desarrollo; supletoriamente se aplicarán las restantes normas de derecho administrativo y, en su defecto, las normas de derecho privado.", "En cuanto a su preparación, adjudicación, efectos y modificación por la Ley de contratos y sus disposiciones de desarrollo; y en cuanto a su extinción por las normas de derecho privado.", "En cuanto a su preparación y adjudicación por esta Ley y sus disposiciones de desarrollo; supletoriamente se aplicarán las restantes normas de derecho administrativo y, en cuanto a sus efectos, modificación y extinción por las normas de derecho privado.", "En cuanto a su preparación, adjudicación, efectos, modificación y extinción, por esta Ley y sus disposiciones de desarrollo y supletoriamente se aplicarán las normas de derecho privado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 9, "De acuerdo con el artículo 27 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, las cuestiones relativas a la preparación y adjudicación de los contratos privados de las Administraciones públicas, serán competencia de:", "El ordenamiento jurisdiccional civil.", "El ordenamiento jurisdiccional penal.", "El ordenamiento jurisdiccional laboral.", "El ordenamiento jurisdiccional contencioso-administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 10, "El contrato de mantenimiento de un centro público educativo es un contrato:", "De obras.", "De servicios.", "De suministros.", "De gestión de servicios públicos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 11, "De acuerdo con el artículo 34 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en los contratos del sector público podrán incluirse cualesquiera pactos, cláusulas y condiciones, siempre que:", "No sean contrarios al interés público, al ordenamiento jurídico y a los principios de buena administración.", "No sean contrarios a la moral y al principio de igualdad.", "No sean contrarios al principio de proporcionalidad y de igualdad.", "No sean contrarios al principio de lealtad institucional."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 12, "De acuerdo con el artículo 19 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, no se consideran sujetos a regulación armonizada, cualquiera que sea su valor estimado, los contratos siguientes:", "Los que tengan por objeto la adquisición, el desarrollo, la producción o la coproducción de programas destinados a servicios de comunicación audiovisual o servicios de comunicación radiofónica.", "Los incluidos dentro del ámbito definido por el artículo 346 del Tratado de Funcionamiento de la Unión Europea que se concluyan en el sector de la inmigración.", "Aquellos que tengan por objeto los servicios de certificación y autenticación de documentos que deban ser prestados por un notario público.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 13, "Señale la respuesta incorrecta. De acuerdo con el artículo 152.4  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "El desistimiento del procedimiento deberá estar fundado en una infracción no subsanable de las normas de preparación del contrato o de las reguladoras del procedimiento de adjudicación.", "Se deberá justificar  en el expediente la concurrencia de la causa del desistimiento.", "El desistimiento no impedirá la iniciación inmediata de un procedimiento de licitación.", "El desistimiento impedirá la iniciación inmediata de un procedimiento de licitación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 14, "Indique cuál de los siguientes no es un procedimiento de adjudicación de los contratos administrativos:", "Diálogo competitivo.", "Asociación para la innovación.", "Procedimiento con negociación.", "Asociación para la investigación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 15, "De acuerdo con el artículo 96 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la inscripción en el Registro Oficial de Licitadores y Empresas Clasificadas del Sector Público acreditará frente a todos los órganos de contratación del sector público, a tenor de lo en él reflejado y salvo prueba en contrario:", "La solvencia económica y financiera y técnica o profesional y la clasificación.", "Las condiciones de aptitud del empresario en cuanto a su personalidad y capacidad de obrar, representación, habilitación profesional o empresarial.", "La concurrencia o no concurrencia de las prohibiciones de contratar.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 16, "En el procedimiento abierto simplificado previsto en el artículo 159.6  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "Solo se eximirá a los licitadores de la acreditación de la solvencia económica.", "Se eximirá a los licitadores de la acreditación de la solvencia económica y financiera y técnica o profesional.", "La oferta se entregará en tres sobres o archivos electrónicos.", "Se requerirá constitución de garantía definitiva."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 17, "De acuerdo con el artículo 26 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, tendrán la consideración de contratos privados:", "Los que celebren las Administraciones Públicas que tengan por objeto servicios financieros con número de referencia CPV de 66100000-1 a 66720000-3.", "Los celebrados por entidades del sector público que siendo poder adjudicador reúnan la condición de Administraciones Públicas.", "Los celebrados por entidades del sector público que no reúnan la condición de poder adjudicador.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 18, "De acuerdo con el artículo 72 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los órganos de contratación apreciarán directamente las prohibiciones de contratar de las personas en quienes concurran algunas de las circunstancias siguientes:", "Haber sido condenadas mediante sentencia firme por delitos de terrorismo.", "Haber sido sancionadas con carácter firme por infracción grave en materia profesional que ponga en entredicho su integridad, de disciplina de mercado, o de falseamiento de la competencia.", "Haber solicitado la declaración de concurso voluntario.", "Haber incurrido en falsedad al facilitar cualesquiera otros datos relativos a su capacidad y solvencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 19, "De acuerdo con el artículo 36.4  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, salvo que se indique otra cosa en su clausulado, los contratos del sector público se entenderán celebrados:", "En el lugar donde se encuentre la sede del órgano de contratación.", "En el lugar donde se encuentre la sede del contratista.", "En el lugar donde se lleve a cabo la ejecución del contrato.", "En el lugar donde se recepcione el contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 20, "Señale la respuesta incorrecta. De acuerdo con el artículo 11 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, quedan excluidos del ámbito de aplicación de la Ley:", "Los contratos relativos a servicios de arbitraje y conciliación.", "Los contratos que tengan por objeto servicios relacionados con campañas políticas.", "Los contratos regulados en la legislación laboral.", "Los contratos de servicios de limpieza."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 21, "De acuerdo con el artículo 198.4 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la Administración tendrá la obligación de abonar el precio:", "Dentro de los treinta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados.", "Dentro de los cuarenta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados.", "Dentro de los sesenta días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados.", "Dentro de los quince días siguientes a la fecha de aprobación de las certificaciones de obra o de los documentos que acrediten la conformidad con lo dispuesto en el contrato de los bienes entregados o servicios prestados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 22, "De acuerdo con el artículo 65 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, solo podrán contratar con el sector público:", "Las personas naturales o jurídicas, españolas o extranjeras, que tengan plena capacidad de obrar.", "Las personas naturales o jurídicas, españolas o extranjeras, que no estén incursas en alguna prohibición de contratar.", "Las personas naturales o jurídicas, españolas o extranjeras, que acrediten su solvencia económica y financiera y técnica o profesional o, en los casos en que así lo exija esta Ley, se encuentren debidamente clasificadas.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 23, "La construcción de una presa es un contrato administrativo:", "De servicios.", "De suministros.", "De obras.", "De concesión de servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 24, "Señale la respuesta correcta, cuando al vencimiento de un contrato no se hubiera formalizado el nuevo contrato que garantice la continuidad de la prestación a realizar por el contratista como consecuencia de incidencias resultantes de acontecimientos imprevisibles para el órgano de contratación producidas en el procedimiento de adjudicación y existan razones de interés público para no interrumpir la prestación:", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de doce meses, sin modificar las restantes condiciones del contrato, siempre que el anuncio de licitación del nuevo contrato se haya publicado con una antelación mínima de tres meses respecto de la fecha de finalización del contrato originario.", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de nueve meses, sin modificar las restantes condiciones del contrato, siempre que el anuncio de licitación del nuevo contrato se haya publicado con una antelación mínima de tres meses respecto de la fecha de finalización del contrato originario.", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de doce meses, sin modificar las restantes condiciones del contrato, aunque el anuncio de licitación del nuevo contrato no se haya publicado.", "Se podrá prorrogar el contrato originario hasta que comience la ejecución del nuevo contrato y en todo caso por un periodo máximo de nueve meses, sin modificar las restantes condiciones del contrato, siempre que el anuncio de licitación del nuevo contrato se haya publicado con una antelación mínima de seis meses respecto de la fecha de finalización del contrato originario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 25, "De acuerdo con el artículo 32.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, para la condición de medio propio personificado de la entidad destinataria del encargo respecto del poder adjudicador concreto que hace el encargo, ¿qué requisitos, entre otros, se deben cumplir?", "Deberá reconocerse expresamente en sus estatutos o actos de creación.", "Será necesaria la conformidad o autorización expresa del poder adjudicador respecto del que vaya a ser medio propio.", "Será necesaria la verificación por la entidad pública de que dependa el ente que vaya a ser medio propio, de que cuenta con medios personales y materiales apropiados para la realización de los encargos de conformidad con su objeto social.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 26, "De acuerdo con el artículo 99  de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014:", "El objeto de los contratos deberá ser indeterminado.", "Podrá fraccionarse un contrato con la finalidad de disminuir la cuantía del mismo.", "Deberá preverse siempre la realización independiente de cada una de sus partes mediante su división en lotes.", "No podrá fraccionarse un contrato con la finalidad de disminuir la cuantía del mismo y eludir así los requisitos de publicidad o los relativos al procedimiento de adjudicación que correspondan."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 27, "De acuerdo con el artículo 27 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, las cuestiones relativas a la preparación y adjudicación de los contratos de entidades del sector público que no tengan el carácter de poderes adjudicadores, serán competencia:", "Del ordenamiento jurisdiccional civil.", "Del ordenamiento jurisdiccional penal.", "Del ordenamiento jurisdiccional laboral.", "Del ordenamiento jurisdiccional contencioso-administrativo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 28, "De acuerdo con el artículo 63.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el caso de la información relativa a los contratos, deberá publicarse en el perfil del contratante:", "La memoria justificativa del contrato, el informe de insuficiencia de medios en el caso de contratos de servicios, la justificación del procedimiento utilizado para su adjudicación cuando se utilice un procedimiento distinto del abierto o del restringido.", "El objeto detallado del contrato, su duración, el presupuesto base de licitación y el importe de adjudicación, incluido el Impuesto sobre el Valor Añadido.", "El pliego de cláusulas administrativas particulares y el de prescripciones técnicas que hayan de regir el contrato o documentos equivalentes, en su caso, y el documento de aprobación del expediente.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 29, "De acuerdo con el artículo 103.5 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, salvo en los contratos de suministro de energía, cuando proceda, la revisión periódica y predeterminada de precios en los contratos del sector público tendrá lugar:", "Cuando el contrato se hubiese ejecutado, al menos, en el 20 por ciento de su importe y hubiesen transcurrido dos años desde su formalización. No obstante, la condición relativa al porcentaje de ejecución del contrato no será exigible en los contratos de concesión de servicios.", "En todo caso cuando el contrato se hubiese ejecutado, al menos, en el 25 por ciento de su importe y hubiesen transcurrido dos años desde su formalización.", "Cuando el contrato se hubiese ejecutado, al menos, en el 30 por ciento de su importe y hubiesen transcurrido dos años desde su formalización. No obstante, la condición relativa al porcentaje de ejecución del contrato no será exigible en los contratos de concesión de servicios.", "En todo caso cuando el contrato se hubiese ejecutado, al menos, en el 15 por ciento de su importe y hubiesen transcurrido dos años desde su formalización."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 30, "De acuerdo con el artículo 107 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en casos especiales, el órgano de contratación podrá establecer en el pliego de cláusulas administrativas particulares que, además de la garantía a que se refiere el apartado anterior, se preste una garantía complementaria:", "De hasta un 5 por 100 del precio final ofertado por el licitador que presentó la mejor oferta, excluido el Impuesto sobre el Valor Añadido, pudiendo alcanzar la garantía total un 10 por 100 del precio.", "De hasta un 3 por 100 del precio final ofertado por el licitador que presentó la mejor oferta, excluido el Impuesto sobre el Valor Añadido, pudiendo alcanzar la garantía total un 8 por 100 del precio.", "De hasta un 5 por 100 del precio final ofertado por el licitador que presentó la mejor oferta, excluido el Impuesto sobre el Valor Añadido, pudiendo alcanzar la garantía total un 8 por 100 del precio.", "De hasta un 3 por 100 del precio final ofertado por el licitador que presentó la mejor oferta, excluido el Impuesto sobre el Valor Añadido, pudiendo alcanzar la garantía total un 10 por 100 del precio."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 31, "De acuerdo con el artículo 29.4 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, como regla general, los contratos de suministros y de servicios de prestación sucesiva tendrán un plazo máximo de duración de:", "Cinco años, incluyendo las posibles prórrogas.", "Cinco años más prórroga de cinco años más.", "Tres años incluyendo las posibles prórrogas.", "Tres años más prórroga de hasta tres años más."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 32, "De acuerdo con el artículo 111.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el acuerdo de devolución de la garantía constituida:", "Deberá adoptarse y notificarse al interesado en el plazo de tres meses desde la finalización del plazo de garantía.", "Deberá adoptarse y notificarse al interesado en el plazo de seis meses desde la finalización del plazo de garantía.", "Deberá adoptarse y notificarse al interesado en el plazo de dos meses desde la finalización del plazo de garantía.", "Deberá adoptarse y notificarse al interesado en el plazo de un mes desde la finalización del plazo de garantía."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 33, "De acuerdo con el artículo 116 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el expediente de contratación se deberá justificar:", "La elección del procedimiento de licitación.", "Los criterios de solvencia técnica o profesional, y económica y financiera, y los criterios que se tendrán en consideración para adjudicar el contrato, pero no la clasificación que se exija a los participantes.", "El presupuesto de licitación del contrato sin incluir el valor estimado del contrato.", "El informe de suficiencia de medios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 34, "Cuando la Administración tenga que contratar de manera inmediata a causa de acontecimientos catastróficos, de situaciones que supongan un grave peligro o de necesidades que afecten a la defensa nacional, se estará ante una tramitación:", "De emergencia.", "De excepción.", "De urgencia.", "De riesgo."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 35, "De acuerdo con el artículo 122 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en los pliegos de cláusulas administrativas particulares se incluirán:", "Los criterios de solvencia y de adjudicación del contrato.", "Las consideraciones sociales, laborales y ambientales que se establezcan como criterios de solvencia, de adjudicación o como condiciones especiales de ejecución.", "Los pactos y condiciones definidores de los derechos y obligaciones de las partes del contrato.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 36, "Los expedientes de contratación administrativa pueden ser de tramitación:", "Ordinaria y urgente.", "Ordinaria y por emergencia.", "Ordinaria.", "Ordinaria, por urgencia y por emergencia."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 37, "Si un licitador suscribe una propuesta en unión temporal con otros y, además, suscribe una propuesta de forma individual o figura en más de una unión temporal, la infracción de estas normas:", "Dará lugar a la admisión sólo de una de las propuestas por él suscritas.", "Dará lugar a la no admisión de todas las propuestas por él suscritas.", "Dará lugar a la admisión de la propuesta que elija el licitador de entre todas las presentadas.", "Dará lugar a la admisión de la primera propuesta que el licitador hubiera presentado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 38, "De acuerdo con el artículo 140 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en relación con la presentación de la documentación acreditativa del cumplimiento de los requisitos previos:", "Las proposiciones en el procedimiento abierto deberán ir acompañadas de una declaración responsable que se ajustará al formulario de documento europeo único de contratación.", "En los casos en que el empresario recurra a la solvencia y medios de otras empresas de conformidad con el artículo 75 de la Ley, cada una de ellas también deberá presentar una declaración responsable.", "En todos los supuestos en que en el procedimiento se exija la constitución de garantía provisional, se aportará el documento acreditativo de haberla constituido.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 39, "De acuerdo con el artículo 145.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la aplicación de más de un criterio de adjudicación procederá, en todo caso, en la adjudicación de los siguientes contratos:", "Cuando el órgano de contratación considere que la definición de la prestación no es susceptible de ser mejorada por otras soluciones técnicas.", "Aquellos que no requieran el empleo de tecnología especialmente avanzada o cuya ejecución sea particularmente compleja.", "Contratos de concesión de obras y de concesión de servicios.", "Contratos de servicios con prestaciones indefinidas técnicamente."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 40, "La evaluación de las ofertas conforme a los criterios cuantificables mediante la mera aplicación de fórmulas:", "En todo caso se realizará previamente a la de aquellos otros criterios en que no concurra esta circunstancia.", "En todo caso se realizará tras efectuar previamente la de aquellos otros criterios en que no concurra esta circunstancia, dejándose constancia documental de ello.", "Podrá realizarse previamente a la de aquellos otros criterios en que no concurra esta circunstancia.", "Podrá realizarse previamente o con posterioridad a la de aquellos otros criterios en que no concurra esta circunstancia a elección del órgano de contratación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 41, "Señale la respuesta correcta, de acuerdo con el artículo 153.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, si el contrato es susceptible de recurso especial en materia de contratación conforme al artículo 44:", "La formalización no podrá efectuarse antes de que transcurran diez días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos. Las Comunidades Autónomas podrán incrementar este plazo, sin que exceda de dos meses.", "La formalización no podrá efectuarse antes de que transcurran diez días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos. Las Comunidades Autónomas podrán incrementar este plazo, sin que exceda de un mes.", "La formalización no podrá efectuarse antes de que transcurran quince días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos. Las Comunidades Autónomas podrán incrementar este plazo, sin que exceda de un mes.", "La formalización no podrá efectuarse antes de que transcurran quince días hábiles desde que se remita la notificación de la adjudicación a los licitadores y candidatos. Las Comunidades Autónomas solo podrán incrementar este plazo en diez días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 42, "La tramitación del procedimiento abierto simplificado se ajustará a las siguientes especialidades:", "La oferta se presentará en dos o tres sobres o archivos electrónico en los supuestos en que en el procedimiento se contemplen criterios de adjudicación cuya cuantificación dependa de un juicio de valor. En caso contrario, la oferta se presentará en dos sobres o archivos electrónicos.", "La oferta se presentará en un único sobre o archivo electrónico en todo caso.", "La oferta se presentará en un único sobre o archivo electrónico en los supuestos en que en el procedimiento no se contemplen criterios de adjudicación cuya cuantificación dependa de un juicio de valor. En caso contrario, la oferta se presentará en dos sobres o archivos electrónicos.", "La oferta se presentará en dos sobres o archivos electrónicos en todo caso."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 43, "Cuando el órgano de contratación proceda a la división en lotes del objeto del contrato, éste podrá introducir las siguientes limitaciones, justificándolas debidamente en el expediente:", "Podrá limitar el número de lotes para los que un mismo candidato o licitador puede presentar oferta.", "Podrá limitar el número de lotes para los que un mismo candidato o licitador puede presentar oferta, pero no podrá limitar el número de lotes que pueden adjudicarse a cada licitador.", "Podrá limitar el número de lotes que pueden adjudicarse a cada licitador.", "Las respuestas a) y c) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 44, "Señale la respuesta incorrecta. En los contratos de obras de valor estimado inferior a 80.000 euros, y en contratos de suministros y de servicios de valor estimado inferior a 60.000 euros, excepto los que tengan por objeto prestaciones de carácter intelectual a los que no será de aplicación el apartado 6 del artículo 159 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el procedimiento abierto simplificado podrá seguir la siguiente tramitación:", "El plazo para la presentación de proposiciones no podrá ser inferior a diez días hábiles, a contar desde el siguiente a la publicación del anuncio de licitación en el perfil de contratante. No obstante lo anterior, cuando se trate de compras corrientes de bienes disponibles en el mercado el plazo será de cinco días hábiles.", "Se eximirá a los licitadores de la acreditación de la solvencia económica y financiera y técnica o profesional.", "La oferta se entregará en un único sobre o archivo electrónico y se evaluará, en todo caso, con arreglo a criterios de adjudicación cuantificables mediante la mera aplicación de fórmulas establecidas en los pliegos.", "Se requerirá la constitución de garantía definitiva y la formalización del contrato podrá efectuarse mediante la firma de aceptación por el contratista de la resolución de adjudicación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 45, "De acuerdo con el artículo 80 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los acuerdos relativos a la clasificación de las empresas se adoptarán  por las Comisiones Clasificadoras de la Junta Consultiva de Contratación Pública del Estado:", "Con eficacia general frente a todos los órganos de contratación.", "Con eficacia limitada al territorio sede del órgano de contratación.", "Con eficacia limitada al procedimiento de licitación en cuestión.", "Con eficacia limitada a seis meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 46, "Cuando en la tramitación de un procedimiento negociado sin publicidad únicamente participe un candidato, la mesa de contratación, o en su defecto, el órgano de contratación:", "Negociará con el candidato en todo caso.", "Podrá negociar con el candidato.", "No tendrá que negociar con el candidato.", "Deberá negociar con el candidato siempre y cuando sea posible."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 47, "Señale la respuesta incorrecta. De acuerdo con el articulo 180 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el procedimiento de contratación de asociación para la innovación:", "Se estructurará en fases sucesivas siguiendo la secuencia de las etapas del proceso de investigación e innovación, que podrá incluir la fabricación de los productos, la prestación de los servicios o la realización de las obras.", "Se estructurará en fases independientemente de que sean sucesivas de acuerdo con una serie de etapas del proceso de investigación e innovación, que podrá incluir la fabricación de los productos, la prestación de los servicios o la realización de las obras.", "La asociación para la innovación fijará unos objetivos intermedios que deberán alcanzar los socios y proveerá el pago de la retribución en plazos adecuados.", "En ningún caso, la resolución de la asociación para la innovación o la reducción del número de candidatos participantes dará lugar a indemnización, sin perjuicio de la contraprestación que, en las condiciones establecidas en el pliego, corresponda por los trabajos realizados."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 48, "De acuerdo con el articulo 190 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el órgano de contratación no ostenta las siguientes prerrogativas:", "Interpretar los contratos administrativos y resolver las dudas que ofrezca su cumplimiento.", "Modificar los contratos administrativos por razones de interés público.", "Declarar la responsabilidad imputable al contratista a raíz de la ejecución del contrato.", "Inspeccionar las instalaciones, oficinas y demás emplazamientos en los que el contratista desarrolle sus actividades, aunque no sean determinantes para el desarrollo de las prestaciones objeto del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 49, "De acuerdo con el artículo 191.3 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, será preceptivo el dictamen del Consell Consultiu en el ámbito de la Comunitat Autònoma de les Illes Balears:", "En el caso de que el órgano de contratación ejerza la prerrogativa de  interpretar el contrato.", "En el caso de que el órgano de contratación ejerza la prerrogativa de anular el contrato.", "En el caso de que el órgano de contratación ejerza la prerrogativa de  resolver el contrato, cuando se formule oposición por parte del contratista.", "En el caso de las modificaciones de los contratos cuando no estuvieran previstas en el pliego de cláusulas administrativas particulares y su cuantía, aislada o conjuntamente, sea superior a un 40 por ciento del precio inicial del contrato, IVA excluido, y su precio sea igual o superior a 8.000.000 de euros."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 50, "De acuerdo con el artículo 204 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los contratos de las Administraciones Públicas podrán modificarse durante su vigencia cuando en los pliegos de cláusulas administrativas particulares se hubiere advertido expresamente de esta posibilidad:", "Hasta un máximo del veinte por ciento del precio inicial.", "Hasta un máximo del diez por ciento del precio inicial.", "Hasta un máximo del quince por ciento del precio inicial.", "Hasta un máximo del treinta por ciento del precio inicial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 51, "En los contratos se fijará un plazo de garantía a contar desde:", "La fecha de recepción o conformidad del contrato.", "La fecha de formalización del contrato.", "La fecha de aprobación del contrato.", "La fecha de pago del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 52, "No son causa de resolución del contrato:", "La prórroga del contrato.", "La declaración de concurso o la declaración de insolvencia en cualquier otro procedimiento.", "El mutuo acuerdo entre la Administración y el contratista.", "El incumplimiento de la obligación principal del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 53, "Señale la respuesta incorrecta:", "Los subcontratistas quedarán obligados solo ante el contratista principal que asumirá, por tanto, la total responsabilidad de la ejecución del contrato frente a la Administración, con arreglo estricto a los pliegos de cláusulas administrativas particulares o documento descriptivo, y a los términos del contrato.", "Si así se prevé en los pliegos, los licitadores deberán indicar en la oferta la parte del contrato que tengan previsto subcontratar, señalando su importe, y el nombre o el perfil empresarial, definido por referencia a las condiciones de solvencia profesional o técnica, de los subcontratistas a los que se vaya a encomendar su realización.", "En todo caso, el contratista deberá comunicar por escrito, tras la adjudicación del contrato y, a más tardar, cuando inicie la ejecución de este, al órgano de contratación la intención de celebrar los subcontratos, señalando la parte de la prestación que se pretende subcontratar y la identidad, datos de contacto y representante o representantes legales del subcontratista, y justificando suficientemente la aptitud de éste para ejecutarla.", "El subcontratista deberá notificar por escrito al órgano de contratación cualquier modificación que sufra."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 54, "De acuerdo con el artículo 68 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, respecto de las empresas no comunitarias:", "Adicionalmente, el pliego de cláusulas administrativas particulares podrá exigir a las empresas no comunitarias que resulten adjudicatarias de contratos de obras que abran una sucursal en España, con designación de apoderados o representantes para sus operaciones.", "Adicionalmente, el pliego de cláusulas administrativas particulares podrá exigir a las empresas no comunitarias que resulten adjudicatarias de contratos de obras que estén inscritas en el Registro Mercantil.", "Adicionalmente, el pliego de cláusulas administrativas particulares podrá exigir a las empresas no comunitarias que resulten adjudicatarias de contratos de obras que tributen en España.", "Las respuestas a) y b) son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 55, "De acuerdo con el artículo 219.2 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la duración de un acuerdo marco:", "No podrá exceder de cinco años.", "No podrá exceder de tres años.", "No podrá exceder de seis años.", "No podrá exceder de cuatro años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 56, "Señale la respuesta incorrecta. De acuerdo con el artículo 232 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, a los efectos de elaboración de los proyectos se clasificarán las obras, según su objeto y naturaleza, en los grupos siguientes:", "Obras de primer establecimiento, reforma, restauración, rehabilitación o gran reparación.", "Obras de reparación simple.", "Obras de conservación y mantenimiento.", "Obras de desgaste."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 57, "De acuerdo con el artículo 82 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la clasificación de las empresas:", "Tendrá una vigencia indefinida en todo caso.", "Tendrá una vigencia indefinida en tanto se mantengan por el empresario las condiciones y circunstancias en que se basó su concesión.", "Tendrá una vigencia anual.", "Tendrá una vigencia por tres años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 58, "La ejecución del contrato de obras comenzará:", "Con la formalización del contrato.", "Con el acta de comprobación del replanteo.", "Con la supervisión del proyecto.", "Con la aprobación del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 59, "Los contratos administrativos se califican en:", "Servicios, obras, suministros, concesión de obras y concesión de servicios.", "Suministros y obras.", "Servicios, obras y suministros.", "Obras y servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 60, "De acuerdo con el artículo 284 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la Administración podrá gestionar indirectamente, mediante contrato de concesión de servicios, los servicios de su titularidad o competencia siempre que sean susceptibles de explotación económica por particulares. En ningún caso podrán prestarse mediante concesión de servicios los que impliquen:", "Efectos económicos.", "Ejercicio de la autoridad inherente a los poderes públicos.", "Riesgo operacional.", "Riesgo y ventura."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 61, "Señale la respuesta incorrecta. De acuerdo con el artículo 16 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, son contratos de suministro:", "Los que tienen por objeto la adquisición, el arrendamiento financiero, o el arrendamiento, con o sin opción de compra, de productos o bienes muebles.", "Los contratos relativos a propiedades incorporales o valores negociables.", "Los que tengan por objeto la adquisición de energía primaria o energía transformada.", "Aquellos en los que el empresario se obligue a entregar una pluralidad de bienes de forma sucesiva y por precio unitario."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 62, "De acuerdo con el artículo 302 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, cuando razones técnicas o económicas debidamente justificadas en el expediente lo aconsejen, podrá establecerse en el pliego de cláusulas administrativas particulares que el pago del precio total de los bienes a suministrar consista parte en dinero y parte en la entrega de otros bienes de la misma clase, sin que, en ningún caso, el importe de éstos:", "Pueda superar el 50 por cien del precio total.", "Pueda superar el 20 por cien del precio total.", "Pueda superar el 30 por cien del precio total.", "Pueda superar el 40 por cien del precio total."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 63, "Una entidad contratante podrá instrumentar la contratación de personal a través del contrato de servicios:", "Sólo mediante un contrato menor.", "En ningún caso.", "Sólo en determinados casos siempre que el órgano de contratación lo autorice.", "Cuando concurran circunstancias sobrevenidas e imprevistas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 64, "De acuerdo con el artículo 131 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, la adjudicación se realizará, ordinariamente:", "Utilizando una pluralidad de criterios de adjudicación basados en el principio de mejor relación calidad-precio, y utilizando el procedimiento abierto o el procedimiento restringido.", "Utilizando un único criterio de adjudicación basado en el precio y utilizando el procedimiento restringido.", "Utilizando un único criterio de adjudicación basado en el precio y utilizando el procedimiento abierto.", "Utilizando una pluralidad de criterios de adjudicación basados en el principio de mejor relación calidad-precio, y utilizando el procedimiento negociado."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 65, "La redacción de un proyecto de obras es un contrato de:", "Suministro.", "Concesión de obras.", "Obras.", "Servicios."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 66, "De acuerdo con el artículo 69.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, podrán contratar con el sector público las uniones de empresarios que se constituyan temporalmente al efecto, sin que sea necesaria la formalización de las mismas en escritura pública:", "Hasta que se haya efectuado la adjudicación del contrato a su favor.", "Hasta que se haya publicado la formalización del contrato en la Plataforma de contratación correspondiente.", "Hasta que no se haya efectuado la aprobación del expediente.", "Hasta que no se haya publicado la licitación del contrato."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 67, "La constitución de la Mesa de contratación será potestativa:", "En los procedimientos abiertos y abierto simplificado.", "En los procedimientos restringidos y de diálogo competitivo.", "En los procedimientos de licitación con negociación y de asociación para la innovación, los órganos de contratación de las administraciones públicas estarán asistidos por una mesa de contratación.", "En los procedimientos abiertos simplificados abreviados a los que se refiere el artículo 159.6 de la Ley 9/2017,de 8 de noviembre, de Contratos del Sector Público."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 68, "De acuerdo con el artículo 156.6 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, en el procedimiento abierto en el caso de los contratos de las Administraciones Públicas que no estén sujetos a regulación armonizada:", "El plazo de presentación de proposiciones no será inferior a quince días, contados desde el día siguiente al de la publicación del anuncio de licitación del contrato en el perfil del contratante. En los contratos de obras y de concesión de obras y concesión de servicios, el plazo será, como mínimo, de veintiséis días.", "El plazo de presentación de proposiciones no será inferior a veinte días, contados desde el día siguiente al de la publicación del anuncio de licitación del contrato en el perfil del contratante. En los contratos de obras y de concesión de obras y concesión de servicios, el plazo será, como mínimo, de treinta días.", "En todo caso el plazo de presentación de proposiciones no será inferior a veinte días, contados desde el día siguiente al de la publicación del anuncio de licitación del contrato en el perfil del contratante.", "El plazo de presentación de proposiciones no será inferior a quince días, contados desde el día siguiente al de la publicación del anuncio de licitación del contrato en el perfil del contratante. En los contratos de obras y de concesión de obras y concesión de servicios, el plazo será, como mínimo, de treinta días."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 69, "La Oficina Independiente de Regulación y Supervisión de la Contratación elaborará un informe de supervisión que remitirá a la Junta Consultiva de Contratación Pública del Estado, que se integrará en el informe nacional a remitir a la Comisión Europea:", "Cada tres años.", "Cada dos años.", "Cada cinco años.", "Cada cuatro años."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 70, "De acuerdo con el artículo 198.5 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, el contratista podrá proceder, en su caso, a la suspensión del cumplimiento del contrato:", "Si la demora en el pago fuese superior a cinco meses.", "Si la demora en el pago fuese superior a cuatro meses.", "Si la demora en el pago fuese superior a tres meses.", "Si la demora en el pago fuese superior a seis meses."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 71, "Señale la respuesta incorrecta. Con relación al Registro de Contratos del Sector Público, que constituye el sistema oficial central de información sobre la contratación pública en España:", "Los poderes adjudicadores comunicarán al Registro de Contratos del Sector Público, para su inscripción, los datos básicos de los contratos por ellos adjudicados, entre los que figurará la identidad del adjudicatario, y el importe de adjudicación de los mismos, junto con el desglose correspondiente del Impuesto sobre el Valor Añadido.", "Los poderes adjudicadores comunicarán al Registro de Contratos del Sector Público, para su inscripción, los datos básicos de los contratos por ellos adjudicados, entre los que figurará la identidad del adjudicatario, el objeto y el importe de adjudicación de los mismos sin el desglose del Impuesto sobre el Valor Añadido.", "Los poderes adjudicadores comunicarán, en su caso, las modificaciones, prórrogas, variaciones de plazos o de precio, importe final y extinción de los contratos.", "Las comunicaciones de datos de contratos al Registro de Contratos del Sector Público se efectuarán por medios electrónicos, informáticos o telemáticos."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 72, "De acuerdo con el artículo 101 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, para el cálculo del valor estimado de los contratos de obras, suministros y servicios, se tendrá en cuenta:", "El importe total, sin incluir el Impuesto sobre el Valor Añadido.", "La totalidad de las modificaciones al alza previstas.", "Cualquier forma de opción eventual y las eventuales prórrogas del contrato.", "Todas las respuestas son correctas."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 73, "Los órganos de contratación de las Administraciones locales, así como los de sus entidades vinculadas o dependientes:", "Podrán optar bien por alojar la publicación de sus perfiles de contratante en el servicio de información que a tal efecto estableciera la Comunidad Autónoma de su ámbito territorial, o bien por alojarlos en la Plataforma de Contratación del Sector Público.", "Deberán de forma exclusiva alojar la publicación de sus perfiles de contratante en el servicio de información que a tal efecto estableciera la Comunidad Autónoma de su ámbito territorial.", "Podrán optar de forma excluyente, bien por alojar la publicación de sus perfiles de contratante en el servicio de información que a tal efecto estableciera la Comunidad Autónoma de su ámbito territorial, o bien por alojarlos en la Plataforma de Contratación del Sector Público.", "Deberán, de forma excluyente y exclusiva, alojar la publicación de sus perfiles de contratante en el servicio de información que a tal efecto estableciera la Comunidad Autónoma de su ámbito territorial."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 74, "Señale la respuesta incorrecta. De acuerdo con la disposición adicional cuadragésima primera de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, se reconoce la naturaleza de prestaciones de carácter intelectual a los servicios:", "De arquitectura.", "De consultoría y urbanismo.", "De ingeniería.", "De investigación."); 
insert into question (administration, grup, theme, number, question, option1, option2, option3, option4) values ("caib", "A2", 12, 75, "De acuerdo con el artículo 36.1 de la Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público, por la que se transponen al ordenamiento jurídico español las Directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero de 2014, los contratos que celebren los poderes adjudicadores, a excepción de los contratos menores y de los contratos basados en un acuerdo marco y los contratos específicos en el marco de un sistema dinámico de adquisición a los que se refiere el apartado 3 de este artículo 36, se perfeccionan:", "Con su adjudicación.", "Con su formalización.", "Con su publicación.", "Con su aprobación."); 
